  ('official_bank_bua201', 'retire', 377, $official_bank_source$"4fa01cec-12a8-5b94-8214-ac05400dcee9"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 378, $official_bank_source$"2a57b63e-fcef-5d3a-8663-e86b25d91ca9"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 379, $official_bank_source$"60fb4a1e-a4d7-528d-b68e-34e07132832e"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 380, $official_bank_source$"82cf4f59-ce6a-5964-910e-a50cb2df542b"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 381, $official_bank_source$"011b05e6-4d32-50a2-a339-0e6bb9b19bfe"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 382, $official_bank_source$"421e1ff1-ad6a-59ab-a932-18774dbf2c40"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 383, $official_bank_source$"a540e958-9b1c-59c4-bdc0-349cf54ef185"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 384, $official_bank_source$"fece9768-1bd7-5c15-ab02-ee43fe1929db"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 385, $official_bank_source$"ae11b0c5-c5d5-54fd-9c9d-7134a95ac466"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 386, $official_bank_source$"185fc50d-2f58-5e70-bf1a-37ba3ffcf7d4"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 387, $official_bank_source$"bbb4817e-4d63-5329-86a8-6d13af97f274"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 388, $official_bank_source$"23a7f13f-5452-5474-82c3-aacf37642f9a"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'retire', 389, $official_bank_source$"1abbe8b7-1d2c-5cf7-85f5-fc9698917cab"$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 1, $official_bank_source${"itemId":"ef3a790d-8bdb-5e64-853d-583333b9f2e9","questionId":"edd7c784-06af-5b63-baeb-1bd71d8a395b","sourceKey":"bank:BUA201:PQ-003","payload":{"prompt":"The behavioural school of management emerged mainly to address:","options":["Capital market instability","Legal compliance gaps in organisations","Cost minimisation inefficiencies in production","The human and social side of work, such as informal groups and worker attitudes, which earlier classical theories largely ignored"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The behavioural (human relations) school grew out of studies such as the Hawthorne experiments, which showed that social relationships, informal groups and attention to workers affect productivity. Option C is closer to the concern of scientific management, which focused on efficient methods of work rather than people's feelings and group behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 2, $official_bank_source${"itemId":"2f820357-0850-562e-9575-85013f3dcc0b","questionId":"59346dbf-cfa3-5eec-acb9-445d09889708","sourceKey":"bank:BUA201:PQ-026","payload":{"prompt":"In Herzberg's two-factor theory, salary is classified as a:","options":["Self-actualisation need","Hygiene factor","Reinforcer","Motivator"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Herzberg found that salary, working conditions and company policy are hygiene factors: when poor they cause dissatisfaction, but improving them does not by itself motivate. Option D covers things like achievement, recognition and responsibility, and option A comes from Maslow's hierarchy, not Herzberg."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 3, $official_bank_source${"itemId":"30c9b92a-6d49-5942-895b-c125f0a3b752","questionId":"0ccd0568-3831-591e-8c0a-bcd72a7f8cd9","sourceKey":"bank:BUA201:PQ-105","payload":{"prompt":"Which historical development most directly led to the separation of ownership from control in business?","options":["The barter system","The Industrial Revolution","Mercantilism","The subsistence economy"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"The Industrial Revolution created large factories and enterprises that needed huge capital from many shareholders and professional managers to run them, so owners stopped running the business themselves. Options A and D describe small-scale exchange or self-sufficient production where the owner did everything. Option C was an older trade policy aimed at building national wealth, not a change in how firms were owned and managed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 4, $official_bank_source${"itemId":"0bd61126-bdfe-5661-b5cc-b2c425034f99","questionId":"68beb5b1-4a23-5d2f-aac2-6ce3c38e3ffb","sourceKey":"bank:BUA201:PQ-107","payload":{"prompt":"Taylor's Scientific Management has been criticised mainly because it:","options":["Ignored the use of technology","Treated workers like economic machines","Paid too much attention to workers' social needs","Discouraged specialisation"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Scientific management broke jobs into small, timed tasks and assumed money was what drove workers, so critics say it treated people as parts of a machine and ignored their feelings and social needs. Option C is the opposite of the real criticism, since social needs were exactly what it neglected. Options A and D are also wrong, because the approach relied on careful study of tools and methods and strongly promoted specialisation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 5, $official_bank_source${"itemId":"ca70c006-bdf1-586d-b763-09096442bb54","questionId":"f724ba2b-9803-5d25-b413-efb6cdd9d47a","sourceKey":"bank:BUA201:PQ-108","payload":{"prompt":"Which conclusion from the Hawthorne studies challenged classical management theory?","options":["Workers respond only to wages","Informal groups influence productivity","Supervision is unnecessary","Division of labour reduces efficiency"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"The Hawthorne studies found that social factors, such as attention from supervisors and the norms of informal work groups, affected output more than physical conditions or pay alone. Option A is the classical assumption the studies challenged. Options C and D were not findings of the studies."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 6, $official_bank_source${"itemId":"79cdffdf-ee98-5453-a95c-a12afe9fb265","questionId":"096bbe2c-73ba-50ee-8746-b1f59dec054d","sourceKey":"bank:BUA201:PQ-109","payload":{"prompt":"A manager who uses strict controls in a crisis but participative methods during stable periods is showing:","options":["Theory X assumptions only","Theory Y assumptions only","Trait leadership","Situational application of Theory X and Theory Y"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Theory X favours close control and Theory Y favours participation, and this manager switches between the two depending on the situation. Options A and B each describe only one side of the behaviour. Option C explains leadership by inborn personal qualities, not by changing style to suit conditions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 7, $official_bank_source${"itemId":"d13dda51-0516-5433-b3e6-15969a404750","questionId":"c1a94db6-e66d-5bf0-9a64-4cfea4925a43","sourceKey":"bank:BUA201:PQ-110","payload":{"prompt":"Which organisational practice aligns MOST with Theory Y?","options":["Tight supervision","Centralised decision-making","Job enrichment and empowerment","Punitive control systems"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Theory Y assumes people can enjoy work, seek responsibility and direct themselves, so it fits practices such as job enrichment and empowerment that give staff more challenge and control. Options A, B and D rest on the Theory X belief that workers must be closely watched and pushed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 8, $official_bank_source${"itemId":"dc398fb4-5d0f-5c21-8883-87844405e278","questionId":"a28ce58e-a12e-5317-9162-306a882f83cf","sourceKey":"bank:BUA201:PQ-129","payload":{"prompt":"Modern management thinking emphasises flexibility because organisations operate in:","options":["Stable environments","Dynamic and complex environments","Closed systems","Predictable conditions"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Today's businesses face fast changes in technology, competition, regulation and customer tastes, so they must be able to adapt quickly. Options A and D describe conditions where rigid plans could work, which is why they do not explain the need for flexibility. Option C is wrong because modern thinking treats organisations as open systems that interact with their environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 9, $official_bank_source${"itemId":"e238e2cf-c0f0-5820-a7ad-6243c91ca314","questionId":"dae14ab0-260a-5f4b-9dff-eff18826807b","sourceKey":"bank:BUA201:PQ-130","payload":{"prompt":"A manager who relies on experience, creativity and judgment while also applying management principles is practising management as:","options":["A pure science","A pure art","Intuition only","Both an art and a science"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Management is a science because it has an organised body of principles, and an art because applying them well takes personal skill, creativity and judgment. This manager combines both. Options A and B each capture only half of what the manager is doing, and option C ignores the principles completely."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 10, $official_bank_source${"itemId":"aeba1b6c-55ee-536e-9d03-77a0070c08e5","questionId":"a4e40fbd-b7ef-5cc8-bc51-878856bb1333","sourceKey":"bank:BUA201:PQ-134-a","payload":{"prompt":"Who is generally regarded as the father of Scientific Management?","options":["Frederick W. Taylor","Henri Fayol","Elton Mayo","Max Weber"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Frederick W. Taylor developed Scientific Management, which used careful study of tasks, standard methods and incentive pay to raise worker efficiency. Option B is known for the principles and functions of administrative management, option C is linked with the Hawthorne studies and the Human Relations School, and option D is known for the theory of bureaucracy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 11, $official_bank_source${"itemId":"517dad43-f6e7-5a34-af60-6abe3fbdd1b0","questionId":"842f1890-1c6c-5343-8d30-4ffd2875b3af","sourceKey":"bank:BUA201:PQ-134-b","payload":{"prompt":"The Human Relations School of management thought grew mainly out of:","options":["Time-and-motion studies of individual tasks","The theory of bureaucracy","The 14 principles of administrative management","The Hawthorne studies associated with Elton Mayo"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The Hawthorne studies at the Western Electric company, associated with Elton Mayo, showed that social factors and group relations affect productivity, and this gave rise to the Human Relations School. Option A belongs to Scientific Management, option B to Max Weber, and option C to Henri Fayol, all part of the earlier classical approach."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 12, $official_bank_source${"itemId":"eb9c8498-462b-5dba-bd63-bf8ac149a20c","questionId":"c16ef31d-2124-5871-9cf3-a0cc2e30500b","sourceKey":"bank:BUA201:PQ-134-c","payload":{"prompt":"The main focus of Scientific Management was to:","options":["Satisfy the social needs of workers","View the organisation as an open system","Adapt leadership style to each situation","Raise worker efficiency through systematic study of tasks and methods"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Scientific Management sought the one best way to do each job by studying tasks, standardising methods, selecting and training workers scientifically and linking pay to output. Option A was the focus of the later Human Relations School, option B comes from systems theory, and option C comes from contingency thinking."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 13, $official_bank_source${"itemId":"7b3b235f-251b-52dc-b40a-599bf310c5f8","questionId":"cb8601c7-7c46-595c-a4a1-4f1dfa564039","sourceKey":"bank:BUA201:PQ-135-a","payload":{"prompt":"McGregor's Theory X assumes that the average worker:","options":["Enjoys work and seeks responsibility","Dislikes work and must be closely supervised and controlled","Is creative and capable of self-direction","Is motivated mainly by self-actualisation"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Theory X holds that people naturally avoid work and responsibility, so managers must direct, watch and sometimes threaten them to get results. Options A, C and D are assumptions of Theory Y, the opposite view of human nature."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 14, $official_bank_source${"itemId":"d5409deb-ca9f-5c86-84f9-4806a6e5ba94","questionId":"50da6863-55d6-588a-a52a-c57881bd3621","sourceKey":"bank:BUA201:PQ-135-b","payload":{"prompt":"Which of the following is an assumption of McGregor's Theory Y?","options":["People inherently dislike work","People avoid responsibility and prefer to be directed","People can exercise self-direction and self-control when committed to objectives","People must be threatened with punishment to perform"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Theory Y assumes work can be as natural as play, and that people who are committed to goals will direct themselves, accept responsibility and use their creativity. Options A, B and D are Theory X assumptions, which lead to close supervision and control."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 15, $official_bank_source${"itemId":"b558a316-8d00-5b49-89da-3936cac310c2","questionId":"394c4ea0-c599-5ef9-9caa-4c61a5ca94d4","sourceKey":"bank:BUA201:PQ-136-a","payload":{"prompt":"A firm that wants to apply Theory Y principles to improve performance would MOST likely:","options":["Introduce stricter clock-in checks and close supervision","Involve employees in setting their own goals and give them responsibility for results","Make all decisions at the top and pass down orders","Rely mainly on penalties for poor performance"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Theory Y sees employees as willing to work and take responsibility, so managers apply it by involving staff in goal-setting, delegating authority and letting them own their results. Options A, C and D reflect Theory X, which assumes people must be watched, directed and pushed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 16, $official_bank_source${"itemId":"14816daf-f147-56ed-833c-aabb0bebe08a","questionId":"8aeabf80-97a1-5acd-b40a-d6f81073466a","sourceKey":"bank:BUA201:PQ-137-a","payload":{"prompt":"Which of the following is a characteristic of business?","options":["It is a one-off exchange made for pleasure","It is carried on regularly with the aim of making a profit, under risk and uncertainty","It guarantees a profit to the owner","It involves only the production of goods, not services"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Business involves the regular production or exchange of goods and services for value, with profit as the main motive, and because the future is uncertain the owner always bears some risk. Option A is wrong because business must be continuous and aimed at gain. Option C ignores risk, and option D ignores the fact that banks, transport firms and other service providers are businesses too."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 17, $official_bank_source${"itemId":"c1b30ddf-730f-5969-9821-16e8687aadda","questionId":"453b4e9f-a9a7-503c-9b14-5115813d77ea","sourceKey":"bank:BUA201:PQ-137-b","payload":{"prompt":"Which of the following activities is a business activity?","options":["A mother cooking dinner for her family","A student giving a classmate a book as a birthday gift","A person selling an old personal phone once to buy a new one","A trader regularly buying rice in bulk and reselling it at a profit"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"A business activity involves the regular exchange of goods or services with the aim of making a profit, which is exactly what the rice trader does. Options A and B involve no exchange for gain, and option C is a one-off personal sale rather than a regular trading activity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 18, $official_bank_source${"itemId":"36472053-f15d-5efa-b143-a39eed9867a4","questionId":"6375d341-9ace-54a0-bf24-5a78e049392f","sourceKey":"bank:BUA201:PQ-138-a","payload":{"prompt":"The main problem of the barter system, which the use of money helped to solve, was the:","options":["Lack of any goods to exchange","Need for a double coincidence of wants","High rate of company taxation","Separation of ownership from control"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Under barter, a trade only happens when each person wants exactly what the other has, which is the double coincidence of wants; money removes this problem by acting as a generally accepted medium of exchange. Option A is wrong because goods existed, and options C and D belong to much later, modern business."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 19, $official_bank_source${"itemId":"f226f419-5a22-51a4-a114-ec726852928d","questionId":"e516057b-69c9-5154-89a1-ecff239dec84","sourceKey":"bank:BUA201:INT-001","payload":{"prompt":"Any organised activity that provides goods or services to customers on a regular basis with the aim of earning a profit is best described as:","options":["A business","A charity","A trade union","A government ministry"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"A business is an organised, continuing activity that supplies goods or services to customers in the hope of earning a profit. Options B and C exist mainly to serve a cause or their members rather than to make profit for owners, and option D is an arm of government that delivers public services rather than a profit-seeking venture."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 20, $official_bank_source${"itemId":"148a9e87-b51c-5f23-a79e-052f851e17de","questionId":"62c628f3-e7e4-5342-a7b3-793e9b4bbe23","sourceKey":"bank:BUA201:INT-002","payload":{"prompt":"In business, profit is best defined as:","options":["The money owners invest when starting the business","The amount a business owes its suppliers","The total amount of money received from selling goods","The amount by which total revenue exceeds total expenses"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Profit is what is left after all expenses are taken out of revenue, so it is revenue minus expenses. Option C describes revenue or sales, which ignores costs, option A describes capital, and option B describes trade payables, which is a liability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 21, $official_bank_source${"itemId":"ea805cc4-35ad-506e-91f7-116752dd2065","questionId":"575805f4-a77c-5054-8beb-75e3205599d6","sourceKey":"bank:BUA201:INT-003","payload":{"prompt":"Which of the following is NOT a factor of production?","options":["Entrepreneurship","Land","Labour","Profit"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The factors of production are land, labour, capital and entrepreneurship, the inputs a business combines to produce goods and services. Profit is not an input; it is the reward earned by the entrepreneur. Options B, C and A are all genuine factors of production."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 22, $official_bank_source${"itemId":"f735db9c-a7b4-54cc-ba96-dac940345de2","questionId":"f7ceb901-c588-573a-ae44-53a191b0d1ef","sourceKey":"bank:BUA201:INT-004","payload":{"prompt":"The reward paid to the factor of production 'labour' is called:","options":["Interest","Rent","Wages","Profit"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Labour is human effort, physical or mental, and it is rewarded with wages or salaries. Option B is the reward for land, option A is the reward for capital, and option D is the reward for entrepreneurship."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 23, $official_bank_source${"itemId":"a04b45f2-6aaa-5f97-a9a7-6ab4bdbb2cfd","questionId":"97cc9c35-f5ce-53b8-9395-44e22a71d1d3","sourceKey":"bank:BUA201:INT-005","payload":{"prompt":"Chidi uses his savings, rents a shop in Yaba, hires two bakers and buys ovens to start a bread business, knowing he could lose his money if customers do not buy. In doing this, Chidi is acting mainly as:","options":["A shareholder of a public company","An entrepreneur","A supervisor","A consumer"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"An entrepreneur organises the other factors of production and bears the risk of loss in the hope of profit, which is exactly what Chidi does. Option C is someone who oversees other workers for an employer, option A merely buys shares in an existing company, and option D buys goods for personal use."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 24, $official_bank_source${"itemId":"90d0d355-4d3f-57a6-9b0d-83c41c825e2a","questionId":"3dd5f936-addb-513d-86a5-6ae62d811069","sourceKey":"bank:BUA201:INT-006","payload":{"prompt":"A stakeholder of a business is best defined as:","options":["Any individual or group that can affect or is affected by the business's activities","Only a person who owns shares in the business","Only a customer who buys from the business regularly","Only a person who sits on the board of directors"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Stakeholders include anyone with an interest in the business, such as owners, employees, customers, suppliers, lenders, government and the host community. Options B, D and C each name only one narrow group and wrongly treat it as the whole idea; shareholders are just one type of stakeholder."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 25, $official_bank_source${"itemId":"3c07266c-378a-5292-977a-9306faad1117","questionId":"2feb3c22-d766-5cee-b9a9-1e79c817f023","sourceKey":"bank:BUA201:INT-007","payload":{"prompt":"Which of the following is an INTERNAL stakeholder of a business?","options":["Its employees","The tax authority","Its customers","Its suppliers"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Internal stakeholders are people inside the organisation, such as employees, managers and owners. Options D, C and B are outside the organisation, so they are external stakeholders even though they are strongly affected by it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 26, $official_bank_source${"itemId":"41466f65-d2f6-5122-ba72-0203e5a9ba9b","questionId":"0dc3cd22-3e3b-51be-b9b2-b6cbab3ea64b","sourceKey":"bank:BUA201:INT-008","payload":{"prompt":"A firm in Ogun State turns limestone and other inputs into bags of cement for sale. This firm operates mainly in the:","options":["Public sector","Primary sector","Secondary sector","Tertiary sector"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"The secondary sector covers manufacturing and processing, where raw inputs are converted into finished or semi-finished goods, as in cement production. Option B is extraction of natural resources such as quarrying or farming, option D covers services, and option A refers to government ownership rather than a stage of production."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 27, $official_bank_source${"itemId":"a7b4149a-e780-50d5-a76f-b02eb062c5e1","questionId":"4580d95d-ce1d-51fa-b09c-27b3304ea208","sourceKey":"bank:BUA201:INT-009","payload":{"prompt":"Which of the following businesses belongs to the TERTIARY sector of the economy?","options":["A textile factory","A commercial bank","A cocoa farm","A tin mine"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"The tertiary sector provides services rather than physical goods, and banking is a service. Options C and D extract natural resources, so they are primary, while option A manufactures goods, so it is secondary."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 28, $official_bank_source${"itemId":"ee3e02d1-cb04-5a54-b050-f32804ab251e","questionId":"e067f39b-3bff-5e5d-87e1-beca978a2296","sourceKey":"bank:BUA201:INT-010","payload":{"prompt":"Which of the following is NOT generally regarded as a purpose of business in society?","options":["Contributing to government revenue through taxes","Making the laws that govern the country","Creating jobs and incomes","Providing goods and services that people need"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Businesses serve society by supplying goods and services, employing people and paying taxes, but law-making is the work of the legislature. Options D, C and A are all genuine ways businesses contribute to society."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 29, $official_bank_source${"itemId":"7022e30f-44d2-50ab-95be-154b759222c5","questionId":"a1e80839-8359-5bb4-b4c8-de47b6054cfe","sourceKey":"bank:BUA201:INT-011","payload":{"prompt":"Which of the following is NOT a characteristic of business?","options":["Exchange of goods or services for value","Guaranteed returns with no risk of loss","The motive of earning profit","Regularity of dealings"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Every business faces risk and uncertainty, because profit is never guaranteed; that is why the entrepreneur is rewarded for bearing risk. Options A, D and C are standard characteristics of business."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 30, $official_bank_source${"itemId":"8b7a0034-a47c-57d9-88db-fd4cda3ab804","questionId":"aa522d46-2be2-5d8a-8c0f-797b86dff155","sourceKey":"bank:BUA201:INT-012","payload":{"prompt":"Aisha sells her own used laptop once to a friend for N150,000 and makes a gain. This single sale is NOT normally regarded as 'business' mainly because it lacks:","options":["A buyer and a seller","An exchange of value","A price agreed in money","Regularity of dealings"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Business involves dealings carried on regularly or continuously, so a one-off sale of a personal item is not treated as business even if it produces a gain. The sale does involve an exchange, a buyer and a seller and an agreed price, so options B, A and C are present and cannot be the missing feature."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 31, $official_bank_source${"itemId":"0928292a-b861-5129-b7b2-9e96360fbb42","questionId":"40e2675a-ebd5-55c0-9ae8-7952732c6f48","sourceKey":"bank:BUA201:INT-013","payload":{"prompt":"Which of the following is an 'aid to trade' within commerce?","options":["Insurance","Manufacturing","Farming","Mining"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Commerce is made up of trade and the aids to trade, such as banking, insurance, transport, warehousing and advertising, which remove obstacles to exchange. Insurance removes the hindrance of risk. Options D, C and B are production activities in industry, not aids to trade."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 32, $official_bank_source${"itemId":"3225606f-38a8-530d-9019-33d2f755b24e","questionId":"f87d56f3-8f3b-58fe-b232-efd0c0319a0f","sourceKey":"bank:BUA201:INT-015","payload":{"prompt":"A non-profit organisation differs from a business mainly because it:","options":["Uses any surplus to pursue its mission instead of distributing it to owners","Cannot employ paid staff","Does not need any management","Is never allowed to earn more income than it spends"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"A non-profit organisation may earn a surplus, but the surplus is reinvested in its social, religious or charitable mission rather than shared among owners. Option D is wrong because a surplus is allowed, option B is wrong because many non-profits employ paid staff, and option C is wrong because every organisation needs management."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 33, $official_bank_source${"itemId":"30381e54-330b-5d57-9ca5-ceb3547a80b6","questionId":"102e8d86-b1eb-5279-a1ac-f959ea705f6e","sourceKey":"bank:BUA201:INT-016","payload":{"prompt":"Management is often described as the art of:","options":["Owning the capital of a business","Avoiding decisions until problems disappear","Getting things done through people","Doing every task personally"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"This classic description stresses that managers achieve goals by working with and through other people rather than doing all the work themselves. Option D describes an operative worker, option B is the opposite of management, and option A describes ownership, which is different from managing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 34, $official_bank_source${"itemId":"04a2d808-63fd-5de7-88a2-4807f277edf1","questionId":"be42022a-fcc0-583c-84e6-57916f349fb8","sourceKey":"bank:BUA201:INT-017","payload":{"prompt":"Using the fewest possible resources (time, money, labour) to achieve a given output is called:","options":["Effectiveness","Esprit de corps","Equity","Efficiency"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Efficiency means doing things right, that is, getting the most output from the least input. Option A means doing the right things, that is, achieving the goals the organisation set. Options C and B are principles of fair treatment and team spirit, not measures of resource use."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 35, $official_bank_source${"itemId":"ae96433c-973f-5f42-99ad-5f64c5dfaae3","questionId":"b32d14d9-66f4-50e5-894b-5e45bf237a17","sourceKey":"bank:BUA201:INT-018","payload":{"prompt":"In management, 'effectiveness' means:","options":["Treating every employee exactly the same","Keeping staff in the same job for a long time","Achieving the goals the organisation set out to achieve (doing the right things)","Minimising the cost of every activity (doing things right)"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Effectiveness is about goal attainment, that is, doing the right things. Option D describes efficiency, which is about resource use rather than goal achievement. Options A and B describe the principles of equity and stability of tenure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 36, $official_bank_source${"itemId":"74416980-6f86-5d34-aa34-e1b62d40d37a","questionId":"63a9da04-61b6-5c64-9e09-31138d19b436","sourceKey":"bank:BUA201:INT-019","payload":{"prompt":"A Lagos factory produces plastic chairs at the lowest cost per unit in its industry, but customers no longer want that design and most chairs remain unsold. The factory is best described as:","options":["Neither efficient nor effective","Both efficient and effective","Effective but not efficient","Efficient but not effective"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Low cost per unit shows the factory uses its inputs well, so it is efficient, but it is not achieving the goal of selling products customers want, so it is not effective. Option C reverses the two ideas, option B ignores the unsold stock, and option A ignores the low production cost."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 37, $official_bank_source${"itemId":"940346d9-d52e-5fbc-8361-4708a2ff22c2","questionId":"ddcf61b7-be53-5aab-a41b-5fc4e8481ebf","sourceKey":"bank:BUA201:INT-020","payload":{"prompt":"Which statement best explains why management is regarded as both an art and a science?","options":["It can be learnt only from experience and has no principles","It is practised only by artists and scientists","Its principles give exactly the same result in every situation","It rests on a body of organised principles, but applying them well requires personal skill and judgement"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Management is a science because it has a systematic body of knowledge and principles, and an art because using those principles successfully depends on creativity, experience and judgement. Option A denies the science side, option C overstates it, since management principles are flexible rather than exact laws, and option B is a misreading of the terms."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 38, $official_bank_source${"itemId":"ba569106-d282-58a5-af80-052ea44149d8","questionId":"137d23c2-0802-5534-ad89-3d8fe51078b7","sourceKey":"bank:BUA201:INT-021","payload":{"prompt":"Which of the following is NOT part of the classical approach to management?","options":["Scientific management","Bureaucratic management","Administrative management","The human relations movement"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The classical approach includes scientific management, administrative management and bureaucracy, all of which focus on structure, efficiency and formal rules. The human relations movement came later as a reaction to the classical view and focused on social and psychological needs of workers. Options A, C and B are all classical schools."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 39, $official_bank_source${"itemId":"1b26ff5e-7643-5882-9f8f-5728bd7eb701","questionId":"6cb10fd6-0afd-5d50-959b-2cd958567339","sourceKey":"bank:BUA201:INT-023","payload":{"prompt":"The main purpose of time and motion study in scientific management was to:","options":["Design the organisation chart of the whole company","Find the one best way of doing a job and set a standard time for it","Decide how much tax a firm should pay","Measure how happy workers feel about their jobs"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Time and motion study broke a job into its movements, timed them and removed wasteful motions so a standard 'one best way' and standard time could be set. Option D reflects the later human relations interest in worker attitudes, while options C and A have nothing to do with job study."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 40, $official_bank_source${"itemId":"13d8825e-304c-550b-810f-f433873f44f2","questionId":"b04a46d3-69d3-548a-a8a0-7d9592c4d6f3","sourceKey":"bank:BUA201:INT-024","payload":{"prompt":"Under Taylor's differential piece-rate system, a worker who produces MORE than the set standard output is:","options":["Paid at a higher rate per unit","Paid at a lower rate per unit","Transferred to a different department","Paid a fixed salary regardless of output"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"The differential piece-rate system paid a higher rate per piece to workers who met or beat the standard and a lower rate to those who fell short, to reward productivity. Option D removes the link between output and pay, option B reverses the scheme, and option C is not part of it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 41, $official_bank_source${"itemId":"50299aa0-0a13-556b-889d-ac1a8e380c03","questionId":"b4a95ddc-ead7-5f97-80ab-e34e9a516900","sourceKey":"bank:BUA201:INT-025","payload":{"prompt":"A bar chart that shows planned and actual progress of tasks against time, used for scheduling work, is known as a:","options":["Break-even chart","Pie chart","Organisation chart","Gantt chart"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The Gantt chart, developed by Henry Gantt during the scientific management era, shows tasks as bars along a time scale so managers can schedule and monitor work. Option C shows reporting relationships, option B shows proportions of a whole, and option A shows the relationship between costs, revenue and output."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 42, $official_bank_source${"itemId":"85ffa345-1652-5659-8b7d-259a86934234","questionId":"56afacb7-97db-53fe-8e7e-fbc33af89c0d","sourceKey":"bank:BUA201:INT-026","payload":{"prompt":"Which of the following is NOT one of Henri Fayol's five elements (functions) of management?","options":["Coordinating","Staffing","Commanding","Planning"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Fayol listed planning, organising, commanding, coordinating and controlling as the elements of management. Staffing was added by later writers, so it is not one of Fayol's five. Options D, C and A are all on Fayol's list."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 43, $official_bank_source${"itemId":"651a2c43-3daa-5251-bdc2-af91d3f7df03","questionId":"fcc92310-dfff-508e-adc0-63123aa313d3","sourceKey":"bank:BUA201:INT-027","payload":{"prompt":"Fayol's principle of 'unity of command' states that:","options":["Employees should be treated with kindness and justice","Each employee should receive orders from only one superior","Each group of activities with the same objective should have one plan and one head","Authority should flow in an unbroken line from top to bottom"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Unity of command means a subordinate should report to and take orders from one boss only, to avoid confusion. Option C is unity of direction, option D is the scalar chain, and option A is equity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 44, $official_bank_source${"itemId":"4e1a375d-1485-5e17-ad7a-d156d99ba8e8","questionId":"f7fe81ab-0076-5dbc-a616-b8c07a5c1e42","sourceKey":"bank:BUA201:INT-028","payload":{"prompt":"Fayol's principle of 'unity of direction' differs from 'unity of command' because unity of direction requires:","options":["One head and one plan for a group of activities having the same objective","Workers to stay in the same job permanently","All decisions to be taken by the owner alone","Each worker to report to only one supervisor"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Unity of direction is about the organisation of activities: activities that share one objective should be under one plan and one manager. Option D is unity of command, which is about individual reporting lines. Options C and B describe extreme centralisation and stability of tenure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 45, $official_bank_source${"itemId":"9d4ad122-1737-52df-b0c9-e0de6383dec5","questionId":"c8b8b08b-5b9b-5ffb-b911-6c43f2867ec7","sourceKey":"bank:BUA201:INT-029","payload":{"prompt":"Bola, a sales officer in a Lagos firm, receives an instruction from the sales manager to visit Ikeja and a conflicting instruction from the finance manager to stay in the office. This situation violates Fayol's principle of:","options":["Initiative","Remuneration","Unity of command","Division of work"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Bola is receiving orders from two superiors at once, which is what unity of command is meant to prevent. Option D is about specialisation of tasks, option B is about fair pay, and option A is about allowing employees to think out and carry out plans."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 46, $official_bank_source${"itemId":"1855c5c9-c8c6-5d9b-bf14-7d71fcdcd70c","questionId":"2a661167-264d-55ed-af9a-eac190cf0736","sourceKey":"bank:BUA201:INT-030","payload":{"prompt":"The line of authority running from the highest to the lowest rank in an organisation, through which communication normally passes, is Fayol's:","options":["Order","Esprit de corps","Scalar chain","Centralisation"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"The scalar chain is the chain of superiors from top to bottom, and Fayol allowed a 'gang plank' for direct communication between people at the same level when delay would be harmful. Option B is team spirit, option A is having a right place for every person and thing, and option D concerns how far decision-making is concentrated at the top."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 47, $official_bank_source${"itemId":"2fae9f31-f405-5f9f-a350-0196577a2b1f","questionId":"be05e3d3-f71c-5326-aa04-45a96f6c95a4","sourceKey":"bank:BUA201:INT-031","payload":{"prompt":"Fayol's principle that stresses building harmony and team spirit among staff is called:","options":["Stability of tenure","Esprit de corps","Equity","Discipline"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Esprit de corps means 'union is strength': managers should promote team spirit and unity. Option C is fair and kind treatment of employees, option D is obedience and respect for agreements, and option A is keeping staff turnover low so people can master their jobs."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 48, $official_bank_source${"itemId":"4b78b5a2-eb1d-5852-a18d-3260d42ba7f5","questionId":"87b27fb8-e1ce-56b2-9f13-e9d0f90182b0","sourceKey":"bank:BUA201:INT-032","payload":{"prompt":"'A place for everything and everything in its place', applied to both people and things, describes Fayol's principle of:","options":["Remuneration","Order","Initiative","Scalar chain"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"The principle of order says every person and every item should have a proper, assigned place in the organisation. Option D is the line of authority, option C is freedom to think out and carry out plans, and option A is fair payment for work."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 49, $official_bank_source${"itemId":"f0c88e35-649d-58dd-a0c9-d7afb4b46860","questionId":"de5f9161-62cf-5651-96cc-86d73f46f669","sourceKey":"bank:BUA201:INT-033","payload":{"prompt":"A branch manager refuses a staff member's request to divert company vehicles for a private family event because the firm's goals must come first. This reflects Fayol's principle of:","options":["Centralisation","Division of work","Subordination of individual interest to the general interest","Unity of direction"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"This principle says the interests of one person or group should not take priority over the interests of the organisation as a whole. Option B is about specialisation, option D is about one plan and one head for related activities, and option A is about where decision-making authority lies."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 50, $official_bank_source${"itemId":"ac8d94ae-3a62-51e5-982d-8f0e0ab41934","questionId":"aaddfcdc-723f-53d6-9e23-f23a3cc84029","sourceKey":"bank:BUA201:INT-034","payload":{"prompt":"Which of the following is NOT a feature of Max Weber's ideal bureaucracy?","options":["Selection and promotion based on technical qualification","A clear hierarchy of authority","Formal written rules and procedures","Promotion based on personal loyalty to the boss"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Weber's bureaucracy relies on hierarchy, written rules, impersonality and appointment and promotion on merit and competence. Promotion based on personal loyalty contradicts the impersonal, merit-based nature of bureaucracy. Options B, C and A are genuine features."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 51, $official_bank_source${"itemId":"2ba9d123-048d-5593-ac09-f0abdc5b1d09","questionId":"fc8353e9-634d-5255-a200-943c1a2ef2fc","sourceKey":"bank:BUA201:INT-035","payload":{"prompt":"In Weber's ideal bureaucracy, the legitimate basis of authority is:","options":["Rational-legal authority, based on rules and the position held","Traditional authority, based on custom and inheritance","Charismatic authority, based on the personal appeal of the leader","Coercive authority, based on force and fear"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Weber argued that bureaucracy rests on rational-legal authority, where people obey the rules and the office rather than the person. Options C and B are Weber's other two types of authority, which he saw as less suited to large modern organisations, and option D is not one of his three types."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 52, $official_bank_source${"itemId":"f62b6922-a4db-5f1d-92ad-624ae7523ed8","questionId":"7c1979c3-ed3b-5727-a579-82b82017d7b5","sourceKey":"bank:BUA201:INT-036","payload":{"prompt":"The 'Hawthorne effect' refers to the tendency of workers to:","options":["Change their behaviour or productivity because they know they are being observed and given attention","Resist every form of supervision","Produce less when lighting is improved","Work harder only when their pay is increased"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"The Hawthorne studies at Western Electric found that productivity rose under many changed conditions because workers responded to the attention and interest shown in them. Option D reflects the purely economic view the studies challenged, option B is not what was found, and option C contradicts the finding that output rose even when lighting changed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 53, $official_bank_source${"itemId":"9627d596-9ff9-5d0a-a066-243745308cbb","questionId":"73955918-62bf-5f1b-be46-f674951c443b","sourceKey":"bank:BUA201:INT-037","payload":{"prompt":"The human relations approach to management placed its main emphasis on:","options":["Using mathematical models to make decisions","Finding the one best way to perform each task","Social needs of workers and the influence of informal groups on productivity","Strict rules and an impersonal hierarchy"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"The human relations approach, which grew out of the Hawthorne studies, stressed that workers are social beings whose attitudes, group norms and feelings affect output. Option B is scientific management, option A is the quantitative approach, and option D is bureaucracy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 54, $official_bank_source${"itemId":"e3b3252e-481a-5666-a2fc-6f41af9569ae","questionId":"cd56684f-890e-5ebf-a4ab-0115268fa5f0","sourceKey":"bank:BUA201:INT-038","payload":{"prompt":"In Maslow's hierarchy of needs, which need is at the TOP of the hierarchy?","options":["Safety","Esteem","Physiological","Self-actualisation"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Maslow's order from bottom to top is physiological, safety, social (belonging), esteem and self-actualisation, so self-actualisation, the need to reach one's full potential, is at the top. Option B is just below the top, while options A and C are lower-order needs."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 55, $official_bank_source${"itemId":"2c72f414-9ea2-5c83-8089-581b739a41b7","questionId":"02d721eb-566e-501a-8685-1d4d2fda75fb","sourceKey":"bank:BUA201:INT-040","payload":{"prompt":"The approach to management that uses mathematical and statistical tools such as linear programming and operations research to improve decision-making is the:","options":["Quantitative (management science) approach","Human relations approach","Administrative approach","Bureaucratic approach"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"The quantitative or management science approach applies mathematics, statistics and models to management problems such as scheduling and inventory. Option B focuses on people and social needs, option C on principles and functions of management, and option D on rules and hierarchy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 56, $official_bank_source${"itemId":"2c745ac9-b53b-5d4a-b055-5982ece3d91f","questionId":"5c437b26-af29-5974-8528-429825d06fb3","sourceKey":"bank:BUA201:INT-041","payload":{"prompt":"In the systems approach, 'synergy' means that:","options":["A system will always run down without new inputs","The parts of an organisation working together achieve more than they would working separately","An organisation has no interaction with its environment","Each department should work independently of the others"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"Synergy is the idea that the whole is greater than the sum of its parts when departments cooperate. Option D contradicts the systems emphasis on interdependence, option C describes a closed system, and option A describes entropy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 57, $official_bank_source${"itemId":"7db121c0-ca61-5b54-ac8d-f2b0b1bc4044","questionId":"52a1b969-82d5-59d4-99bd-cb65f32289fe","sourceKey":"bank:BUA201:INT-042","payload":{"prompt":"The contingency (situational) approach to management holds that:","options":["There is one best way to manage in all situations","Management is purely a matter of mathematics","Only workers' social needs matter","The best management practice depends on the particular situation"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"The contingency approach says there is no universal best way; the right structure or style depends on factors such as size, technology and environment. Option A is the classical belief the contingency approach rejects, option C overstates human relations, and option B overstates the quantitative approach."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 58, $official_bank_source${"itemId":"2de574c5-0194-50b0-b9e6-4eb11e08622a","questionId":"92d796fa-b654-5cea-9f2e-de5251bb9c89","sourceKey":"bank:BUA201:INT-043","payload":{"prompt":"Which sequence shows the correct historical order in which these schools of management thought emerged?","options":["Contingency approach, scientific management, human relations","Scientific management, contingency approach, human relations","Scientific management, human relations, contingency approach","Human relations, scientific management, contingency approach"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Scientific management emerged around the early 1900s, the human relations movement grew from the Hawthorne studies of the 1920s and 1930s, and the contingency approach developed from the 1960s. Options D, A and B each place at least one school out of its historical order."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 59, $official_bank_source${"itemId":"4c79cb8a-e935-5b32-9588-938e44c37fda","questionId":"2d0d464c-a137-5345-b5f8-aebc4b4abdf2","sourceKey":"bank:BUA201:INT-044","payload":{"prompt":"Managers combine four broad kinds of organisational resources: human, financial, physical and information resources. Which of the following is an INFORMATION resource?","options":["A bank loan of N5,000,000","A fleet of delivery vans","The firm's sales staff","Market research data on customer preferences"],"correctOption":3,"section":"Introduction to Business and Management","explanation":"Information resources are usable data such as market research, sales records and forecasts. Option B is a physical resource, option A is a financial resource, and option C is a human resource."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 60, $official_bank_source${"itemId":"2a9be4fe-06c5-55d6-9b8e-58bf11059e18","questionId":"ff0d4d55-832a-53b1-af1f-215ce743a0c5","sourceKey":"bank:BUA201:INT-045","payload":{"prompt":"Which of the following is NOT one of the resources managers combine to achieve organisational goals?","options":["Financial resources","Human resources","Customer satisfaction","Physical resources"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"Human, financial, physical and information resources are the inputs managers work with. Customer satisfaction is an outcome the business hopes to achieve by using those inputs well, not an input itself. Options B, A and D are genuine resource categories."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 61, $official_bank_source${"itemId":"413b02c9-18e8-5c1e-b499-d18f361a9250","questionId":"22401fd3-08cc-5108-9933-ec24668a02cc","sourceKey":"bank:BUA201:INT-046","payload":{"prompt":"Chester Barnard's 'acceptance theory of authority' states that a manager's authority depends mainly on:","options":["Whether subordinates accept the manager's orders","The manager's share ownership in the firm","The number of years the manager has spent in the firm","The size of the manager's salary"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Barnard argued that authority is real only if subordinates accept it, so orders must be understood, consistent with goals and within people's ability. Options D, C and B are personal attributes that do not by themselves make subordinates obey."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 62, $official_bank_source${"itemId":"d90ff5df-46f5-5ac9-9a5f-02797afd156c","questionId":"2bd54e18-dace-5536-9826-e88b9455a13d","sourceKey":"bank:BUA201:INT-047","payload":{"prompt":"Management by objectives (MBO), associated with Peter Drucker, is best described as:","options":["A system in which top management sets all targets without consulting staff","A method of paying workers per unit produced","A system in which managers and subordinates jointly set specific goals and later review performance against them","A mathematical technique for allocating scarce resources"],"correctOption":2,"section":"Introduction to Business and Management","explanation":"MBO involves joint goal-setting between superior and subordinate, periodic review of progress and appraisal against the agreed objectives. Option A lacks the participative element that defines MBO, option B is piece-rate pay, and option D describes linear programming."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 63, $official_bank_source${"itemId":"3b112e41-b1a0-5401-8c64-5087c10d55f5","questionId":"d9e7acf7-04bd-57f2-9787-ef3bb35c484c","sourceKey":"bank:BUA201:INT-048","payload":{"prompt":"A manager at a Kano textile mill splits the production process into spinning, weaving and dyeing, with workers specialising in one stage each. This applies Fayol's principle of:","options":["Division of work","Equity","Scalar chain","Unity of command"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Division of work means specialisation, so that each worker becomes more skilled and productive at a narrower task. Option D concerns having one boss, option C the line of authority, and option B fair treatment of staff."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 64, $official_bank_source${"itemId":"667fea05-7124-561d-8a64-59e80a4c5036","questionId":"ed1d2193-18d5-53ba-b764-449fbee7ded8","sourceKey":"bank:BUA201:INT-049","payload":{"prompt":"An organisation is best defined as:","options":["A government licence to trade","A group of people working together in a structured way to achieve common goals","Any building where goods are stored","A collection of individuals with no shared purpose"],"correctOption":1,"section":"Introduction to Business and Management","explanation":"An organisation is a deliberate arrangement of people with a common purpose, a structure and a division of tasks. Option C describes a warehouse, option D lacks the shared goal that defines an organisation, and option A is a legal permit."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 65, $official_bank_source${"itemId":"16019d4f-8d42-5042-b9da-9dc49a4289f7","questionId":"415f1195-bab6-5283-a4c1-3762b9b9d32e","sourceKey":"bank:BUA201:INT-050","payload":{"prompt":"A Lagos supermarket allows its cashiers to suggest and test new ways of reducing queues at the till. This applies Fayol's principle of:","options":["Initiative","Order","Centralisation","Discipline"],"correctOption":0,"section":"Introduction to Business and Management","explanation":"Initiative means encouraging employees to think out and carry out plans, which raises morale and improvement. Option C concentrates decision-making at the top, option D is obedience and respect for rules, and option B is having a right place for people and things."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 66, $official_bank_source${"itemId":"794d4f08-93d7-5d77-a568-5f3fef94720d","questionId":"b827c406-ff40-51ec-ba30-d35a8005ef53","sourceKey":"bank:BUA201:PQ-004","payload":{"prompt":"A manager who builds and maintains a network of contacts with external regulators and with managers in other organisations, in order to gain information and goodwill for the unit, is performing which Mintzberg role?","options":["Liaison","Resource allocator","Entrepreneur","Disseminator"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"In Mintzberg's framework, the liaison role is an interpersonal role in which the manager develops and maintains contacts outside his or her own unit. Option D is about passing information to people inside the organisation, while options C and B are decisional roles about starting change and deciding who gets what resources."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 67, $official_bank_source${"itemId":"60613dfb-317d-56c9-8960-28df97c20073","questionId":"df97a90c-2b77-566e-96b4-8a354fa34014","sourceKey":"bank:BUA201:PQ-005","payload":{"prompt":"Conceptual skills are most critical when a manager is:","options":["Managing production lines","Supervising routine tasks","Formulating corporate strategy","Conducting performance appraisals"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Conceptual skill is the ability to see the organisation as a whole and think through complex, abstract situations, which is exactly what strategy formulation demands, mostly at top management level. Options B and A lean more on technical skills, and option D relies heavily on human (interpersonal) skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 68, $official_bank_source${"itemId":"d579eca4-271f-5161-aef9-7b39cf69c238","questionId":"f02bf473-6a8d-5206-b197-24351343fe01","sourceKey":"bank:BUA201:PQ-036","payload":{"prompt":"Which of the following is one of Mintzberg's decisional roles?","options":["Liaison","Spokesperson","Entrepreneur","Monitor"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Mintzberg's decisional roles are entrepreneur, disturbance handler, resource allocator and negotiator. Options D and B are informational roles, while option A is an interpersonal role."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 69, $official_bank_source${"itemId":"a70b3971-816a-5f44-bba7-45de8abfe755","questionId":"f1ffbc30-ebaf-5465-9672-ddafcf706ae1","sourceKey":"bank:BUA201:PQ-046","payload":{"prompt":"The organising function of management involves:","options":["Motivating employees","Setting objectives","Allocating tasks, resources and authority","Controlling the budget"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Organising means arranging work, grouping tasks into jobs and departments, and deciding who reports to whom. Option B belongs to planning, option A to leading, and option D to controlling."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 70, $official_bank_source${"itemId":"7a12e1fb-a7bc-57df-8e01-fd1b883c3349","questionId":"5d834a4b-fe0f-5002-b21b-d414706a89ba","sourceKey":"bank:BUA201:PQ-049","payload":{"prompt":"A mission statement defines an organisation's:","options":["Tactical goals","Departmental duties","Fundamental, long-term purpose","Short-term budget"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"A mission statement explains why the organisation exists, what it does and whom it serves, guiding all later planning. Options A, D and B are more detailed, short-range plans that flow from the mission."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 71, $official_bank_source${"itemId":"300f95d1-05e4-5456-9168-75c2ca44d80e","questionId":"fd577a88-0a38-50a9-8290-6153c20e1ee9","sourceKey":"bank:BUA201:PQ-052","payload":{"prompt":"A company with a decentralised structure promotes:","options":["Limited accountability","Bureaucratic delay","Faster decision-making at lower levels","Concentration of authority at the top"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Decentralisation pushes decision-making authority down to lower-level managers who are closer to the problems, so decisions are made more quickly. Option D describes centralisation, and option B is a typical drawback of highly centralised structures."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 72, $official_bank_source${"itemId":"b155b786-76d6-5840-819b-92f00ebeaa93","questionId":"092b6537-b38d-5eb4-acef-06faf0f94599","sourceKey":"bank:BUA201:PQ-061","payload":{"prompt":"Strategic control differs from operational control because it focuses on:","options":["Routine supervision","The organisation's long-term direction","Payroll processing","Daily tasks"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Strategic control checks whether the organisation's overall strategy is still working and on course over the long term. Options D and A are the concerns of operational control, which deals with day-to-day activities."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 73, $official_bank_source${"itemId":"58f65aec-57c9-5449-b2b4-ea7619dfce1c","questionId":"e48a1653-753f-5d76-90ff-34a8c440f2a8","sourceKey":"bank:BUA201:PQ-088","payload":{"prompt":"A highly centralised structure limits:","options":["Top management authority","Employee empowerment","Governance control","Budget planning"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"In a centralised structure most decisions are made at the top, so lower-level staff have little room to take decisions on their own, which limits empowerment. Option A is the opposite, because centralisation concentrates authority in top management. Options C and D can still be carried out, often more tightly, under centralisation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 74, $official_bank_source${"itemId":"7990ae9b-5acf-5b41-b729-97fc7e4d3b2b","questionId":"8e806299-0777-5fec-90c1-cfbd3b00e07d","sourceKey":"bank:BUA201:PQ-089","payload":{"prompt":"Corporate-level strategy differs from business-level strategy because it focuses on:","options":["Day-to-day functional tasks","Production scheduling","Portfolio decisions about which businesses or industries the firm should be in","Staff performance appraisal"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Corporate-level strategy is set by top management for the whole organisation and answers the question of which businesses or industries to compete in, including expansion, acquisition and exit. Business-level strategy then decides how each unit competes in its own market. Options A, B and D are operational or functional matters handled lower down."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 75, $official_bank_source${"itemId":"204d2066-ed59-5be4-9c66-8d1238a3b989","questionId":"0c9f124f-92ef-5e16-bb91-e0657d23221c","sourceKey":"bank:BUA201:PQ-111","payload":{"prompt":"A manager who uses systems theory would MOST likely:","options":["Focus only on internal efficiency","Emphasise the interdependence of sub-systems","Ignore environmental forces","Apply universal principles rigidly"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Systems theory sees an organisation as a set of interrelated parts that interact with each other and with the outside environment, so a change in one part affects the others. Options A and C describe a closed-system view that systems theory rejects. Option D reflects the classical one-best-way thinking, not systems thinking."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 76, $official_bank_source${"itemId":"8a3dd6df-6b10-5614-9ee8-3b941f6141a9","questionId":"58fbf972-6e10-57a2-8c8e-8fb71f26f318","sourceKey":"bank:BUA201:PQ-121","payload":{"prompt":"Which management function ensures that deviations from plans are corrected?","options":["Controlling","Planning","Organising","Directing"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Controlling involves setting standards, measuring actual performance, comparing it with the plan and taking corrective action when there are deviations. Option B sets the goals in the first place, option C arranges resources and tasks, and option D guides and motivates people; none of these is the checking-and-correcting function."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 77, $official_bank_source${"itemId":"dc211fb1-c98b-5fb0-b99b-b3a07de3acdf","questionId":"23a5a9c1-56a5-54a6-bb94-1d127b2cbaf2","sourceKey":"bank:BUA201:PQ-122","payload":{"prompt":"Planning and controlling are closely related because:","options":["Control provides feedback for future plans","Both are performed at exactly the same time","Planning replaces the need for control","Control comes before planning"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Planning sets the targets that control measures against, and the results of control show where plans worked or failed, which feeds into the next round of planning. Option C is wrong because even good plans need checking, and option D reverses the order, since there is nothing to control until a plan exists. Option B misses the point that one feeds the other."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 78, $official_bank_source${"itemId":"923cc648-c8b5-57c3-9164-edd6d87b9ab9","questionId":"4d7144eb-aa71-5fe6-bd6d-585aea41afa9","sourceKey":"bank:BUA201:UNI-001","payload":{"prompt":"The management function that involves setting goals and deciding in advance what to do, how and when to do it, is:","options":["Planning","Controlling","Leading","Organising"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Planning means defining goals and choosing the courses of action to reach them, so it decides in advance what is to be done. Option D arranges people and resources to carry out the plan, option C motivates and directs people, and option B checks performance against the plan."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 79, $official_bank_source${"itemId":"561b4810-5f79-5930-887e-c5189fa38c7d","questionId":"02e3853d-19c5-5567-9172-84a94b65bda9","sourceKey":"bank:BUA201:UNI-002","payload":{"prompt":"Which management function is usually described as the foundation of the others because it comes first and gives them direction?","options":["Planning","Leading","Organising","Controlling"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Planning is called the primary function because organising, leading and controlling all depend on the goals and plans it sets; there is nothing to organise or control without a plan. Options D, B and C are important but follow from the plan."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 80, $official_bank_source${"itemId":"041edb61-dbcb-5c3c-99bd-3c9ef72d0900","questionId":"f0ff6369-1093-5199-a43d-88d57c4879aa","sourceKey":"bank:BUA201:UNI-003","payload":{"prompt":"The MD of a Lagos logistics firm sets a target to open three new depots by December 2026 and decides which cities, budgets and timelines to use. She is performing the function of:","options":["Leading","Organising","Controlling","Planning"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Setting a target and deciding locations, budgets and timelines in advance is planning. Option B would come next when she assigns staff and resources to each depot, option A when she motivates and directs the teams, and option C when she checks progress against the target."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 81, $official_bank_source${"itemId":"8e1cd20d-e374-5437-ae01-b84b2c3f4ef5","questionId":"90685d8c-6963-5248-919f-9ff2bde7a6a7","sourceKey":"bank:BUA201:UNI-004","payload":{"prompt":"After a new strategy is approved, a manager creates departments, assigns tasks to job holders, sets reporting lines and allocates equipment to each unit. This is the management function of:","options":["Leading","Controlling","Organising","Planning"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Organising means arranging tasks, people and other resources into a structure so the plan can be carried out. Option D set the strategy already, option A involves motivating and influencing people, and option B involves measuring and correcting performance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 82, $official_bank_source${"itemId":"5432dccd-fbda-5869-89be-431732896199","questionId":"032decb0-08d2-597a-8b90-61bab4710939","sourceKey":"bank:BUA201:UNI-005","payload":{"prompt":"The management function concerned with motivating, communicating with and influencing employees to work towards organisational goals is:","options":["Planning","Controlling","Leading","Organising"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Leading (also called directing) is about guiding and inspiring people, communicating and resolving conflicts so that they work willingly towards goals. Option A sets the goals, option D designs the structure, and option B monitors results."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 83, $official_bank_source${"itemId":"6fd042cf-940d-5e96-8dea-0102c0af66a5","questionId":"edec5c04-73b5-50b5-a625-e37d20bb5d16","sourceKey":"bank:BUA201:UNI-006","payload":{"prompt":"A supervisor at an Abuja call centre holds a morning meeting to encourage her team, explains the day's targets and settles a quarrel between two agents. She is mainly performing the function of:","options":["Controlling","Organising","Planning","Leading"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Encouraging staff, communicating targets and handling conflict are leading activities. Option C would involve setting the targets in the first place, option B would involve arranging shifts and duties, and option A would involve checking actual performance against the targets."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 84, $official_bank_source${"itemId":"c47f7a6e-3a0f-58fd-a802-4faccee57150","questionId":"c4a3cd2b-9f18-595e-b587-686a284ef01a","sourceKey":"bank:BUA201:UNI-007","payload":{"prompt":"Which sequence correctly shows the basic steps in the control process?","options":["Take corrective action, set standards, compare with standards, measure actual performance","Compare with standards, measure actual performance, set standards, take corrective action","Measure actual performance, set standards, take corrective action, compare with standards","Set standards, measure actual performance, compare performance with standards, take corrective action"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Control starts with standards, because performance cannot be judged without a yardstick; actual results are then measured, compared with the standard, and deviations are corrected. Options C, A and B each place a step before the information it needs is available."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 85, $official_bank_source${"itemId":"4affbea9-e010-5c51-923d-1f1d77b3178b","questionId":"b7ad3ece-be74-5fda-ac59-24b04c2cfb91","sourceKey":"bank:BUA201:UNI-008","payload":{"prompt":"At the end of each month, the sales manager of an Ibadan distributor compares actual sales of N8,200,000 with the budgeted N10,000,000 and investigates the shortfall. This is an example of:","options":["Organising","Controlling","Leading","Planning"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Comparing actual results with the budget and investigating the gap is controlling, which keeps performance on track. Option D produced the N10,000,000 budget in the first place, option A arranges people and resources, and option C motivates and directs staff."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 86, $official_bank_source${"itemId":"c548d8d9-3bba-57dc-b723-97de53499e15","questionId":"0ea58058-7f94-5e30-84a5-a606a89169a5","sourceKey":"bank:BUA201:UNI-009","payload":{"prompt":"Which of the following is NOT one of the four functions in the planning-organising-leading-controlling (POLC) framework of management?","options":["Bargaining","Planning","Organising","Controlling"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"The POLC framework names planning, organising, leading and controlling as the four basic management functions. Bargaining is a negotiation activity, not one of the four functions. Options B, C and D are all part of POLC."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 87, $official_bank_source${"itemId":"ff0d30d2-3283-5bb8-9d8b-1355476bb553","questionId":"83deee76-c642-5c1d-9ab8-c04e0220258f","sourceKey":"bank:BUA201:UNI-010","payload":{"prompt":"Which statement best describes the relationship among the management functions?","options":["They are completely separate and are performed only once each","Each function is performed by a different level of management only","Controlling must be finished before any planning can begin","They are interrelated and continuous, with controlling feeding information back into planning"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"The functions overlap and repeat: results from controlling show where plans must be revised, so the process is a continuous cycle. Option A ignores the cyclical nature, option B is wrong because managers at every level perform all four, and option C reverses the usual order."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 88, $official_bank_source${"itemId":"e0dd2a53-f821-5f4e-97b6-717f6d95dd09","questionId":"5fbbe2b3-7849-53c6-bcb2-b375f49e243c","sourceKey":"bank:BUA201:UNI-011","payload":{"prompt":"The 'universality of management' means that:","options":["Management principles are laws that never change","Every manager in the world uses exactly the same style","Management principles and functions apply to all kinds of organisations and at all levels","Management is needed only in large profit-making companies"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Universality means planning, organising, leading and controlling are needed in businesses, governments, schools, hospitals, clubs and religious bodies, and at every level. Option D wrongly restricts management to big firms, option B confuses universal functions with identical styles, and option A confuses principles with fixed laws."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 89, $official_bank_source${"itemId":"c87b2764-cf2a-5359-b0c4-fbd67a936a52","questionId":"03b98d97-e75c-525f-83a0-867abf1740e4","sourceKey":"bank:BUA201:UNI-012","payload":{"prompt":"The leader of a church youth fellowship in Surulere sets goals for the year, forms committees, motivates members and reviews each event. This best illustrates:","options":["The universality of management","The scalar chain","Bureaucracy","Entrepreneurship"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"The fellowship is not a business, yet its leader performs planning, organising, leading and controlling, which shows that management applies to every kind of organisation. Option B is a line of authority, option C is Weber's model of rules and hierarchy, and option D involves bearing business risk for profit."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 90, $official_bank_source${"itemId":"23562dc2-dd7c-5aa2-9ed0-f8af2c26e2d8","questionId":"5a1676f8-433b-5f8e-938b-6fe69d8ef9c9","sourceKey":"bank:BUA201:UNI-013","payload":{"prompt":"Viewing management from the PROCESS perspective means seeing it as:","options":["A collection of unrelated tasks with no order","The legal ownership structure of a company","A single decision taken once a year","A continuous series of interrelated functions such as planning, organising, leading and controlling"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"The process view treats management as an ongoing set of linked activities that managers perform repeatedly to achieve goals. Option A ignores the link among the functions, option C reduces management to one act, and option B describes forms of ownership."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 91, $official_bank_source${"itemId":"41d721dd-764f-5e02-8af7-dd41464fd448","questionId":"db689e66-98e0-5e01-9dd6-2bed30394cc0","sourceKey":"bank:BUA201:UNI-014","payload":{"prompt":"From the SYSTEMS perspective, an organisation is viewed as:","options":["A set of interrelated parts that takes inputs from the environment, transforms them and returns outputs","A closed unit that does not depend on its environment","A list of rules that employees must obey","A group of departments that each work alone"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"The systems view sees the organisation as an open system of interdependent subsystems that interacts with its environment through inputs, transformation and outputs, with feedback. Option B describes a closed system, option D ignores interdependence, and option C describes bureaucracy."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 92, $official_bank_source${"itemId":"fa11797a-d343-5988-90ef-a938c0a16604","questionId":"2b87d55f-e59c-544c-91de-020c33e0c1c0","sourceKey":"bank:BUA201:UNI-015","payload":{"prompt":"In the systems view of a bakery, which of the following is an INPUT?","options":["Loaves of bread sold to customers","Customer complaints about stale bread","Mixing and baking the dough","Flour, sugar and the bakers' labour"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Inputs are the resources the system takes in, such as raw ingredients, labour, money and information. Option A is the output, option C is the transformation process, and option B is feedback that tells the bakery how its output is received."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 93, $official_bank_source${"itemId":"7e8ed65f-e12f-570c-929b-a49db1b6afbe","questionId":"9b8dc095-5ddd-52c5-9057-6b68226e52a9","sourceKey":"bank:BUA201:UNI-016","payload":{"prompt":"In the systems view of an organisation, 'feedback' refers to:","options":["Information about outputs that is used to adjust inputs or the transformation process","The raw inputs bought from suppliers","The building in which production takes place","The finished goods delivered to customers"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Feedback is information on how the outputs perform, for example sales figures or customer complaints, which management uses to make corrections. Option B describes inputs, option D describes outputs, and option C is a physical resource."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 94, $official_bank_source${"itemId":"b446db06-5b1d-5947-8436-7071f85708f0","questionId":"14a00bf4-8218-5037-a57c-7df586827116","sourceKey":"bank:BUA201:UNI-017","payload":{"prompt":"An organisation that constantly interacts with and depends on its external environment for resources and customers is described in systems theory as:","options":["A subsystem","Entropy","An open system","A closed system"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"An open system exchanges inputs and outputs with its environment, which is true of every real business. Option D is self-contained and does not interact with its environment, option A is a part of a larger system such as a department, and option B is the tendency of a system to run down."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 95, $official_bank_source${"itemId":"4cac497a-fc0c-57b2-8df9-97ac69dd3f58","questionId":"935e25f1-cb62-5b54-b254-c5727516d0b6","sourceKey":"bank:BUA201:UNI-018","payload":{"prompt":"A breakdown in the production department of a Lagos beverage company causes the marketing department to miss delivery promises to distributors. This mainly illustrates the systems idea that:","options":["An organisation is a closed system","Departments should never share information","Subsystems of an organisation are interdependent","Only top managers need to understand the system"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Because the departments are linked subsystems, a problem in one quickly affects the others, which is the core idea of interdependence in systems thinking. Option A contradicts the systems view, option B would make the problem worse, and option D ignores that all managers must coordinate with other units."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 96, $official_bank_source${"itemId":"96c4e645-079b-5e64-b104-1192addb8981","questionId":"2751588c-a3dc-5355-b0c6-f6c34b2ea02f","sourceKey":"bank:BUA201:UNI-019","payload":{"prompt":"A manager who is responsible for a single specialised area of the business, such as finance, marketing or human resources, is called a:","options":["Project manager","Board chairman","General manager","Functional manager"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"A functional manager heads one specialised department, such as finance or marketing. Option C oversees a complex unit that includes several functions, option A coordinates a temporary project team, and option B leads the board rather than a department."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 97, $official_bank_source${"itemId":"d0d26eb4-d11b-5680-8320-887948cd50db","questionId":"37d298d5-684f-5f59-afba-3d9d71ecff7b","sourceKey":"bank:BUA201:UNI-020","payload":{"prompt":"The head of a regional division of a Nigerian food company is responsible for that division's production, marketing, finance and personnel. She is best described as a:","options":["General manager","Functional manager","First-line supervisor","Staff specialist"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"A general manager is responsible for a whole unit that contains several functional areas. Option B would head only one function, option C supervises operative workers directly, and option D advises line managers in a specialised field."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 98, $official_bank_source${"itemId":"8f442cf5-e4cc-5a70-b609-f517faf99529","questionId":"11820c24-0e3d-5711-8077-d134b4580b6f","sourceKey":"bank:BUA201:UNI-021","payload":{"prompt":"Which of the following shows how management applies across functional areas of a business?","options":["Marketing managers need no control systems","Only the finance manager plans; others only carry out orders","Management functions apply only to the production department","The production, marketing, finance and HR managers each plan, organise, lead and control within their own areas"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Every functional manager performs all four management functions in their own area; for example, a marketing manager plans campaigns, organises the sales team, leads staff and controls sales results. Options B, C and A wrongly limit management to one function or department."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 99, $official_bank_source${"itemId":"8d2a5ece-31aa-55b0-91d1-5421b6fec47c","questionId":"6771287b-a073-5cd0-9400-c6f90a0ae54b","sourceKey":"bank:BUA201:UNI-022","payload":{"prompt":"Managers responsible for making organisation-wide decisions and setting long-term strategy and policies are:","options":["Middle managers","First-line managers","Top managers","Operative employees"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Top managers such as the managing director or chief executive set overall direction, strategy and policy for the whole organisation. Option A translates those plans for their units, option B supervises day-to-day work of operatives, and option D are non-managerial staff."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 100, $official_bank_source${"itemId":"901e28be-c73c-58f8-a5cb-6396c8b5ced8","questionId":"ed6c0350-07a4-5834-993b-a30d5bfdcd8a","sourceKey":"bank:BUA201:UNI-023","payload":{"prompt":"The main role of MIDDLE managers is to:","options":["Represent shareholders at the annual general meeting","Set the overall mission and long-term strategy of the organisation","Personally perform the routine production work","Translate top management's goals into specific plans for their units and coordinate first-line managers"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Middle managers stand between top and first-line management, turning broad strategy into departmental plans and coordinating the managers below them. Option B is top management's role, option C is done by operative employees, and option A is not a managerial level role."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 101, $official_bank_source${"itemId":"9737b763-ff29-59cd-b244-eecd7de3e7dd","questionId":"44f011a9-8523-504b-b08a-6f93ce42017e","sourceKey":"bank:BUA201:UNI-024","payload":{"prompt":"A foreman in a Kaduna factory assigns daily tasks to machine operators, checks their work and reports problems to the production manager. He is a:","options":["Top manager","Non-executive director","Middle manager","First-line manager"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"First-line (supervisory) managers direct the daily work of operative employees, as the foreman does. Option A sets strategy for the whole firm, option C manages other managers such as the production manager, and option B serves on the board without running daily operations."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 102, $official_bank_source${"itemId":"74bebf5a-cb00-5db0-b2f9-b262432f18d4","questionId":"f1ffcbd9-a671-57c7-8bc5-4648a33aed93","sourceKey":"bank:BUA201:UNI-025","payload":{"prompt":"Which of the following job titles is usually a MIDDLE-level management position?","options":["Regional sales manager","Shift supervisor","Managing director","Machine operator"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"A regional sales manager typically reports to top management and supervises area or branch supervisors, which is the middle level. Option C is top management, option B is first-line management, and option D is a non-managerial operative job."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 103, $official_bank_source${"itemId":"ee92fd42-7d5c-524b-92b5-ccdedb1dbce1","questionId":"d531f2ca-ea79-5ded-8615-fb1b2839da14","sourceKey":"bank:BUA201:UNI-026","payload":{"prompt":"Compared with first-line managers, top managers generally focus on decisions that:","options":["Require mainly detailed technical skill","Have a longer time horizon and affect the whole organisation","Concern a single machine or task","Cover only the next few hours of work"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Top managers deal with strategic decisions covering several years and the whole organisation, while first-line managers handle short-term operational issues. Options D and C describe first-line concerns, and option A describes the skill most needed at the first-line level."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 104, $official_bank_source${"itemId":"743cee71-4dad-5166-81d3-72123a57d852","questionId":"b9afa3fd-11ba-5736-ab70-74d2f1b76d4f","sourceKey":"bank:BUA201:UNI-027","payload":{"prompt":"Henry Mintzberg grouped his ten managerial roles into three categories. These are:","options":["Strategic, tactical and operational roles","Planning, organising and controlling roles","Interpersonal, informational and decisional roles","Technical, human and conceptual roles"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Mintzberg's ten roles fall into interpersonal, informational and decisional groups. Option D lists Katz's three managerial skills, option B lists management functions, and option A lists types of plans or decisions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 105, $official_bank_source${"itemId":"b9bb34b9-3e4c-5c67-83cf-824cd96dd2b0","questionId":"9f0e1a84-984c-5401-a482-94afff3fdf70","sourceKey":"bank:BUA201:UNI-028","payload":{"prompt":"How many managerial roles did Henry Mintzberg identify?","options":["Five","Three","Ten","Fourteen"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Mintzberg identified ten roles, organised into three groups: interpersonal, informational and decisional. Option B is the number of groups, option A is the number of Fayol's elements of management, and option D is the number of Fayol's principles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 106, $official_bank_source${"itemId":"39d259d3-243d-5e64-9be2-8911524978b0","questionId":"515aea81-ac5b-5707-88ea-52154b4ddaa9","sourceKey":"bank:BUA201:UNI-029","payload":{"prompt":"Which of the following roles belongs to Mintzberg's INFORMATIONAL category?","options":["Resource allocator","Disseminator","Figurehead","Negotiator"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The informational roles are monitor, disseminator and spokesperson. Option C is an interpersonal role, while options D and A are decisional roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 107, $official_bank_source${"itemId":"969174de-db4a-5f97-b36e-405e46db5d06","questionId":"097df6c0-1c1a-509f-828e-ee9a2c94a66d","sourceKey":"bank:BUA201:UNI-030","payload":{"prompt":"Which of the following is NOT one of Mintzberg's INTERPERSONAL roles?","options":["Leader","Spokesperson","Figurehead","Liaison"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The interpersonal roles are figurehead, leader and liaison. Spokesperson is an informational role, because it involves passing information to outsiders. Options C, A and D are all interpersonal roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 108, $official_bank_source${"itemId":"773a6a97-2158-5e78-bdad-81016a0de76e","questionId":"7d8d2973-f107-5c6f-b9de-e76d02faebbf","sourceKey":"bank:BUA201:UNI-031","payload":{"prompt":"Which of the following is NOT one of Mintzberg's DECISIONAL roles?","options":["Disturbance handler","Monitor","Entrepreneur","Negotiator"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The decisional roles are entrepreneur, disturbance handler, resource allocator and negotiator. Monitor is an informational role, because it involves seeking and receiving information. Options C, A and D are decisional roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 109, $official_bank_source${"itemId":"4f9d5f6b-ce62-5f83-a9c4-e6f8d23799ec","questionId":"4bf6ae13-a46d-5960-941c-a5f1a0dbe10f","sourceKey":"bank:BUA201:UNI-032","payload":{"prompt":"The MD of a Nigerian bank cuts the ribbon at a new branch opening and signs certificates for long-serving staff. In Mintzberg's terms, he is performing the role of:","options":["Spokesperson","Leader","Entrepreneur","Figurehead"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"The figurehead role covers ceremonial and symbolic duties performed because of the manager's position, such as opening branches and signing documents. Option B involves motivating and directing staff, option A involves giving official information to outsiders, and option C involves starting improvement projects."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 110, $official_bank_source${"itemId":"7f6ce642-287c-51e1-ba2c-4cc09dafc91d","questionId":"a0335f1f-8929-52f7-8bee-b661fb196762","sourceKey":"bank:BUA201:UNI-033","payload":{"prompt":"A plant manager regularly reads trade journals, reviews daily production reports and listens to suppliers to keep track of what is happening in and around the business. In Mintzberg's terms, this is the role of:","options":["Disseminator","Monitor","Resource allocator","Liaison"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The monitor role involves seeking and receiving information from inside and outside the organisation. Option A passes information on to subordinates, option D maintains a network of outside contacts, and option C decides how resources are shared."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 111, $official_bank_source${"itemId":"07fc3eca-bab9-5093-9b84-7ca6dc9f8ce9","questionId":"518cb9aa-f9f4-5c5d-bee5-ca765ee6f7a3","sourceKey":"bank:BUA201:UNI-034","payload":{"prompt":"After a meeting with top management, a branch manager calls her staff together and passes on the new policy on customer service. In Mintzberg's terms, she is acting as a:","options":["Monitor","Spokesperson","Figurehead","Disseminator"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"The disseminator role transmits information received from outside or from above to members of the manager's own unit. Option B transmits information to people outside the organisation, option A gathers information, and option C performs ceremonial duties."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 112, $official_bank_source${"itemId":"5b8e74a7-dd41-5d61-9eb4-3ab3911694f6","questionId":"0ca34100-f03f-533a-b7d4-e7d74e3a87f5","sourceKey":"bank:BUA201:UNI-035","payload":{"prompt":"The head of corporate affairs of a telecom company appears on television to explain to the public why the company's network was down for six hours. In Mintzberg's terms, this is the role of:","options":["Leader","Spokesperson","Disseminator","Negotiator"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The spokesperson role transmits information about the organisation to outsiders such as the media, regulators and the public. Option C shares information inside the unit, option A motivates staff, and option D bargains with other parties over resources or terms."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 113, $official_bank_source${"itemId":"d740c436-2331-5812-96f2-c338942b2408","questionId":"41d07307-a1fc-5ce1-b51c-de8e03472c73","sourceKey":"bank:BUA201:UNI-036","payload":{"prompt":"A manager at a Lagos fintech starts a new project to let customers open accounts through a USSD code, looking for ways to improve the business. In Mintzberg's terms, she is acting as an:","options":["Entrepreneur","Monitor","Liaison","Disturbance handler"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"The entrepreneur role involves searching for opportunities and initiating improvement projects or changes. Option D reacts to unexpected crises, option B gathers information, and option C maintains outside networks."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 114, $official_bank_source${"itemId":"49e2764f-a8ad-5a58-846e-5e5586066712","questionId":"ce383c84-0f75-5086-b7ff-53e8bf86296d","sourceKey":"bank:BUA201:UNI-037","payload":{"prompt":"When fire breaks out in a warehouse and workers threaten to walk off the job, the factory manager immediately takes charge of the crisis. In Mintzberg's terms, this is the role of:","options":["Figurehead","Resource allocator","Entrepreneur","Disturbance handler"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"The disturbance handler role deals with unexpected crises and conflicts that demand immediate corrective action. Option C starts planned improvements, option B decides who gets which resources, and option A performs ceremonial duties."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 115, $official_bank_source${"itemId":"fac2fa3a-8ce3-564c-8393-e515316b90ca","questionId":"94427418-2fc6-5e58-bea9-df304d81a366","sourceKey":"bank:BUA201:UNI-038","payload":{"prompt":"A divisional head decides how the year's N50,000,000 budget will be shared among the sales, production and training units. In Mintzberg's terms, this is the role of:","options":["Leader","Resource allocator","Disseminator","Negotiator"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"The resource allocator role decides who gets the organisation's money, people, time and equipment. Option D involves bargaining with others, option C passes information to subordinates, and option A involves motivating and guiding staff."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 116, $official_bank_source${"itemId":"5c5e970a-67d9-5a24-a195-e2817b2f2bc9","questionId":"8425a80c-a4cb-5627-a2c0-f786b45d7e06","sourceKey":"bank:BUA201:UNI-039","payload":{"prompt":"The HR director of a manufacturing firm meets union officials to agree a new wage settlement for workers. In Mintzberg's terms, she is acting as a:","options":["Negotiator","Liaison","Disturbance handler","Spokesperson"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"The negotiator role represents the organisation in major bargaining, such as wage agreements with unions or contracts with suppliers. Option D only transmits information to outsiders, option B maintains contacts for information and favours, and option C handles sudden crises rather than planned bargaining."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 117, $official_bank_source${"itemId":"16d5fd34-15b9-5c4f-a23b-8bb9d3b5700e","questionId":"48ac0dda-c893-52d0-8cc6-10ec8e252836","sourceKey":"bank:BUA201:UNI-040","payload":{"prompt":"A departmental manager hires a new officer, trains her and praises staff who meet their targets. In Mintzberg's terms, this is the role of:","options":["Resource allocator","Figurehead","Leader","Monitor"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"The leader role covers hiring, training, motivating and directing subordinates. Option B is ceremonial, option D is about gathering information, and option A is about distributing resources."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 118, $official_bank_source${"itemId":"a054714f-f2e6-5974-bc20-6f8a29ab5c55","questionId":"669130a8-96c0-5e5a-a007-d79ca0e897a9","sourceKey":"bank:BUA201:UNI-041","payload":{"prompt":"Robert Katz identified three basic skills that managers need. These are:","options":["Interpersonal, informational and decisional skills","Planning, organising and controlling skills","Technical, human and conceptual skills","Financial, legal and political skills"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Katz described technical, human (interpersonal) and conceptual skills as the basic managerial skills. Option A names Mintzberg's role groups, option B names management functions, and option D is not Katz's classification."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 119, $official_bank_source${"itemId":"bbd83376-38c0-57a4-9002-236860c29270","questionId":"ca799a86-0df6-5bf6-b2bf-05b4d6bbb9b4","sourceKey":"bank:BUA201:UNI-042","payload":{"prompt":"The ability to use the tools, techniques and specialised knowledge of a particular field, such as accounting or engineering, is called:","options":["Technical skill","Human skill","Conceptual skill","Political skill"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Technical skill is know-how in a specific discipline or method. Option C is the ability to see the organisation as a whole and think abstractly, option B is the ability to work well with people, and option D is not one of Katz's three skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 120, $official_bank_source${"itemId":"06328716-353d-507f-a23b-b7e77c28eb6f","questionId":"7b6e3568-6758-5919-916d-ef6f615df71a","sourceKey":"bank:BUA201:UNI-043","payload":{"prompt":"The ability to work well with others, communicate, motivate and build cooperation within a team is called:","options":["Technical skill","Conceptual skill","Design skill","Human skill"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Human (interpersonal) skill is the ability to understand, work with and motivate people, individually and in groups. Option A relates to specialised know-how, option B to seeing the big picture, and option C is not one of Katz's three basic skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 121, $official_bank_source${"itemId":"1b93a161-1e50-5309-be5a-86bd4e5f887d","questionId":"4bd32a44-f02f-5989-b118-f8fb50a3d430","sourceKey":"bank:BUA201:UNI-044","payload":{"prompt":"The ability to see the organisation as a whole, understand how its parts relate to each other and to the environment, and think in abstract terms is called:","options":["Technical skill","Human skill","Conceptual skill","Clerical skill"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Conceptual skill is the 'big picture' ability to analyse complex situations and see how the parts fit together. Option A is specialised know-how, option B is the ability to work with people, and option D is not one of Katz's skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 122, $official_bank_source${"itemId":"e706ac74-1e57-5990-ad02-27491265abc6","questionId":"3b5eb060-fd7a-5978-be4d-8c3e7c2d14cc","sourceKey":"bank:BUA201:UNI-045","payload":{"prompt":"Which managerial skill is generally considered MOST important for first-line managers?","options":["Conceptual skill","Technical skill","Political skill","Negotiation skill"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"First-line managers supervise operative work directly, so they need strong technical knowledge of how the work is done. Option A becomes more important as one rises to top management, and options C and D are not among Katz's three basic skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 123, $official_bank_source${"itemId":"341d70ea-dfba-50b0-a13c-e46403219291","questionId":"86c9b7d3-3410-5797-8213-18db8f1d5c39","sourceKey":"bank:BUA201:UNI-046","payload":{"prompt":"Which of Katz's managerial skills is generally considered roughly EQUALLY important at all levels of management?","options":["Accounting skill","Human skill","Conceptual skill","Technical skill"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Managers at every level work with and through people, so human skill is about equally important at the top, middle and first-line levels. Option D matters most at lower levels and option C matters most at the top, while option A is a technical speciality rather than one of Katz's skill groups."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 124, $official_bank_source${"itemId":"ac9fc860-e335-57a7-8049-77c166fe4bab","questionId":"a171e436-a2a8-5914-b1f0-9384e62b5666","sourceKey":"bank:BUA201:UNI-047","payload":{"prompt":"The CEO of a Nigerian conglomerate studies how a new import ban, rising interest rates and a rival's expansion will together affect each of the group's businesses. She is mainly using:","options":["Human skill","Conceptual skill","Clerical skill","Technical skill"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Seeing how many external forces and internal units fit together and affect the whole organisation requires conceptual skill. Option D is specialised know-how in a particular field, option A concerns dealing with people, and option C is not one of Katz's skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 125, $official_bank_source${"itemId":"08f481a9-ab23-5f86-922d-303cff042186","questionId":"0323aab0-8c9e-5d33-8424-0cad679deae5","sourceKey":"bank:BUA201:UNI-048","payload":{"prompt":"A new production supervisor calmly settles a quarrel between two operators and persuades them to work together again. He is mainly using:","options":["Financial skill","Human skill","Technical skill","Conceptual skill"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Resolving conflict and getting people to cooperate is human skill. Option C would be shown by repairing a machine or explaining a procedure, option D by analysing how the whole organisation is affected, and option A is not one of Katz's three skills."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 126, $official_bank_source${"itemId":"db4f16f2-16d4-54ec-9ddc-43f920808e13","questionId":"063acf50-ede8-5f47-b590-be19bfec636b","sourceKey":"bank:BUA201:UNI-049","payload":{"prompt":"As a manager moves from first-line to top management, the relative importance of technical and conceptual skills generally changes as follows:","options":["Technical skill becomes more important and conceptual skill becomes less important","Both stay exactly the same at every level","Both become less important","Technical skill becomes less important and conceptual skill becomes more important"],"correctOption":3,"section":"Universality of Management and Managerial Roles","explanation":"Higher-level managers spend less time on specialised operational tasks and more time on strategy, so the need for conceptual skill rises while the need for technical skill falls. Option A reverses the pattern, option C ignores the rising need for conceptual skill, and option B ignores the shift altogether."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 127, $official_bank_source${"itemId":"abd3c472-a71e-5dc1-996c-aa514d1191c2","questionId":"0d478afe-551a-5a93-97c0-1f6cd1a56020","sourceKey":"bank:BUA201:UNI-050","payload":{"prompt":"When managers are described as 'organisational stabilisers', it means that they:","options":["Avoid making any decisions","Leave all coordination to employees","Maintain order, continuity and predictable operations so the organisation keeps running smoothly","Resist every form of change in the organisation"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"As stabilisers, managers keep routines, rules and coordination in place so that work continues reliably even when the environment changes. Option D is wrong because stability does not mean blocking all change, and options A and B describe an absence of management."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 128, $official_bank_source${"itemId":"bf2f2a39-825c-5d0f-9505-6447ed467c52","questionId":"31714e0e-d903-5549-9f07-f1901157a7e1","sourceKey":"bank:BUA201:UNI-051","payload":{"prompt":"During a period of fuel scarcity, the operations manager of a transport company reorganises schedules, secures alternative suppliers and keeps buses running so services continue normally. This best shows the manager acting as:","options":["A sleeping partner","A figurehead","An organisational stabiliser","An external consultant"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"The manager is protecting continuity and keeping operations steady despite disruption, which is the stabilising role of managers. Option B refers to ceremonial duties, option A is a partner who takes no part in management, and option D is an outsider brought in for advice."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 129, $official_bank_source${"itemId":"0ed0b756-b5b3-5a8a-9387-f75d664e176e","questionId":"0fd53a34-5eb9-5e10-91a1-58fab2ddf874","sourceKey":"bank:BUA201:UNI-052","payload":{"prompt":"A person who plans, organises, leads and controls the work of others so that organisational goals are achieved is called a:","options":["Shareholder","Manager","Customer","Operative employee"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"A manager coordinates and oversees the work of other people to accomplish organisational goals. Option D performs tasks directly without overseeing others, option A owns shares and may not manage at all, and option C buys the organisation's goods or services."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 130, $official_bank_source${"itemId":"58a66907-f392-54d6-b288-65c64094c8e1","questionId":"56873a3f-0cca-54fb-94b5-8d067ede3574","sourceKey":"bank:BUA201:UNI-053","payload":{"prompt":"Which of the following correctly matches a management function with an example activity?","options":["Controlling: checking whether production costs are within budget","Planning: settling a quarrel between workers","Leading: writing a five-year strategy","Organising: praising a worker for good performance"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Checking costs against the budget compares actual performance with a standard, which is controlling. Option B is a leading activity, option D is also leading because it motivates, and option C is planning."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 131, $official_bank_source${"itemId":"d0462d8a-f36e-5b0c-aa10-b3a4354f02c0","questionId":"b74448f4-91f0-59be-957e-2bc06dd089cc","sourceKey":"bank:BUA201:UNI-054","payload":{"prompt":"Which of the following best shows that controlling and planning are linked in the management process?","options":["Controlling replaces the need for organising","Controlling is done only by the board of directors","Deviations found during controlling lead managers to revise their plans","Plans are never changed once made"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"Controlling compares results with plans; when results fall short, managers use the information to correct actions or revise the plans, closing the management cycle. Option B wrongly limits control to the board, option D ignores feedback, and option A confuses two distinct functions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 132, $official_bank_source${"itemId":"b4b91599-baef-55ad-9aa9-3b8fac917ca0","questionId":"52ab9a81-c9ee-552d-9de5-a1ab68d16cfc","sourceKey":"bank:BUA201:UNI-055","payload":{"prompt":"A production manager at a Lagos bottling plant notices that bottles are leaving the line under-filled and immediately adjusts the filling machine. Which step of the control process is she performing?","options":["Taking corrective action","Setting standards","Planning the production schedule","Designing the organisation structure"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Adjusting the machine fixes the deviation between actual and standard fill levels, which is the corrective-action step of control. Option B comes at the start of control before measurement, option C is planning, and option D is organising."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 133, $official_bank_source${"itemId":"115eb10c-267d-5e35-8aef-efc8447a532b","questionId":"53ed45c5-2966-5c72-ae95-820a122fb1ee","sourceKey":"bank:BUA201:UNI-056","payload":{"prompt":"In Mintzberg's framework, the role in which a manager builds and maintains a network of contacts outside his or her own unit to obtain information and favours is the:","options":["Disseminator role","Resource allocator role","Liaison role","Leader role"],"correctOption":2,"section":"Universality of Management and Managerial Roles","explanation":"The liaison role is about networking with people outside the manager's own unit, both inside and outside the organisation. Option D deals with the manager's own subordinates, option A passes information down to them, and option B decides how resources are shared."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 134, $official_bank_source${"itemId":"2a702fee-2afe-5fc4-8d66-a18d2864db57","questionId":"bc5c6e04-198e-5362-b988-be57d1e329fc","sourceKey":"bank:BUA201:UNI-057","payload":{"prompt":"Which of the following correctly pairs a Mintzberg role with its category?","options":["Monitor - interpersonal","Negotiator - decisional","Spokesperson - decisional","Figurehead - informational"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Negotiator is a decisional role, alongside entrepreneur, disturbance handler and resource allocator. Option D is wrong because figurehead is interpersonal, option A because monitor is informational, and option C because spokesperson is informational."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 135, $official_bank_source${"itemId":"370d962b-d03f-5186-b61e-d2ddc0a4c957","questionId":"1a4c9531-76cc-56ed-894c-78c009731bdc","sourceKey":"bank:BUA201:UNI-058","payload":{"prompt":"Although managers at all levels perform all four management functions, how does the time spent on them typically differ by level?","options":["Top managers spend relatively more time planning, while first-line managers spend relatively more time leading and directing day-to-day work","Every level spends exactly the same share of time on each function","First-line managers do no controlling at all","Top managers spend all their time leading, while first-line managers only plan"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"All managers plan, organise, lead and control, but top managers concentrate more on planning and organising for the whole organisation, while first-line managers spend more time directing and supervising operatives. Option D reverses the pattern, option C is wrong because supervisors constantly check work, and option B ignores the difference in emphasis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 136, $official_bank_source${"itemId":"5719c3f1-cb6b-558b-8f59-edfb4a67cdae","questionId":"670f1ee2-32da-5213-b65a-3db99a1ca605","sourceKey":"bank:BUA201:UNI-059","payload":{"prompt":"In the systems view of a commercial bank, which of the following is part of the TRANSFORMATION process?","options":["Assessing loan applications and processing customers' transactions","Customers' deposits and the skills of staff","Customer complaints received through the call centre","Satisfied customers and profit for the year"],"correctOption":0,"section":"Universality of Management and Managerial Roles","explanation":"Transformation is the work that converts inputs into outputs, such as processing transactions and evaluating loans in a bank. Option B lists inputs, option D lists outputs, and option C is feedback from customers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 137, $official_bank_source${"itemId":"6ce6f7c6-e4f6-5f59-b695-151be43e5e89","questionId":"feb6ac9a-bc74-5dfb-b673-277ad298ce48","sourceKey":"bank:BUA201:UNI-060","payload":{"prompt":"The formal framework of jobs, departments, reporting relationships and lines of authority that results from the organising function is called the:","options":["Budget","Organisation structure","Control standard","Strategic plan"],"correctOption":1,"section":"Universality of Management and Managerial Roles","explanation":"Organising produces an organisation structure, often shown on an organisation chart, which sets out who does what and who reports to whom. Option D is the output of planning, option A is a financial plan, and option C is a yardstick used in controlling."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 138, $official_bank_source${"itemId":"b0939cc2-efd2-5390-b12e-6d3b66551f90","questionId":"299068f7-8519-5b30-b313-6fcec2b2cf5a","sourceKey":"bank:BUA201:PQ-016","payload":{"prompt":"In Lewin's three-step model of change, the \"refreezing\" stage ensures:","options":["Continuous experimentation","Stabilisation of the change so new behaviours become the norm","Employee resistance","Strategic uncertainty"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Lewin's model runs unfreeze, change (move), then refreeze; refreezing locks in the new ways of working through policies, rewards and culture so people do not slip back. Option A is the opposite of refreezing, and option C is a problem that unfreezing tries to reduce."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 139, $official_bank_source${"itemId":"8459a67e-ebba-5bc9-8e9c-6ec409e2c67d","questionId":"1967ed5a-6c3d-5255-9143-a80a10ed696c","sourceKey":"bank:BUA201:PQ-035","payload":{"prompt":"Nigeria's banking consolidation of 2004-2005, when the Central Bank of Nigeria under Governor Charles Soludo raised banks' minimum capital base and the number of banks fell from 89 to 25, is best described as:","options":["Radical (transformational) change","Incremental change","Routine operational adjustment","Market exit by the banking sector"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Raising the capital requirement more than tenfold forced mergers, acquisitions and closures that reshaped the whole industry within about two years, which is radical change. Options B and C describe small step-by-step adjustments, and option D is wrong because the sector was restructured, not abandoned."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 140, $official_bank_source${"itemId":"d1a9c58c-74db-58c2-a409-cbab00355860","questionId":"f5f6f0b4-1751-5c49-9db7-d2d7700c7b72","sourceKey":"bank:BUA201:PQ-035-b","payload":{"prompt":"In the 2004 Nigerian banking consolidation led by CBN Governor Charles Soludo, the minimum capital base for banks was raised from N2 billion to:","options":["N5 billion","N50 billion","N10 billion","N25 billion"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Banks were required to raise their minimum capital base from N2 billion to N25 billion, a target that pushed many smaller banks to merge. Options A, C and B are not the figure set for that reform."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 141, $official_bank_source${"itemId":"af41c3ce-7af2-5dae-beac-bd5da77308d6","questionId":"e3b461a8-b084-5a8c-a148-ebd899a3dc3a","sourceKey":"bank:BUA201:PQ-045","payload":{"prompt":"Resistance to change in organisations is often rooted in:","options":["Clear legal rules","Fear of uncertainty","Capital inflow","A surplus of skills"],"correctOption":1,"section":"Managers as Change Agents","explanation":"People often resist change because they do not know how it will affect their jobs, status or routines, and the unknown feels threatening. Options D, C and A would, if anything, make change easier to accept."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 142, $official_bank_source${"itemId":"919f884f-6d59-52d1-83d8-a9ec72cc413d","questionId":"82b49a36-1ed1-57e0-92bd-725763f07813","sourceKey":"bank:BUA201:PQ-075","payload":{"prompt":"Corporate restructuring may involve:","options":["Inflation","Exchange rate control","Downsizing","Market segmentation"],"correctOption":2,"section":"Managers as Change Agents","explanation":"Corporate restructuring means reorganising a company's structure, operations or ownership to improve performance, and downsizing (cutting staff or units) is one of its common forms. Options A and B are economy-wide conditions or government policies, not actions a company takes on itself. Option D is a marketing technique for dividing customers into groups, not a restructuring move."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 143, $official_bank_source${"itemId":"329305ce-3c26-52e8-a630-823a60ffb6af","questionId":"4f04c2a6-d0d1-53f3-be98-531405ede821","sourceKey":"bank:BUA201:PQ-096","payload":{"prompt":"Organisational learning supports:","options":["Bureaucracy","Cost rigidity","Strategic drift","Innovation"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Organisational learning is the process by which a firm gains, shares and uses new knowledge, which helps it improve and come up with new ideas, products and methods. Options A and B describe rigidity that learning helps to overcome. Option C is when a firm's strategy falls out of step with its environment, which is what happens when an organisation stops learning."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 144, $official_bank_source${"itemId":"6046eb07-bbdc-5be8-ae5e-01c0c4c349da","questionId":"1ae72047-5bfd-5390-992b-101ce0412a89","sourceKey":"bank:BUA201:PQ-125","payload":{"prompt":"A very common cause of resistance to organisational change is:","options":["Fear of the unknown","Poor technology","Excessive communication","Leadership commitment"],"correctOption":0,"section":"Managers as Change Agents","explanation":"People often resist change because they are unsure how it will affect their jobs, skills or status, and that uncertainty breeds fear. Option C is wrong because clear, frequent communication usually reduces resistance, and option D supports change rather than blocking it. Option B may be a reason for change, not a cause of people resisting it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 145, $official_bank_source${"itemId":"ffdac962-6d76-5d0b-91be-e74fa63de3e0","questionId":"7c1e5ffe-a0de-56cf-b4ce-f3db86cf2fe5","sourceKey":"bank:BUA201:PQ-126","payload":{"prompt":"Which approach is MOST effective in reducing resistance to change?","options":["Coercion","Participation and involvement","Manipulation","Threats"],"correctOption":1,"section":"Managers as Change Agents","explanation":"When employees take part in planning and carrying out a change, they understand it better and feel ownership of it, which builds commitment. Options A, C and D may force short-term compliance, but they damage trust and often create more resistance later."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 146, $official_bank_source${"itemId":"4a2989e5-5173-532c-8a0f-4e1c58f2dec2","questionId":"1a943006-04d0-5e0b-8d6a-d1645f026a08","sourceKey":"bank:BUA201:PQ-127","payload":{"prompt":"Compared with an external consultant, an internal change agent is more likely to face resistance because:","options":["The agent always lacks technical skills","The agent has no authority at all","Outside parties interfere with the agent's work","Colleagues may see the agent as too close to existing relationships and politics to be objective"],"correctOption":3,"section":"Managers as Change Agents","explanation":"An internal change agent knows the organisation well, but colleagues may see him or her as part of existing friendships, rivalries and politics, so the agent's proposals can be viewed as biased. Option A and option B are overstatements, since internal agents are often skilled managers with formal authority. Option C describes outside interference, which is not what makes an insider's position difficult."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 147, $official_bank_source${"itemId":"5ca7f9c7-ddc0-5e68-a93e-251afc7ea37e","questionId":"cd58b238-6e94-50a3-9847-e9b2bc26cb78","sourceKey":"bank:BUA201:PQ-128","payload":{"prompt":"Which role is LEAST associated with a change agent?","options":["Diagnosing problems","Facilitating communication","Supporting implementation","Maintaining existing structures unchanged"],"correctOption":3,"section":"Managers as Change Agents","explanation":"A change agent's job is to move the organisation from its current state to a better one, so preserving structures exactly as they are runs against that role. Options A, B and C are typical change-agent roles: finding what needs to change, keeping people informed and helping the change take hold."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 148, $official_bank_source${"itemId":"6b9a77bb-4a1f-57bd-92dd-adf6390b63b8","questionId":"a121ddfc-4ab8-52e0-9496-5525ed6257c9","sourceKey":"bank:BUA201:PQ-144-a","payload":{"prompt":"Change management is BEST described as:","options":["A structured approach to moving individuals and the organisation from the current state to a desired future state","Keeping the organisation exactly as it is","Replacing all employees with new ones","Changing the company's name and logo only"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Change management is the planned process of preparing, supporting and guiding people and the organisation through a transition so that the change is adopted and lasts. Option B is the opposite of change. Options C and D are extreme or superficial actions, not a managed process."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 149, $official_bank_source${"itemId":"cd8dcdcb-027f-5b18-b646-ce75195637a6","questionId":"85cc27c7-d6a9-58a3-a7f3-5b295c63e896","sourceKey":"bank:BUA201:PQ-144-b","payload":{"prompt":"Which of the following is NOT a cause of resistance to change?","options":["Clear communication and involvement of employees in the change","Fear of losing one's job","Fear of the unknown","Threats to existing status and power"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Clear communication and involvement are ways of reducing resistance, because they help people understand the change and feel part of it. Options B, C and D are common causes of resistance, since people worry about their security, about uncertainty and about losing their position."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 150, $official_bank_source${"itemId":"fbac4104-3b9c-5f5a-95c1-26dfd8287101","questionId":"b52011f9-9cd7-57d7-8ef7-33c83060ac40","sourceKey":"bank:BUA201:PQ-145-a","payload":{"prompt":"A change agent is BEST defined as:","options":["Anyone who resists new methods of work","A government official who registers companies","A worker who keeps existing procedures unchanged","A person or group who initiates, guides and supports change in an organisation"],"correctOption":3,"section":"Managers as Change Agents","explanation":"A change agent takes responsibility for starting and steering change, for example by diagnosing problems, communicating the need for change and helping people adapt. Options A and C describe people who block or ignore change, and option B describes a regulatory role."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 151, $official_bank_source${"itemId":"649abfe9-6d51-5d16-a695-e313ee75ade7","questionId":"d7b12429-0c06-54f7-ac66-32e35121b462","sourceKey":"bank:BUA201:PQ-145-b","payload":{"prompt":"Which of the following is a role of a change agent in organisational transformation?","options":["Discouraging employees from giving feedback","Preserving outdated procedures","Diagnosing problems and communicating the need for change","Avoiding any contact with employees"],"correctOption":2,"section":"Managers as Change Agents","explanation":"A change agent studies the organisation to find what needs to change, explains why the change matters and supports people as it is implemented. Options A, B and D would weaken the change effort, because feedback, updated procedures and close contact with employees are all needed for change to succeed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 152, $official_bank_source${"itemId":"3caf70b4-c466-502e-923c-1ce45d156b2d","questionId":"cd6e0895-de8f-5c00-8bfb-d9a4ae648e68","sourceKey":"bank:BUA201:CHG-001","payload":{"prompt":"A person who acts as a catalyst for change and takes responsibility for initiating and managing a change process in an organisation is called a:","options":["Figurehead","Sleeping partner","Change agent","Shareholder"],"correctOption":2,"section":"Managers as Change Agents","explanation":"A change agent initiates, guides and manages change, and may be a manager inside the organisation or an outside consultant. Option B is a partner who takes no part in management, option A is Mintzberg's ceremonial role, and option D is an owner who may play no part in change at all."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 153, $official_bank_source${"itemId":"25280478-5a3a-584e-bf0f-9710e9cb3aae","questionId":"2c0c3e17-1b2a-5e22-b212-e225131820a3","sourceKey":"bank:BUA201:CHG-002","payload":{"prompt":"Which statement best describes a manager's responsibility for organisational transformation?","options":["Managers should avoid change to protect stability","Managers should leave all change decisions to external consultants","Managers must recognise the need for change, plan and lead it, and help staff adjust to new ways of working","Managers need only announce change and staff will adapt automatically"],"correctOption":2,"section":"Managers as Change Agents","explanation":"As change agents, managers identify when the organisation must change, set direction, plan implementation and support people through the transition. Option B shifts responsibility away from managers, option A confuses stability with standing still, and option D ignores resistance and the need for support."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 154, $official_bank_source${"itemId":"35c9a742-17c1-56e0-aa41-493344c0cd7c","questionId":"37d350cd-88e1-5545-88ac-0855851095df","sourceKey":"bank:BUA201:CHG-003","payload":{"prompt":"An EXTERNAL change agent, such as a management consultant, usually has which advantage over an internal change agent?","options":["A more objective, fresh view of the organisation's problems","Lower risk of being seen as an outsider","Stronger existing relationships with staff","Deeper knowledge of the organisation's history and culture"],"correctOption":0,"section":"Managers as Change Agents","explanation":"An outside consultant is not tied to internal politics or habits, so he or she can see problems more objectively and bring new ideas. Options D and C are advantages of internal change agents, and option B is the opposite of the truth, since external agents are more likely to be seen as outsiders."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 155, $official_bank_source${"itemId":"795e6715-0eda-5079-859d-6dcc14ca98e1","questionId":"eb229b47-a646-53d0-80a8-5b80bb5c3e7d","sourceKey":"bank:BUA201:CHG-004","payload":{"prompt":"A key DISADVANTAGE of an external change agent compared with an internal one is that the external agent:","options":["Is too closely tied to internal politics","Has no professional training in change","May not fully understand the organisation's culture, history and people","Cannot bring any new ideas"],"correctOption":2,"section":"Managers as Change Agents","explanation":"External agents often lack detailed knowledge of the organisation and may propose changes that do not fit its culture. Option A is a risk for internal agents, option D contradicts the usual strength of outsiders, and option B is not generally true of consultants."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 156, $official_bank_source${"itemId":"3fcf47ee-da03-56e4-a985-4ac21872c1aa","questionId":"d8d68d6a-dece-53a9-84d4-26fc900186be","sourceKey":"bank:BUA201:CHG-005","payload":{"prompt":"Which statement best distinguishes CHANGE LEADERSHIP from CHANGE MANAGEMENT?","options":["Change leadership creates the vision and drives people to embrace change, while change management uses structured processes and tools to implement and control it","Change leadership is done by junior staff, while change management is done only by consultants","They mean exactly the same thing","Change leadership deals only with budgets, while change management deals only with vision"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Change leadership is about the 'why' and 'what': setting a vision, inspiring and energising people to move. Change management is about the 'how': plans, schedules, training and controls that keep the change on track. Option D reverses the emphasis, option C ignores the distinction, and option B wrongly assigns them by rank."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 157, $official_bank_source${"itemId":"91f36d35-b45b-5311-958d-f90207f8e63e","questionId":"067bd30e-5d9e-5fac-b677-5b8cb61a725d","sourceKey":"bank:BUA201:CHG-006","payload":{"prompt":"The new CEO of a Nigerian bank travels to every region, paints an inspiring picture of a fully digital bank and urges staff to see themselves as innovators. This is mainly an example of:","options":["Refreezing","Coercion","Change leadership","Change management"],"correctOption":2,"section":"Managers as Change Agents","explanation":"Creating and communicating an inspiring vision and energising people to move toward it is change leadership. Option D would involve detailed implementation plans, timelines and training schedules, option A is the final stage of Lewin's model, and option B means forcing people to accept change."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 158, $official_bank_source${"itemId":"7d748092-7025-5249-8192-7fb0a2efab62","questionId":"352d0b96-f49d-5b48-b15a-5d347cff288b","sourceKey":"bank:BUA201:CHG-007","payload":{"prompt":"A project office draws up a timetable for migrating 200 branches to new software, assigns responsibilities, schedules staff training and tracks progress against milestones. This is mainly an example of:","options":["Change management","Unfreezing","Change leadership","Manipulation and co-optation"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Structured planning, scheduling, training and monitoring of a change are the tools of change management. Option C would focus on vision and inspiration, option B is the first stage of Lewin's model where readiness for change is created, and option D is a tactic for dealing with resistance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 159, $official_bank_source${"itemId":"db9638c1-25d1-57df-a365-97b5f7d09ca8","questionId":"87b7d361-2f11-564e-b9f0-192e2756ab63","sourceKey":"bank:BUA201:CHG-008","payload":{"prompt":"Which of the following is an EXTERNAL driver of organisational change?","options":["Low morale among employees","A decision to restructure departments","The appointment of a new managing director","A new government regulation affecting the industry"],"correctOption":3,"section":"Managers as Change Agents","explanation":"External drivers arise outside the organisation, such as regulation, technology, competition, economic conditions and social trends. Options C, A and B arise inside the organisation, so they are internal drivers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 160, $official_bank_source${"itemId":"6f3aebd5-3b69-5318-9f81-5433f55cc04d","questionId":"585b0739-0f82-545c-bc58-a53891ae9e07","sourceKey":"bank:BUA201:CHG-009","payload":{"prompt":"Which of the following is an INTERNAL driver of organisational change?","options":["Persistently high staff turnover","Entry of a new foreign competitor","A change in tax law","Rising inflation in the economy"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Internal drivers come from within, such as staff problems, new strategy, new leadership or poor performance. Options D, B and C all come from the external environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 161, $official_bank_source${"itemId":"a150d112-a1cd-562f-b715-7bc83ac198a6","questionId":"d519c62d-f24f-55c7-a072-bf582a377304","sourceKey":"bank:BUA201:CHG-010","payload":{"prompt":"A traditional bank finds that young customers are moving to mobile-only fintech apps, so it launches its own app and closes some branches. The main driver of this change is:","options":["An internal conflict between departments","A change in the bank's ownership structure","Technological change and competition in the external environment","A decline in the population of Nigeria"],"correctOption":2,"section":"Managers as Change Agents","explanation":"The pressure comes from outside: new technology and new competitors are changing customer behaviour, forcing the bank to adapt. Option A is internal and not described, option B is not mentioned, and option D is not true and is not the trigger in the scenario."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 162, $official_bank_source${"itemId":"fb6d37db-5f95-5f62-b83f-f781c812f122","questionId":"5032635d-d536-50a0-baf8-79a4b5e2b44f","sourceKey":"bank:BUA201:CHG-011","payload":{"prompt":"Change that is deliberately designed and implemented in advance by management to achieve specific goals is called:","options":["Incremental drift","Reactive change","Unplanned change","Planned change"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Planned change is proactive and intentional, introduced after analysis to move the organisation toward desired goals. Options B and C describe change that happens in response to events or without design, and option A is not a standard type of change."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 163, $official_bank_source${"itemId":"4424ad25-c692-5179-84fa-b97502332ece","questionId":"8fca2348-fc75-5e74-aa20-489a2e7de407","sourceKey":"bank:BUA201:CHG-012","payload":{"prompt":"Which statement best distinguishes INCREMENTAL change from TRANSFORMATIONAL change?","options":["Incremental change is always unplanned, while transformational change is always planned","Incremental change makes small, continuous improvements, while transformational change fundamentally alters strategy, structure or culture","There is no difference between them","Incremental change affects the whole organisation at once, while transformational change affects one task"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Incremental change fine-tunes existing ways of working step by step, while transformational (radical) change reshapes the organisation as a whole. Option A confuses scale with planning, option D reverses the scope, and option C ignores the distinction."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 164, $official_bank_source${"itemId":"7d0f412b-fa1a-5f51-a3b6-2b32034296fa","questionId":"528ee3b0-fc2d-58e2-abf6-1fac36d325af","sourceKey":"bank:BUA201:CHG-013","payload":{"prompt":"What is the correct order of the three stages in Kurt Lewin's change model?","options":["Unfreezing, changing (moving), refreezing","Refreezing, unfreezing, changing","Unfreezing, refreezing, changing","Changing, unfreezing, refreezing"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Lewin's model first unfreezes current behaviour by creating readiness for change, then moves to the new state, and finally refreezes the new behaviour so it becomes stable. Options D, B and C put the stages in an illogical order."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 165, $official_bank_source${"itemId":"961804f8-5f35-59b4-a5c7-77130bfc9291","questionId":"f009778f-eafa-5524-bf59-0d75ecfd8be6","sourceKey":"bank:BUA201:CHG-014","payload":{"prompt":"In Lewin's change model, the UNFREEZING stage mainly involves:","options":["Evaluating the change after it is complete","Making people aware that the current situation must change and preparing them for it","Installing the new system or structure","Making the new behaviour permanent through rewards and policies"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Unfreezing reduces attachment to old ways, often by showing evidence of problems, so that people become ready to change. Option D is refreezing, option C is the changing or moving stage, and option A is a later review step, not unfreezing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 166, $official_bank_source${"itemId":"71b639c2-79e2-5f08-aab4-cc0342d69a92","questionId":"f883352b-6d5d-517e-b9d6-1749eac56a9c","sourceKey":"bank:BUA201:CHG-015","payload":{"prompt":"In Lewin's force field analysis, an organisation's current state is kept in balance by:","options":["Only the forces pushing for change","Only the forces resisting change","The number of employees in the organisation","Driving forces pushing for change and restraining forces resisting it"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Force field analysis says the present situation is an equilibrium between driving forces and restraining forces; change occurs when driving forces are strengthened or restraining forces are reduced. Options A and B each consider only one side, and option C is irrelevant."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 167, $official_bank_source${"itemId":"6bf30d95-f15f-5777-9732-1180e1ee286d","questionId":"9965b493-3743-5e22-afe7-2764c67af67a","sourceKey":"bank:BUA201:CHG-016","payload":{"prompt":"A manager listing reasons for and against a new shift system writes 'competition from cheaper rivals' on one side and 'workers' fear of losing overtime pay' on the other. In force field terms, 'workers' fear of losing overtime pay' is a:","options":["Driving force","Scalar force","Restraining force","Refreezing force"],"correctOption":2,"section":"Managers as Change Agents","explanation":"A restraining force works against change; workers' fear of losing income makes them resist the new shift system. Option A would be the competitive pressure pushing for change, while options D and B are not terms used in force field analysis."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 168, $official_bank_source${"itemId":"e47afc36-e10b-5c10-b505-582765b46e73","questionId":"d06ebe95-ab77-5b9d-a25c-41da8f9be67a","sourceKey":"bank:BUA201:CHG-017","payload":{"prompt":"In John Kotter's eight-step model of leading change, which step comes FIRST?","options":["Anchoring new approaches in the culture","Establishing a sense of urgency","Generating short-term wins","Empowering employees for broad-based action"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Kotter argues change must begin by creating a sense of urgency so people see why the status quo cannot continue. Option A is the final step, while options C and D come in the middle of the model after a vision has been formed and communicated."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 169, $official_bank_source${"itemId":"354446eb-718d-5784-9494-3faba97d182f","questionId":"2da86bcc-4bb6-538c-9cf7-d99ac58b2c90","sourceKey":"bank:BUA201:CHG-018","payload":{"prompt":"In Kotter's eight-step model, the LAST step is:","options":["Anchoring new approaches in the organisation's culture","Developing a vision and strategy","Establishing a sense of urgency","Creating a guiding coalition"],"correctOption":0,"section":"Managers as Change Agents","explanation":"The final step makes the change stick by embedding it in the culture, norms and values. Option D is step two, option B is step three, and option C is step one."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 170, $official_bank_source${"itemId":"00132da9-9200-5ca3-b660-28396beb13c0","questionId":"822adc98-4573-579e-bce9-38f038e2fc18","sourceKey":"bank:BUA201:CHG-019","payload":{"prompt":"In Kotter's model, 'creating a guiding coalition' means:","options":["Forming a union to oppose the change","Building a group with enough power, credibility and skill to lead the change effort","Merging with another company","Asking the government to approve the change"],"correctOption":1,"section":"Managers as Change Agents","explanation":"A guiding coalition is a team of influential people inside the organisation who work together to drive the change. Option C describes a merger, option D describes regulatory approval, and option A describes resistance rather than leadership of change."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 171, $official_bank_source${"itemId":"56e79899-01b2-5e8c-a81a-a4dc942ad4cd","questionId":"6b173daa-5d2a-5880-990d-f6c95907e454","sourceKey":"bank:BUA201:CHG-020","payload":{"prompt":"Three months into a new customer-service programme, a company publicly celebrates branches that have cut queue times by half to keep momentum going. In Kotter's model, this is:","options":["Generating short-term wins","Creating a guiding coalition","Establishing a sense of urgency","Unfreezing"],"correctOption":0,"section":"Managers as Change Agents","explanation":"Visible early successes reward those involved and keep people committed, which Kotter calls generating short-term wins. Option C comes at the start before change begins, option B concerns forming the leadership team, and option D is a stage in Lewin's model, not Kotter's."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 172, $official_bank_source${"itemId":"bc35c7a7-b2e7-5c60-8512-f8a8f3ea0853","questionId":"3158d8ad-9f7d-587c-8ebf-35733f11cdf1","sourceKey":"bank:BUA201:CHG-021","payload":{"prompt":"Before introducing a new appraisal system, managers hold workshops, share data and answer questions so staff understand why the change is needed. Which method of reducing resistance is this?","options":["Manipulation and co-optation","Education and communication","Negotiation and agreement","Explicit coercion"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Education and communication reduce resistance that comes from lack of information or misunderstanding. Option D forces acceptance through threats, option A uses selective information or gives resisters a token role, and option C trades concessions for acceptance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 173, $official_bank_source${"itemId":"8fa24241-9ec1-5e69-b93c-dcbd1610307e","questionId":"8032677f-52e4-539c-bea8-9f786f1f5d3b","sourceKey":"bank:BUA201:CHG-022","payload":{"prompt":"A manager invites representatives of affected workers to help design a new work schedule, so that they feel ownership of it. This method of reducing resistance is:","options":["Facilitation and support","Participation and involvement","Explicit coercion","Negotiation and agreement"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Involving those affected in designing the change builds commitment because people rarely resist what they helped create. Option A offers training or emotional support, option C relies on threats, and option D offers incentives in exchange for acceptance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 174, $official_bank_source${"itemId":"7d23269b-208b-5167-8d13-4a1e5b57e942","questionId":"8fad2ee3-d32c-5ab3-8868-31adfda548f9","sourceKey":"bank:BUA201:CHG-023","payload":{"prompt":"To win the union's acceptance of a new automated line, management agrees to retrain affected workers and give a one-off bonus. This approach to resistance is:","options":["Participation and involvement","Manipulation and co-optation","Education and communication","Negotiation and agreement"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Offering something of value, such as retraining and a bonus, in exchange for acceptance is negotiation and agreement. Option C relies on information, option A relies on involving workers in design, and option B relies on covert influence or token roles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 175, $official_bank_source${"itemId":"9bda817c-2bc8-5283-ad08-93538ee90904","questionId":"3d769544-82fc-50a3-8109-cb81f788cfd9","sourceKey":"bank:BUA201:CHG-024","payload":{"prompt":"Management tells staff that anyone who refuses to use the new attendance system by Friday will lose their job. This approach to resistance is:","options":["Participation and involvement","Explicit and implicit coercion","Education and communication","Facilitation and support"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Using threats of dismissal or other penalties to force acceptance is coercion; it is fast but can create resentment. Options D, C and A are supportive or persuasive approaches that do not rely on threats."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 176, $official_bank_source${"itemId":"d41ec57c-c00b-5a34-8dc9-30607baac271","questionId":"2847e81f-c809-5c99-b2aa-f28fda6b6ee5","sourceKey":"bank:BUA201:CHG-025","payload":{"prompt":"Organisational development (OD) is best defined as:","options":["A method of calculating the cost of production","The legal process of registering a new company","A planned, organisation-wide effort to improve effectiveness and health using behavioural science knowledge","A one-off decision to reduce staff numbers"],"correctOption":2,"section":"Managers as Change Agents","explanation":"OD is a long-term, planned approach to change that applies behavioural science to improve how people and groups work. Option D is a single cost-cutting action, option B is incorporation, and option A is costing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 177, $official_bank_source${"itemId":"578034cb-ebb0-5cfe-b273-75c46f89ecce","questionId":"7390f47d-aebd-5e8f-88e8-774723396dd2","sourceKey":"bank:BUA201:CHG-026","payload":{"prompt":"Which of the following is NOT usually a quality of an effective managerial change agent?","options":["Building trust with employees","Communicating a clear vision of the change","Keeping plans secret from those affected until the last minute","Being willing to listen to concerns"],"correctOption":2,"section":"Managers as Change Agents","explanation":"Effective change agents communicate openly, build trust and listen, because secrecy breeds fear and rumours that feed resistance. Options B, A and D are qualities that help change succeed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 178, $official_bank_source${"itemId":"9347af44-905f-58a3-8a8c-bb62002f0669","questionId":"13310f5c-67db-5895-b382-8fd85e6ceaef","sourceKey":"bank:BUA201:CHG-028","payload":{"prompt":"As a result of the 2004-2005 banking consolidation in Nigeria, the number of banks fell from about 89 to:","options":["10","50","75","25"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Banks that could not meet the N25 billion capital requirement merged or were acquired, reducing the number of banks from 89 to 25. Options A, B and C do not reflect the outcome of the exercise."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 179, $official_bank_source${"itemId":"b9d4b13c-08ac-5798-a031-acfe7e97c749","questionId":"335a01b6-067c-5375-b95b-c37ac272cf33","sourceKey":"bank:BUA201:CHG-029","payload":{"prompt":"Under the bank recapitalisation programme announced by the CBN in March 2024, the new minimum capital for a commercial bank with an INTERNATIONAL licence is:","options":["N25 billion","N500 billion","N200 billion","N50 billion"],"correctOption":1,"section":"Managers as Change Agents","explanation":"The March 2024 circular set N500 billion for international commercial banks, N200 billion for national banks and N50 billion for regional banks, with a deadline of 31 March 2026. Option C is the national licence threshold, option D is the regional threshold, and option A is the 2004 consolidation figure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 180, $official_bank_source${"itemId":"df88147a-7ec9-5dc0-b976-eb38ce9d4972","questionId":"3e08cc96-8592-5d97-aca6-ec1690c622b4","sourceKey":"bank:BUA201:CHG-030","payload":{"prompt":"Under the CBN's 2024 bank recapitalisation programme, banks were required to meet the new capital thresholds by:","options":["31 March 2026","31 December 2024","31 December 2030","31 March 2025"],"correctOption":0,"section":"Managers as Change Agents","explanation":"The March 2024 circular gave banks 24 months to comply, so the deadline was 31 March 2026. Options B, D and C do not match the compliance window set by the CBN."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 181, $official_bank_source${"itemId":"6440e154-3fdf-51a6-b638-82a990925789","questionId":"e9c4432d-5d29-5d78-9073-ccb665533239","sourceKey":"bank:BUA201:CHG-031","payload":{"prompt":"When the CBN raised minimum bank capital in 2004 and again in 2024, bank managers had to raise fresh capital, merge or change their licence category. For those managers, the recapitalisation was mainly:","options":["An example of refreezing","An internal driver arising from staff conflict","A purely voluntary incremental change","An external, regulatory driver of change"],"correctOption":3,"section":"Managers as Change Agents","explanation":"The pressure came from a regulator outside the banks, so it was an external regulatory driver that forced major, often transformational change. Option B is internal and not the trigger, option C ignores that compliance was mandatory, and option A is the final stage of Lewin's model, not a driver."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 182, $official_bank_source${"itemId":"f0c458d2-932b-52bd-bc2b-0ea16fd799c4","questionId":"04e2ca4f-0dc9-5f27-ad68-e999cad6312a","sourceKey":"bank:BUA201:CHG-032","payload":{"prompt":"Nigeria's telecommunications revolution began when GSM licences were auctioned in January 2001. The regulator that conducted the auction was the:","options":["Bureau of Public Enterprises (BPE)","Central Bank of Nigeria (CBN)","Corporate Affairs Commission (CAC)","Nigerian Communications Commission (NCC)"],"correctOption":3,"section":"Managers as Change Agents","explanation":"The NCC regulates telecommunications in Nigeria and conducted the January 2001 GSM licence auction. Option B regulates banks, option C registers companies and business names, and option A handles privatisation of public enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 183, $official_bank_source${"itemId":"25273593-46f4-515e-b105-6cf129dc0b69","questionId":"b505d81c-c969-58f3-9a9e-2b764de4dc35","sourceKey":"bank:BUA201:CHG-033","payload":{"prompt":"At Nigeria's January 2001 GSM licence auction, each of the successful bidders paid a licence fee of:","options":["2.85 billion US dollars","855 million US dollars","20 million US dollars","285 million US dollars"],"correctOption":3,"section":"Managers as Change Agents","explanation":"Each GSM licence cost 285 million US dollars. Option C was only the deposit included in that price, option B was the total raised from all three licences, and option A overstates the fee tenfold."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 184, $official_bank_source${"itemId":"a457d397-6acb-5265-a07b-eabb05ba02ad","questionId":"78b22feb-2ba5-5f8f-b154-ff1c10c0c45a","sourceKey":"bank:BUA201:CHG-034","payload":{"prompt":"Which two operators launched commercial GSM services in Nigeria in August 2001 after winning licences at the January 2001 auction?","options":["9mobile and Airtel","Globacom and Airtel","Econet Wireless and MTN Nigeria","NITEL and Globacom"],"correctOption":2,"section":"Managers as Change Agents","explanation":"Econet Wireless began commercial operations on 7 August 2001 and MTN followed a day later. Globacom entered later through a 2002 process, so options B and D are wrong, and option A names brands that did not exist under those names in 2001."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 185, $official_bank_source${"itemId":"49066970-b372-570a-b5f5-55234c20484d","questionId":"54e516ce-f266-59e1-85e4-da4011384c57","sourceKey":"bank:BUA201:CHG-035","payload":{"prompt":"The Petroleum Industry Act (PIA), a major change in Nigeria's oil and gas sector, was signed into law in:","options":["August 2021","March 2024","December 2015","January 2001"],"correctOption":0,"section":"Managers as Change Agents","explanation":"President Muhammadu Buhari signed the PIA on 16 August 2021. Option D is when GSM licences were auctioned, option B is when the CBN announced bank recapitalisation, and option C is not linked to the Act."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 186, $official_bank_source${"itemId":"a2dec95c-93d7-5a5d-97fc-1073a041d54a","questionId":"abb934b8-672a-5a4a-9805-128c16ffc627","sourceKey":"bank:BUA201:CHG-036","payload":{"prompt":"One major structural change made by the Petroleum Industry Act 2021 was that NNPC was to be:","options":["Turned into a partnership of state governments","Converted into a cooperative society owned by its workers","Abolished and its assets sold to foreign oil firms","Incorporated as a limited liability company with the Corporate Affairs Commission"],"correctOption":3,"section":"Managers as Change Agents","explanation":"The PIA required NNPC to be incorporated as a limited liability company with the CAC, with the Ministries of Finance and Petroleum as shareholders, so it would run on commercial lines. Options C, B and A do not describe what the Act provided."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 187, $official_bank_source${"itemId":"1e6c805d-0d88-5d0f-93c7-1d3df174c6cf","questionId":"2a1f82c5-3bfe-520e-a337-adcda6a1bb97","sourceKey":"bank:BUA201:CHG-037","payload":{"prompt":"Under the Petroleum Industry Act 2021, upstream companies must contribute to host community development trusts an amount equal to what percentage of their actual annual operating expenditure of the preceding year?","options":["5%","1%","3%","10%"],"correctOption":2,"section":"Managers as Change Agents","explanation":"The PIA requires settlors to contribute 3% of their actual annual operating expenditure in upstream operations from the preceding year to host community trusts. Options B, A and D do not match the percentage in the Act."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 188, $official_bank_source${"itemId":"a6305cd5-e54f-5b58-8caa-fe691bb06bff","questionId":"be2bb982-2a31-5758-9bc7-07c206e926bf","sourceKey":"bank:BUA201:CHG-038","payload":{"prompt":"To regulate the oil and gas industry, the Petroleum Industry Act 2021 created:","options":["A single regulator for banks and oil companies","Separate regulators for each of the 36 states","No regulator, leaving the industry fully self-regulated","Two regulators, one for upstream and one for midstream and downstream operations"],"correctOption":3,"section":"Managers as Change Agents","explanation":"The Act created an upstream regulatory commission and a separate midstream and downstream regulatory authority. Options A, C and B do not describe the structure the Act set up."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 189, $official_bank_source${"itemId":"8a270890-d6a0-5289-ae1b-ce0e9678614f","questionId":"34b35803-698f-5ff1-b8ea-38aae6571a89","sourceKey":"bank:BUA201:CHG-039","payload":{"prompt":"When GSM operators arrived in 2001, many Nigerian firms quickly changed how they sold goods, communicated with customers and managed staff in the field. For those firms, GSM was mainly a:","options":["Internal driver of change caused by poor morale","Technological driver of change in the external environment","Refreezing activity","Form of business ownership"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Mobile telephony was a new technology arising outside the firms that forced them to change their processes, which makes it an external technological driver. Option A is internal and unrelated, option D confuses a driver of change with ownership forms, and option C is the last stage in Lewin's model."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 190, $official_bank_source${"itemId":"2b8f36e7-19f4-5d9b-8b68-78867fbe1768","questionId":"8b9217eb-7f22-50c5-ada8-d80809e7fe5b","sourceKey":"bank:BUA201:CHG-040","payload":{"prompt":"Which of the following is NOT a common reason why change efforts fail?","options":["Failing to create a sense of urgency","Clear communication of the reasons for change","Declaring victory too soon","Not anchoring the change in the culture"],"correctOption":1,"section":"Managers as Change Agents","explanation":"Clear communication helps change succeed, so it is not a reason for failure. Options A, C and D are classic causes of failed change efforts, each mirroring a step in Kotter's model that was skipped."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 191, $official_bank_source${"itemId":"c701bcc0-6fcb-58ba-b877-db7edcd6b946","questionId":"ee9b30ab-34ed-59b2-9588-fbb7679f4e4e","sourceKey":"bank:BUA201:PQ-006","payload":{"prompt":"A company that exists as a separate legal entity from its owners, able to own property, sue and be sued in its own name, demonstrates:","options":["Corporate personality","Perpetual partnership","Mutual agency","Unlimited liability"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Corporate personality means that once incorporated, a company is a legal person distinct from its shareholders. Option D is a feature of sole proprietorships and ordinary partnerships, and option C is the partnership rule that each partner can bind the others."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 192, $official_bank_source${"itemId":"0692dd3d-6257-5673-93ab-f996209dcfdc","questionId":"b980bdc1-7775-53a1-b5d5-d36026983e27","sourceKey":"bank:BUA201:PQ-007","payload":{"prompt":"Which of the following is a major weakness of a sole proprietorship?","options":["Heavy regulatory burden","Separation of ownership and control","Limited access to capital","Double taxation"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A sole proprietor usually depends on personal savings, family and small loans, so raising large capital is difficult. Options D and B are features associated with companies, not one-person businesses, and sole proprietorships actually face the lightest regulation of all ownership forms."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 193, $official_bank_source${"itemId":"cfe44280-a15c-547f-bfed-d330f25b2a54","questionId":"d78203a2-ec69-55ab-b17f-159ca9f8d7e7","sourceKey":"bank:BUA201:PQ-008","payload":{"prompt":"Under section 305 of Nigeria's Companies and Allied Matters Act (CAMA) 2020, in force since 2020, a director stands in a fiduciary relationship primarily towards:","options":["The company itself","Shareholders","Customers","Employees"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"CAMA 2020 states that a director stands in a fiduciary relationship towards the company and must act in the best interests of the company as a whole. Option B is the most tempting, but because the company is a separate legal person, the duty is owed to the company rather than to individual shareholders; employees and customers are interests directors may consider, not the party the duty is owed to."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 194, $official_bank_source${"itemId":"b3674eab-1a4b-5f81-871e-836170b29a0c","questionId":"9bfe7ae1-b4ef-5e2b-8730-ab5a00032643","sourceKey":"bank:BUA201:PQ-037","payload":{"prompt":"A public limited company (PLC) differs from a private limited company mainly in that a PLC:","options":["Gives its members limited liability","Is owned by members who share profits according to patronage","Has legal personality","Can invite the public to subscribe for its shares"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"The main distinction is that a public company may offer its shares to the general public, for example through the stock exchange, while a private company cannot. Options C and A are shared by both types of company, and option B describes a cooperative society."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 195, $official_bank_source${"itemId":"d9ac4b1e-5087-5548-8ee3-448c810841d4","questionId":"704779f8-1978-5234-b94b-1d4ee230d273","sourceKey":"bank:BUA201:PQ-062","payload":{"prompt":"A cooperative society mainly aims to:","options":["Earn capital market returns","Maximise wealth for outside investors","Obtain a stock exchange listing","Provide benefits to its members"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"A cooperative is owned and controlled by members who join together to meet common needs, and surpluses are shared among members. Options B, C and A describe the goals of investor-owned public companies."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 196, $official_bank_source${"itemId":"f5785c6a-09da-5a17-ab6f-77ea21892942","questionId":"ef873332-9bee-50a8-8953-01f61eb7d278","sourceKey":"bank:BUA201:PQ-083","payload":{"prompt":"A franchisor earns revenue mainly through:","options":["Royalties and franchise fees","Interest income","Dividends only","Debt instruments"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"In a franchise, the franchisor lets the franchisee use its brand name and business system in return for an initial franchise fee and ongoing royalties, usually a share of sales. Option B is income from lending, and option D is a way of borrowing or lending money, not a franchise payment. Option C is wrong because a franchisee is an independent business, not a company paying the franchisor dividends."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 197, $official_bank_source${"itemId":"61583112-8444-525d-8a01-e3795ba9906e","questionId":"e2933e1d-c343-5062-bf62-b0edbbd81ac5","sourceKey":"bank:BUA201:PQ-103","payload":{"prompt":"Which form of business organisation BEST combines limited liability with operational flexibility?","options":["Private limited company","Sole proprietorship","Partnership","Public limited company"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A private limited company gives its owners limited liability while keeping ownership in a small group, with fewer disclosure and listing obligations than a public company, so it remains flexible to run. Options B and C are flexible but their owners usually have unlimited liability. Option D has limited liability but faces stricter rules, public disclosure and shareholder pressure, which reduce flexibility."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 198, $official_bank_source${"itemId":"85566e4c-79d1-5d0f-85f2-17aae89c4487","questionId":"500e69a6-bab2-5e29-a216-9c5047de1580","sourceKey":"bank:BUA201:PQ-104","payload":{"prompt":"The emergence of joint-stock companies was driven mainly by the need to:","options":["Eliminate competition","Reduce government interference","Increase managerial control","Finance large-scale ventures"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Joint-stock companies arose because ventures such as long-distance trade, railways and large factories needed more capital than one person or a few partners could provide, so the capital was divided into shares sold to many investors. Option A was not the purpose, option B is wrong because these companies were created under the law, and option C is wrong because spreading ownership actually made it harder for owners to control managers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 199, $official_bank_source${"itemId":"3d0a4a59-f5cc-5433-bab4-9b5d495a79cc","questionId":"5fb56d8d-c758-52a9-a75e-41403119f2bd","sourceKey":"bank:BUA201:PQ-106","payload":{"prompt":"The doctrine of separate legal entity mainly protects shareholders from:","options":["All business losses","Managerial inefficiency","Taxation","Personal liability for the company's debts"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Because a registered company is a legal person separate from its members, its debts belong to the company, and shareholders with limited liability can lose at most what they invested. Option A is wrong because shareholders still bear losses through a fall in the value of their shares. Options B and C are not things the doctrine guards against."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 200, $official_bank_source${"itemId":"06fdd90b-f0b5-5206-9bfb-1274a0c89958","questionId":"d62f6025-7869-5dba-8311-276be42d7e06","sourceKey":"bank:BUA201:PQ-138-b","payload":{"prompt":"Modern corporate entities differ from early forms of business such as sole traders mainly because they have:","options":["Only one owner who manages everything","A separate legal personality and limited liability for their members","Unlimited liability for all owners","No need to register with any authority"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A modern company is a legal person in its own right, separate from its shareholders, who usually have limited liability; this lets it raise capital from many investors and continue beyond the life of any owner. Option A describes a sole proprietorship, option C describes sole traders and ordinary partnerships, and option D is wrong because companies must be registered."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 201, $official_bank_source${"itemId":"106cc8c1-ee4d-5a79-a1e2-0b70198cc0a7","questionId":"0a283b66-8f5f-5b12-98ed-995d19de6c3b","sourceKey":"bank:BUA201:PQ-139-a","payload":{"prompt":"An entrepreneur who needs to raise substantial capital while protecting the owners' personal assets from business debts should MOST likely choose a:","options":["Sole proprietorship","Ordinary partnership","Business name registered to one person","Limited liability company"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"A limited liability company can bring in capital from several shareholders, and their liability is limited to their investment, so their personal assets are protected. Options A, B and C all expose the owners to unlimited personal liability and usually have limited ability to raise large capital."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 202, $official_bank_source${"itemId":"22d3b16c-b9b9-5bf7-b13d-70cdc5ef30f6","questionId":"12640820-9dbd-5565-926d-afa95db87e60","sourceKey":"bank:BUA201:PQ-139-b","payload":{"prompt":"As at 2026, which body registers companies and business names in Nigeria under the Companies and Allied Matters Act (CAMA) 2020?","options":["The Nigerian Institute of Management","The Corporate Affairs Commission (CAC)","The Central Bank of Nigeria","The Securities and Exchange Commission"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"The Corporate Affairs Commission administers CAMA 2020 and is responsible for registering companies, business names and incorporated trustees in Nigeria, which makes registration a legal factor in choosing an ownership form. Option A regulates the management profession, option C regulates banks and monetary policy, and option D regulates the capital market."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 203, $official_bank_source${"itemId":"813bab2e-15d6-5cf2-a801-ca7462b53557","questionId":"6317a4f1-f4fc-58b6-9d13-3111a356227a","sourceKey":"bank:BUA201:OWN-001","payload":{"prompt":"A business owned and controlled by one person, who takes all the profits and bears all the risks, is a:","options":["Sole proprietorship","Private limited company","Cooperative society","Partnership"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A sole proprietorship has a single owner who makes all the decisions, keeps all the profit and carries all the losses. Option D has two or more owners, option B is a separate legal person owned by shareholders, and option C is owned by its members for mutual benefit."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 204, $official_bank_source${"itemId":"3668050e-3444-517f-acd9-6147be3c00c2","questionId":"6fc7c161-5668-5e78-b4d3-af009bac144e","sourceKey":"bank:BUA201:OWN-002","payload":{"prompt":"'Unlimited liability', as it applies to a sole proprietor, means that:","options":["The owner's losses are limited to the capital invested","The business can never be closed down","The owner's personal assets can be taken to pay the debts of the business","The owner can borrow without any limit"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"With unlimited liability, there is no legal separation between the owner and the business, so creditors can claim the owner's house, car or savings to settle business debts. Option D confuses liability with borrowing capacity, option B confuses it with continuity, and option A describes limited liability."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 205, $official_bank_source${"itemId":"635b49de-ac3e-5089-98d2-3fea423b8cc6","questionId":"0aa57bbb-20ab-56c7-b525-824199d02c63","sourceKey":"bank:BUA201:OWN-003","payload":{"prompt":"Ngozi runs a fashion shop as a sole proprietor. The business owes suppliers N3,000,000 but has assets worth only N1,000,000. Which statement is correct?","options":["Only the shop's landlord is liable for the shortfall","The suppliers must write off the N2,000,000 by law","Ngozi can be made to pay the remaining N2,000,000 from her personal assets","Ngozi owes nothing beyond the N1,000,000 in the business"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A sole proprietor has unlimited liability, so the N2,000,000 shortfall can be recovered from her personal property. Option D would only be true if the business had limited liability, while options B and A have no legal basis."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 206, $official_bank_source${"itemId":"28d48f81-9534-5d8c-bbae-326f05554a2c","questionId":"84c7c36d-0da2-5762-be61-cf40114d9dac","sourceKey":"bank:BUA201:OWN-004","payload":{"prompt":"Which of the following is an ADVANTAGE of a sole proprietorship?","options":["Continuity of existence after the owner's death","Easy access to large amounts of capital","Quick decision-making, because the owner does not need to consult anyone","Limited liability of the owner"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Because one person owns and controls the business, decisions can be made quickly and flexibly. Options B, D and A are actually features a sole proprietorship lacks: its capital is limited to what one person can raise, the owner's liability is unlimited, and it lacks continuity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 207, $official_bank_source${"itemId":"85845310-e370-5926-b499-755fbcec39c8","questionId":"e39bccfb-a4c1-5371-bfd1-d944caf97567","sourceKey":"bank:BUA201:OWN-005","payload":{"prompt":"Mr Adewale's well-run printing shop in Ibadan closes after his sudden death because nobody else is legally entitled to continue it. This illustrates the sole proprietorship's problem of:","options":["Lack of continuity","Excessive regulation by shareholders","Separation of ownership and control","Double taxation"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A sole proprietorship is not separate from its owner, so it usually ends when the owner dies or becomes incapacitated. Option D relates to companies whose profits are taxed and then dividends taxed again, option C is a feature of large companies, and option B does not apply since there are no shareholders."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 208, $official_bank_source${"itemId":"22e3576f-09ea-59d9-9248-db5ad20bd1b4","questionId":"939ae78f-ba15-5884-bb1b-073c823e8816","sourceKey":"bank:BUA201:OWN-006","payload":{"prompt":"In Nigeria, a sole trader who wants to trade under a name other than his or her own true name should register a business name with the:","options":["Bureau of Public Enterprises (BPE)","Central Bank of Nigeria (CBN)","Nigerian Communications Commission (NCC)","Corporate Affairs Commission (CAC)"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Business names, companies, limited partnerships and limited liability partnerships are registered with the CAC under CAMA 2020. Option B regulates banks, option C regulates telecommunications, and option A handles privatisation of government enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 209, $official_bank_source${"itemId":"1b450c20-2f63-5abe-b309-4bb8f38278e7","questionId":"d785f50f-b107-5b77-bf60-240ee56263bb","sourceKey":"bank:BUA201:OWN-007","payload":{"prompt":"A partnership is best defined as:","options":["The relationship between persons carrying on a business in common with a view of profit","A company owned by the government and private investors","A business owned by one person with the help of family members","An association of members who buy goods in bulk for their own use"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"This is the classic definition of a partnership: two or more persons jointly carrying on a business to make profit. Option B describes a mixed or joint venture enterprise, option D describes a consumer cooperative, and option C remains a sole proprietorship."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 210, $official_bank_source${"itemId":"3d8303db-8b6a-54ef-89a6-105cb1ebe81f","questionId":"82ed8ea8-dce7-5c48-be94-98a4feb15aa7","sourceKey":"bank:BUA201:OWN-008","payload":{"prompt":"Under section 19 of CAMA 2020, an ordinary partnership formed to carry on business for profit may NOT have more than how many persons unless it is registered as a company or formed under another enactment?","options":["20","10","100","50"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Section 19(1) of CAMA 2020 forbids an association or partnership of more than 20 persons carrying on business for profit unless it is registered as a company or formed under another law. Option D is the maximum membership of a private company, and options B and C are not the statutory limit."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 211, $official_bank_source${"itemId":"d7740c36-6422-50f3-936d-af37eeac69bf","questionId":"6050859e-286c-5850-8c52-4e137a599c39","sourceKey":"bank:BUA201:OWN-009","payload":{"prompt":"Section 19 of CAMA 2020 limits partnerships to 20 persons, but this limit does NOT apply to which of the following?","options":["A partnership of building contractors","A partnership of legal practitioners or of accountants","A partnership of transport operators","A partnership of traders in a market"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Section 19(2) exempts partnerships of legal practitioners and of accountants, as well as registered cooperative societies, from the 20-person limit. Options D, C and A are ordinary trading partnerships and remain subject to the limit."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 212, $official_bank_source${"itemId":"96ec238e-596f-5788-952a-9cd7bd435f27","questionId":"daad98a6-9c57-5969-ad71-265b33b7e75e","sourceKey":"bank:BUA201:OWN-010","payload":{"prompt":"A partner who contributes capital and shares in profits but takes no active part in managing the business is called a:","options":["Sleeping (dormant) partner","Nominal partner","Active (general) partner","Managing director"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A sleeping or dormant partner provides capital and shares profits but does not take part in day-to-day management. Option C takes part in running the business, option B lends only his or her name and usually contributes no capital, and option D is an officer of a company, not a type of partner."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 213, $official_bank_source${"itemId":"4959cc5b-2975-59f1-ade2-387b23d49d74","questionId":"b0991b0a-892a-5701-81d0-5c617c97230a","sourceKey":"bank:BUA201:OWN-011","payload":{"prompt":"A person who allows his or her name to be used by a partnership to boost its reputation, but contributes no capital and takes no part in management, is a:","options":["Limited partner","Nominal partner","Active partner","Sleeping partner"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A nominal partner lends only his or her name and goodwill to the firm and can still be held liable to outsiders who relied on that name. Option D contributes capital, option A contributes capital with liability limited to it, and option C manages the business."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 214, $official_bank_source${"itemId":"1d99c22a-c01d-5897-a376-654dad64fa66","questionId":"94ad7307-6fd7-5e67-aee7-b87338ed9abf","sourceKey":"bank:BUA201:OWN-012","payload":{"prompt":"Which of the following is NOT usually contained in a partnership deed?","options":["The capital contributed by each partner","The ratio in which profits and losses are shared","The procedure for admitting or retiring a partner","The company's memorandum of association"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"A partnership deed sets out the terms between partners, such as capital, profit-sharing ratio, interest on capital, drawings and admission or retirement of partners. A memorandum of association is a company's constitutional document, not part of a partnership deed. Options B, A and C are typical contents of a deed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 215, $official_bank_source${"itemId":"d1835d9f-449f-500a-9e5b-47285c594f55","questionId":"1e5d4055-d6f5-5287-97f6-8f70854ef3ea","sourceKey":"bank:BUA201:OWN-013","payload":{"prompt":"Where partners have no written or oral agreement on how profits are to be shared, the general rule is that profits and losses are shared:","options":["In proportion to capital contributed","Entirely by the senior partner","In proportion to hours worked","Equally among the partners"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"In the absence of agreement, partnership law treats partners as entitled to share profits equally and to contribute equally to losses. Option A applies only if the partners agree to it, while options C and B have no basis in the default rule."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 216, $official_bank_source${"itemId":"1739a82c-8c51-5e57-9e04-968fe7e2c978","questionId":"64df9fb1-8b98-521c-8f37-0459d55a38bf","sourceKey":"bank:BUA201:OWN-014","payload":{"prompt":"In an ordinary partnership, 'joint and several liability' means that:","options":["Partners are liable together, and each partner can also be held personally liable for all the firm's debts","No partner is personally liable for the firm's debts","Each partner is liable only for his or her own share of debts","Only the senior partner is liable for the firm's debts"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Creditors of an ordinary partnership can sue the partners together or any one of them for the full debt, leaving that partner to recover contributions from the others. Option C wrongly limits liability to a share, option D wrongly limits it to one partner, and option B describes limited liability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 217, $official_bank_source${"itemId":"fb77e9b8-baeb-5cb3-833a-7323df8a4b99","questionId":"0bdf2ca2-398b-5e92-a67c-4203f7bec7e4","sourceKey":"bank:BUA201:OWN-015","payload":{"prompt":"The principle of 'mutual agency' in a partnership means that:","options":["Only a sleeping partner can sign contracts","The partnership cannot enter into contracts","Partners must employ agents to make contracts for them","Each partner can bind the firm and the other partners by acts done in the ordinary course of business"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Every partner is an agent of the firm and of the other partners for ordinary business, so a contract one partner makes binds all. Options C, A and B misdescribe or deny this authority."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 218, $official_bank_source${"itemId":"3aa26776-7509-559d-8139-72ece6d60666","questionId":"338bf522-96b3-5307-8f40-da6e4de7f2b2","sourceKey":"bank:BUA201:OWN-016","payload":{"prompt":"Under CAMA 2020, a limited partnership must have at least:","options":["One general partner and one limited partner","Two limited partners and no general partner","Twenty partners","One limited partner only"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"A limited partnership needs at least one general partner, who is liable for all the firm's debts, and at least one limited partner, whose liability is capped at the capital contributed. Options B and D leave out the general partner the law requires, and option C confuses the minimum with the 20-partner maximum."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 219, $official_bank_source${"itemId":"10febe78-ab25-5750-8a2b-180fafa0d40c","questionId":"0d5cded2-311d-56fb-b892-52cdc6ac8aa5","sourceKey":"bank:BUA201:OWN-017","payload":{"prompt":"Funke is a limited partner in a registered limited partnership. She begins to take part in managing the firm and signs contracts on its behalf. Under CAMA 2020 the likely result is that she:","options":["Is protected even more strongly from the firm's debts","Automatically becomes a director of a company","Becomes liable for the firm's debts incurred while she takes part in management","Loses her share of the profits permanently"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A limited partner's protection depends on staying out of management; if she takes part in management, she becomes liable for debts incurred during that period like a general partner. Options B, D and A do not describe this legal consequence."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 220, $official_bank_source${"itemId":"de8075e3-c61a-5c2a-9eb8-751f4ca4cecf","questionId":"941b23d1-7ef0-5d10-b13a-4436bce40996","sourceKey":"bank:BUA201:OWN-018","payload":{"prompt":"Which of the following is a feature of a limited liability partnership (LLP) under CAMA 2020?","options":["Its partners have unlimited liability for all its debts","It is a separate legal person that can sue and be sued and hold property in its own name","It needs no registration with any authority","It must have more than 50 partners"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"CAMA 2020 introduced the LLP as a body with its own legal personality and limited liability for partners, registered with the CAC. Option A describes an ordinary partnership, option D is not a requirement, and option C is wrong because LLPs must be registered."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 221, $official_bank_source${"itemId":"a24ef58a-2f79-598e-bc27-3d5531d14a39","questionId":"d9041e48-41c6-51b1-9b68-5cad382c3e4f","sourceKey":"bank:BUA201:OWN-019","payload":{"prompt":"Under CAMA 2020, a limited liability partnership must have at least two designated partners who are individuals, and at least one of them must be:","options":["Resident in Nigeria","A lawyer","A Nigerian civil servant","A chartered accountant"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"CAMA 2020 requires at least two designated partners who are individuals, with at least one resident in Nigeria, so there is always someone locally responsible for compliance. Options B, D and C are not requirements of the Act."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 222, $official_bank_source${"itemId":"45cf9663-c0d6-55ac-b1b1-70047874e96f","questionId":"5a189c5b-0e55-5652-b158-b64facdb1a1d","sourceKey":"bank:BUA201:OWN-020","payload":{"prompt":"The legal principle that a registered company is a separate legal person, distinct from its members, is associated with the case of:","options":["Carlill v Carbolic Smoke Ball Co (1893)","Donoghue v Stevenson (1932)","Foss v Harbottle (1843)","Salomon v Salomon and Co Ltd (1897)"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Salomon v Salomon established that once a company is properly incorporated it is a legal person separate from its shareholders, even a dominant one. Option B is the key negligence case, option A concerns offer and acceptance in contract, and option C concerns who may sue for wrongs done to a company."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 223, $official_bank_source${"itemId":"2a2c218a-3b11-52f6-be11-d025715d635d","questionId":"6c313fd8-a87d-55eb-b6c7-8a0dfa7da5e9","sourceKey":"bank:BUA201:OWN-021","payload":{"prompt":"The feature of a company by which it continues to exist even when its shareholders die or sell their shares is called:","options":["Unity of command","Limited liability","Perpetual succession","Mutual agency"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Perpetual succession means the company's life does not depend on the life or membership of its shareholders; it continues until it is wound up. Option B limits members' losses to their unpaid shares, option D is a partnership principle, and option A is a management principle."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 224, $official_bank_source${"itemId":"d5e652fb-ab88-5b56-9490-e03e84a51203","questionId":"79813ec1-028a-51c7-9bbd-88b946f248eb","sourceKey":"bank:BUA201:OWN-022","payload":{"prompt":"In a company limited by shares, the liability of a member is limited to:","options":["The amount he or she agreed to contribute on winding up","Twice the nominal value of his or her shares","The total debts of the company","The amount, if any, unpaid on the shares he or she holds"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"In a company limited by shares, once a member has fully paid for the shares, he or she cannot be asked to contribute more to the company's debts. Option C describes unlimited liability, option A describes a company limited by guarantee, and option B has no legal basis."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 225, $official_bank_source${"itemId":"268adf57-a78f-566d-a2a2-ea61462bbb71","questionId":"92e8b054-0637-586a-bb85-6cb37ce65747","sourceKey":"bank:BUA201:OWN-023","payload":{"prompt":"Under section 21 of CAMA 2020, which of the following is a type of company that may be registered?","options":["A company limited by guarantee","A cooperative society","A limited partnership","A business name"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Section 21 recognises companies limited by shares, companies limited by guarantee and unlimited companies. Options D and C are registered with the CAC but are not companies, and option B is formed under cooperative law."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 226, $official_bank_source${"itemId":"80ac2ba0-aade-551d-9f16-6fcdf102e94b","questionId":"9a38c35c-5f7d-53e4-a5b1-d0b17a83b2b8","sourceKey":"bank:BUA201:OWN-024","payload":{"prompt":"In a company limited by guarantee, a member's liability is limited to:","options":["Nothing at all in any circumstance","The amount he or she undertook to contribute to the company's assets if it is wound up","All the company's debts without limit","The amount unpaid on his or her shares"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Members of a guarantee company promise to contribute a stated amount if the company is wound up, and that guarantee sets the limit of their liability. Option D describes a company limited by shares, option A ignores the guarantee, and option C describes an unlimited company."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 227, $official_bank_source${"itemId":"7bf444ac-858c-54f7-bc0e-6e2c5dcfe5e2","questionId":"b36e56e7-429d-5d73-b77f-62c0d6d2df05","sourceKey":"bank:BUA201:OWN-025","payload":{"prompt":"A group of alumni wants to register a body in Lagos to promote education and award scholarships, with no profits distributed to members. The most suitable type of company is a:","options":["Public company limited by shares","Private company limited by shares","Company limited by guarantee","Unlimited company"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Companies limited by guarantee are formed to promote objects such as education, charity, science or culture, and their income is not distributed to members. Options A and B are designed to make and distribute profits to shareholders, and option D would expose members to unlimited liability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 228, $official_bank_source${"itemId":"df56d242-af63-5965-9132-9d5030ef720b","questionId":"0b5869e7-dbed-50f8-afb7-d9df6952690a","sourceKey":"bank:BUA201:OWN-026","payload":{"prompt":"In an unlimited company, if the company's liabilities exceed its assets on winding up:","options":["Members lose only the amount they guaranteed","Creditors cannot recover anything from members","Members lose only the amount unpaid on their shares","Members can be required to contribute from their personal assets to settle the shortfall"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Members of an unlimited company have no limit on their liability, so creditors can reach their personal property through contributions on winding up. Option C applies to companies limited by shares, option A to companies limited by guarantee, and option B contradicts unlimited liability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 229, $official_bank_source${"itemId":"2bd9f944-36fb-5f7b-b24f-1b1e57e886ea","questionId":"d08f2857-7518-536f-bdd4-50d226228916","sourceKey":"bank:BUA201:OWN-027","payload":{"prompt":"Under CAMA 2020, the minimum issued share capital of a PRIVATE company is:","options":["N10,000","N2,000,000","N500,000","N100,000"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Section 27(2)(a) of CAMA 2020 sets the minimum issued share capital at N100,000 for a private company and N2,000,000 for a public company. Option B is the public company figure, while options A and C are not the statutory minimum."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 230, $official_bank_source${"itemId":"38afbf6e-5d37-53dc-ad2e-b66fbc56ba57","questionId":"bf66d255-844a-537c-84ea-a7b4cae80d7f","sourceKey":"bank:BUA201:OWN-028","payload":{"prompt":"Under CAMA 2020, the minimum issued share capital of a PUBLIC company is:","options":["N100,000","N2,000,000","N25,000,000","N500,000"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Section 27(2)(a) of CAMA 2020 requires a public company to have a minimum issued share capital of N2,000,000. Option A is the private company minimum, while options D and C do not match the Act."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 231, $official_bank_source${"itemId":"116ba594-345b-56ac-82eb-cccfb2f78777","questionId":"b4e45667-82d8-5d72-8904-06894a11d88a","sourceKey":"bank:BUA201:OWN-029","payload":{"prompt":"Which of the following was introduced by CAMA 2020?","options":["One person may form a private company (a single-member company)","A private company must have at least seven members","Partnerships may have unlimited numbers of partners","Public companies may have only one member"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Section 18(2) of CAMA 2020 allows one person to form and incorporate a private company, which was not possible under the previous law. Option B does not reflect the law, option C contradicts the 20-person limit in section 19, and option D is wrong because a public company needs at least two members."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 232, $official_bank_source${"itemId":"624cc5b4-9e7d-5d1f-a0e9-90bfda7370f7","questionId":"e2856550-30d9-5433-a380-f1ef82242a3a","sourceKey":"bank:BUA201:OWN-030","payload":{"prompt":"Under CAMA 2020, the maximum number of members of a PRIVATE company (joint holders of a share counting as one) is:","options":["20","7","50","There is no maximum"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A private company's membership is limited to 50, with joint holders of shares treated as one member. Option A is the limit for ordinary partnerships, option B is not the rule, and option D describes a public company, which has no maximum."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 233, $official_bank_source${"itemId":"294951f3-05dc-56e0-a6cb-5bb177b669fb","questionId":"fb7b6cdf-e50f-59c2-9508-b5e67307087c","sourceKey":"bank:BUA201:OWN-031","payload":{"prompt":"Which of the following correctly distinguishes a PRIVATE company from a PUBLIC company under CAMA 2020?","options":["A private company is owned by government, while a public company is owned by private investors","A private company restricts the transfer of its shares and may not invite the public to subscribe for its shares, while a public company may","A private company must have at least two members, while a public company may have one","A private company has unlimited liability, while a public company has limited liability"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Private companies must restrict share transfers and cannot offer shares or debentures to the public, while public companies can raise capital from the public. Option D confuses private status with liability, option C reverses the membership rules, and option A confuses 'public company' with a government-owned enterprise."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 234, $official_bank_source${"itemId":"83cf6e4f-e811-5360-b0b3-2aee854ae16e","questionId":"916bb98e-4de6-5683-b9ff-fa44b7c5c792","sourceKey":"bank:BUA201:OWN-032","payload":{"prompt":"Under CAMA 2020, a small company is NOT required to:","options":["Register with the Corporate Affairs Commission","Keep any accounting records at all","Have at least one member","Appoint auditors"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Section 402 of CAMA 2020 exempts small companies from the requirement to appoint auditors, reducing compliance costs for small businesses. Options B, A and C remain necessary: every company must keep records, be registered with the CAC and have at least one member."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 235, $official_bank_source${"itemId":"2c29b706-9949-54a1-b69d-74429e56f4d6","questionId":"aad2b9b0-aa52-53e0-bb98-ff24c16cd65f","sourceKey":"bank:BUA201:OWN-033","payload":{"prompt":"Which of the following CAMA 2020 provisions reduces the cost of running a small private company?","options":["It must appoint at least three independent directors","It is not mandatory for a small company to appoint a company secretary","It must hold an annual general meeting every quarter","It must list its shares on the Nigerian Exchange"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Section 330 of CAMA 2020 makes the appointment of a company secretary optional for small companies, and section 237 also excuses small companies from holding AGMs. Option A is a public company requirement, option C is not a requirement for any company, and option D applies only to listed public companies."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 236, $official_bank_source${"itemId":"ad7bc2dc-f4d3-52c9-98e7-1df87d3e7433","questionId":"6a3f920f-a4a3-522c-b3a6-765934f1c295","sourceKey":"bank:BUA201:OWN-034","payload":{"prompt":"Under CAMA 2020, a public company must have at least how many independent directors?","options":["Three","Two","One","Five"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Section 275 of CAMA 2020 requires every public company to have at least three independent directors who meet stated criteria, to strengthen board objectivity. Options C, B and D do not match the statutory minimum."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 237, $official_bank_source${"itemId":"52d50c19-8e6c-5e33-98ee-4f2aafb0783d","questionId":"92a5e5bb-ada2-52c9-adef-a72d0bda3fa6","sourceKey":"bank:BUA201:OWN-035","payload":{"prompt":"Under section 307 of CAMA 2020, a person may NOT be a director of more than how many PUBLIC companies at the same time?","options":["Ten","Three","Five","Two"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Section 307(1) of CAMA 2020 limits a person to directorships of not more than five public companies, so directors can give enough time to each board. Options D, B and A do not match the limit in the Act."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 238, $official_bank_source${"itemId":"b20598e5-a8dc-5f28-86c0-f414bbca66e6","questionId":"a77f8b1d-6d0c-53fb-8ac8-2b289824ac24","sourceKey":"bank:BUA201:OWN-036","payload":{"prompt":"The memorandum of association of a company differs from its articles of association mainly because the memorandum:","options":["States the company's basic constitution, such as its name, objects or business, liability of members and share capital","Contains the detailed internal rules for meetings and appointment of directors","Is a contract among partners of a firm","Is the annual report sent to shareholders"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"The memorandum sets out the company's fundamental details and its relationship with the outside world, while the articles are the internal regulations on matters such as meetings, directors and share transfers. Option B describes the articles, option C describes a partnership deed, and option D describes annual accounts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 239, $official_bank_source${"itemId":"3951b911-f536-5456-8874-48005221f312","questionId":"5dca2b60-0934-591a-be3a-6b639dc27510","sourceKey":"bank:BUA201:OWN-037","payload":{"prompt":"Which of the following is an ADVANTAGE of a public limited company over a sole proprietorship?","options":["It is cheaper and quicker to form","It can raise large amounts of capital by offering shares to the public","Its owner can keep all business information secret","One person makes all decisions without consultation"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A public company can invite the public to buy its shares, which allows it to raise far more capital than one person could. Options C, A and D are advantages of a sole proprietorship, not of a public company, which must disclose information and is costlier to form."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 240, $official_bank_source${"itemId":"8d144f16-3205-5240-844c-316811a583a6","questionId":"3cce0943-d574-5c92-8011-2186f854395a","sourceKey":"bank:BUA201:OWN-038","payload":{"prompt":"Which of the following is a DISADVANTAGE of a public limited company?","options":["It cannot employ professional managers","It ends when a major shareholder dies","Its shareholders have unlimited liability","It must disclose a great deal of information and comply with heavy regulation"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Public companies face extensive disclosure, reporting and governance rules, and ownership is often separated from control. Option C is wrong because shareholders have limited liability, option B ignores perpetual succession, and option A is wrong because public companies typically employ professional managers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 241, $official_bank_source${"itemId":"63c43799-418b-57b3-94b7-8f100c82d199","questionId":"b535192c-7f13-5d0f-89a1-8be4b4f0b552","sourceKey":"bank:BUA201:OWN-039","payload":{"prompt":"A voluntary association of people who join together on equal terms to meet their common economic needs through a jointly owned and democratically controlled enterprise is a:","options":["Statutory corporation","Public limited company","Sole proprietorship","Cooperative society"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"A cooperative is owned and controlled by its members and run for their mutual benefit rather than for outside investors. Option B is owned by shareholders seeking returns, option C has one owner, and option A is a government enterprise created by statute."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 242, $official_bank_source${"itemId":"8f3b5b0d-5c15-5f1d-a9fb-2abcb44ffdf8","questionId":"efe47d29-9bd4-50b0-a48b-43ee60322961","sourceKey":"bank:BUA201:OWN-040","payload":{"prompt":"In a cooperative society, voting at general meetings is usually based on the principle of:","options":["One member, one vote, regardless of shares held","One share, one vote","Votes in proportion to years of membership","Only founding members may vote"],"correctOption":0,"section":"Forms of Business Ownership","explanation":"Democratic member control means each member has one vote, however much capital he or she has contributed. Option B applies in companies, while options C and D are not cooperative principles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 243, $official_bank_source${"itemId":"f6550a52-f012-5602-919e-ada4e609c647","questionId":"44f8033d-06b4-50b7-95e5-302c872b2ed7","sourceKey":"bank:BUA201:OWN-041","payload":{"prompt":"A cooperative society usually distributes its surplus to members:","options":["Only to the chairman and committee","In proportion to the number of shares each member holds, like a company","In proportion to the business each member did with the society (patronage)","Never, because cooperatives cannot have a surplus"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Cooperatives often return surplus as a patronage dividend, so members who buy or sell more through the society get more. Option A contradicts democratic control, option B describes company dividends, and option D is wrong because cooperatives can earn a surplus."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 244, $official_bank_source${"itemId":"f7a47d46-534c-5a85-b54a-89ef53ba9817","questionId":"4ce10ff8-05e6-5bd1-b44a-cb258e4fdaa6","sourceKey":"bank:BUA201:OWN-042","payload":{"prompt":"Staff of a Lagos hospital contribute part of their salaries each month into a society that grants them low-interest loans. This is an example of a:","options":["Consumers' cooperative","Thrift and credit cooperative","Marketing cooperative","Producers' cooperative"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A thrift and credit cooperative encourages members to save regularly and lends to them at low interest. Option D is formed by producers to produce jointly, option A buys goods in bulk for resale to members, and option C helps producers sell their output."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 245, $official_bank_source${"itemId":"e2305a4f-ce0b-5e7d-b5bf-58d5e609f2b8","questionId":"f82e9cf8-cbb7-59f2-8f5f-34d6e6385655","sourceKey":"bank:BUA201:OWN-043","payload":{"prompt":"Cocoa farmers in Ondo State form a society to collect, grade and sell their cocoa together to get better prices from exporters. This is a:","options":["Consumers' cooperative","Marketing cooperative","Public enterprise","Thrift and credit cooperative"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"A marketing cooperative helps producers sell their output jointly, gaining bargaining power and better prices. Option A buys goods for members' own consumption, option D focuses on savings and loans, and option C is owned by government."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 246, $official_bank_source${"itemId":"f2433c36-e2de-5bca-a693-77ad5f5e5dc9","questionId":"730c28fe-e71e-5d09-9b8c-3a9f0d7dcf29","sourceKey":"bank:BUA201:OWN-044","payload":{"prompt":"A business enterprise that is owned and controlled wholly or mainly by government to provide goods or services to the public is a:","options":["Public limited company","Public enterprise","Cooperative society","Partnership"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Public enterprises, such as statutory corporations and government-owned companies, are owned and controlled by government. Option A is owned by private shareholders even though its shares are offered to the public, option C is owned by its members, and option D is owned by private partners."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 247, $official_bank_source${"itemId":"b75838ed-5469-551e-a900-0fca966517c8","questionId":"d5357fd8-c8ca-5067-a2a3-7fbad7f44c8a","sourceKey":"bank:BUA201:OWN-045","payload":{"prompt":"A public enterprise established by a specific Act of the legislature, which defines its powers, functions and management, is called a:","options":["Limited partnership","Private limited company","Statutory corporation","Sole proprietorship"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"A statutory corporation is created by its own law, which sets its objectives and powers. Option B is incorporated by private persons under CAMA, option D has no special statute, and option A is registered under CAMA by private partners."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 248, $official_bank_source${"itemId":"e7b7af41-6d6f-547f-9324-db46b84294ab","questionId":"02de881b-a268-567a-9966-c33a7852fa74","sourceKey":"bank:BUA201:OWN-046","payload":{"prompt":"Which of the following is NOT usually a reason why governments set up public enterprises?","options":["To control strategic sectors of the economy","To prevent private monopolies from exploiting consumers","To provide essential services that private firms may neglect","To maximise profits for private shareholders"],"correctOption":3,"section":"Forms of Business Ownership","explanation":"Public enterprises are created to serve public interest goals such as providing essential services, controlling strategic industries and protecting consumers. Maximising profit for private shareholders is the goal of private companies. Options C, A and B are typical reasons for public enterprises."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 249, $official_bank_source${"itemId":"066f6afb-5db1-5282-a32d-b0ae46f33be4","questionId":"817b4bd8-8d53-5c0e-8e89-cfd122d5cd4b","sourceKey":"bank:BUA201:OWN-047","payload":{"prompt":"Which statement correctly distinguishes PRIVATISATION from COMMERCIALISATION of a public enterprise?","options":["Both mean closing down the enterprise","Both mean converting the enterprise into a cooperative","Privatisation transfers ownership to private investors, while commercialisation keeps government ownership but requires the enterprise to run on commercial, profit-making lines","Privatisation keeps government ownership, while commercialisation sells the enterprise to private investors"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"In privatisation, government sells all or part of its shares to private investors; in commercialisation, government remains the owner but the enterprise must cover its costs and operate like a business. Option D reverses the two, and options A and B do not describe either policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 250, $official_bank_source${"itemId":"ae25a36b-8565-560e-a603-55334b134afd","questionId":"f03713a5-4c4d-52b8-869f-180b14a94f21","sourceKey":"bank:BUA201:OWN-048","payload":{"prompt":"Which of the following is a common PROBLEM of public enterprises in Nigeria?","options":["Unlimited personal liability of the managers","A legal ban on receiving government funds","Political interference in appointments and decisions","Too much pressure from private shareholders for dividends"],"correctOption":2,"section":"Forms of Business Ownership","explanation":"Public enterprises often suffer from political interference, bureaucracy and weak accountability, which reduce efficiency. Option D relates to private companies, option A is not a feature of public enterprises, and option B is wrong because they usually depend on government funding."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 251, $official_bank_source${"itemId":"811329dc-8451-57d8-8258-9ae8c28da12a","questionId":"6ac50857-a474-5095-9a3d-32bf811a1e60","sourceKey":"bank:BUA201:OWN-049","payload":{"prompt":"An arrangement in which a business owner grants another party the right to sell its products under its brand name and business system, in return for fees or royalties, is a:","options":["Partnership","Franchise","Cooperative","Merger"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"In a franchise, the franchisor licenses its brand and methods to a franchisee, who pays initial fees and ongoing royalties. Option A involves co-ownership of one business, option C is member-owned for mutual benefit, and option D combines two firms into one."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 252, $official_bank_source${"itemId":"570873df-3250-5aa6-aa50-302a7fd61e39","questionId":"24e3e0c6-f44a-5a73-80fc-755706247dde","sourceKey":"bank:BUA201:OWN-050","payload":{"prompt":"When choosing a form of business ownership, which of the following considerations is mainly LEGAL?","options":["The managerial skills available to the owners","The extent of the owners' liability for business debts","The amount of capital the owners can raise","How quickly decisions can be made"],"correctOption":1,"section":"Forms of Business Ownership","explanation":"Liability is a legal consideration, since it depends on whether the law treats the business as separate from its owners. Option C is a financial consideration, while options D and A are managerial considerations."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 253, $official_bank_source${"itemId":"74d36a04-ddfb-5c82-b8fb-bb513271f359","questionId":"c395bef8-e273-59be-8d5a-b2766b30c7da","sourceKey":"bank:BUA201:PQ-002","payload":{"prompt":"When managers sacrifice some short-term profit to build long-term trust with employees, customers and the community, this reflects:","options":["Agency theory dominance","Shareholder primacy","Classical economic theory","Stakeholder capitalism"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Stakeholder capitalism holds that a business should create value for all its stakeholders, not only its owners, even if that means giving up some profit in the short run. Option B and option C both treat maximising returns to shareholders as the main goal, which is the opposite of what the managers are doing here."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 254, $official_bank_source${"itemId":"bb200a28-4bc4-541e-96a4-bdd801198a83","questionId":"42b0c7a5-e1fa-558d-8c72-86d8d9b9ec9f","sourceKey":"bank:BUA201:PQ-009","payload":{"prompt":"Agency costs in a company arise mainly because of:","options":["Market competition","Trade liberalisation","Divergence of interests between owners (principals) and managers (agents)","Inflation"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Agency costs are the costs of monitoring and aligning managers who may pursue their own interests instead of the owners'. Options A, D and B are external conditions in the business environment and do not create the owner-manager conflict that agency theory describes."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 255, $official_bank_source${"itemId":"a1a6071f-37f9-5431-b802-9906a5713ab0","questionId":"cbf4ee90-1439-5e03-9bad-231949e71a21","sourceKey":"bank:BUA201:PQ-010","payload":{"prompt":"An independent non-executive director on a company board mainly enhances:","options":["Operational efficiency","Executive power","Monitoring effectiveness","Production output"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Independent non-executive directors are not part of management, so they can objectively oversee and challenge executives on behalf of the company. Option B is the opposite of their purpose, since they act as a check on executive power, and options A and D are the day-to-day work of management."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 256, $official_bank_source${"itemId":"5e9fc6ae-b618-5c4e-89b5-dba486c9a7f9","questionId":"f91dd4e0-a991-5f34-99a1-a7bea38450a5","sourceKey":"bank:BUA201:PQ-011","payload":{"prompt":"Ethical decision-making based on achieving \"the greatest good for the greatest number\" aligns with:","options":["Ethical egoism","Utilitarianism","Deontology","Virtue ethics"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Utilitarianism judges an action by its consequences and favours the choice that produces the most benefit for the most people. Option C judges actions by duties and rules regardless of outcome, and option A focuses on what benefits the decision-maker personally."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 257, $official_bank_source${"itemId":"02e096c5-b007-52c7-84ae-ae353d23e33f","questionId":"f6dbc292-3f97-5a47-b884-51da6ba41c49","sourceKey":"bank:BUA201:PQ-015","payload":{"prompt":"A transformational leader differs from a transactional leader by focusing on:","options":["Inspiring followers with a vision to achieve more than expected","Rewards and punishments","Standard operating procedures","Routine supervision"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Transformational leaders inspire and motivate followers to go beyond expected results, often through a compelling vision and charisma. Option B is the defining feature of transactional leadership, which motivates through exchanges of rewards and punishments."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 258, $official_bank_source${"itemId":"b566fa3a-4b85-5565-9602-b3cc688fd3b1","questionId":"82de94cd-4de1-5c25-b280-8f93dd1ca752","sourceKey":"bank:BUA201:PQ-030","payload":{"prompt":"Corporate Social Responsibility (CSR) aligns most closely with:","options":["Scientific management","Classical profit doctrine","Agency theory","Stakeholder theory"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"CSR asks businesses to consider employees, customers, communities and the environment, which is the central idea of stakeholder theory. Option B holds that a firm's only social responsibility is to make profit for its owners, and option C deals with the owner-manager relationship."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 259, $official_bank_source${"itemId":"368c0538-a0c4-5435-8f18-bdf7d62044dc","questionId":"e296bcd8-11e3-5be6-afcc-f6bc696dbdb8","sourceKey":"bank:BUA201:PQ-038","payload":{"prompt":"An autocratic leadership style may be most effective when:","options":["Employee morale is already high","Urgent decisions are needed in a crisis","Creativity is required","Decision-making is decentralised"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"In a crisis there is little time for consultation, so a leader making quick, firm decisions alone can be effective. Option C calls for a participative style that draws ideas from the team, and option D contradicts autocracy, which centralises decisions in the leader."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 260, $official_bank_source${"itemId":"ace38ae7-b238-5e30-ab8f-d53d91c0f33c","questionId":"bdd15513-6657-5783-be9f-42d5ae39addc","sourceKey":"bank:BUA201:PQ-043","payload":{"prompt":"Corporate governance failure often results in:","options":["Market expansion","Higher stakeholder confidence","Innovation growth","Financial misreporting"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"When boards fail to oversee management, problems like manipulated accounts and hidden losses are common outcomes, as many corporate scandals show. Options B, A and C are positive outcomes linked with good governance, not its failure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 261, $official_bank_source${"itemId":"ff922792-d90d-595c-8a18-ed3129481062","questionId":"a2aa90f4-b509-554f-9618-645b37ef66a3","sourceKey":"bank:BUA201:PQ-050","payload":{"prompt":"Ethical compliance differs from ethics in general because compliance is mainly:","options":["Voluntary","A branch of moral philosophy","Driven by laws and rules","Based on stakeholder preferences"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Compliance means obeying laws, regulations and codes that are enforced, while ethics goes further to what is morally right even where no law requires it. Option A describes ethics, which often goes beyond what is compulsory, and option B describes ethics as a field of study."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 262, $official_bank_source${"itemId":"93bd1f88-976d-5175-a8fa-675d267e84bc","questionId":"0f3d05ea-970f-5218-b9a4-cffaba26102c","sourceKey":"bank:BUA201:PQ-063","payload":{"prompt":"Leadership ethics most directly influence:","options":["Interest rates","Organisational trust","The exchange rate","Inflation"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"When leaders act with honesty, fairness and accountability, employees and other stakeholders come to trust the organisation. Options D, C and A are economy-wide variables outside a leader's ethical conduct."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 263, $official_bank_source${"itemId":"ccfce782-9010-56b2-a40c-b2d18a694c8b","questionId":"c4be2344-b60d-5625-be56-18467a3fe5a2","sourceKey":"bank:BUA201:PQ-070","payload":{"prompt":"Ethical leadership mainly enhances an organisation's:","options":["Reputation","Market volatility","Access to foreign exchange","Inflation rate"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Leaders who consistently act with integrity build the organisation's good name with customers, investors and regulators, a valuable form of reputation capital. Options D, C and B are economic conditions that ethical behaviour does not directly create."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 264, $official_bank_source${"itemId":"23430938-55d3-595b-b8be-2f088cc04a1b","questionId":"79d5a504-5b18-54b6-85ba-660aff144bf8","sourceKey":"bank:BUA201:PQ-076","payload":{"prompt":"Stakeholder mapping is mainly used to:","options":["Share profit among the shareholders","Prepare the monthly payroll","Classify stakeholders by their power or influence and their interest in the organisation","Raise debt finance from banks"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Stakeholder mapping identifies the people and groups affected by an organisation and ranks them by how much influence and interest they have, so managers know whom to consult, inform or monitor closely. Option A is a dividend decision, option B is a routine HR or accounting task, and option D is a financing decision; none of them involves analysing stakeholders."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 265, $official_bank_source${"itemId":"8c5914ee-48d9-5642-9c37-78b7e566535f","questionId":"bf16694e-3d12-5d33-b41e-044db3945e1e","sourceKey":"bank:BUA201:PQ-084","payload":{"prompt":"Social responsibility reporting improves:","options":["Inflation","Forex supply","Transparency","Tax evasion"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Social responsibility reporting discloses how a company affects society and the environment, which makes its conduct more open and lets stakeholders hold it to account. Options A and B are economy-wide conditions that a company's report cannot change. Option D is illegal and is exactly what openness and disclosure discourage."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 266, $official_bank_source${"itemId":"2cb67a3a-fb08-5047-be7a-90d13025704f","questionId":"d38b9d80-62f3-5fc3-a6ad-da3153311776","sourceKey":"bank:BUA201:PQ-085","payload":{"prompt":"Internal audit strengthens:","options":["Market segmentation","The exchange rate","Operational control","Product pricing"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Internal audit is an independent check within the organisation that tests whether controls, procedures and records are working properly, so it strengthens operational control and helps detect errors and fraud. Option A and option D are marketing decisions, and option B is set by the economy and monetary policy, not by a firm's auditors."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 267, $official_bank_source${"itemId":"325fd091-07c7-52be-acea-475531da0aa0","questionId":"72ab19be-c1b5-5827-a546-f88a08985def","sourceKey":"bank:BUA201:PQ-097","payload":{"prompt":"Corporate failure is often linked to:","options":["High corporate social responsibility","Stakeholder engagement","Ethical leadership","Weak corporate governance"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Weak governance, such as poor board oversight, lack of accountability and unchecked management, allows bad decisions and fraud to go unnoticed until the company collapses. Options A, B and C are generally signs of a well-run, responsible company, not causes of failure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 268, $official_bank_source${"itemId":"17784f71-f2b5-5fa2-a8df-d515ee2fa2db","questionId":"569de7c2-9f9b-5922-a390-569f3d5c3e1d","sourceKey":"bank:BUA201:PQ-101","payload":{"prompt":"Which combination BEST explains why management is often regarded as a semi-profession rather than a full profession in many countries?","options":["Absence of a profit motive and of ethical codes","Lack of theoretical knowledge and formal training","Dependence on intuition rather than principles","Free entry into practice and no compulsory licence or statutory regulation"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Full professions such as medicine and law restrict entry: you cannot practise without a recognised qualification and a licence from a regulating body. In many countries anyone can become a manager without such a licence, which is the main reason management is called a semi-profession. Option B is wrong because management has a large body of theory and many formal training programmes, and option C is wrong because managers apply established principles. In Nigeria the argument is weaker, since a statutory body regulates the management profession there."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 269, $official_bank_source${"itemId":"c14612c5-9ad3-5fa1-ae96-ce008accd538","questionId":"dd80aa84-6019-5cb7-b501-b11b888be9ad","sourceKey":"bank:BUA201:PQ-102","payload":{"prompt":"A profession differs from an ordinary occupation mainly because it:","options":["Enforces discipline through a recognised professional body","Guarantees higher income","Requires long years of experience","Involves human relations"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"A profession has a recognised body that sets entry standards, issues licences, enforces a code of conduct and disciplines members who break it. Option B is wrong because no profession guarantees income, and many occupations also require long experience (option C) or dealing with people (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 270, $official_bank_source${"itemId":"26fa1784-400a-54dd-9efd-fda946aa337f","questionId":"c5a243ee-ef50-57ea-97f0-7ff26537eb8f","sourceKey":"bank:BUA201:PQ-112","payload":{"prompt":"Which situation represents a breach of professional integrity under the Nigerian Institute of Management (NIM) code of ethics?","options":["Manipulating reports to protect management's image","Refusing assignments beyond one's competence","Declining gifts from clients","Updating one's professional skills"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Integrity and honesty require managers to present facts truthfully, so altering reports to make management look good is a clear breach. Options B, C and D are examples of good professional conduct: being honest about one's limits, avoiding conflicts of interest and keeping skills current."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 271, $official_bank_source${"itemId":"5453f104-07d6-5554-8236-b5f3ae7d67ef","questionId":"efdea90f-59a1-5a09-9ce6-a3b4943512f5","sourceKey":"bank:BUA201:PQ-113","payload":{"prompt":"A major objective of corporate governance is to resolve conflicts between:","options":["Owners and managers","Management and customers","Shareholders and government","Employees and trade unions"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"In a company the shareholders own the business but managers run it, and managers may pursue their own interests instead of the owners' (the agency problem). Corporate governance sets up boards, controls and disclosure so that managers are held to account to the owners. Options B, C and D are other relationships that governance may touch, but they are not its central concern."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 272, $official_bank_source${"itemId":"8d02614a-64be-59ca-9976-59a0dd972a35","questionId":"341df9fe-9d47-513f-9045-b75af6cc95c9","sourceKey":"bank:BUA201:PQ-114","payload":{"prompt":"Under the Nigerian Code of Corporate Governance (NCCG) 2018, requiring independent non-executive directors on the board is mainly intended to:","options":["Reduce company costs","Strengthen accountability and oversight of management","Increase executive power","Promote government control"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Independent directors have no management role or close ties to the company, so they can question executives objectively and protect the interests of shareholders and other stakeholders. Option C is the opposite, since independence is meant to check executive power. Options A and D are not aims of board independence."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 273, $official_bank_source${"itemId":"b8bc0f0e-085e-582a-9252-f1fb1776bf9a","questionId":"37324e1f-4981-5e92-b692-9a36e5928750","sourceKey":"bank:BUA201:PQ-115","payload":{"prompt":"Which leadership theory argues that no single leadership style is effective in every situation?","options":["Contingency theory","Trait theory","Behavioural theory","Charismatic theory"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Contingency theory holds that the best way to lead depends on the situation, such as the task, the followers and the leader's position. Option B looks for inborn qualities that all leaders share, and option C looks for the behaviours that make leaders successful, so both seek general answers. Option D focuses on a leader's personal appeal rather than on matching style to situation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 274, $official_bank_source${"itemId":"0ccc268a-3706-5e94-b2eb-aba415facd4b","questionId":"4565c1d0-34c0-53e7-b43d-dbfd634a4b40","sourceKey":"bank:BUA201:PQ-116","payload":{"prompt":"A leader who changes style according to the maturity (readiness) of followers is applying:","options":["Situational leadership theory","Trait theory","Autocratic leadership","Bureaucratic leadership"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Situational leadership theory says leaders should adjust how much direction and support they give according to how willing and able followers are to do a task. Option B explains leadership by inborn qualities, while options C and D are fixed styles that do not change with followers' maturity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 275, $official_bank_source${"itemId":"9a2ed337-23cc-5002-8efc-f4d225594c63","questionId":"2eb6ba2f-81c8-5a58-b02b-44ff98651aad","sourceKey":"bank:BUA201:PQ-131-a","payload":{"prompt":"As at 2026, which body is legally charged with regulating and controlling the practice of management as a profession in Nigeria?","options":["The Corporate Affairs Commission","The Financial Reporting Council of Nigeria","The Nigerian Institute of Management (Chartered)","The Institute of Chartered Accountants of Nigeria"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Nigerian Institute of Management (Chartered) is the statutory body that sets standards for the management profession, keeps a register of members and regulates management practice in Nigeria. Option A registers companies and business names, option B oversees financial reporting and corporate governance codes, and option D regulates accountants, not managers in general."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 276, $official_bank_source${"itemId":"3671109c-fd1d-5444-99a2-9a01c7dbdcc1","questionId":"91054f5c-4ffc-597f-aab9-c36635116335","sourceKey":"bank:BUA201:PQ-131-b","payload":{"prompt":"The Nigerian Institute of Management was given its statutory regulatory role by:","options":["The Companies and Allied Matters Act 2020","The Nigerian Code of Corporate Governance 2018","A resolution of its members without any law","The Nigerian Institute of Management (Establishment) Act No. 14 of 2003"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NIM became a statutory regulator through an Act of the National Assembly, Act No. 14 of 2003, which empowers it to set standards for, and regulate, the management profession. Option A is the general law on companies and business registration. Option B is a governance code for organisations, not a law creating a professional body, and option C would not give NIM legal power over non-members."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 277, $official_bank_source${"itemId":"0725394f-acb2-577b-a2ce-471d4f3ec997","questionId":"42166447-ef9f-591d-96b2-5917969882f1","sourceKey":"bank:BUA201:PQ-132-a","payload":{"prompt":"Which of the following is NOT a characteristic of a profession?","options":["A guaranteed high income for every member","Extensive training to acquire specialised knowledge","A licence or certification to practise","A code of ethics and code of conduct"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The usual marks of a profession are specialised training, skills from practice, a licence or certification, a code of ethics with a code of conduct, and standards of practice. Income is not one of them, because no profession can promise its members high earnings. Options B, C and D are all genuine characteristics."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 278, $official_bank_source${"itemId":"b269b6a6-bc0d-5e73-9898-b5464ccd8fb8","questionId":"e213379b-f6d8-5111-96ff-efe67fac38df","sourceKey":"bank:BUA201:PQ-132-b","payload":{"prompt":"A permission granted by a professional body or government authority to individuals who meet specific qualifications, allowing them to practise a profession, is called a:","options":["Code of conduct","Licence or certification","Standard","Code of ethics"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"A licence or certification is formal permission to practise, given only to people who meet the required qualifications. Option A sets out practical rules of behaviour, option C is a measure of quality of practice, and option D states the broad moral principles of the profession; none of them is permission to practise."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 279, $official_bank_source${"itemId":"4cb50b4c-14db-5eeb-90b7-42b8da068b69","questionId":"75ad8c6d-1cff-5490-8b16-484789aea677","sourceKey":"bank:BUA201:PQ-132-c","payload":{"prompt":"In a profession, the document that translates broad ethical principles into practical guidelines for behaviour, such as obeying the law and avoiding conflicts of interest, is the:","options":["Code of ethics","Licence","Quality standard","Code of conduct"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"A code of conduct turns values into specific rules on how members should behave in everyday situations. Option A is close but it states the overarching moral principles and values, while the code of conduct spells out how to apply them. Options B and C deal with permission to practise and quality measures, not behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 280, $official_bank_source${"itemId":"c0aa2832-579b-514e-a40e-d4fe8e775391","questionId":"ebd66d5c-74df-5edd-8f3c-ac85f5d3fd83","sourceKey":"bank:BUA201:PQ-132-d","payload":{"prompt":"Criteria or measures of the quality of practice or performance, such as units of measurement, building regulations or the ISO 9000 quality management system, are known as:","options":["Licences","Codes of ethics","Standards","Certificates of incorporation"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Standards are agreed benchmarks for judging the quality of work or performance, and ISO 9000 is a well-known example for quality management. Option A gives permission to practise, option B states moral principles, and option D is the document that shows a company has been registered."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 281, $official_bank_source${"itemId":"51fc5697-e3ec-5fbe-8211-cd37077f653e","questionId":"0572f464-c339-5a5c-900e-ddc6ced768a6","sourceKey":"bank:BUA201:PQ-133-a","payload":{"prompt":"Which of the following is a reason commonly given for regarding management as a semi-profession rather than a full profession?","options":["Management has no organised body of knowledge","Managers never receive formal training","Management involves working with people","In many countries people can work as managers without a compulsory licence or a specific required qualification"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Full professions such as law and medicine bar anyone without the required qualification and licence from practising, but in many countries people become managers without either, so entry is open. Options A and B are false, since management has well-developed theories and many degree and training programmes. Option C is true of management but is not why it falls short of a full profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 282, $official_bank_source${"itemId":"a53e5947-7cf7-5789-ad19-7085caf95835","questionId":"5f9c2480-fc3d-55fc-9a01-6ea5628b38ef","sourceKey":"bank:BUA201:PQ-133-b","payload":{"prompt":"Which of the following is NOT an argument for calling management a semi-profession?","options":["Entry into management is generally not restricted","Practising as a manager usually does not require a licence","There is no single qualification every manager must hold","Management has a systematic body of principles that can be taught"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Having a teachable body of principles is one of the features that management shares with full professions, so it supports treating management as a profession rather than counting against it. Options A, B and C are the usual reasons why management is seen as only a semi-profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 283, $official_bank_source${"itemId":"93d46990-aea2-58dc-8f82-0b79974f1b51","questionId":"a4d8d572-ac7c-5294-90d2-19e388ee6d15","sourceKey":"bank:BUA201:PQ-140-a","payload":{"prompt":"Corporate governance is BEST defined as:","options":["The system by which organisations are directed and controlled","The process of selling a company's products","The day-to-day supervision of factory workers","The preparation of a company's tax returns"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Corporate governance is the framework of rules, policies and processes by which organisations are directed and controlled, covering the roles of the board, management and shareholders. Option B is marketing, option C is operational supervision, and option D is a tax and accounting task."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 284, $official_bank_source${"itemId":"efb890bb-1f3e-513d-87eb-961b9413594e","questionId":"4093e1de-7425-53ff-8a43-0deef22e2bcf","sourceKey":"bank:BUA201:PQ-140-b","payload":{"prompt":"Which of the following is NOT one of the core principles of corporate governance?","options":["Accountability","Transparency","Fairness","Secrecy"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The core principles of corporate governance are responsibility, accountability, transparency and fairness. Secrecy is the opposite of transparency, because good governance requires openness so that shareholders and other stakeholders can judge how the company is run. Options A, B and C are all core principles."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 285, $official_bank_source${"itemId":"fbff7139-0d2b-55df-b94a-a6b41b536dca","questionId":"28b3cc58-4111-500c-adba-530cebb260a0","sourceKey":"bank:BUA201:PQ-140-c","payload":{"prompt":"Good corporate governance is important to modern business organisations mainly because it:","options":["Protects the interests of shareholders and other stakeholders and builds investor trust","Guarantees that the company will make a profit","Gives managers unlimited power over company resources","Removes the need for external audit"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Good governance holds management accountable, improves disclosure and reduces the risk of fraud and abuse, which protects stakeholders and makes investors more willing to commit funds. Option B is wrong because no system can guarantee profit. Options C and D describe exactly the lack of checks that good governance is meant to prevent."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 286, $official_bank_source${"itemId":"4623b93a-906f-50e8-8539-b8323d3220f8","questionId":"3af20f2a-ba6e-5953-9c01-8595c1b8cdca","sourceKey":"bank:BUA201:PQ-141-a","payload":{"prompt":"Which body issued the Nigerian Code of Corporate Governance (NCCG) 2018?","options":["The Corporate Affairs Commission","The Financial Reporting Council of Nigeria","The Nigerian Institute of Management","The Central Bank of Nigeria"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The NCCG 2018 was issued by the Financial Reporting Council of Nigeria and unveiled in January 2019 as the national code of governance principles and practices. Option A registers companies under CAMA, option C regulates the management profession, and option D issues rules for banks; none of them issued this code."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 287, $official_bank_source${"itemId":"05ffc83d-d9ca-53f7-9077-f9dfb44b9460","questionId":"3fc3a0c3-fa25-5bc2-8185-afa7b7378b01","sourceKey":"bank:BUA201:PQ-141-b","payload":{"prompt":"The compliance approach adopted by the Nigerian Code of Corporate Governance (NCCG) 2018 is known as:","options":["Comply or explain","Comply or be fined automatically","Apply and explain","Voluntary disclosure only"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Under the NCCG 2018, companies are expected to apply the principles in a way that suits their size and business and then explain how their practices achieve the purpose of those principles. Option A is close and is used in some other countries, but it allows a company not to comply as long as it explains why, which is not the NCCG 2018 approach. Options B and D do not describe the code at all."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 288, $official_bank_source${"itemId":"52763c07-7f18-5170-95bc-9963420abfa4","questionId":"8a8688bc-5d68-5fa1-8700-a3340065c447","sourceKey":"bank:BUA201:PQ-141-c","payload":{"prompt":"The main aim of the Nigerian Code of Corporate Governance (NCCG) 2018 is to:","options":["Fix the prices of goods sold by Nigerian companies","Register new companies and business names","Promote transparency, integrity and public trust in Nigerian organisations","Set the exchange rate of the naira"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The NCCG 2018 sets out standard principles and practices of corporate governance, including requirements on board structure, board and committee meetings and disclosure, in order to promote transparency, integrity and public trust. Option A is not a governance matter, option B is the work of the Corporate Affairs Commission, and option D is a monetary policy matter."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 289, $official_bank_source${"itemId":"fdde206a-5605-57ad-85ea-4d1af64876de","questionId":"1de3b3ca-1bec-5273-bd81-feccbc629167","sourceKey":"bank:BUA201:PQ-142-a","payload":{"prompt":"Which of the following is NOT one of the values in the Nigerian Institute of Management (NIM) code of ethics?","options":["Favouritism","Integrity and honesty","Transparency","Accountability"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The NIM code of ethics includes integrity and honesty, transparency, fairness, accountability, responsibility, effectiveness and efficiency. Favouritism is the opposite of fairness, which requires managers to be impartial and avoid discrimination. Options B, C and D are all values in the code."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 290, $official_bank_source${"itemId":"8c827e6d-2708-55b0-a2e4-9fdf2fd60d75","questionId":"1817500f-2156-5430-bc8e-55cb12197f4e","sourceKey":"bank:BUA201:PQ-142-c","payload":{"prompt":"A manager who accomplishes a task using the least possible resources is demonstrating:","options":["Effectiveness","Efficiency","Transparency","Accountability"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Efficiency means getting a task done with the minimum use of resources such as time, money and materials. Option A is the most tempting, but effectiveness means achieving the desired objective or result, whatever resources it takes. Options C and D relate to openness and answering for one's actions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 291, $official_bank_source${"itemId":"152ca1fe-8ffa-5905-989c-652da682d776","questionId":"a0f09113-6abd-5dd0-a232-6e1990231c54","sourceKey":"bank:BUA201:GOV-001","payload":{"prompt":"In its basic meaning, a profession is best described as:","options":["A one-off commercial transaction","A regular work or occupation","A government-owned enterprise","An unpaid leisure activity"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"At its simplest, a profession is the regular work or occupation a person does, such as teaching, medicine, law or engineering. Option A is a single deal, not ongoing work, while D and C describe a hobby and a form of ownership rather than an occupation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 292, $official_bank_source${"itemId":"fa92e174-2a1c-5e30-823a-aa7a5e537078","questionId":"db99f2eb-7dc5-57e2-82f5-21d378adf15c","sourceKey":"bank:BUA201:GOV-002","payload":{"prompt":"Which of the following pairs correctly matches a profession with its practitioner?","options":["Medicine - Engineer","Teaching - Lawyer","Law - Accountant","Architecture - Architect"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Architecture is practised by an architect, just as law is practised by a lawyer and medicine by a doctor. Options A, B and C all pair a profession with the practitioner of a different profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 293, $official_bank_source${"itemId":"15e27682-fbf5-57b1-8310-636b91db978f","questionId":"38f87f16-a766-5056-91b0-0d7bffaa725b","sourceKey":"bank:BUA201:GOV-004","payload":{"prompt":"Which of the following is NOT a characteristic of a profession?","options":["Licence or certification to practise","Extensive training to acquire specialised knowledge","Membership passed down automatically from parent to child","A code of ethics and code of conduct"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Entry into a profession depends on training, demonstrated expertise and licensing, not on family inheritance. Options A, B and D are all recognised characteristics of a profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 294, $official_bank_source${"itemId":"aa07084c-cc25-5a52-9e8e-0c767aa53efd","questionId":"312a6cd0-6e19-5fac-9c56-a663cc43d32f","sourceKey":"bank:BUA201:GOV-005","payload":{"prompt":"As a characteristic of a profession, the 'extensive preparation to acquire specialised knowledge, usually combining education and practical instruction' refers to:","options":["Training","Certification","Standards","Code of conduct"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Training is the extensive preparation through which members acquire specialised knowledge, and most professions require both education and training. Option B is the permission that follows qualification, while C and D govern quality and behaviour after entry."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 295, $official_bank_source${"itemId":"a085678a-ca97-56c4-9839-6da52e7722d1","questionId":"94327d65-361b-5ce3-9d00-9ddad990a51a","sourceKey":"bank:BUA201:GOV-006","payload":{"prompt":"Skills or expertise, as a characteristic of a profession, result mainly from:","options":["Inheriting a family business","Holding a position in government","Paying an annual membership fee","Experience and practice in applying knowledge"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Professional skill or expertise grows out of experience and practice, that is, repeatedly applying knowledge to real tasks. Options A, B and C may give someone a position or membership but do not by themselves create expertise."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 296, $official_bank_source${"itemId":"eba01237-0d6f-54ab-8175-36d98297c8ca","questionId":"19b7efcd-db80-5117-b17e-cba898e43032","sourceKey":"bank:BUA201:GOV-007","payload":{"prompt":"In the context of a profession, ethics refers to:","options":["The fees charged for professional services","The measurement units used in quality control","The minimum educational qualification for entry","The principles an organisation sets for itself in its internal and external dealings"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Ethics are the principles an organisation sets for itself in dealing with people inside and outside it, and a code of ethics states the overarching moral principles and values. Option C describes an entry requirement and B describes standards, not ethics."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 297, $official_bank_source${"itemId":"679c4408-be44-5542-9e64-f7828efd0960","questionId":"b808ec60-9944-5ad0-bee7-539eea74e051","sourceKey":"bank:BUA201:GOV-009","payload":{"prompt":"Which statement best distinguishes a code of ethics from a code of conduct?","options":["A code of ethics states overarching moral principles, while a code of conduct gives practical guidelines for behaviour","A code of ethics sets quality measures, while a code of conduct sets licensing fees","A code of ethics is enforced by courts, while a code of conduct is purely voluntary","A code of ethics applies only to employees, while a code of conduct applies only to directors"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The code of ethics provides the broad moral principles and values, and the code of conduct translates them into specific behavioural guidelines. Options B, C and D invent differences in enforcement, coverage and content that do not define the two codes."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 298, $official_bank_source${"itemId":"8e2d536c-b227-5e40-9eee-a97091ae7011","questionId":"15236e79-6191-5741-bebd-d9feaefc82ef","sourceKey":"bank:BUA201:GOV-010","payload":{"prompt":"Criteria or measures for the quality of practice or performance in a profession are known as:","options":["Skills","Standards","Licences","Ethics"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Standards are the criteria used to judge the quality of practice or performance, for example units of measurement, building regulations and quality management systems. Option D concerns moral principles and C concerns permission to practise."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 299, $official_bank_source${"itemId":"ca89988d-84f7-53e0-825d-4414fc2a2963","questionId":"4c4838f6-fea1-5b5a-abc3-3c0dae29768f","sourceKey":"bank:BUA201:GOV-011","payload":{"prompt":"Which of the following is an example of a standard as a characteristic of professional practice?","options":["A personal mission statement","A company's logo","ISO 9000 quality management system","An employee's birthday celebration"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"ISO 9000 is a quality management system standard, a recognised measure of the quality of practice. Other examples of standards are units of measurement and building regulations; options A, D and B do not measure quality of performance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 300, $official_bank_source${"itemId":"13698587-9579-5a8e-8f15-d948d52ad869","questionId":"d216ffa0-7c68-5881-aacf-60963bd0a593","sourceKey":"bank:BUA201:GOV-012","payload":{"prompt":"'The process of designing and maintaining an environment in which individuals, working together in groups, efficiently accomplish selected aims' is a definition of:","options":["Leadership","Corporate governance","Management","Professional licensing"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"This is the classic Koontz-and-Weihrich definition of management: creating and maintaining an environment in which people working in groups achieve chosen aims efficiently. Option B concerns how organisations are directed and controlled, and A is the process of influencing people towards goals."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 301, $official_bank_source${"itemId":"cbf38f9f-5ba0-5c5c-860b-d56007d7fe8c","questionId":"1342396e-1503-59fc-86f2-f3019cafe058","sourceKey":"bank:BUA201:GOV-014","payload":{"prompt":"Management is regarded as a profession in Nigeria mainly because it involves:","options":["Only a university degree with no ethical code","Education, training, skills, ethical codes of conduct and a statutory regulatory body","Hereditary entry, informal skills and no regulator","Registration of a company with the Corporate Affairs Commission"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Management qualifies as a profession in Nigeria because it has education, specialised training, skills, ethical codes of conduct and a statutory body that regulates it. Option C lacks the defining features, A leaves out ethics and regulation, and D describes company registration, not a profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 302, $official_bank_source${"itemId":"22964a9a-b39f-56a9-8938-be5d47f0cf0f","questionId":"00253205-c04d-55f5-8035-8c504b6da256","sourceKey":"bank:BUA201:GOV-015","payload":{"prompt":"The statutory body established by an Act of the National Assembly to regulate and control the management profession in Nigeria is the:","options":["Financial Reporting Council of Nigeria (FRCN)","Nigerian Bar Association (NBA)","Corporate Affairs Commission (CAC)","Nigerian Institute of Management (NIM)"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Nigerian Institute of Management (NIM) is the statutory body that regulates and controls the practice of management in Nigeria. Option C registers companies, A oversees financial reporting and issued the corporate governance code, and B is the body for lawyers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 303, $official_bank_source${"itemId":"98272d79-a582-53b5-bd76-b1b966d07372","questionId":"fd32f682-f83f-547b-a045-efa9d9edf67c","sourceKey":"bank:BUA201:GOV-016","payload":{"prompt":"The Act of the National Assembly that established the Nigerian Institute of Management as the regulator of the management profession was passed in:","options":["2018","2003","1990","1960"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Nigerian Institute of Management was given statutory backing by Act 14 of 2003 to regulate the management profession. Option A is the year of the Nigerian Code of Corporate Governance, and D is the year of independence."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 304, $official_bank_source${"itemId":"b297ce77-0a05-5e32-9f0e-6f472996c81c","questionId":"9bcfcf96-48ee-5746-a39c-8ceb12759844","sourceKey":"bank:BUA201:GOV-017","payload":{"prompt":"A key function of the Nigerian Institute of Management (NIM) is to:","options":["Determine standards for the management profession and control its practice in Nigeria","Register business names and incorporate companies","Issue licences to commercial airlines","Set the monetary policy rate for banks"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NIM determines the standards of the management profession and controls the practice of management in Nigeria. Option B is the work of the Corporate Affairs Commission and D is the work of the Central Bank of Nigeria."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 305, $official_bank_source${"itemId":"bb205f29-398b-53c8-80a3-28c9f39b684a","questionId":"4121fa22-3521-58ba-a4f0-aeb0f85a03f5","sourceKey":"bank:BUA201:GOV-018","payload":{"prompt":"Under the NIM Code of Ethics, 'openness in dealings' describes the value of:","options":["Transparency","Efficiency","Responsibility","Fairness"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Transparency means openness in dealings, so that relevant information and decisions are visible to those affected. Option D is about impartiality, B is about using the least resources, and C is the duty to perform a task."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 306, $official_bank_source${"itemId":"96c2a5a9-e6f1-5067-a72d-6f5f641fa0ea","questionId":"83a05abe-6c1c-52cf-9b1f-7d61f6f13016","sourceKey":"bank:BUA201:GOV-019","payload":{"prompt":"Under the NIM Code of Ethics, being impartial and showing no favouritism or discrimination describes:","options":["Effectiveness","Accountability","Fairness","Transparency"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Fairness means being impartial, with no favouritism or discrimination in how people are treated. Option D is openness in dealings, B is the obligation to give account, and A is achieving objectives."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 307, $official_bank_source${"itemId":"d1d5c219-0dae-5d07-80fe-b5fd0010df8d","questionId":"f53fe91b-d9ee-5276-8198-28fdc3a4c6a0","sourceKey":"bank:BUA201:GOV-021","payload":{"prompt":"Which statement correctly distinguishes responsibility from accountability?","options":["Responsibility applies only to directors, while accountability applies only to junior staff","Responsibility and accountability mean exactly the same thing","Responsibility is the duty to perform a task, while accountability is the obligation to give account for how it was done","Responsibility is about using the least resources, while accountability is about achieving results"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Responsibility is the obligation or duty to perform a task, and accountability is the obligation to answer for how that task or responsibility was carried out. Option D confuses them with efficiency and effectiveness, and B ignores the difference between doing and answering for."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 308, $official_bank_source${"itemId":"4e5334b0-021c-5c7b-bbde-85aa8ea6e0a7","questionId":"9f2e3947-8c75-57b0-9078-056588cf622a","sourceKey":"bank:BUA201:GOV-023","payload":{"prompt":"In managerial terms, effectiveness differs from efficiency because effectiveness means:","options":["Treating all staff impartially","Reporting results to the board","Accomplishing a task with the least resources","Achieving the objectives or desired results"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Effectiveness is about achieving objectives or desired results, while efficiency is about accomplishing a task with the least resources. Option C is the definition of efficiency, the most common mix-up, and A describes fairness."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 309, $official_bank_source${"itemId":"5c16ef20-820e-5280-8823-86f0c5a8d8c6","questionId":"fbe66171-0e60-5fe0-808b-63a068793c1e","sourceKey":"bank:BUA201:GOV-024","payload":{"prompt":"Two Lagos bakeries each produce 2,000 loaves a day as planned. Bakery A spends N180,000 on inputs daily, while Bakery B spends N240,000 for the same output and quality. Compared with Bakery B, Bakery A is:","options":["Less effective and less efficient","Equally efficient but more effective","More effective but less efficient","Equally effective but more efficient"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Both bakeries achieve the same target output, so they are equally effective; Bakery A uses fewer resources for that output, so it is more efficient. Option C wrongly claims a difference in results and gets efficiency backwards, and B wrongly treats lower cost as a difference in results achieved."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 310, $official_bank_source${"itemId":"2cb5fab2-3403-5360-b219-a9b78fc417a2","questionId":"fb5f2e1f-fe29-5f90-aed5-466b4c28423d","sourceKey":"bank:BUA201:GOV-025","payload":{"prompt":"A procurement manager at an Abuja agency awards a N12 million supply contract to a company owned by his cousin even though another qualified bidder quoted less. Which NIM value is most directly violated?","options":["Standards","Fairness","Effectiveness","Efficiency"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Fairness requires impartiality with no favouritism, and favouring a relative's company over a cheaper qualified bidder is favouritism. Option D could also suffer from paying more, but the core ethical breach is the lack of impartiality; C and A are not the values at stake."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 311, $official_bank_source${"itemId":"f67a16ba-7621-5519-92b4-12e9acb84741","questionId":"31c70d7b-9d6b-5755-b67d-084838f74460","sourceKey":"bank:BUA201:GOV-026","payload":{"prompt":"A Nigerian state agency publishes the full list of bidders, bid prices and the winning bid for every contract on its website. This practice best demonstrates:","options":["Transparency","Effectiveness","Responsibility","Efficiency"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Publishing bids and outcomes openly is transparency, which means openness in dealings. Options B and D relate to resources and results, and C is the duty to perform a task, not openness about it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 312, $official_bank_source${"itemId":"f44a7351-1abd-5686-94cb-661948cf744b","questionId":"5091f5dd-4b87-5566-96d6-e9557a612c93","sourceKey":"bank:BUA201:GOV-027","payload":{"prompt":"Which of the following is NOT one of the values in the NIM Code of Ethics?","options":["Efficiency","Profit maximisation at all costs","Accountability","Transparency"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The NIM values include integrity and honesty, transparency, fairness, accountability, responsibility, effectiveness and efficiency; profit at any cost is not an ethical value and would conflict with several of them. Options A, C and D are all on the list."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 313, $official_bank_source${"itemId":"22a40137-c689-52d0-b67b-515598cdb16b","questionId":"ab25dec5-5102-5a04-8635-3411ad878fed","sourceKey":"bank:BUA201:GOV-029","payload":{"prompt":"Which set lists the four key principles of corporate governance?","options":["Training, licensing, standards and skills","Product, price, place and promotion","Responsibility, accountability, transparency and fairness","Planning, organising, leading and controlling"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The key principles of corporate governance are responsibility, accountability, transparency and fairness. Option D lists the management functions, B the marketing mix, and A the characteristics of a profession."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 314, $official_bank_source${"itemId":"d8fa252d-3406-543e-94a2-7bebe890362c","questionId":"5b47fd47-c112-5a45-9060-68d89455f54d","sourceKey":"bank:BUA201:GOV-031","payload":{"prompt":"The Nigerian Code of Corporate Governance (NCCG) 2018 states:","options":["The minimum wage for Nigerian workers","The tax rates payable by Nigerian companies","The standard of principles and practices for corporate governance in Nigerian public and private organisations","The procedure for registering business names in Nigeria"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NCCG 2018 sets out the standard of principles and practices for corporate governance in Nigerian organisations. Options B, D and A are matters covered by tax law, company registration rules and labour law respectively."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 315, $official_bank_source${"itemId":"355d900f-57a9-50ce-9723-cbfa0e33c10f","questionId":"6a1f708c-03f2-5b0c-aed1-98c420363730","sourceKey":"bank:BUA201:GOV-033","payload":{"prompt":"Which of the following does the Nigerian Code of Corporate Governance 2018 set requirements for?","options":["Recruitment of junior staff and annual leave","Board structure, board and committee meetings, and disclosure reports","Product pricing, advertising and distribution","Exchange rates, interest rates and inflation"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Code sets requirements for board structure, board and committee meetings, and disclosure reports. Option C is the marketing mix, D is macroeconomic policy, and A is routine HR administration."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 316, $official_bank_source${"itemId":"1b07ef0e-c1f1-5f49-9051-788e17816118","questionId":"f2debe70-8589-591c-956f-93c7e743877b","sourceKey":"bank:BUA201:GOV-035","payload":{"prompt":"Companies applying the Nigerian Code of Corporate Governance 2018 are expected to follow which approach?","options":["Comply or be fined automatically","Comply or explain","Apply only if convenient","Apply and explain"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NCCG 2018 uses an 'apply and explain' approach: companies apply the principles in the way that suits their business and explain how they have done so. Option B is the different approach used in some older codes, where a company may choose not to comply if it explains why."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 317, $official_bank_source${"itemId":"8fc036eb-5c85-5fb0-93b9-d5fe7a6035b4","questionId":"efa834ca-80e3-5037-87eb-56640f839b2c","sourceKey":"bank:BUA201:GOV-036","payload":{"prompt":"The board of a Nigerian plc proposes that its Managing Director/CEO should also become Chairman of the Board. Under NCCG 2018 this proposal is:","options":["Required by the Code for all listed companies","Inconsistent with the Code, because the Chairman and MD/CEO roles should be held by different persons","Permitted only if the CEO holds more than half of the shares","Recommended by the Code, because it speeds up decisions"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NCCG 2018 requires the positions of Chairman and MD/CEO to be held by different people, and the Chairman should be a non-executive director. Separating the roles prevents one person from both running the company and supervising that work, so options D, A and C are wrong."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 318, $official_bank_source${"itemId":"cf13de3a-e08b-5a20-81c7-bcec8713c7fb","questionId":"d556747f-418f-514b-b16c-8ff4a21449bc","sourceKey":"bank:BUA201:GOV-037","payload":{"prompt":"Under NCCG 2018, the board of directors should meet at least:","options":["Once every quarter","Once every two years","Once every five years","Only at the annual general meeting"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Code requires the board to meet at least once in every quarter, so that directors can oversee the company regularly. Options B, C and D would leave the board unable to give regular oversight."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 319, $official_bank_source${"itemId":"45c9092b-4d34-5d6b-b379-963188a4ee8c","questionId":"fc6461ca-01cc-5bda-997e-9729d33a31d3","sourceKey":"bank:BUA201:GOV-038","payload":{"prompt":"Under NCCG 2018, a company should have a framework that allows staff and others to report unethical conduct confidentially and without suffering harm. This is a:","options":["Board evaluation","Dividend policy","Whistleblowing framework","Succession plan"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"A whistleblowing framework lets people report unethical conduct or violations while keeping their identity confidential and protecting them from detriment. Option A is the board's review of its own performance, and B and D deal with profits and leadership continuity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 320, $official_bank_source${"itemId":"6a5b7fca-bcff-5bdd-9b3c-a8f74a57f76e","questionId":"0b362be6-0088-5b63-954c-d6f8a37305e4","sourceKey":"bank:BUA201:GOV-039","payload":{"prompt":"Under NCCG 2018, in addition to the board's annual evaluation of itself, an evaluation by an independent external consultant should be carried out at least once every:","options":["Ten years","Six months","Twenty years","Three years"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Code expects an annual board evaluation plus an external evaluation by an independent consultant at least every three years. Options A and C are too infrequent for independent review, and B is more often than the Code requires."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 321, $official_bank_source${"itemId":"34f9ff98-5bab-5da4-b711-80692882a281","questionId":"1166f3eb-b735-5646-849d-0efaca3bbd5d","sourceKey":"bank:BUA201:GOV-040","payload":{"prompt":"How many key principles does the Nigerian Code of Corporate Governance 2018 contain?","options":["4","28","10","52"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"NCCG 2018 contains 28 principles grouped under areas such as the board, business conduct and ethics, relationship with shareholders, sustainability, transparency and assurance. Option A is the number of general corporate governance principles (responsibility, accountability, transparency, fairness), a common mix-up."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 322, $official_bank_source${"itemId":"e63bbfcc-81a9-5507-a597-f7e3b4b2efb6","questionId":"a4593185-372b-5ae0-97e0-f3634c43c505","sourceKey":"bank:BUA201:GOV-041","payload":{"prompt":"Ethics and responsibility in managerial practice require managers to:","options":["Set standards through integrity, fairness and transparency and consider all stakeholders, not only themselves and shareholders","Avoid setting standards so that staff can decide freely","Serve shareholders only and ignore employees and customers","Maximise their own bonuses before any other goal"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Ethical managers set standards through integrity, fairness and transparency and make decisions that benefit other stakeholders as well, including employees, customers and the operating environment. Option C looks only at shareholders and D looks only at the manager."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 323, $official_bank_source${"itemId":"9bec1af9-c56c-5817-a1dc-98b658e4fe74","questionId":"08498b33-9b16-574d-95dc-63352bb34df3","sourceKey":"bank:BUA201:GOV-042","payload":{"prompt":"The process in which an individual influences other group members towards the attainment of group or organisational goals is called:","options":["Corporate governance","Leadership","Standardisation","Licensing"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Leadership is the process of influencing group members towards achieving group or organisational goals. Option A is the system for directing and controlling organisations, while D and C are characteristics of a profession."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 324, $official_bank_source${"itemId":"361fa930-4824-599c-9bd5-346a3d7db46e","questionId":"d5212fbe-7807-5827-b669-070b5cf0c931","sourceKey":"bank:BUA201:GOV-043","payload":{"prompt":"The leadership theory which holds that people are born with innate abilities such as intelligence, charisma and courage that predispose them to lead is the:","options":["Contingency theory","Transactional theory","Behavioural theory","Great Man / Trait theory"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"The Great Man or Trait theory says leaders are born with qualities such as intelligence, charisma and courage, and that the fate of organisations depends on them. Option C looks at what leaders do rather than what they are, and A says the situation decides the right approach."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 325, $official_bank_source${"itemId":"91a0c8a1-993a-53d4-99b4-977c39c182d2","questionId":"0829cc9d-6e2e-5c98-a6f5-4abefe6bfea2","sourceKey":"bank:BUA201:GOV-044","payload":{"prompt":"A leadership theory that focuses on what leaders do, such as being task-oriented or people-oriented, rather than on what they are, is the:","options":["Servant leadership theory","Trait theory","Behavioural theory","Great Man theory"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Behavioural theories focus on leaders' actions, for example whether they are task-oriented or people-oriented, as the key to leadership success. Options B and D focus on inborn qualities, the opposite emphasis."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 326, $official_bank_source${"itemId":"a1d6cf24-bcff-5d56-bfad-f36ad36d4cbf","questionId":"9fc3b76b-8d1e-5752-957d-ab33df4fcee1","sourceKey":"bank:BUA201:GOV-045","payload":{"prompt":"Contingency or situational theories of leadership state that:","options":["Rewards and punishments are the only way to motivate","Leaders are born, not made","Followers should never take part in decisions","The situation should determine the leadership approach"],"correctOption":3,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Contingency or situational theories hold that the right leadership approach depends on the situation and on how leaders and group members interact. Option B is the trait view and A is the transactional view."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 327, $official_bank_source${"itemId":"b070a66d-ce6e-5272-9876-bd6ac342a25b","questionId":"0d198aba-5f19-53c8-bf1d-757c584ad06f","sourceKey":"bank:BUA201:GOV-046","payload":{"prompt":"Leaders who inspire and motivate followers to achieve more than the expected result, as in charismatic leadership, follow the:","options":["Trait theory","Behavioural theory","Transformational theory","Transactional theory"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Transformational or inspirational leaders inspire followers to perform beyond expectations, and charismatic leadership is an example. Option D relies on rewards and punishments for meeting set targets rather than on inspiration."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 328, $official_bank_source${"itemId":"d530b48c-b3f2-5392-b36f-517b27cd967a","questionId":"3b0a3f72-0e98-536f-9a62-97fcd27b7114","sourceKey":"bank:BUA201:GOV-047","payload":{"prompt":"Participative or democratic leadership theories argue that:","options":["Involving followers in decision making promotes consensus and commitment","Leaders should rely mainly on rewards and punishments","Leadership ability is entirely inborn","Leaders should focus only on tasks, never on people"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Participative or democratic theories hold that involving followers in decisions builds consensus and commitment. Option B describes transactional leadership and C describes the trait view."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 329, $official_bank_source${"itemId":"0092556e-639b-5b69-88d3-d13e2e949117","questionId":"6b91e3a4-d6de-5cb7-b558-2765b3e0bb39","sourceKey":"bank:BUA201:GOV-048","payload":{"prompt":"A sales manager in Kano pays a N50,000 bonus to every sales officer who meets the monthly target and issues a query to those who fall short. Which leadership theory does this reflect?","options":["Transactional","Participative","Transformational","Servant"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Using rewards for meeting targets and punishments for missing them is transactional leadership. Option C inspires people to go beyond expectations, D focuses on supporting and developing followers, and B involves them in decisions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 330, $official_bank_source${"itemId":"fc070cd3-f0a0-56a8-8164-b07e3a4d1d2e","questionId":"5d4c4e29-c8e1-5232-a5cf-0874526c1298","sourceKey":"bank:BUA201:GOV-049","payload":{"prompt":"Before changing the shift schedule, the plant manager of a Port Harcourt bottling company holds meetings in which workers discuss and vote on three proposed options. This is an example of:","options":["Trait leadership","Transactional leadership","Participative (democratic) leadership","Great Man leadership"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Letting workers discuss and vote on the options involves them in the decision, which is participative or democratic leadership and builds commitment. Option B relies on rewards and punishments, while D and A focus on the leader's inborn qualities."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 331, $official_bank_source${"itemId":"403e0149-2c10-554e-8595-e477e59401e9","questionId":"68beb8fa-8ff1-59d3-aa53-0f1f27b90fd5","sourceKey":"bank:BUA201:GOV-050","payload":{"prompt":"A leader who focuses on empowering and supporting group members, showing empathy, listening, and committing to their personal and professional development rather than exercising authority, practises:","options":["Autocratic leadership","Servant leadership","Transactional leadership","Trait leadership"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Servant leadership puts the growth and support of group members first, through empathy, listening and commitment to their development, rather than through use of authority. Options A and C rely on rewards or command rather than service to followers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 332, $official_bank_source${"itemId":"a152c757-98e7-51b5-a65d-86fe0faf2059","questionId":"b50234b0-37d1-530b-b086-0ea2689e6563","sourceKey":"bank:BUA201:GOV-051","payload":{"prompt":"A board member says: 'Great leaders are born, not made; you either have the charisma and courage or you do not.' This view reflects the:","options":["Great Man / Trait theory","Participative theory","Behavioural theory","Contingency theory"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Believing that leadership comes from inborn traits such as charisma and courage is the Great Man or Trait view. Option D says the situation decides the approach, and C says leadership depends on what leaders do, which can be learned."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 333, $official_bank_source${"itemId":"3c35573d-e841-568d-a236-cf5315938c44","questionId":"115a3838-c63f-50c1-882d-b7a7b7ebdafe","sourceKey":"bank:BUA201:GOV-052","payload":{"prompt":"A bank branch manager in Ibadan is directive during a cash-system failure but consults staff freely during normal periods, explaining that 'the right style depends on the circumstances'. Which theory best explains this approach?","options":["Transactional theory","Great Man theory","Contingency / Situational theory","Trait theory"],"correctOption":2,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Changing leadership approach to fit the circumstances is the core idea of contingency or situational theory. Options B and D tie leadership to inborn qualities and A is about rewards and punishments, none of which explains a deliberate change of style."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 334, $official_bank_source${"itemId":"b19dbfe2-d5d2-5411-81b9-9de9900672c7","questionId":"93035e20-17f7-5e8f-aac7-a496f0f75888","sourceKey":"bank:BUA201:GOV-053","payload":{"prompt":"Leadership ethics requires leaders to:","options":["Guide people with honesty, fairness, respect and accountability, considering all stakeholders rather than profit alone","Keep all decisions secret from employees","Pursue profit alone whatever the effect on others","Reward only friends and relatives"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Leadership ethics means guiding people with honesty, fairness, respect and accountability while considering the interests of all stakeholders, not only profit. Option C focuses on profit alone, and B and D breach transparency and fairness."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 335, $official_bank_source${"itemId":"84c5b503-f969-5853-915c-21030fe39c20","questionId":"7b0a0e43-467d-500e-b9cf-b3affc333084","sourceKey":"bank:BUA201:GOV-054","payload":{"prompt":"Responsible leadership pays attention to ethics, sustainability and accountability, and considers the interests of:","options":["The chief executive only","Employees, customers, shareholders and the wider society","Shareholders only","Government officials only"],"correctOption":1,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Responsible leadership weighs the interests of employees, customers, shareholders and the wider society, and such leaders promote organisational effectiveness. Options A, C and D each consider only one group."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 336, $official_bank_source${"itemId":"1da998c7-1e6a-5c4e-8719-92bbcd483b13","questionId":"9ccb02aa-7c4d-505a-bc37-b21c6fae64f9","sourceKey":"bank:BUA201:GOV-055","payload":{"prompt":"Which of the following is NOT one of the leadership theories that explain how and why people lead?","options":["Comparative advantage theory","Servant leadership","Contingency theory","Behavioural theory"],"correctOption":0,"section":"Corporate Governance, Leadership and Management as a Profession","explanation":"Comparative advantage is a theory of international trade, not of leadership. The leadership theories include Great Man/Trait, behavioural, contingency, transformational, participative, transactional and servant leadership, so options C, B and D all belong."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 337, $official_bank_source${"itemId":"3ad0acbf-e4da-5860-bf32-99ec43eae47c","questionId":"dbed7be2-8ed0-5a3a-8b83-01520f91b5bb","sourceKey":"bank:BUA201:CAS-001","payload":{"prompt":"Aliko Dangote, founder of the Dangote Group, was born in 1957 in which Nigerian state?","options":["Oyo State","Lagos State","Anambra State","Kano State"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Aliko Dangote was born in Kano in 1957, and his business began as a trading company. Options A, B and C are linked to other leaders or businesses in this group, not to Dangote's birthplace."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 338, $official_bank_source${"itemId":"2c5ff5e4-1ec9-5772-a7d9-63413caa365c","questionId":"db958b1e-798b-5592-bd22-12ef039c3c29","sourceKey":"bank:BUA201:CAS-002","payload":{"prompt":"The Dangote Group began in 1977 as a:","options":["Commercial bank licensed by the Central Bank","Large oil refinery in Lagos","State-owned cement factory bought at privatisation","Small commodity-trading business started with a loan from a relative"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Dangote started in 1977 as a commodity trader, funded with a loan from an uncle, and only later moved into manufacturing. Options B and C reflect much later stages of the group's growth, and A was never how Dangote began."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 339, $official_bank_source${"itemId":"e2d7c432-fe49-58c6-9cd5-4bfb2505465e","questionId":"5dc71b78-19d0-5556-beef-7d50410def7c","sourceKey":"bank:BUA201:CAS-003","payload":{"prompt":"Aliko Dangote's move from importing cement and sugar to producing them in Nigeria is an example of which strategy?","options":["Import substitution","Franchising","Export subsidy","Divestment"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Import substitution means replacing imported goods with locally produced ones, which is what Dangote did in cement and sugar. Option D is selling off a business, as Femi Otedola did with Forte Oil, and B is licensing a brand to others."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 340, $official_bank_source${"itemId":"b592616a-f4e4-54f0-ab40-bd0e7c0468a0","questionId":"c5586add-1b3c-53f4-8af7-6a42a23b2998","sourceKey":"bank:BUA201:CAS-004","payload":{"prompt":"A stated purpose of the Dangote Refinery, commissioned in Lagos in 2023, is to:","options":["Replace cement production in the Dangote Group","Export crude oil without refining it","Reduce Nigeria's dependence on imported fuel","Increase Nigeria's imports of refined petroleum"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"The Dangote Refinery was established to refine petroleum in Nigeria and so reduce dependence on imported fuel, an extension of the import substitution idea. Option D is the opposite of its purpose, and B would leave the country still importing refined products."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 341, $official_bank_source${"itemId":"b059a709-904d-5dbe-b8c1-12b6f7e0b7ff","questionId":"fb03ebc8-28da-5151-b59d-e9dda83ded92","sourceKey":"bank:BUA201:CAS-005","payload":{"prompt":"The Dangote Group built which of the following into Africa's largest producer in its industry?","options":["Its airline business","Its cement business","Its banking business","Its telecommunications business"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Dangote built Africa's largest cement production company, with major plants such as Obajana in Kogi State. Options A, C and D are industries not associated with Dangote's flagship business."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 342, $official_bank_source${"itemId":"6b5a2e47-7acc-5441-85ca-f4168007b039","questionId":"6f5b0697-54b8-57d5-8dc4-fdeacd9c41b9","sourceKey":"bank:BUA201:CAS-006","payload":{"prompt":"Aliko Dangote earned his business studies degree from:","options":["Harvard Business School","University of Ife","Al-Azhar University, Cairo","University of Lagos"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Dangote studied business at Al-Azhar University in Cairo, Egypt. Option B is where Ibukun Awosika studied chemistry, and A is where Cosmas Maduka attended an executive programme."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 343, $official_bank_source${"itemId":"f788eb5b-9eef-5905-810c-f08f3ab1c082","questionId":"542e8582-4edd-5b21-ae90-dc87b483e3c9","sourceKey":"bank:BUA201:CAS-007","payload":{"prompt":"Ibukun Awosika is best known as the founder of:","options":["The Chair Centre Group, a furniture manufacturing business","Heirs Holdings, an investment company","Coscharis Group, an automobile business","Zenon Petroleum and Gas"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Ibukun Awosika founded The Chair Centre Group, a furniture manufacturing business. Option C was founded by Cosmas Maduka, B by Tony Elumelu, and D by Femi Otedola."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 344, $official_bank_source${"itemId":"010b64b9-365d-541f-88dd-9ad6dcc68bf6","questionId":"2d821aa8-f157-5f6b-b253-2b5e54ab02fa","sourceKey":"bank:BUA201:CAS-008","payload":{"prompt":"In 2015 Ibukun Awosika became the first woman to hold which position?","options":["Director-General of the Nigerian Institute of Management","Chief Executive of Access Bank","Chairman of First Bank of Nigeria","Governor of the Central Bank of Nigeria"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Ibukun Awosika was appointed Chairman of First Bank of Nigeria in 2015, the first woman to chair the bank. Option B was held by Herbert Wigwe, and D and A are public offices she did not hold."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 345, $official_bank_source${"itemId":"081a47e4-7a04-5490-b225-223e4d5c5da0","questionId":"8b7a50ee-942e-5281-bc30-b075cb435276","sourceKey":"bank:BUA201:CAS-009","payload":{"prompt":"A young Nigerian woman wants to build a manufacturing brand in a male-dominated industry while championing corporate governance and ethical leadership. Whose career is the closest model?","options":["Jack Welch","Ibukun Awosika","Femi Otedola","Elon Musk"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Ibukun Awosika built a furniture manufacturing brand in a male-dominated industry and is a strong advocate of corporate governance, ethical leadership and women's entrepreneurship. Options A, C and D are noted for other things: performance management, high-risk innovation and energy-sector restructuring."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 346, $official_bank_source${"itemId":"e8efee83-0d11-59af-bf45-c53c7029c10d","questionId":"4be4a5ae-7d98-5bae-81e1-21188d12bd71","sourceKey":"bank:BUA201:CAS-010","payload":{"prompt":"Femi Otedola became chairman of African Petroleum in 2007 and in 2010 renamed it:","options":["Coscharis Motors","Transcorp Plc","Geregu Power Plc","Forte Oil Plc"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Otedola gained control of African Petroleum in 2007 and the company was renamed Forte Oil Plc in 2010. Option C is the power company he later focused on, B is linked to Tony Elumelu, and A to Cosmas Maduka."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 347, $official_bank_source${"itemId":"4befc2c9-0632-52d0-951d-231dbad497dc","questionId":"3ecc7d7e-5df3-5e76-94d5-2b8263d13af2","sourceKey":"bank:BUA201:CAS-011","payload":{"prompt":"In 2019 Femi Otedola sold his stake in Forte Oil and concentrated on electricity generation through Geregu Power. This decision is best described as:","options":["Strategic divestment into power generation","Backward integration into sugar farming","Franchising of fuel stations","Import substitution in cement"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Otedola divested from fuel marketing (Forte Oil) and moved into power generation (Geregu Power), a strategic divestment. Option D describes Dangote's strategy, and B and C do not describe selling one business to focus on another."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 348, $official_bank_source${"itemId":"b0c94e84-4277-5468-b9df-7ecaf3b8e29e","questionId":"e0f5910a-3e70-5942-b054-e06f59fdfd6f","sourceKey":"bank:BUA201:CAS-012","payload":{"prompt":"Geregu Power Plc, associated with Femi Otedola, operates in which sector?","options":["Electricity generation","Furniture manufacturing","Commercial banking","Automobile assembly"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Geregu Power operates a power plant and is in electricity generation, which is why Otedola's impact is linked to generation capacity. Options D, B and C are the sectors of Coscharis, The Chair Centre and Access Bank respectively."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 349, $official_bank_source${"itemId":"4cf7b468-8963-50fa-9753-9e034300f776","questionId":"0ce15d03-5a01-5a7f-998e-25ca8be58750","sourceKey":"bank:BUA201:CAS-013","payload":{"prompt":"Before African Petroleum, Femi Otedola set up Zenon Petroleum and Gas in 2003, a company mainly involved in:","options":["Mobile telephone services","Cement production","Insurance underwriting","Fuel marketing and distribution, especially diesel"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Zenon Petroleum and Gas, set up in 2003, marketed and distributed fuel and became a major player in Nigeria's diesel market. Options A, B and C are unrelated industries."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 350, $official_bank_source${"itemId":"9f17b3f2-4add-572f-9b7c-7072662b5800","questionId":"ecab0511-95dd-5098-9646-60724c6f4218","sourceKey":"bank:BUA201:CAS-014","payload":{"prompt":"Cosmas Maduka, founder of the Coscharis Group, learned business through:","options":["The Igbo apprenticeship system","A graduate trainee scheme at a bank","A government scholarship abroad","A family inheritance of a large factory"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Cosmas Maduka is a product of the Igbo apprenticeship system: he trained under a relative in the motor spare-parts trade before starting his own business with very little capital. Options B, C and D do not describe his humble start."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 351, $official_bank_source${"itemId":"4ddf1013-4297-5578-be3a-e6e2456d4604","questionId":"5e96adf0-b1ef-577c-9fc9-18b11b662cf4","sourceKey":"bank:BUA201:CAS-015","payload":{"prompt":"Coscharis began in 1977 as a business dealing in:","options":["Automobile spare parts","Furniture","Crude oil","Cement"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Coscharis started in automobile spare parts and expanded into vehicle distribution and assembly. Option D is Dangote's flagship product, C is linked to oil companies, and B is Ibukun Awosika's industry."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 352, $official_bank_source${"itemId":"7cbf9749-feec-56e6-8b77-32712ee7d879","questionId":"25a0fdfd-23e5-5063-8cec-a7df835baaf0","sourceKey":"bank:BUA201:CAS-016","payload":{"prompt":"The name 'Coscharis' was formed by combining:","options":["The names of two Nigerian cities","The names of two foreign partner companies","Two Igbo words meaning 'hard work'","The founder's first name and his wife's name"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Coscharis combines Cosmas, the founder's first name, with Charis from Charity, his wife's name. Options A, B and C are invented explanations."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 353, $official_bank_source${"itemId":"d0977ba2-afb7-5864-bd79-290865cbe4de","questionId":"e915928d-c2d1-5888-b8c5-0f6c72e6d021","sourceKey":"bank:BUA201:CAS-017","payload":{"prompt":"Cosmas Maduka's leadership style is commonly described as:","options":["Rank-and-yank performance ranking","Faith-driven and discipline-oriented","Cloud-first technology transformation","Africapitalism-driven investment"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Maduka's leadership is described as faith-driven and discipline-oriented, and his impact includes youth mentorship. Option A is associated with Jack Welch, D with Tony Elumelu, and C with Satya Nadella."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 354, $official_bank_source${"itemId":"975a19df-71ad-58c3-91a2-f274d26fe920","questionId":"86ff2578-f9ad-57b5-8e50-599b158500ff","sourceKey":"bank:BUA201:CAS-018","payload":{"prompt":"In 2015 Coscharis Motors became the sole distributor in Nigeria of which car brand?","options":["Tesla","BMW","Toyota","Peugeot"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Coscharis Motors became Nigeria's sole BMW distributor in 2015 and also set up a Ford Ranger assembly plant. Option D is linked to a Dangote-Stellantis assembly plan, and A is Elon Musk's company."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 355, $official_bank_source${"itemId":"9813c3ec-1a57-52cf-bea8-d916c9fa2cae","questionId":"64bbc7af-315d-51f3-a5c6-c58b54750def","sourceKey":"bank:BUA201:CAS-019","payload":{"prompt":"A traditional, mentorship-based business incubation system in which a young person trains under a master trader and is then given settlement capital is the:","options":["Six Sigma programme","Africapitalism model","Igbo apprenticeship system (Igba Boi)","Graduate management trainee scheme"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Under the Igbo apprenticeship system (Igba Boi), an apprentice serves a master trader and is then 'settled' with capital to start his own business. Option A is a quality method, and B is Tony Elumelu's investment philosophy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 356, $official_bank_source${"itemId":"5dc1673c-5575-5f82-bb0b-9fb6c6d46bbd","questionId":"6a58fe88-1240-5fb5-81f3-9d9dd10e2f81","sourceKey":"bank:BUA201:CAS-020","payload":{"prompt":"Under the Igbo apprenticeship system, an apprentice typically trains under a master trader for about:","options":["5 to 7 years","3 to 6 months","15 to 20 years","1 to 2 years"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"An Igba Boi apprentice typically serves a master trader for about five to seven years before being settled with capital. Options B and D are too short for the full apprenticeship, and C is far longer than usual."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 357, $official_bank_source${"itemId":"fcb23d8a-481b-5d3a-9b1c-326a93bbe444","questionId":"178528a1-1521-58c2-8947-7d32b66dc58a","sourceKey":"bank:BUA201:CAS-021","payload":{"prompt":"Which of the following is NOT a feature of the Igbo apprenticeship system (Igba Boi)?","options":["Mentorship under a master trader","Trust-based, community-enforced agreements","Agreements enforced mainly by written contracts filed in court","Post-training settlement capital for the apprentice"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Igba Boi agreements rest on trust and are enforced by the community, not by court-filed written contracts. Options A, B and D are all genuine features of the system."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 358, $official_bank_source${"itemId":"fc7f6b16-f78b-5149-83b5-2b96fe8f8921","questionId":"02a978f3-f364-58c1-a14e-38287cdce4b8","sourceKey":"bank:BUA201:CAS-022","payload":{"prompt":"The philosophy that Africa's private sector can transform the continent through long-term investment that creates both economic prosperity and social wealth is called:","options":["Import substitution","Performance with Purpose","Responsible capitalism","Africapitalism"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Africapitalism, promoted by Tony Elumelu, holds that the African private sector can transform Africa through long-term investment that creates economic and social wealth. Option B is Indra Nooyi's PepsiCo strategy, and C is the broader idea associated with Paul Polman."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 359, $official_bank_source${"itemId":"c48e9080-eb23-5ec0-a09f-846768d5ef3c","questionId":"24af565f-c797-5a71-a3be-c2663b9e0c8a","sourceKey":"bank:BUA201:CAS-023","payload":{"prompt":"In 2010 Tony Elumelu founded both Heirs Holdings and:","options":["Geregu Power","The Tony Elumelu Foundation","The Chair Centre Group","Access Bank"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"In 2010 Elumelu founded Heirs Holdings, his family investment company, and the Tony Elumelu Foundation, which promotes African entrepreneurship. Options D, A and C are linked to Herbert Wigwe, Femi Otedola and Ibukun Awosika respectively."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 360, $official_bank_source${"itemId":"276d9242-4e35-5d33-b4a6-e17c1f5fab03","questionId":"621adb53-65f1-57b2-a104-fcbb5cabc2ee","sourceKey":"bank:BUA201:CAS-024","payload":{"prompt":"In 2015 Tony Elumelu committed US$100 million to an entrepreneurship programme intended to:","options":["Build a cement plant in every African country","Buy a controlling stake in Microsoft","Train, fund and mentor 10,000 African entrepreneurs over 10 years","Fund Nigeria's national football team"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"The 2015 pledge of US$100 million aimed to create 10,000 African entrepreneurs over ten years through training, funding and mentoring. This is why his impact is described as entrepreneurship-driven economic empowerment; options A, B and D are not part of it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 361, $official_bank_source${"itemId":"5ec2ffbe-eeea-5a7d-90f7-db47be8cda52","questionId":"aa8b2f07-1ad9-5386-b4a2-efa7ecf0d1ea","sourceKey":"bank:BUA201:CAS-025","payload":{"prompt":"Standard Trust Bank, led by Tony Elumelu, merged with which bank in 2005?","options":["Access Bank","United Bank for Africa (UBA)","First Bank of Nigeria","Diamond Bank"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Standard Trust Bank merged with United Bank for Africa in 2005, and Elumelu became group managing director of the enlarged UBA. Option D later merged with Access Bank, and C is the bank Ibukun Awosika chaired."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 362, $official_bank_source${"itemId":"329d635e-70ef-5e47-9e87-b91682c4c380","questionId":"148822e4-7319-5730-abf0-15fb9e8251b2","sourceKey":"bank:BUA201:CAS-026","payload":{"prompt":"Herbert Wigwe and his partner Aigboje Aig-Imoukhuede acquired which bank in 2002 and grew it into a multinational institution?","options":["United Bank for Africa","First Bank of Nigeria","Standard Trust Bank","Access Bank"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Wigwe and Aig-Imoukhuede acquired Access Bank in 2002, and Wigwe later became its CEO in 2014, expanding it into a multinational group. Option A is associated with Tony Elumelu, and B with Ibukun Awosika."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 363, $official_bank_source${"itemId":"9f56d86f-863f-5d6f-bd39-e3356bd06415","questionId":"289d6834-bc38-5e12-9173-ec846a51b237","sourceKey":"bank:BUA201:CAS-027","payload":{"prompt":"Access Bank's merger with Diamond Bank, under Herbert Wigwe's leadership, made it Nigeria's largest bank. This illustrates Wigwe's contribution to:","options":["Banking consolidation and corporate expansion","The Igbo apprenticeship system","Import substitution in manufacturing","Electric vehicle adoption"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Merging with Diamond Bank expanded Access Bank's size and reach, which reflects Wigwe's focus on banking consolidation and corporate expansion. Options C and D describe Dangote and Musk, and B is a traditional business training system."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 364, $official_bank_source${"itemId":"4f35f3c6-8635-55b3-87c6-1e1fca744ec2","questionId":"e7f86e27-e1a5-5810-925d-949c10e29f1e","sourceKey":"bank:BUA201:CAS-028","payload":{"prompt":"Herbert Wigwe's investment in education includes founding Wigwe University in:","options":["Kano, Kano State","Ibadan, Oyo State","Isiokpo, Rivers State","Nnewi, Anambra State"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Wigwe founded Wigwe University in his hometown of Isiokpo, Rivers State, reflecting his investment in education and leadership development. Options A, B and D are places linked to other leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 365, $official_bank_source${"itemId":"2f46cc06-6f18-503d-8dc6-38cc16fc8ed5","questionId":"ed465e5f-4b20-5332-b670-bc59c24af764","sourceKey":"bank:BUA201:CAS-029","payload":{"prompt":"Jack Welch served as Chairman and CEO of General Electric (GE) from:","options":["2009 to 2019","2006 to 2018","1995 to 2005","1981 to 2001"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Jack Welch led GE as Chairman and CEO from 1981 to 2001. Option B is Indra Nooyi's tenure as PepsiCo CEO, and A is Paul Polman's tenure at Unilever."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 366, $official_bank_source${"itemId":"7d63c047-6e18-5e41-8d50-446d230ea1ca","questionId":"6f2e45d6-f511-5241-a94e-09d81d8f2ceb","sourceKey":"bank:BUA201:CAS-030","payload":{"prompt":"The quality-improvement programme that Jack Welch introduced at General Electric in the mid-1990s was:","options":["Growth mindset","Six Sigma","Sustainable Living Plan","Performance with Purpose"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Welch adopted Motorola's Six Sigma quality programme at GE in 1995, alongside performance-based ranking. Option D is Nooyi's PepsiCo strategy, C is Polman's Unilever plan, and A is the culture Nadella promoted at Microsoft."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 367, $official_bank_source${"itemId":"0cba2680-a8b7-56f2-9406-24e3bc588f7f","questionId":"08c10845-907a-5841-92e6-5c4014d1a230","sourceKey":"bank:BUA201:CAS-031","payload":{"prompt":"Each year a company's chief executive rewards the top 20% of managers with bonuses and stock options and dismisses the bottom 10%. This system is most closely associated with:","options":["Jack Welch at General Electric","Paul Polman at Unilever","Indra Nooyi at PepsiCo","Satya Nadella at Microsoft"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Rewarding the top 20% and removing the bottom 10% is Jack Welch's performance-based ranking system, often called the vitality curve or 'rank and yank'. Options B, C and D are known for growth mindset, Performance with Purpose and sustainability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 368, $official_bank_source${"itemId":"b669e632-9051-5b37-b1d3-24efa4bc8bc1","questionId":"d10ac881-693a-5869-bce2-1ee13560f635","sourceKey":"bank:BUA201:CAS-032","payload":{"prompt":"Jack Welch insisted that every GE business should be:","options":["Number one or number two in its industry","Run entirely by founders' family members","The lowest-priced firm in every market","Free of any performance targets"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Welch required each GE business to be No. 1 or No. 2 in its industry, otherwise it would be fixed, sold or closed, which reflects his focus on efficiency and restructuring. Options B, C and D do not describe his policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 369, $official_bank_source${"itemId":"41c952a4-45c6-5fc3-9742-a3500db5eea2","questionId":"00bc5f71-bed4-544f-8a4f-41aed577bb57","sourceKey":"bank:BUA201:CAS-033","payload":{"prompt":"Indra Nooyi served as CEO of PepsiCo from:","options":["2009 to 2019","2006 to 2018","1981 to 2001","2014 to 2020"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Indra Nooyi was CEO of PepsiCo from 2006 to 2018. Option C is Jack Welch's tenure at GE and A is Paul Polman's tenure at Unilever."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 370, $official_bank_source${"itemId":"5779a2ef-b452-5b77-9446-49915d097610","questionId":"8b4b034b-42b8-5eac-aea8-980cc30fe465","sourceKey":"bank:BUA201:CAS-034","payload":{"prompt":"Indra Nooyi's strategy of pursuing long-term growth at PepsiCo while having a positive impact on society and the environment was called:","options":["Six Sigma","Africapitalism","Hit Refresh","Performance with Purpose"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Performance with Purpose was Nooyi's strategy at PepsiCo, linking business growth to healthier products and environmental responsibility. Option B is Elumelu's philosophy, A is Welch's quality method, and C is the title of Nadella's book."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 371, $official_bank_source${"itemId":"d4881d49-80fa-5f99-9c82-c1d7ca870fb2","questionId":"b2b41365-c36f-5c9b-b982-722c8a5a0b7c","sourceKey":"bank:BUA201:CAS-035","payload":{"prompt":"PepsiCo under Indra Nooyi grouped its products into 'fun for you', 'better for you' and 'good for you' categories and grew the healthier ones. This reflects:","options":["Performance-based ranking of managers","A shift toward healthier product diversification","Import substitution in cement","Divestment from all food products"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Classifying products from indulgent to healthy and expanding the healthier lines was Nooyi's shift toward healthier product diversification. Option A is Jack Welch's method, and D contradicts the fact that PepsiCo kept and reshaped its product range."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 372, $official_bank_source${"itemId":"344a0943-7e2b-5023-ad81-fefe13bea675","questionId":"b06cb637-21da-5dec-a9c5-26c26f4f4809","sourceKey":"bank:BUA201:CAS-036","payload":{"prompt":"Satya Nadella became CEO of Microsoft in February 2014, succeeding:","options":["Steve Ballmer","Jack Welch","Bill Gates","Ramon Laguarta"],"correctOption":0,"section":"Case Studies of Successful Managers","explanation":"Satya Nadella was announced as Microsoft's CEO in February 2014, succeeding Steve Ballmer. Option C co-founded Microsoft and was CEO before Ballmer, B led GE, and D succeeded Indra Nooyi at PepsiCo."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 373, $official_bank_source${"itemId":"e62131f0-b880-5d59-ad73-fad362a35b40","questionId":"d0e049a9-364d-5d2d-87e1-4412bc584f75","sourceKey":"bank:BUA201:CAS-037","payload":{"prompt":"A new CEO wants to change a rigid 'know-it-all' corporate culture into one where employees keep learning and experimenting. Which leader's approach is the best model?","options":["Jack Welch's 'No. 1 or No. 2' rule at GE","Aliko Dangote's import substitution in cement","Satya Nadella's growth-mindset leadership at Microsoft","Femi Otedola's divestment from Forte Oil"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Nadella promoted empathetic, growth-mindset leadership and continual learning, which revitalised Microsoft's culture. Option A is a portfolio rule, and D and B are business strategies rather than culture change."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 374, $official_bank_source${"itemId":"d8509b7a-1135-5a7d-b04d-4ec8bf2b15b5","questionId":"5b5ff1df-8d05-553f-8463-815c0fbdb472","sourceKey":"bank:BUA201:CAS-038","payload":{"prompt":"Satya Nadella is credited with transforming Microsoft into a:","options":["Soft drinks company","Fuel distribution company","Cloud-first company","Rocket manufacturing company"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Under Nadella, Microsoft was transformed into a cloud-first company, building on his earlier work leading the cloud and enterprise group and Azure. Options A, B and D describe the industries of other leaders."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 375, $official_bank_source${"itemId":"34367ef0-88ff-55ab-8831-9e94ab614d32","questionId":"f20ebda5-ba14-5785-b4b8-e988fd296486","sourceKey":"bank:BUA201:CAS-039","payload":{"prompt":"Elon Musk founded SpaceX in 2002 and became CEO of which electric-vehicle company in 2008?","options":["PepsiCo","Tesla","General Electric","Unilever"],"correctOption":1,"section":"Case Studies of Successful Managers","explanation":"Musk founded SpaceX in 2002 and became CEO of Tesla in 2008, after joining it as an investor and chairman in 2004. His high-risk, innovation-driven style is linked to electric vehicles and private space travel; options C, A and D were led by Welch, Nooyi and Polman."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 376, $official_bank_source${"itemId":"417f8b98-7151-516a-b3e1-b5bd6bd2838c","questionId":"71128340-e62d-54d8-bb59-a706a714d10a","sourceKey":"bank:BUA201:CAS-040","payload":{"prompt":"Elon Musk's leadership style is best described as:","options":["Cautious and focused on avoiding new technology","Based mainly on an apprenticeship system","Faith-driven and discipline-oriented","High-risk and innovation-driven"],"correctOption":3,"section":"Case Studies of Successful Managers","explanation":"Musk's leadership is high-risk and innovation-driven, which accelerated electric vehicle adoption and technological disruption. Option C describes Cosmas Maduka, and A is the opposite of Musk's approach."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 377, $official_bank_source${"itemId":"c2ea207e-c5c2-5b99-b4d0-8c80ea49326f","questionId":"048ab992-0b63-52e8-a816-e1539b935159","sourceKey":"bank:BUA201:CAS-041","payload":{"prompt":"As CEO of Unilever (2009 to 2019), Paul Polman launched the Unilever Sustainable Living Plan in 2010, which aimed among other things to:","options":["Stop selling food products entirely","Close all factories in developing countries","Halve the environmental footprint of Unilever's products","Double the company's use of plastic packaging"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"The Unilever Sustainable Living Plan, launched in November 2010 under Polman, aimed to halve the environmental footprint of the company's products while growing the business. Options A, B and D contradict its sustainability goals."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 378, $official_bank_source${"itemId":"3a177204-f20f-5b83-a353-31d7a9c76f8c","questionId":"47a1b8c2-b028-52df-a081-c79cd40fe12d","sourceKey":"bank:BUA201:CAS-042","payload":{"prompt":"Arguing that quarterly targets push managers into short-term decisions that hurt the business, a CEO stops giving short-term earnings guidance to investors. Which leader is famous for doing this?","options":["Femi Otedola at Forte Oil","Elon Musk at Tesla","Paul Polman at Unilever","Jack Welch at General Electric"],"correctOption":2,"section":"Case Studies of Successful Managers","explanation":"Paul Polman discontinued short-term earnings guidance at Unilever to focus managers on long-term, responsible performance, part of his promotion of responsible capitalism. Option D is known for strict short-term performance ranking, and B and A are not known for this decision."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 379, $official_bank_source${"itemId":"18706c7d-e653-59ff-a3d9-f03bc9abd61b","questionId":"7ac9024e-ea52-5705-9773-6b12e46c7931","sourceKey":"bank:BUA201:PQ-014","payload":{"prompt":"PESTLE analysis is most useful during:","options":["Inventory control","Environmental scanning","Performance appraisal","Budget variance analysis"],"correctOption":1,"section":"The Business Environment","explanation":"PESTLE looks at Political, Economic, Social, Technological, Legal and Environmental factors outside the firm, so it is a tool for scanning the external environment. Options C, A and D are internal management tasks dealing with staff, stock and budgets."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 380, $official_bank_source${"itemId":"0df77089-ca78-54ac-8fb7-ceba1c804ee6","questionId":"63ed5af7-e57b-569a-a00a-4ad9e6f11167","sourceKey":"bank:BUA201:PQ-041","payload":{"prompt":"An economic recession reduces consumer demand primarily because of:","options":["A stable exchange rate","Increased liquidity","Market liberalisation","Reduced disposable income"],"correctOption":3,"section":"The Business Environment","explanation":"In a recession, job losses and falling incomes leave households with less money to spend after taxes, so demand falls. Options B and A would generally support spending rather than reduce it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 381, $official_bank_source${"itemId":"f28efb0c-34bc-56cf-b931-0ec5fc697d81","questionId":"dfaff60a-447c-5f78-bbc1-e1c4eee4d610","sourceKey":"bank:BUA201:PQ-048","payload":{"prompt":"Inflation may benefit debtors because:","options":["The real value of the money they owe declines","The currency appreciates","Interest rates always fall","Liquidity increases"],"correctOption":0,"section":"The Business Environment","explanation":"With inflation, a fixed amount of debt is repaid with money that buys less than when it was borrowed, so the real burden of the debt falls. Option C is wrong because interest rates often rise during inflation, and option B is the reverse of what inflation usually does to a currency."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 382, $official_bank_source${"itemId":"3279b7ce-8138-56ea-8d1a-ce6f3682d220","questionId":"c8bb64ab-bb74-5ae6-a50b-15c967b1135b","sourceKey":"bank:BUA201:PQ-055","payload":{"prompt":"Which of the following is part of internal environment analysis?","options":["The inflation rate","Government policy","Evaluating the firm's strengths in a SWOT analysis","PESTLE analysis"],"correctOption":2,"section":"The Business Environment","explanation":"Strengths and weaknesses in SWOT come from inside the firm, such as its skills, resources and reputation. Options D, B and A all concern the external environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 383, $official_bank_source${"itemId":"6c8350ed-5622-5e78-b267-c35d464e9a49","questionId":"bd02e828-2e40-5bb1-94fd-b024c800fdce","sourceKey":"bank:BUA201:PQ-056","payload":{"prompt":"In a SWOT analysis, opportunities arise from the:","options":["External environment","Firm's internal weaknesses","Organisational culture","Firm's financial ratios"],"correctOption":0,"section":"The Business Environment","explanation":"Opportunities and threats are the external half of SWOT, coming from markets, technology, government policy and competitors. Options C and D are internal matters that would be analysed as strengths or weaknesses, as would option B."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 384, $official_bank_source${"itemId":"e617d9e2-3ce1-5ad3-b644-10bf02802b29","questionId":"d73f2d4c-ebd3-59a0-abe4-88e162a2cde3","sourceKey":"bank:BUA201:PQ-057","payload":{"prompt":"An organisation's corporate culture directly influences its:","options":["National interest rates","Ethical climate","Exchange rate","Inflation rate"],"correctOption":1,"section":"The Business Environment","explanation":"Corporate culture is the shared values and norms inside the organisation, and it shapes how people judge right and wrong at work. Options C, D and A are macroeconomic variables outside the firm's control."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 385, $official_bank_source${"itemId":"115e36e4-0d8a-53c7-9c30-489bcc38c4b5","questionId":"b46221d8-d418-5bd3-a95d-6086e5745aaa","sourceKey":"bank:BUA201:PQ-082","payload":{"prompt":"Strategic flexibility mainly enhances a firm's:","options":["Ability to adapt to changes in its environment","Likelihood of exiting markets","Chances of governance failure","Exposure to inflation"],"correctOption":0,"section":"The Business Environment","explanation":"Strategic flexibility is a firm's capacity to shift resources and change course quickly when the environment changes, so it can absorb shocks and take up new opportunities. Option B is wrong because flexibility helps a firm stay in markets rather than leave them. Options C and D are threats, not benefits."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 386, $official_bank_source${"itemId":"e8d452f3-dddd-5a45-bd5c-041b361c2a77","questionId":"a9e94256-4032-5dc5-a5a2-8490b4bad01e","sourceKey":"bank:BUA201:PQ-095","payload":{"prompt":"Economic liberalisation tends to increase:","options":["Monopoly","Competition","Centralisation","Governance rigidity"],"correctOption":1,"section":"The Business Environment","explanation":"Economic liberalisation removes government restrictions such as price controls, licensing limits and state monopolies, so more firms can enter markets and competition rises. Option A is the opposite, since liberalisation breaks up protected positions. Options C and D describe tighter control, which liberalisation moves away from."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 387, $official_bank_source${"itemId":"a5d1b7a4-5416-5050-b9c3-7e2b4bb2a406","questionId":"6389d3ad-c3b9-5ed6-b7bd-aef87114fbce","sourceKey":"bank:BUA201:PQ-100","payload":{"prompt":"A sustainable competitive advantage arises from resources that are:","options":["Valuable, rare and hard to imitate","Common and easily accessible","Easily transferable to rivals","Short-term oriented"],"correctOption":0,"section":"The Business Environment","explanation":"A firm keeps its advantage over rivals when its resources and capabilities are valuable, rare and difficult for others to copy or substitute. Options B and C describe resources any competitor can obtain, so they cannot set a firm apart for long. Option D is wrong because an advantage that lasts only briefly is not sustainable."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 388, $official_bank_source${"itemId":"0a616817-c5e9-5123-8a44-35b997ffec80","questionId":"d3421d5a-48ca-50ed-8aa6-dfd081098c7b","sourceKey":"bank:BUA201:PQ-123","payload":{"prompt":"Which of the following is the greatest cause of uncertainty for a business because it lies outside management's control?","options":["Internal resources","Organisational culture","Political instability","Employee morale"],"correctOption":2,"section":"The Business Environment","explanation":"Political instability is part of the external (macro) environment, so management cannot control it, and it can suddenly change policies, security and demand. Options A, B and D are internal factors that management can plan for and influence directly."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 389, $official_bank_source${"itemId":"a7ab198b-7d1d-5a59-bfff-e160c556ccc8","questionId":"f45495f9-5aa1-59e0-b2fa-d4f8a64529f7","sourceKey":"bank:BUA201:PQ-124","payload":{"prompt":"A PESTLE analysis is MOST useful for assessing:","options":["Internal strengths","Competitors' strategies","Macro-environmental factors","Employee performance"],"correctOption":2,"section":"The Business Environment","explanation":"PESTLE stands for Political, Economic, Social, Technological, Legal and Environmental factors, which together make up the broad external (macro) environment of a business. Option A is internal analysis, as in the strengths part of SWOT, option B is competitor analysis in the immediate market, and option D is an HR appraisal matter."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 390, $official_bank_source${"itemId":"12ef9ed5-1acd-5ea1-80e4-f50fbb8720ac","questionId":"3eb0924e-166d-5ae0-b048-30cbc164c284","sourceKey":"bank:BUA201:PQ-143-a","payload":{"prompt":"Which of the following is part of a firm's internal environment?","options":["Its organisational culture","Government policy","The rate of inflation","Technological change in the economy"],"correctOption":0,"section":"The Business Environment","explanation":"The internal environment consists of factors within the organisation that management can largely control, such as its culture, staff, structure and resources. Options B, C and D come from outside the firm and belong to the external environment, which management cannot control."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 391, $official_bank_source${"itemId":"8fc42207-4523-5b67-a1a1-a5ba8b1e903d","questionId":"e635542c-2a59-5d56-9397-2a97ac176f8b","sourceKey":"bank:BUA201:PQ-143-b","payload":{"prompt":"Customers, suppliers and competitors are part of a firm's:","options":["Macro (general) environment","Internal environment","Micro (task) environment","Political environment"],"correctOption":2,"section":"The Business Environment","explanation":"The micro or task environment consists of external groups that deal directly with the firm and affect it day to day, such as customers, suppliers and competitors. Option A covers broad forces like the economy, politics and technology that affect all firms. Option B is wrong because these groups are outside the firm, and option D is just one part of the macro environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 392, $official_bank_source${"itemId":"e6c6f55c-00c9-5344-b702-c1c154da8486","questionId":"6c688235-377c-503e-9e23-c9ab7465f88e","sourceKey":"bank:BUA201:ENV-001","payload":{"prompt":"The business environment of an organisation is best defined as:","options":["Only the physical building in which the business operates","Only the customers who buy the firm's products","All the internal and external factors and forces that affect its operations and performance","Only the laws made by government for businesses"],"correctOption":2,"section":"The Business Environment","explanation":"The business environment is the full set of internal and external factors and forces that influence how a business operates and performs. Options A, B and D each pick out one small part and treat it as the whole."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 393, $official_bank_source${"itemId":"b369028c-6e3e-572d-9113-d82990d05925","questionId":"062b42f2-5c84-5424-ba12-56692dfa9632","sourceKey":"bank:BUA201:ENV-002","payload":{"prompt":"The factors within an organisation, such as its employees, culture, owners, board and physical resources, make up its:","options":["Political environment","Macro environment","Internal environment","General environment"],"correctOption":2,"section":"The Business Environment","explanation":"The internal environment consists of factors inside the organisation, such as staff, culture, owners, the board and physical resources, which management can largely influence. Options B and D are names for the broad external forces, and A is one part of that external environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 394, $official_bank_source${"itemId":"22d8e8ab-ea38-5c3f-9427-9ade20a0960a","questionId":"dd08e6f4-29dd-5798-b8f0-732d8a16fd80","sourceKey":"bank:BUA201:ENV-003","payload":{"prompt":"Factors outside an organisation that affect it but over which it has little or no direct control make up its:","options":["External environment","Management hierarchy","Internal environment","Organisational culture"],"correctOption":0,"section":"The Business Environment","explanation":"The external environment covers forces outside the firm, such as customers, competitors, the economy and government, which the firm cannot directly control but must respond to. Options B, C and D are all inside the organisation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 395, $official_bank_source${"itemId":"0a79f98a-4214-53df-b6e3-eeccc0c313fd","questionId":"b44afc92-c4f9-5b3c-ae40-c5dc7ae6ac10","sourceKey":"bank:BUA201:ENV-005","payload":{"prompt":"Which of the following is NOT part of a firm's external environment?","options":["The country's exchange rate","The firm's suppliers","The firm's competitors","The skills of the firm's own employees"],"correctOption":3,"section":"The Business Environment","explanation":"The skills of the firm's own employees are an internal resource. Suppliers, the exchange rate and competitors in options B, A and C all lie outside the firm and form part of its external environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 396, $official_bank_source${"itemId":"e625bc6d-0917-5992-ad44-61c7c574f051","questionId":"4be5c5b9-f39c-589f-a377-219cee2cb776","sourceKey":"bank:BUA201:ENV-006","payload":{"prompt":"Compared with the external environment, the internal environment of a business is:","options":["Made up only of government policies","The same for every business in the country","Completely outside management's influence","More within the control of the firm's management"],"correctOption":3,"section":"The Business Environment","explanation":"Internal factors such as staff, structure and culture can be shaped by management, while external factors can only be anticipated and responded to. Option C describes the external environment, and B is wrong because each firm's internal environment is unique."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 397, $official_bank_source${"itemId":"90f2f3e9-d269-502d-b8d3-fbd7492710f2","questionId":"2c128c1e-a8bf-5625-8c16-17884944d4d7","sourceKey":"bank:BUA201:ENV-007","payload":{"prompt":"The forces close to a company that directly affect its ability to serve its customers, such as suppliers, customers, competitors and intermediaries, make up its:","options":["Legal environment","Micro (task) environment","Macro (general) environment","Internal environment"],"correctOption":1,"section":"The Business Environment","explanation":"The micro or task environment contains the specific groups close to the firm, such as customers, suppliers, competitors and intermediaries, that directly affect its daily operations. Option C refers to broad societal forces such as PESTLE factors, and D is inside the firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 398, $official_bank_source${"itemId":"0b43dfa0-f540-50c6-832c-9380336f2150","questionId":"3b1e31c9-e93c-5714-8ca6-9049f26ad146","sourceKey":"bank:BUA201:ENV-008","payload":{"prompt":"The broad external forces that affect all businesses in an economy, such as political, economic, social and technological conditions, make up the:","options":["Macro (general) environment","Organisational structure","Internal environment","Micro (task) environment"],"correctOption":0,"section":"The Business Environment","explanation":"The macro or general environment is made up of broad forces such as political, economic, social, technological, legal and environmental conditions that affect all firms. Option D is the narrower set of groups that deal directly with one firm, and C and B are inside the organisation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 399, $official_bank_source${"itemId":"afcc2a07-f8d1-5771-8c2f-45bb6558b9c8","questionId":"1ec5edd1-c041-5a25-b20d-739786b4aa0c","sourceKey":"bank:BUA201:ENV-009","payload":{"prompt":"Which of the following is a MICRO environment factor for a Lagos restaurant?","options":["The level of internet penetration in Nigeria","The farmers and traders who supply its foodstuffs","The national unemployment rate","Nigeria's population growth rate"],"correctOption":1,"section":"The Business Environment","explanation":"The restaurant's suppliers deal with it directly and affect its daily operations, so they are part of its micro environment. Options A, C and D are broad national conditions in the macro environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 400, $official_bank_source${"itemId":"a3887b8b-97eb-5285-a323-552c0ec8b6ae","questionId":"a52b88b4-45d1-529e-b951-965ca52945cf","sourceKey":"bank:BUA201:ENV-010","payload":{"prompt":"Which of the following is a MACRO environment factor for a Nigerian manufacturing firm?","options":["A new competitor opening next door","A dispute with its main raw-material supplier","A rise in the national inflation rate","A complaint from one of its distributors"],"correctOption":2,"section":"The Business Environment","explanation":"The national inflation rate affects all firms in the economy and is a macro (economic) factor. Options A, B and D involve specific suppliers, competitors and distributors that deal directly with the firm, so they are micro factors."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 401, $official_bank_source${"itemId":"384ef801-60b7-5109-bba5-0a2f2f87665a","questionId":"eb9fb77e-86c2-5e1b-a9df-9484ac81aab1","sourceKey":"bank:BUA201:ENV-011","payload":{"prompt":"Which statement best distinguishes the micro environment from the macro environment?","options":["The micro environment affects a particular firm directly, while the macro environment consists of broad forces affecting all firms","The micro environment is inside the firm, while the macro environment is outside it","The micro environment includes only government, while the macro environment includes only customers","There is no real difference; they are two names for the same thing"],"correctOption":0,"section":"The Business Environment","explanation":"Both are external, but the micro environment consists of groups that deal with a particular firm directly, while the macro environment is the broad set of forces affecting every firm. Option B confuses micro with internal, a common mix-up."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 402, $official_bank_source${"itemId":"64019216-8658-50b2-8680-40d4cf35dd50","questionId":"3501483a-7c47-5f6f-9586-a77fdae28278","sourceKey":"bank:BUA201:ENV-012","payload":{"prompt":"In PESTLE analysis, the letters stand for:","options":["Product, Economic, Sales, Technology, Labour and Employment","Political, Ethical, Strategic, Tactical, Legal and Economic","Political, Economic, Social, Technological, Legal and Environmental","Planning, Economic, Strategic, Technical, Leadership and Ethical"],"correctOption":2,"section":"The Business Environment","explanation":"PESTLE stands for Political, Economic, Social, Technological, Legal and Environmental factors in the macro environment. Options A, B and D mix in words that are not part of the framework."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 403, $official_bank_source${"itemId":"bb150c62-3b27-5112-8bd0-0a904513f6b9","questionId":"075c56e9-78a9-5dad-93a5-3e85d3d1341d","sourceKey":"bank:BUA201:ENV-013","payload":{"prompt":"Which environment does a PESTLE analysis NOT directly examine?","options":["The economic conditions facing all firms","The legal framework businesses must obey","The political climate of the country","The firm's internal strengths and weaknesses"],"correctOption":3,"section":"The Business Environment","explanation":"PESTLE scans the external macro environment, so it does not directly examine a firm's internal strengths and weaknesses, which are assessed through tools such as the strengths and weaknesses part of SWOT. Options A, B and C are exactly what PESTLE covers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 404, $official_bank_source${"itemId":"dadae5de-30f0-5862-94d5-2e697310b505","questionId":"35ee8721-1cbe-5a47-88e1-5c660ded3e42","sourceKey":"bank:BUA201:ENV-014","payload":{"prompt":"Ahead of a general election, investors delay projects in Nigeria because they are unsure whether a new government will continue existing economic policies. Under PESTLE, this uncertainty is mainly a(n):","options":["Technological factor","Political factor","Social factor","Environmental factor"],"correctOption":1,"section":"The Business Environment","explanation":"Uncertainty about elections, government stability and the direction of government policy is a political factor. Option A concerns innovation, D concerns the natural environment, and C concerns demographics and culture."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 405, $official_bank_source${"itemId":"3e6c27f0-04fa-56d5-9e81-cafe68bd68be","questionId":"1807bad7-0e60-5a22-a1b8-6199a2cad8a7","sourceKey":"bank:BUA201:ENV-015","payload":{"prompt":"A Nigerian importer finds that the naira price of a container of goods has risen from N18 million to N27 million because the naira has weakened against the dollar. Under PESTLE, this is a(n):","options":["Technological factor","Economic factor","Legal factor","Social factor"],"correctOption":1,"section":"The Business Environment","explanation":"Exchange rate movements are an economic factor, because they change the cost of imports and the purchasing power of money. Option C would require a change in the law, and D and A concern society and technology."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 406, $official_bank_source${"itemId":"99bbfc91-c79b-50b5-a804-3726ef5e9365","questionId":"c0876d85-7c88-5d31-b690-99ac1849a53b","sourceKey":"bank:BUA201:ENV-016","payload":{"prompt":"Rising inflation means a family in Ibadan can now buy less food with the same N50,000 monthly budget, so a supermarket's sales volume falls. Under PESTLE, the supermarket is affected by a(n):","options":["Economic factor","Legal factor","Environmental factor","Political factor"],"correctOption":0,"section":"The Business Environment","explanation":"Inflation reduces real purchasing power, which is an economic factor in the macro environment. Option D relates to government stability and policy direction, C to the natural environment, and B to laws."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 407, $official_bank_source${"itemId":"78ba171c-249b-5c3a-92ca-5451c699d7a6","questionId":"cc47f891-4e40-50fa-8f24-f149f082fb03","sourceKey":"bank:BUA201:ENV-017","payload":{"prompt":"The Central Bank of Nigeria raises its monetary policy rate, and a manufacturer's bank loan becomes more expensive. Under PESTLE, the higher cost of borrowing is best classified as a(n):","options":["Economic factor","Environmental factor","Technological factor","Social factor"],"correctOption":0,"section":"The Business Environment","explanation":"Interest rates and the cost of credit are economic factors, because they affect how expensive it is for firms to borrow and invest. Options B, C and D concern society, innovation and the natural environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 408, $official_bank_source${"itemId":"8ed30295-1ed3-5145-8f61-b658f3fd0964","questionId":"81efa9a1-6cbf-5f19-9cd8-d308648228e8","sourceKey":"bank:BUA201:ENV-018","payload":{"prompt":"A Nigerian company notices that a large and growing share of the population is young and moving into cities, so it launches products aimed at young urban buyers. Under PESTLE, it is responding to a(n):","options":["Legal factor","Environmental factor","Political factor","Social factor"],"correctOption":3,"section":"The Business Environment","explanation":"Population structure, age distribution and urbanisation are social (socio-cultural) factors. Option A would involve a new law, C would involve government or elections, and B the natural environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 409, $official_bank_source${"itemId":"498b9564-040b-5c3c-8003-dcb2ba45a23c","questionId":"48ff355d-94d8-529c-8ac6-a59078e8038c","sourceKey":"bank:BUA201:ENV-019","payload":{"prompt":"A food company in Kano reformulates its products and adjusts its advertising to respect the religious and cultural values of its customers. Under PESTLE, it is responding to a(n):","options":["Technological factor","Social factor","Economic factor","Environmental factor"],"correctOption":1,"section":"The Business Environment","explanation":"Religion, culture, values and lifestyles are social factors that shape what customers will buy and how they respond to marketing. Option C concerns prices and incomes, A innovation, and D the natural environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 410, $official_bank_source${"itemId":"40f66b98-82a9-5232-9377-c3a38d90980e","questionId":"466ab086-2a5b-5d0a-bb98-844ad6af09a4","sourceKey":"bank:BUA201:ENV-020","payload":{"prompt":"The rapid spread of smartphones and mobile payment apps in Nigeria allows a small Aba shoe-maker to sell online and receive payments instantly. Under PESTLE, this is a(n):","options":["Technological factor","Legal factor","Political factor","Environmental factor"],"correctOption":0,"section":"The Business Environment","explanation":"New tools such as smartphones, the internet and mobile payments are technological factors that create new ways of doing business. Options B, C and D concern government, laws and the natural environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 411, $official_bank_source${"itemId":"3cd72623-0cb4-5bf9-bec5-3b5c39d9ed0c","questionId":"ff3d47ec-5070-5974-88cf-f92da950ae81","sourceKey":"bank:BUA201:ENV-021","payload":{"prompt":"A bank in Lagos replaces many manual teller transactions with automated machines and online banking. The development that made this possible is mainly a(n):","options":["Political factor","Economic factor","Social factor","Technological factor"],"correctOption":3,"section":"The Business Environment","explanation":"Automation and online banking are technological developments that change how services are produced and delivered. Option C could influence how quickly customers adopt it, but the change itself comes from technology."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 412, $official_bank_source${"itemId":"846a16c5-1a15-567e-9934-bb99b6d2db0b","questionId":"5ca56c03-0da2-56df-b23e-d4913165f0c9","sourceKey":"bank:BUA201:ENV-022","payload":{"prompt":"After the Nigeria Data Protection Act 2023 was signed into law, a fintech company had to change how it collects and stores customers' personal information. Under PESTLE, this is a(n):","options":["Social factor","Legal factor","Environmental factor","Economic factor"],"correctOption":1,"section":"The Business Environment","explanation":"A law that sets rules businesses must obey, such as the Nigeria Data Protection Act 2023, is a legal factor. Options A, C and D do not involve binding legal rules."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 413, $official_bank_source${"itemId":"9fed0488-fe13-5fd5-8daa-a647714c420a","questionId":"3259e708-bd2a-5cb6-82d5-a571638a2168","sourceKey":"bank:BUA201:ENV-023","payload":{"prompt":"A new labour law raises the minimum wage that employers must pay, and a Nigerian factory must increase its wage bill. Under PESTLE, the requirement to pay the new wage is best classified as a(n):","options":["Legal factor","Social factor","Environmental factor","Technological factor"],"correctOption":0,"section":"The Business Environment","explanation":"A statutory requirement that employers must obey, such as a minimum wage law, is a legal factor. Options B, C and D do not create binding obligations of this kind."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 414, $official_bank_source${"itemId":"8d89e1f3-8993-502b-91cd-839300fb27d7","questionId":"2699f422-1d1e-5208-8604-c3a3d6a6a891","sourceKey":"bank:BUA201:ENV-024","payload":{"prompt":"In PESTLE analysis, the difference between political and legal factors is that:","options":["Political factors concern government stability, ideology and policy direction, while legal factors concern the actual laws and regulations businesses must obey","Political factors are internal, while legal factors are external","There is no difference; the two terms are interchangeable","Political factors concern only taxes, while legal factors concern only elections"],"correctOption":0,"section":"The Business Environment","explanation":"Political factors relate to the stability, attitudes and direction of government, while legal factors are the specific laws and regulations that bind businesses. Option D swaps and narrows the ideas, and B is wrong because both are external."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 415, $official_bank_source${"itemId":"4eb5aceb-5a89-532d-8be8-e605fd22d275","questionId":"2cbe20f0-335e-5583-b79a-281dfe7f30b4","sourceKey":"bank:BUA201:ENV-025","payload":{"prompt":"Heavy seasonal flooding damages a warehouse in Kogi State and cuts road access for weeks. Under PESTLE, this is a(n):","options":["Legal factor","Environmental factor","Social factor","Technological factor"],"correctOption":1,"section":"The Business Environment","explanation":"Weather, climate and natural events such as floods are environmental (ecological) factors. Options A, C and D concern society, laws and technology rather than the natural environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 416, $official_bank_source${"itemId":"035fc3d5-a5e4-55c6-bf92-f93830cc88db","questionId":"e0e8327f-7db5-5dd6-9062-ccaa2a66952c","sourceKey":"bank:BUA201:ENV-026","payload":{"prompt":"Communities in an oil-producing area complain about pollution from a company's operations, and the company invests in cleaner production and waste control. Under PESTLE, the pollution issue is mainly a(n):","options":["Technological factor","Political factor","Environmental factor","Economic factor"],"correctOption":2,"section":"The Business Environment","explanation":"Pollution, waste and the impact of operations on the natural environment are environmental factors. Option A may be part of the solution, but the issue being responded to is environmental."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 417, $official_bank_source${"itemId":"6142e7b7-0c6d-5e1c-ba37-51d878dad37a","questionId":"a3170d33-5d99-5932-9cda-9d4b635f2420","sourceKey":"bank:BUA201:ENV-027","payload":{"prompt":"The main purpose of carrying out a PESTLE analysis is to:","options":["Decide the salaries of individual employees","Record the daily sales of each product","Identify external macro-environmental factors that may create opportunities or threats","Calculate the firm's net profit for the year"],"correctOption":2,"section":"The Business Environment","explanation":"PESTLE helps managers scan the macro environment to spot political, economic, social, technological, legal and environmental changes that may become opportunities or threats. Options A, B and D are accounting or HR tasks, not environmental analysis."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 418, $official_bank_source${"itemId":"e859e7d1-2dec-510c-be04-42804ea5235f","questionId":"08cbfa09-1acc-58e1-be00-1368b40397a7","sourceKey":"bank:BUA201:ENV-028","payload":{"prompt":"The process of monitoring and analysing the external environment to detect changes that may affect a business is called:","options":["Environmental scanning","Job evaluation","Market segmentation","Budgetary control"],"correctOption":0,"section":"The Business Environment","explanation":"Environmental scanning means systematically watching the external environment for trends and changes that may affect the firm, and PESTLE is one tool for doing it. Options B, C and D are HR, marketing and finance techniques."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 419, $official_bank_source${"itemId":"1753ec3f-57ba-5f2a-bbec-de1d59c33f2f","questionId":"eb1309b6-b8f3-5390-9a93-fd19f8d844da","sourceKey":"bank:BUA201:ENV-029","payload":{"prompt":"In SWOT analysis, which elements come from the internal environment?","options":["Threats and weaknesses","Opportunities and threats","Opportunities and strengths","Strengths and weaknesses"],"correctOption":3,"section":"The Business Environment","explanation":"Strengths and weaknesses are internal features of the firm, while opportunities and threats come from the external environment. Option B is the external half, and C and A mix internal and external elements."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 420, $official_bank_source${"itemId":"e205844e-3977-5911-95e2-ec54718633dc","questionId":"5c171501-cbc7-5a51-b7d5-10672e00bede","sourceKey":"bank:BUA201:ENV-030","payload":{"prompt":"A Nigerian paint manufacturer finds that its machines are old and its staff lack modern skills. In SWOT terms, these are:","options":["Threats arising from the external environment","Strengths arising from the micro environment","Weaknesses arising from the internal environment","Opportunities arising from the macro environment"],"correctOption":2,"section":"The Business Environment","explanation":"Old machines and skill gaps are internal shortcomings, so they are weaknesses. Option A wrongly places them outside the firm, and D and B misdescribe them as favourable."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 421, $official_bank_source${"itemId":"869fb168-4282-594b-9f6f-c1cf3ccbde55","questionId":"0a1d71a9-8d45-56bd-8984-38ad0caf1b1f","sourceKey":"bank:BUA201:ENV-031","payload":{"prompt":"A foreign company with lower prices opens a large plant in Nigeria and begins taking customers from a local biscuit maker. For the local firm, this is best described as:","options":["A strength in its internal environment","An opportunity in its internal environment","A weakness in its internal environment","A threat in its micro (task) environment"],"correctOption":3,"section":"The Business Environment","explanation":"A new competitor is an external group that directly affects the firm, so it is part of the micro environment and, here, a threat. Options A, B and C wrongly treat an outside competitor as an internal factor."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 422, $official_bank_source${"itemId":"98bf679c-4f5d-59f0-918b-63cbccf3ade1","questionId":"d72c2922-960d-51da-911e-a4eba7d6383a","sourceKey":"bank:BUA201:ENV-032","payload":{"prompt":"A Nigerian bottling company loses sales after its biggest distributor in the South-West goes out of business. The distributor is part of the company's:","options":["Legal environment","Micro environment","Internal environment","Macro environment"],"correctOption":1,"section":"The Business Environment","explanation":"Distributors are marketing intermediaries who deal with the company directly, so they belong to its micro (task) environment. Option D refers to broad national forces, and C is inside the company."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 423, $official_bank_source${"itemId":"4461da74-0048-5782-9a94-da9878717d8a","questionId":"8ae32bf7-6b61-56e0-a91c-dac9c66a8884","sourceKey":"bank:BUA201:ENV-033","payload":{"prompt":"Which of the following groups is part of a firm's micro environment?","options":["Population growth","Interest rates","Climate change","Customers"],"correctOption":3,"section":"The Business Environment","explanation":"Customers interact directly with the firm and determine its sales, so they are part of the micro environment. Options A, B and C are broad macro forces affecting all firms."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 424, $official_bank_source${"itemId":"a6dba2a1-bd1d-5a74-a90f-71c72ccf81d5","questionId":"a4f06cf3-6a97-53ed-968c-805439d302ed","sourceKey":"bank:BUA201:ENV-034","payload":{"prompt":"A company's board of directors and its owners (shareholders) are best classified as part of its:","options":["Macro environment","Internal environment","Political environment","Technological environment"],"correctOption":1,"section":"The Business Environment","explanation":"Owners and the board of directors are inside the organisation's structure of control, so they are part of the internal environment. Options A, C and D are external."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 425, $official_bank_source${"itemId":"9ab36bde-e972-532f-b2e4-d6655a817e06","questionId":"02bfc09d-fca5-556b-a4f0-d4b05786303f","sourceKey":"bank:BUA201:ENV-035","payload":{"prompt":"Which of the following is NOT an economic factor in the macro environment?","options":["Inflation","Changes in religious beliefs","Exchange rates","Interest rates"],"correctOption":1,"section":"The Business Environment","explanation":"Religious beliefs are a social factor, not an economic one. Inflation, exchange rates and interest rates in options A, C and D are standard economic factors."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 426, $official_bank_source${"itemId":"e7730ea4-0c0a-53ee-a21c-6a7d2136b0e6","questionId":"95cd56ad-a537-5de2-9256-6730472bc772","sourceKey":"bank:BUA201:ENV-036","payload":{"prompt":"Which of the following is NOT a social factor in PESTLE analysis?","options":["Level of education","A new tax law passed by the National Assembly","Cultural values and lifestyles","Population age structure"],"correctOption":1,"section":"The Business Environment","explanation":"A new tax law is a legal factor, because it is a binding rule businesses must obey. Population, education and culture in options D, A and C are social factors."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 427, $official_bank_source${"itemId":"2f4c9b37-4e81-5e98-b38f-8c6afd2cce4d","questionId":"d7ea0f27-e73e-5ded-ba3b-2a32ece3a3c8","sourceKey":"bank:BUA201:ENV-037","payload":{"prompt":"Which of the following is NOT a technological factor?","options":["Development of mobile payment systems","Growth of internet access","A fall in household incomes","Automation of production"],"correctOption":2,"section":"The Business Environment","explanation":"A fall in household incomes is an economic factor. Internet access, automation and mobile payments in options B, D and A are technological factors."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 428, $official_bank_source${"itemId":"53c756f7-57cf-52a5-8df3-5c73b0685abb","questionId":"ef11696e-d3e2-51c3-af86-2227ada8f195","sourceKey":"bank:BUA201:ENV-038","payload":{"prompt":"Which of the following is an example of an environmental (ecological) factor?","options":["A new competitor","A change in government","The firm's management style","Climate change and extreme weather"],"correctOption":3,"section":"The Business Environment","explanation":"Climate change and extreme weather are environmental factors in PESTLE. Option B is political, A belongs to the micro environment, and C is internal."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 429, $official_bank_source${"itemId":"040b5df4-f182-58a3-b15a-232939d4eea3","questionId":"e6c83d5e-f48f-5516-8828-fb20e51e6f00","sourceKey":"bank:BUA201:ENV-039","payload":{"prompt":"The Federal Government reduces import duty on industrial machinery, and a Nigerian packaging firm saves N3 million on a new production line. This shows that changes in the external environment can:","options":["Create opportunities as well as threats for businesses","Be controlled directly by the firm's managers","Affect only the firm's internal culture","Only ever harm businesses"],"correctOption":0,"section":"The Business Environment","explanation":"External changes are not always harmful; a lower import duty cuts costs and opens an opportunity to expand. Option D ignores favourable changes, B wrongly suggests firms control government policy, and C misplaces an external change inside the firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 430, $official_bank_source${"itemId":"46134451-b8dd-5608-8922-d82879acd66b","questionId":"3dc7c462-ca1b-5f44-b0c6-d71799ada3c4","sourceKey":"bank:BUA201:ENV-040","payload":{"prompt":"An environment in which conditions change rapidly and unpredictably is described as:","options":["Stable","Static","Internal","Dynamic"],"correctOption":3,"section":"The Business Environment","explanation":"A dynamic environment is one where conditions such as prices, technology and regulations change often and unpredictably, which increases uncertainty for managers. Options A and B describe environments where conditions change little."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 431, $official_bank_source${"itemId":"317a82e1-6f71-5cf0-abea-2dab116045d4","questionId":"cb889f28-3e6e-5c29-a9e6-977b9ea8bdce","sourceKey":"bank:BUA201:ENV-041","payload":{"prompt":"A Nigerian firm's managers cannot stop a rise in global crude oil prices, but they can adjust their pricing and sourcing in response. This illustrates that external environmental factors are:","options":["Irrelevant to firms that do not sell oil","Largely uncontrollable, so managers must anticipate and adapt to them","Part of the firm's internal environment","Fully controllable by top management"],"correctOption":1,"section":"The Business Environment","explanation":"External factors such as world oil prices are outside the firm's control, so managers anticipate them and adapt their strategies. Option D is wrong because no firm can set world prices, and C misplaces the factor inside the firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 432, $official_bank_source${"itemId":"13c73397-22e6-5888-8abd-acd19eca3453","questionId":"43839cd7-f766-5f06-85b5-1b8b7145c66c","sourceKey":"bank:BUA201:ENV-042","payload":{"prompt":"A Nigerian fashion brand notices that more young customers now prefer locally made clothing and promote it on social media. To the brand, this change in taste is mainly:","options":["A political factor that creates a threat","A social factor that creates an opportunity","An internal weakness","A legal factor that creates a threat"],"correctOption":1,"section":"The Business Environment","explanation":"A shift in tastes and lifestyles is a social factor, and because it favours the brand's products it is an opportunity. Options A and D misclassify it, and C wrongly places it inside the firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 433, $official_bank_source${"itemId":"028072e7-0f85-5a5d-b87e-5dd7766296de","questionId":"3de37138-6486-50da-bb1b-bb11ff5cc7c1","sourceKey":"bank:BUA201:ENV-043","payload":{"prompt":"Which of the following is part of a firm's internal environment?","options":["The level of insecurity in the country","Changes in world commodity prices","Its financial resources and equipment","The government's fiscal policy"],"correctOption":2,"section":"The Business Environment","explanation":"A firm's money, machinery and other physical resources belong to its internal environment. Options A, B and D are external conditions that the firm cannot directly control."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 434, $official_bank_source${"itemId":"4d8af472-98be-5700-9c79-be004eab8389","questionId":"28bb787f-a50c-547d-9552-74813936f70a","sourceKey":"bank:BUA201:ENV-044","payload":{"prompt":"A Nigerian state government announces a new policy direction that favours locally produced goods in all public procurement. For local manufacturers, this is mainly a:","options":["Social factor that creates a weakness","Technological factor that creates a threat","Political factor that creates an opportunity","Internal factor that creates a strength"],"correctOption":2,"section":"The Business Environment","explanation":"A government's policy direction and priorities are political factors, and a policy that favours local goods is an opportunity for local manufacturers. Option A confuses an external factor with an internal weakness, and D wrongly places it inside the firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 435, $official_bank_source${"itemId":"75a78f92-9949-590e-813d-87d41e0148d6","questionId":"5361a45f-8d75-52ab-bf28-db214cf8c91b","sourceKey":"bank:BUA201:ENV-045","payload":{"prompt":"Rising insecurity on highways makes it risky for a Kaduna food distributor to move goods, increasing its insurance and security costs. This shows how the external environment can:","options":["Be ignored by well-managed firms","Be changed directly by one firm's managers","Increase operating costs and reduce performance","Improve profitability automatically"],"correctOption":2,"section":"The Business Environment","explanation":"Insecurity is an external condition that raises costs for security, insurance and logistics and so harms performance. Options A and B wrongly suggest that external factors can be ignored or controlled by one firm."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 436, $official_bank_source${"itemId":"1ffc15a1-346b-58e2-b615-6487823279e6","questionId":"1145bbc1-276b-579d-aad5-3cf9723bbf7f","sourceKey":"bank:BUA201:ENV-046","payload":{"prompt":"Why should managers study the business environment?","options":["To anticipate changes, seize opportunities and reduce the impact of threats","To eliminate all competition permanently","Because the environment never changes","To avoid the need for planning"],"correctOption":0,"section":"The Business Environment","explanation":"Studying the environment helps managers foresee changes, take advantage of opportunities and prepare for threats, which supports better planning. Option C is false because environments change constantly, and D is the opposite of the purpose."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 437, $official_bank_source${"itemId":"2a83b17a-2321-5411-8eff-6c6a76941d76","questionId":"8d031a33-c233-55e6-bcd3-6b5bda751e49","sourceKey":"bank:BUA201:ENV-047","payload":{"prompt":"A small business in Enugu earns N2 million in monthly sales. Its owner says: 'Inflation, interest rates and government policies are not my concern; only my shop matters.' The best response is that:","options":["Macro factors affect only government agencies","The owner is right, because macro factors affect only large firms","The owner is right, because small firms have no external environment","Macro factors affect all businesses, including small ones, through costs, prices and demand"],"correctOption":3,"section":"The Business Environment","explanation":"Macro forces such as inflation, interest rates and government policy affect every business, small or large, through the prices it pays, the prices it can charge and customer demand. Options A, B and C wrongly limit the reach of the macro environment."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 438, $official_bank_source${"itemId":"5d1041dd-5037-52cb-a210-d9fcac1e5839","questionId":"213d5b44-abe2-5a5d-89c4-dfa88122dbb0","sourceKey":"bank:BUA201:ENV-048","payload":{"prompt":"A Nigerian telecom company sees two developments: (1) a new regulation requires all SIM cards to be linked to national identification numbers, and (2) mobile internet use is growing rapidly. Which PESTLE classification is correct?","options":["(1) Social and (2) Economic","(1) Environmental and (2) Political","(1) Technological and (2) Legal","(1) Legal and (2) Technological"],"correctOption":3,"section":"The Business Environment","explanation":"A binding regulation on SIM registration is a legal factor, while the spread of mobile internet is a technological factor. Option C reverses the two, a common error, and A and B misclassify both."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 439, $official_bank_source${"itemId":"e841627b-5556-5db4-ba84-77089a2b8849","questionId":"b19cf98c-1a87-5332-b35b-d8f7b79ae3f5","sourceKey":"bank:BUA201:ENV-049","payload":{"prompt":"Which of the following correctly lists two components of the micro (task) environment?","options":["Elections and ideology","Inflation and unemployment","Suppliers and competitors","Climate and pollution"],"correctOption":2,"section":"The Business Environment","explanation":"Suppliers and competitors deal directly with the firm and form part of its micro environment. Options A, B and D are pairs of macro factors (economic, environmental and political)."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 440, $official_bank_source${"itemId":"93348799-1142-5efb-98b8-de1df028ea0c","questionId":"e330a010-4bad-5b2b-bf03-e31b2261ad84","sourceKey":"bank:BUA201:ENV-050","payload":{"prompt":"Which of the following is NOT part of a firm's micro (task) environment?","options":["The government's national fiscal policy","The firm's competitors","The firm's customers","The firm's suppliers"],"correctOption":0,"section":"The Business Environment","explanation":"National fiscal policy is a broad political-economic force that affects all firms, so it belongs to the macro environment. Customers, suppliers and competitors in options C, D and B deal directly with the firm and form its micro environment."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 441, $official_bank_source${"itemId":"2a3b4ba0-afbd-520c-8d13-c5bcfbc64e75","questionId":"0c957723-54b7-5461-b2e9-fc4c609c69a2","sourceKey":"bank:BUA201:PQ-017","payload":{"prompt":"Market segmentation improves a firm's marketing strategy mainly by:","options":["Increasing the debt ratio","Minimising capital structure","Reducing governance costs","Enhancing targeting precision"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Segmentation splits a broad market into groups with similar needs, so the firm can choose and serve the most attractive groups with tailored offers. Options C, A and B are finance and governance matters that have nothing to do with how a market is divided."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 442, $official_bank_source${"itemId":"77fcc14f-46c6-5579-867d-fb5f03885912","questionId":"52cb53e1-2c49-5927-8941-00bed19f9157","sourceKey":"bank:BUA201:PQ-018","payload":{"prompt":"In marketing, positioning refers to:","options":["The image of a brand in customers' minds relative to competitors","Distribution logistics","Financial leverage","Physical shelf placement"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Positioning is the final step of STP: creating a distinct, desirable image for the product in the target customers' minds so it stands out from rivals. Option D sounds similar but is about where goods sit in a shop, and option B belongs to the place element of the marketing mix."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 443, $official_bank_source${"itemId":"5d581633-8537-53f2-a4a4-f67dedd7f5ad","questionId":"c23c0163-17e9-5604-9ab1-a75efc687e87","sourceKey":"bank:BUA201:PQ-025","payload":{"prompt":"Workforce (human resource) planning mainly ensures that:","options":["Dividends remain stable","Shareholder activism is reduced","Tax returns are filed correctly","The organisation has the right number of people with the right skills when needed"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Workforce planning forecasts future staffing needs and compares them with current staff so gaps in numbers and skills can be filled through recruitment or training. Options A, C and B are finance, tax and governance concerns rather than people planning."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 444, $official_bank_source${"itemId":"df5076eb-edcb-542a-a2a6-522c3c599a31","questionId":"799ade0c-5c40-509a-a44f-4f80df1c6ad9","sourceKey":"bank:BUA201:PQ-027","payload":{"prompt":"The effectiveness of a training programme is best measured using:","options":["The debt-equity ratio","Changes in trainees' behaviour and job performance","Share price","Market share"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Training is effective when trainees apply what they learnt, so the best evidence is improved behaviour and performance on the job. Options A, D and C reflect the whole firm's finances or market position and are affected by many things besides training."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 445, $official_bank_source${"itemId":"4db76e4c-66d3-58af-960b-b23da95956e6","questionId":"94ffc5df-268c-503e-b1c1-faf066198246","sourceKey":"bank:BUA201:PQ-028","payload":{"prompt":"Which of the following is NOT one of the 4Ps of the marketing mix?","options":["Product","People","Price","Promotion"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The 4Ps are product, price, place and promotion. People is added only in the extended services marketing mix (the 7Ps), so it is not one of the original four; options D, C and A are all part of the 4Ps."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 446, $official_bank_source${"itemId":"3046e6db-fa96-5ed1-b001-9ee6a042af91","questionId":"ea8d68ac-49bb-5408-9a91-f02a8d81e2a9","sourceKey":"bank:BUA201:PQ-060","payload":{"prompt":"High employee engagement mainly improves:","options":["Productivity","Exchange rate stability","The debt ratio","Inflation"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Engaged employees are committed and put in discretionary effort, which raises output and service quality. Options D, B and C are economic or financial measures that employee attitudes do not directly control."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 447, $official_bank_source${"itemId":"ec6f35eb-eb9d-5e08-bc50-894b98c33b07","questionId":"9cf0ac02-dd5a-5a26-bd39-0f6ca126ce6f","sourceKey":"bank:BUA201:PQ-079","payload":{"prompt":"High employee turnover increases:","options":["Liquidity","The firm's share capital","Governance quality","Recruitment and training costs"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"When employees leave frequently, the firm must keep advertising, selecting and training replacements, so recruitment and training costs rise. Option A is wrong because these extra costs drain cash rather than add to it. Options B and C are unrelated to staff leaving."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 448, $official_bank_source${"itemId":"72b7035c-0544-5c25-8896-e38a8bcc0578","questionId":"2aae93d5-39cd-5838-bff0-45fd6d4a1e63","sourceKey":"bank:BUA201:PQ-081","payload":{"prompt":"A market penetration strategy aims at:","options":["Growing sales of existing products in existing markets","Entering new markets","Diversification into unrelated businesses","Retrenchment"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Market penetration means selling more of the products a firm already has to the customers and markets it already serves, for example through lower prices or heavier promotion. Option B describes market development, and option C describes diversification, which involves new products and new markets. Option D is cutting back operations, the opposite of a growth strategy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 449, $official_bank_source${"itemId":"eb19d8dc-07ba-55fa-b30b-884ca904dbe3","questionId":"fecd6bd7-5265-5588-82a3-d30034bf7d50","sourceKey":"bank:BUA201:PQ-087","payload":{"prompt":"Giving teams more autonomy is most likely to improve:","options":["Employee motivation","Inflation","Forex stability","Market crashes"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Autonomy means letting team members decide how to do their work, and having that control and responsibility tends to raise motivation and commitment. Options B, C and D are economy-wide conditions that a firm's team design cannot change."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 450, $official_bank_source${"itemId":"d03c01a8-f312-5c8e-a955-e4c4893ce3c7","questionId":"e2bea87f-0718-551d-8015-bd48b26f60ed","sourceKey":"bank:BUA201:PQ-091","payload":{"prompt":"Succession planning reduces the risk of:","options":["Inflation","A leadership vacuum","Exchange rate volatility","A high debt ratio"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Succession planning identifies and develops people who can step into important positions, so when a leader leaves or retires there is someone ready to take over. Options A and C are economy-wide conditions, and option D is a financing matter that grooming future leaders does not address."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 451, $official_bank_source${"itemId":"545557c4-a45c-5702-b24f-ae7a5938807a","questionId":"c79bd96a-05f2-5c2b-9f7d-b958f4f7adf5","sourceKey":"bank:BUA201:PQ-117","payload":{"prompt":"Which decision BEST demonstrates the marketing concept?","options":["Producing at the lowest possible cost","Selling aggressively","Starting production only after market research","Cutting advertising expenses"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The marketing concept says a firm should first find out what customers need and want, then produce to satisfy those needs better than competitors. Option A reflects the production concept, and option B reflects the selling concept, which pushes whatever has been made. Option D is a cost decision, not a customer-focused philosophy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 452, $official_bank_source${"itemId":"620bd467-3e6e-5337-8d96-c4a9a3efa90d","questionId":"39ce2a9c-a389-56d5-a7b3-912816bc8ae7","sourceKey":"bank:BUA201:PQ-118","payload":{"prompt":"Which HR activity MOST directly supports change management?","options":["Payroll administration","Recruitment only","Training and development","Job evaluation"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Change usually requires people to learn new skills, systems and ways of working, and training and development is the HR activity that equips them to do so. Options A and D are routine pay matters, and option B brings in new people but does nothing for the existing staff who must adapt."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 453, $official_bank_source${"itemId":"f89a784a-d081-55be-bba1-1e4a14b0c6f3","questionId":"3547f431-222c-5032-8e8a-4890aa2c2873","sourceKey":"bank:BUA201:PQ-119","payload":{"prompt":"Which marketing approach generally suits Nigeria's rural consumer markets best?","options":["Premium pricing based on brand prestige","Offering affordable, durable, value-for-money products","Relying only on online promotion","Stressing global fashion trends and luxury aesthetics"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Rural Nigerian consumers often have lower incomes, are careful about quality and value, and prefer products that are functional and long-lasting, so value-for-money offers suit them. Options A and D fit higher-income urban buyers who respond to brand image and international trends. Option C is wrong because, although mobile access is growing in rural areas, open markets and kiosks still matter a great deal there."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 454, $official_bank_source${"itemId":"247eb037-b781-5a9b-894b-9c4ab2e8dccd","questionId":"a7f962bb-d6bf-51bc-b705-2dbb4d46519c","sourceKey":"bank:BUA201:PQ-120","payload":{"prompt":"Urban consumers in Nigeria are more likely to switch brands mainly because of their:","options":["Low literacy","Limited options","High exposure to alternatives","Cultural resistance"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"City consumers see many competing brands in modern retail outlets and through digital and international marketing, so they have more choice and information and switch more easily. Options A, B and D would make switching less likely, not more, and they do not describe typical urban buyers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 455, $official_bank_source${"itemId":"34fed94e-5619-5b9c-bc3c-3554cbfbc8c5","questionId":"87ff480f-f6ba-5db0-81df-edb14123d1f3","sourceKey":"bank:BUA201:FMH-001","payload":{"prompt":"In modern marketing, the term 'market' is best described as:","options":["Only the physical location where buyers and sellers meet to trade","All individuals and organisations that are actual or potential buyers of a product","The total stock of goods a firm has available for sale","The group of firms that produce and sell the same product"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Because of innovation and globalisation, a market now means the actual or potential buyers of a product, not just a place. Option A is the older, narrower meaning of a market as a location. Option D describes an industry (the sellers), while Option C describes inventory."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 456, $official_bank_source${"itemId":"1085e0d4-f186-51ba-8bee-1dc2926fd8d5","questionId":"085f1f2e-8754-50fd-b4a9-7a45c4059d54","sourceKey":"bank:BUA201:FMH-002","payload":{"prompt":"A marketing manager says 'the car market in Nigeria is growing.' In the modern sense of the word, she is referring to:","options":["Only people who bought a car in the last twelve months","The factories that assemble cars within Nigeria","The car dealership lots located along major Lagos roads","All individuals and organisations that are actual or potential buyers of cars"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"A car market refers to all individuals and organisations that are actual or potential buyers of cars, not a particular place where cars are sold. Option C treats the market as a location, and Option A leaves out potential buyers. Option B describes producers, not buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 457, $official_bank_source${"itemId":"d95eea84-23b4-563b-9cad-3804b768cb48","questionId":"f01747c1-efda-5fea-80db-988f8832ed0b","sourceKey":"bank:BUA201:FMH-003","payload":{"prompt":"The market made up of all individuals who purchase goods and services for direct consumption or household use is the:","options":["Capital market","Industrial market","Government market","Consumer market"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The consumer market consists of individuals buying for their own direct consumption or household use. Option B, the industrial market, buys goods for further production. Options A and C are not the category being described here."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 458, $official_bank_source${"itemId":"a24c7fe7-dc56-557a-b357-ed3e7c600659","questionId":"ca3e819a-7a8b-5c82-9426-7020ee552d31","sourceKey":"bank:BUA201:FMH-004","payload":{"prompt":"A construction company in Abuja buys 2,000 bags of cement to use in building an estate. In this purchase, the company is part of the:","options":["Retail market","Consumer market","Industrial market","Household market"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The industrial market includes organisations, such as construction firms, that buy goods and services for further production. Option B is wrong because the cement is not bought for direct household consumption. Options A and D also describe buying for final or household use."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 459, $official_bank_source${"itemId":"ca513c58-1346-5523-a4b2-3c6b8c2707ba","questionId":"fc7fa33d-cbed-55f4-bb37-7fad745de1f9","sourceKey":"bank:BUA201:FMH-005","payload":{"prompt":"Which of the following purchases does NOT belong to the industrial market?","options":["A family buying rice and vegetables for its own meals","A mining firm buying explosives for its quarry operations","A transport company buying tyres for its fleet of buses","A fishery buying nets to expand its catch"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Industrial buyers purchase goods for further production, while a family buying food for its own meals is a consumer purchase. Options B, C and D are organisations in transport, mining and fisheries buying inputs for their operations, which places them in the industrial market."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 460, $official_bank_source${"itemId":"2474ddab-5de7-5ddb-bfbc-5718f8976165","questionId":"cef4daa3-220a-5318-95ae-aceee5906cb9","sourceKey":"bank:BUA201:FMH-006","payload":{"prompt":"The starting point of marketing activities is:","options":["Delivering finished goods to retail outlets","Collecting payment from customers after a sale","Setting the advertising budget for the year","Identifying and analysing the needs, wants and demands of consumers"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Marketing begins even before goods are produced, with identifying and analysing what consumers need, want and demand. Option A is a later distribution activity, and Option C is part of planning promotion once products exist. Option B happens at the end of a sale, not at the start."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 461, $official_bank_source${"itemId":"fbc6aadd-b09e-573f-b6ad-8aca09c33837","questionId":"94969980-cb47-540e-8f8a-2bad6d9e9479","sourceKey":"bank:BUA201:FMH-007","payload":{"prompt":"Defining marketing simply as 'business activities that direct the flow of goods and services to the consumer' is considered too limited mainly because:","options":["Marketing ends once goods reach the wholesaler","Marketing applies to services but not to physical goods","Marketing is concerned only with advertising, not distribution","Marketing starts before production and continues after the purchase"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The narrow definition ignores that marketing starts with identifying consumer needs before goods exist and continues after purchase with after-sales services. Option C wrongly shrinks marketing to advertising, and Option B wrongly excludes goods. Option A is the very gap that makes the narrow view inadequate."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 462, $official_bank_source${"itemId":"f8662980-517b-5cf3-be10-394b1fa8637d","questionId":"fed13096-3b00-575e-8f8c-936c1dc10c44","sourceKey":"bank:BUA201:FMH-008","payload":{"prompt":"Which of the following is an example of a marketing activity that takes place AFTER a customer has bought a product?","options":["Testing the product in a pilot market","Researching what consumers need","Providing maintenance and repair services","Designing the product's packaging"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Marketing does not end at purchase; after-sales activities such as maintenance, repair and allowing returns of defective items keep customers satisfied. Options A, B and D all happen before or during the launch of a product, not after the sale."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 463, $official_bank_source${"itemId":"dbf82660-9398-5250-b05b-30d51d503e41","questionId":"29aa800e-36cc-5345-a59e-f159dc704146","sourceKey":"bank:BUA201:FMH-009","payload":{"prompt":"Which of the following is NOT a function of marketing?","options":["Preparing the firm's statement of financial position","Training and motivating salespersons","Pricing the product","Distributing products to where they are needed"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Preparing the statement of financial position is an accounting task, not a marketing function. Options B, C and D are all marketing functions: pricing, distribution and training and motivating the sales force."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 464, $official_bank_source${"itemId":"7e1b443e-5146-575a-848c-a56222fd6286","questionId":"5d45bad8-f55f-5637-9a9f-a38d9e023d81","sourceKey":"bank:BUA201:FMH-010","payload":{"prompt":"A phone retailer in Ikeja offers buyers free repairs and screen checks for six months after purchase. Which marketing function is this?","options":["Planning and controlling the marketing effort","Rendering after-sale services to customers","Pricing the product","Distribution of the product"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Free repairs after the sale are an after-sale service, which adds convenience for customers and helps promote sales. Option D concerns getting products to where they are needed, and Option C concerns setting the price. Option A is the overall management of marketing, not a service given to buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 465, $official_bank_source${"itemId":"419c09ea-f12a-56a5-ba1f-875eb1db5155","questionId":"7fb7ec3c-53ff-5c38-8f50-30fdece913d8","sourceKey":"bank:BUA201:FMH-011","payload":{"prompt":"A beverage company organises a two-day workshop to improve the selling skills of its field sales team and rewards top performers. Which marketing function is being performed?","options":["Rendering after-sale services","Pricing the product","Training and motivating salespersons","Distribution of the product"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Improving selling skills and encouraging the sales team to make more sales is the function of training and motivating salespersons. Option A is help given to customers after purchase, not to staff. Options B and D deal with moving goods and setting price."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 466, $official_bank_source${"itemId":"a188907b-b925-51eb-87c8-5e8c83f31b67","questionId":"47f876ad-ca40-51e6-9fa3-4c18b55d35bf","sourceKey":"bank:BUA201:FMH-012","payload":{"prompt":"The marketing function that makes new and existing products known, helping the company become a household name, is:","options":["Pricing","Distribution","Promotion","After-sale service"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Promotion makes products, and through them the company, known to the public. Option B moves products to where they are needed, and Option A puts a price on each product. Option D supports customers after they buy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 467, $official_bank_source${"itemId":"faeba59d-4b43-5ba3-bac4-0bafc0a0da50","questionId":"378a6958-016a-567e-a4b0-cb973982d5c4","sourceKey":"bank:BUA201:FMH-013","payload":{"prompt":"The correct order of the steps in the STP framework is:","options":["Segmentation, positioning, targeting","Positioning, segmentation, targeting","Targeting, segmentation, positioning","Segmentation, targeting, positioning"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"A firm first divides the market into segments, then selects the most attractive segments as targets, and finally positions its product in the minds of those target consumers. Options A, B and C put the steps out of order; you cannot pick a target before segments exist, or position before knowing who the target is."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 468, $official_bank_source${"itemId":"efbff087-480f-54f4-8318-47e44b54d4a5","questionId":"c11f432b-45e3-58a9-80de-219d54b63a2b","sourceKey":"bank:BUA201:FMH-014","payload":{"prompt":"Market segmentation is the process of:","options":["Creating a distinct image of a product in the minds of target consumers","Dividing a market into smaller groups of consumers who share similar needs, characteristics or behaviours","Choosing the most profitable group of consumers to serve","Setting different prices for the same product in different shops"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Segmentation splits the whole market into smaller, more manageable groups with similar needs or characteristics. Option C is targeting, the step that comes after segmentation. Option A is positioning, and Option D is a pricing tactic, not segmentation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 469, $official_bank_source${"itemId":"ebd0dae2-0a69-53a2-a86d-16892e6c3b02","questionId":"a7228ab4-d126-55fa-b9c2-ea10c696afa5","sourceKey":"bank:BUA201:FMH-015","payload":{"prompt":"A bank designs one savings account for customers earning below N100,000 a month and another for customers earning above N1,000,000 a month. It is segmenting the market on a:","options":["Psychographic basis","Behavioural basis","Geographic basis","Demographic basis"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Income is a demographic variable, together with age, gender, education and family size. Option C would divide customers by location, and Option A by lifestyle, values or personality. Option B would use purchase habits, usage rate or loyalty."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 470, $official_bank_source${"itemId":"3699c764-251f-5913-a4e3-c25a4b85c771","questionId":"b922f61b-e477-5357-b96d-8acc3fe2067d","sourceKey":"bank:BUA201:FMH-016","payload":{"prompt":"A paint company sells different product ranges in the South-South and the North-West because of differences in climate and building styles between the regions. This is segmentation on a:","options":["Behavioural basis","Geographic basis","Psychographic basis","Demographic basis"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Dividing customers by location, such as country, region or city, is geographic segmentation. Option D would use age, income or education, and Option C would use lifestyle and values. Option A would use buying habits or loyalty."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 471, $official_bank_source${"itemId":"fafcf72f-bec3-55b9-9ae5-0497a3a7cfd0","questionId":"f975dd42-8170-5974-b472-bd0713374cb7","sourceKey":"bank:BUA201:FMH-017","payload":{"prompt":"A fitness brand targets people of all ages and income levels who share a healthy, active lifestyle and a love of outdoor sports. This is segmentation on a:","options":["Psychographic basis","Demographic basis","Behavioural basis","Geographic basis"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Lifestyle, values, personality and interests are psychographic variables. Option B would group people by age or income, which the brand deliberately ignores here. Options C and D would use location and purchase behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 472, $official_bank_source${"itemId":"e850cc42-7b20-578c-8c8d-c12d20b6c129","questionId":"228c9cbc-2c1b-5234-a981-da6591777bf1","sourceKey":"bank:BUA201:FMH-018","payload":{"prompt":"A supermarket chain gives special rewards to customers who shop with it every week and treats occasional shoppers as a separate group. This is segmentation on a:","options":["Behavioural basis","Demographic basis","Geographic basis","Psychographic basis"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Grouping customers by purchase habits, usage rate and loyalty is behavioural segmentation. Option D would use lifestyle and values, and Option B would use age or income. Option C would use where customers live."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 473, $official_bank_source${"itemId":"bb475fb1-53fd-5a58-ade5-ccfddc98e89c","questionId":"88663067-4c87-5d06-aedb-4d57356655ec","sourceKey":"bank:BUA201:FMH-019","payload":{"prompt":"Which of the following is NOT a demographic segmentation variable?","options":["Education","Family size","Lifestyle","Income"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Lifestyle is a psychographic variable, describing how people live and what they value. Options A, B and D (income, family size and education) are all demographic variables."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 474, $official_bank_source${"itemId":"d23e951f-de8a-5926-a5fc-84c8c7959da1","questionId":"e88f11a1-0b4e-5d5e-944e-68aed0a2e0d8","sourceKey":"bank:BUA201:FMH-020","payload":{"prompt":"In the STP framework, targeting refers to:","options":["Evaluating the segments and selecting one or more to focus marketing efforts on","Dividing the market into groups with similar needs","Promoting the product through advertising and public relations","Building a unique image for the product in consumers' minds"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Targeting comes after segmentation: the firm evaluates segments and selects the most attractive ones that fit its goals and resources. Option B is segmentation and Option D is positioning. Option C is the promotion element of the marketing mix."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 475, $official_bank_source${"itemId":"74f5d3ea-8f56-5a28-ab97-a45beb7f4556","questionId":"c8197a57-f318-5e41-9ba2-2afc2414f4db","sourceKey":"bank:BUA201:FMH-021","payload":{"prompt":"When evaluating market segments during targeting, which of the following is NOT usually a factor to assess?","options":["The size of the segment","The level of competition in the segment","The personal hobbies of the company's directors","The growth potential of the segment"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Segments are assessed on size, growth potential, profitability and competition, then matched to the firm's goals and resources. Options A, B and D are all standard evaluation factors. The directors' hobbies have nothing to do with how attractive a segment is."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 476, $official_bank_source${"itemId":"9fd0d9e6-24cb-5daf-bc93-24d7c33c007c","questionId":"44ae88ad-0e2d-52bd-919f-8149f37c4c9e","sourceKey":"bank:BUA201:FMH-022","payload":{"prompt":"A juice company advertises its drink as 'the 100% natural choice for health-conscious mothers' to stand apart from sugary competitors. Which STP step is this mainly?","options":["Targeting","Positioning","Market research","Segmentation"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Creating a distinct, desirable image for the product in the minds of the target group, and differentiating it from competitors, is positioning. Option D would divide the market into groups, and Option A would choose which groups to serve. Option C gathers information but does not by itself create an image."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 477, $official_bank_source${"itemId":"383596a5-8190-54c4-a1dd-5ca256050242","questionId":"7b2d0577-96e2-572d-86a8-6232dba94399","sourceKey":"bank:BUA201:FMH-023","payload":{"prompt":"In the STP framework, adapting the product, price, place and promotion to resonate with the chosen target group is part of which step?","options":["Market definition","Targeting","Segmentation","Positioning"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Under positioning, a firm defines its unique value and adapts the marketing mix (4Ps) so the target segment sees the product as the best solution. Option C only divides the market, and Option B only selects segments. Option A is not one of the STP steps."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 478, $official_bank_source${"itemId":"f4fcab42-f539-501e-a517-6c8880e9b9bb","questionId":"af675c6a-ec62-5ba1-8917-f375c28e7ae9","sourceKey":"bank:BUA201:FMH-024","payload":{"prompt":"Which of the following is NOT a benefit of using the STP approach?","options":["It makes marketing messages more relevant and personalised","It helps a company stand out in a crowded market","It concentrates resources on the most promising customers","It removes the need for any promotion of the product"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"STP brings focus, relevance, loyalty and a competitive edge, but positioning itself relies on the marketing mix, including promotion. Options A, B and C are genuine benefits of STP, so only the claim that promotion becomes unnecessary is false."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 479, $official_bank_source${"itemId":"dc4e1f6b-f5a8-5a56-8741-52105b3b17a4","questionId":"cd2c0927-25cc-5c7e-83d9-9e712453b6dd","sourceKey":"bank:BUA201:FMH-025","payload":{"prompt":"The marketing mix is best described as:","options":["The proportion of a firm's budget spent on advertising","The set of factors (product, price, place and promotion) that help to execute a marketing programme","The list of all segments a firm has chosen to serve","The combination of shareholders who own a marketing company"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"The marketing mix is the set of four key elements, product, price, place and promotion, used to carry out a marketing programme. Option D has nothing to do with marketing activities, and Option C is the result of targeting. Option A is only one part of promotion spending."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 480, $official_bank_source${"itemId":"790861a2-19ee-5087-b03d-c813dd0aeb36","questionId":"cc49bb13-3c97-5f62-a261-057cfa9a0cfc","sourceKey":"bank:BUA201:FMH-026","payload":{"prompt":"Which element of the marketing mix answers the question 'How much are customers willing to pay for the product?'","options":["Price","Place","Promotion","Product"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Price is the value or worth placed on an item and answers how much customers are willing to pay. Option D answers what is being offered, Option C answers how to make the product known, and Option B answers where the product can be obtained."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 481, $official_bank_source${"itemId":"24b20861-5419-5962-b82a-14ec04b624ec","questionId":"722be3d7-1f10-5219-b5c2-d17a3c5924f4","sourceKey":"bank:BUA201:FMH-027","payload":{"prompt":"Which element of the marketing mix answers the question 'What is being offered for sale in the market?'","options":["Promotion","Product","Price","Place"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Product is anything offered to the public for consumption or use, so it answers what is being offered for sale. Option C deals with how much customers will pay, Option D with where the product is available, and Option A with making customers aware of it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 482, $official_bank_source${"itemId":"c770a6a5-250b-5e3b-a8c7-abe8b7f4088e","questionId":"fa569374-51e8-5f95-86ea-f1dd489b0775","sourceKey":"bank:BUA201:FMH-028","payload":{"prompt":"Which of the following is NOT one of the activities covered by promotion in the marketing mix?","options":["Sales promotion","Public relations","Advertising","Choosing warehouses and transport routes for the product"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Promotion covers advertising, public relations and sales promotion, which make the product known and persuade customers. Choosing warehouses and routes belongs to place, which is about making the product available. Options A, B and C are all promotion activities."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 483, $official_bank_source${"itemId":"b6869dda-2e6b-50cc-841b-bc4d6f1307a4","questionId":"7217fd5e-18c5-57e0-85eb-706699eb681e","sourceKey":"bank:BUA201:FMH-029","payload":{"prompt":"Which element of the marketing mix is linked to the view that 'without customers accessing the products, production is incomplete'?","options":["Promotion","Product","Place","Price"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Place is about making products accessible and available to consumers, and production is seen as incomplete until customers can get the product. Option D concerns value and willingness to pay, and Option B is the item being offered. Option A makes customers aware but does not get the product to them."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 484, $official_bank_source${"itemId":"60232ba5-fded-52fc-b28b-62ebb4e61183","questionId":"eaa47c75-a285-5b94-b01e-91fb3d8c6802","sourceKey":"bank:BUA201:FMH-030","payload":{"prompt":"A flour mill sells flour to bakeries, which use it to make bread. To the bakeries, the flour is classified as:","options":["A convenience service","An industrial product","A consumer product","A finished good for final users"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Industrial products are used in the production of other products, as the bakery does with flour. Option C is wrong because consumer products are used directly by final users, which is also why Option D is wrong. Option A is not the product category being tested."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 485, $official_bank_source${"itemId":"f9d9842f-4a71-5d8c-a15a-53b12ea2a37a","questionId":"d9d95931-9d86-5abf-a962-31114b9b5d86","sourceKey":"bank:BUA201:FMH-031","payload":{"prompt":"A soap manufacturer runs radio jingles in Yoruba, Hausa and Igbo to persuade listeners to try its new brand. Which element of the marketing mix is this?","options":["Product","Place","Promotion","Price"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Promotion means making a product known and communicating with customers persuasively, for example through advertising. Option B concerns making the soap available in outlets, and Option D concerns its selling price. Option A is the soap itself."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 486, $official_bank_source${"itemId":"c30f22d4-2a53-515c-9489-4747edfa2ed9","questionId":"3f61e47b-4406-534a-b49a-aaff0467afa0","sourceKey":"bank:BUA201:FMH-032","payload":{"prompt":"A snack company signs up 300 new kiosks and supermarkets in Ibadan so that its chips are easy to find wherever customers shop. Which element of the marketing mix is being improved?","options":["Place","Product","Price","Promotion"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Place deals with making products accessible and available and getting the right product to the right place. Option D would involve communicating with customers, such as advertising. Options B and C would involve changing the price or the snack itself."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 487, $official_bank_source${"itemId":"3096fe3f-d91b-5c82-aeb1-92195736a32b","questionId":"cf2bf901-1e46-51ea-b02e-8fcf7ce114ac","sourceKey":"bank:BUA201:FMH-033","payload":{"prompt":"Compared with urban consumers, rural consumers in Nigeria tend to prioritise:","options":["Spending mainly on non-necessities","Functionality, durability and bulk purchases","International fashion trends and aesthetics","Modern shopping malls and luxury brands"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Rural consumers focus on value, functionality and durability, and often buy in bulk. Options C and D describe urban consumers, who are influenced by global trends and have more access to modern retail. Option A matches the higher disposable income of urban markets."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 488, $official_bank_source${"itemId":"0489b86d-0b8b-5133-9e7f-26ac96e7580e","questionId":"6402c74f-685f-5d1a-9e55-55fd56e6155d","sourceKey":"bank:BUA201:FMH-034","payload":{"prompt":"Which of the following best describes the urban consumer market in Nigeria?","options":["Low exposure to brands and little concern for aesthetics","Retail dominated almost entirely by open-air markets with no digital adoption","Higher disposable income and strong influence of international trends and digital marketing","Purchases driven mainly by bulk buying and durability"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Urban markets have higher disposable incomes, more spending on non-necessities, and are shaped by international trends and digital marketing. Option B and Option D are closer to rural market features. Option A contradicts the urban focus on quality and aesthetics."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 489, $official_bank_source${"itemId":"41d02018-cedc-5cb4-939c-a2a2a7357707","questionId":"359f8e71-6fca-52e0-a129-8c36a213ab25","sourceKey":"bank:BUA201:FMH-035","payload":{"prompt":"Which of the following statements about rural consumer markets in Nigeria is NOT correct?","options":["Digital and mobile access in rural areas is growing rapidly","Rural retail is dominated by informal open-air markets and kiosks","Rural consumers often have lower incomes than urban consumers","Rural consumers have little knowledge of product quality and value"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Rural consumers may earn less, but they are highly knowledgeable about product quality and value, so Option D is the false statement. Options A, B and C are all accurate: informal markets dominate rural retail, mobile access is growing fast, and incomes are often lower."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 490, $official_bank_source${"itemId":"e2f56e07-5aec-506a-9a35-ebdf50fd5ca9","questionId":"1bcd8fe9-580b-5b8f-96b9-9738ccda4c61","sourceKey":"bank:BUA201:FMH-036","payload":{"prompt":"A detergent firm entering villages in Benue State wants a value proposition suited to rural buyers. Which emphasis fits best?","options":["Global celebrity endorsements and fashion appeal","Durability and value for money","Exclusive availability in modern supermarkets","Premium brand image and shopping experience"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"For rural markets the value proposition should stress durability and value, while urban marketing leans on brand and experience. Options A and D are more suited to urban consumers. Option C ignores that rural retail relies mostly on open markets and kiosks."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 491, $official_bank_source${"itemId":"5d0cda0b-04ff-5f22-938b-a2c873ae243e","questionId":"b0b296d4-7658-5b98-b8b9-06270d8cd3c5","sourceKey":"bank:BUA201:FMH-037","payload":{"prompt":"In Nigerian foodstuff markets, the link between urban and rural prices is best described as:","options":["Integrated, with urban prices often driving rural prices","Driven entirely by rural prices, which urban markets follow","Completely separate, with no link between them","Fixed by the government for both markets"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Foodstuff markets are integrated, and urban prices often drive rural prices. Option C denies the integration, and Option B reverses the direction of influence. Option D is not how these markets are described."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 492, $official_bank_source${"itemId":"6b21bd38-3f02-5c94-83ab-a5e92463c9b8","questionId":"7e4d5a86-2cf7-5af8-ae8e-6aef5b79f5be","sourceKey":"bank:BUA201:FMH-038","payload":{"prompt":"The main distribution implication of the difference between rural and urban markets in Nigeria is the need for:","options":["Avoiding rural markets until infrastructure is fully developed","Selling only through modern supermarkets in all areas","Robust channels that overcome infrastructure gaps, especially in rural zones","Using the same single warehouse for the whole country"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Because rural areas have weaker infrastructure, firms need robust distribution channels to reach them. Option B ignores that rural retail relies on kiosks and open markets. Option A gives up a large market, and Option D would make delivery to distant areas harder."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 493, $official_bank_source${"itemId":"859ed253-2a39-5ffa-b392-3dd4db196c2f","questionId":"dd3eeff3-b389-5466-ad9e-664a06bc46fa","sourceKey":"bank:BUA201:FMH-039","payload":{"prompt":"Which trend is narrowing the gap between rural and urban consumer markets in Nigeria?","options":["A decline in literacy in rural areas","Urban consumers abandoning all digital shopping","The closure of open-air markets in cities","Rural consumers adopting digital and e-commerce tools through mobile phones"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Rural areas are catching up on digital and e-commerce via mobile, which reduces the gap, and rural consumers increasingly research online. Option B is the opposite of the high digital adoption in cities. Option A contradicts rising rural literacy, and Option C contradicts the continued dominance of informal markets."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 494, $official_bank_source${"itemId":"dbb50457-6d87-5bbb-9c16-5b75b9616ad3","questionId":"193766e6-74ac-59a0-886d-1f0fcd635dad","sourceKey":"bank:BUA201:FMH-040","payload":{"prompt":"Human Resource Management (HRM) is best defined as the practice of:","options":["Recording and reporting an organisation's financial transactions","Recruiting, hiring, deploying and managing an organisation's employees","Promoting and distributing an organisation's products","Converting raw inputs into finished goods"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"HRM is the function that recruits, hires, deploys and manages employees and provides guidelines for the workforce. Option A describes accounting, and Option C describes marketing. Option D describes production."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 495, $official_bank_source${"itemId":"40f7b5e9-fbde-581b-ba0a-6078b5e720a3","questionId":"d7c476f4-9a1f-50ce-b274-818c60ae1614","sourceKey":"bank:BUA201:FMH-041","payload":{"prompt":"Over the years, the practice of HRM has evolved:","options":["From planned exploitation of staff to HR metrics, measurement and strategic direction","From employee welfare to simple record keeping only","From a marketing function to an accounting function","From strategic direction to the planned exploitation of staff"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"HRM moved from planned exploitation of staff towards using HR metrics, measurement and strategic direction to show its value. Option D reverses the direction of change. Options B and C do not describe how HRM developed."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 496, $official_bank_source${"itemId":"99170d67-0c60-51cf-8a27-6b656e910fb2","questionId":"b5c4303c-0031-53fb-86be-eb697faf3099","sourceKey":"bank:BUA201:FMH-042","payload":{"prompt":"Which of the following is NOT a function of Human Resource Management?","options":["Recruitment of employees","Setting the selling price of the company's products","Compensation and benefits","Performance appraisal"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Setting product prices is a marketing function. Options A, C and D are HR functions, together with training and development, ensuring legal compliance and advising management."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 497, $official_bank_source${"itemId":"642a0e7b-fb1c-5804-92ea-164a62865811","questionId":"40cb12ad-3108-52e9-9c3b-5b1237ad8ae5","sourceKey":"bank:BUA201:FMH-043","payload":{"prompt":"The HR unit of a manufacturing firm in Ota checks that all workers are paid at least the national minimum wage and that employment tax rules are followed. Which HR function is this?","options":["Training and development","Performance appraisal","Recruitment","Ensuring legal compliance"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Making sure the company follows laws and policies on employment, tax allowance and minimum wage is the legal compliance function. Option C concerns hiring staff, Option A concerns improving their skills, and Option B concerns evaluating their performance."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 498, $official_bank_source${"itemId":"532838ce-2e34-57ee-82c5-45af069b256b","questionId":"3f468df2-0c15-5e45-8bac-ea46cd3bbfd8","sourceKey":"bank:BUA201:FMH-044","payload":{"prompt":"At the end of each year, an HR manager evaluates every officer's work and identifies who needs new skills to perform better. This is the HR function of:","options":["Recruitment","Compensation and benefits","Performance appraisal","Advising"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Monitoring and evaluating employees' performance, and spotting skill gaps, is performance appraisal. Option B concerns pay and welfare, and Option A concerns hiring new staff. Option D is HR guiding management on policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 499, $official_bank_source${"itemId":"c0656461-20bb-5638-ad0c-3de89b4c89b0","questionId":"a2f290a5-89c8-5c6b-b1f6-33a56148e7fc","sourceKey":"bank:BUA201:FMH-045","payload":{"prompt":"An HR department reviews salaries, housing allowances and medical cover attached to each job grade so that staff are adequately remunerated. Which HR function is this?","options":["Ensuring legal compliance","Training and development","Recruitment","Compensation and benefits"],"correctOption":3,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Compensation and benefits covers workers' pay, remuneration and welfare packages attached to each position. Option B concerns building skills, and Option A concerns obeying employment laws. Option C concerns bringing in new employees."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 500, $official_bank_source${"itemId":"f1292b19-4408-5976-a06c-f23c0465dcea","questionId":"8fc09de5-57aa-5b63-944b-88b0a4922ba9","sourceKey":"bank:BUA201:FMH-046","payload":{"prompt":"When HR advises top management on formulating policies and advises department heads on job design, selection and job descriptions, it is performing its:","options":["Compensation function","Performance appraisal function","Advising function","Recruitment function"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"HR's advising function covers guiding top management on policies and procedures and guiding departments on job design, recruitment, selection and job descriptions. Options A, B and D are separate HR functions that deal with hiring, evaluating and paying staff."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 501, $official_bank_source${"itemId":"e649a765-4cca-5552-9df9-a4a157d994df","questionId":"cf55b041-611d-5c03-a1e7-853f92c265df","sourceKey":"bank:BUA201:FMH-047","payload":{"prompt":"Developing a succession plan and supporting organisational restructuring are part of which area of HRM's importance?","options":["Organisational strategy and planning","Recruitment and retention","Compliance and risk management","Performance management"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Under organisational strategy and planning, HR identifies workers' needs, supports restructuring and develops a succession plan. Option B is about selecting and keeping staff, and Option C is about rule adherence and risk. Option D is about monitoring employees' duties."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 502, $official_bank_source${"itemId":"ba22ccaa-a86f-550e-9827-04868bacd644","questionId":"69a74204-dbf3-5e97-b995-6870bca04889","sourceKey":"bank:BUA201:FMH-048","payload":{"prompt":"Marketing helps HR attract top talent mainly through:","options":["Employer branding, using messaging, candidate personas and channels such as social media","Setting the legal minimum wage","Conducting the annual performance appraisal","Preparing the payroll for new employees"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Marketing's skills in messaging, audiences such as candidate personas, and channels such as social media make recruitment more effective by building the employer brand. Options C and D are HR tasks, not marketing contributions. Option B is set by government, not by either department."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 503, $official_bank_source${"itemId":"e6e9dbd8-12e3-5920-87f8-c7de23ffd421","questionId":"b2692798-f1ac-5474-baf9-92ff72c36b7e","sourceKey":"bank:BUA201:FMH-049","payload":{"prompt":"HR supports the marketing function mainly by:","options":["Choosing distribution channels for the products","Designing the company's advertising campaigns","Hiring skilled, culturally aligned people who can deliver the experience marketing promises","Setting product prices for each market segment"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"By hiring the right skilled and culturally aligned people, HR ensures the workforce can deliver the quality experiences marketing promises customers. Options A, B and D are marketing mix decisions that marketing itself makes."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 504, $official_bank_source${"itemId":"9bb4047d-a7b1-5bc4-b93e-7b542dc8d2ea","questionId":"14b7761a-9fe0-5dd1-8de9-91f2b7c7d70d","sourceKey":"bank:BUA201:FMH-050","payload":{"prompt":"Which statement best summarises the relationship between marketing and HR in building a company's brand?","options":["Marketing and HR work on separate goals that never overlap","Marketing sells the brand externally, while HR builds the brand internally","HR sells the brand externally, while marketing builds it internally","Only marketing is responsible for the brand; HR has no role"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Marketing promotes the brand to customers outside, while HR builds it inside through culture and employees, and integration makes the employee experience match the customer promise. Option C swaps the roles. Options A and D ignore the interdependence between the two functions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 505, $official_bank_source${"itemId":"054df873-f921-5f80-b215-31f67a78524c","questionId":"03ad2d6f-436a-528c-a6be-6b45b48c27e3","sourceKey":"bank:BUA201:FMH-051","payload":{"prompt":"A bank finds that branches with highly engaged staff also have the most satisfied, loyal customers. This illustrates the idea that:","options":["Employee retention supports customer retention","Engaged employees reduce the need for training","HR and marketing should work in silos","Customer complaints improve staff engagement"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Happy, engaged employees, fostered by HR, give better customer service, which directly improves brand perception and keeps customers. Option D reverses the cause and effect. Option C is the opposite of the recommended coordination, and Option B does not follow from the scenario."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 506, $official_bank_source${"itemId":"4fc66780-4e86-5c2b-804d-a4ebcb5194db","questionId":"1233bb13-9adb-56f8-acdc-0e042ed21927","sourceKey":"bank:BUA201:FMH-052","payload":{"prompt":"Which of the following is NOT a recommended strategy for effective coordination between marketing and HR?","options":["Forming cross-functional teams for key initiatives","Aligning key performance indicators for both departments","Keeping each department's data on separate, unconnected systems","Holding regular joint meetings and workshops"],"correctOption":2,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Recommended strategies include shared goals and KPIs, regular meetings, integrated technology and cross-functional teams. Separate, unconnected systems would do the opposite of integrated technology and keep the departments in silos. Options A, B and D are all recommended."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 507, $official_bank_source${"itemId":"50c56b5d-02fa-59f4-bb50-78a0343486b6","questionId":"485f4b95-f27f-5dd5-a5b6-42a4f1487f44","sourceKey":"bank:BUA201:FMH-053","payload":{"prompt":"For a new product launch, a company puts staff from marketing and HR into one dedicated team that plans the launch together. This coordination strategy is called:","options":["A cross-functional team","Shared metrics","Integrated technology","Employer branding"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"A cross-functional team brings members of different functions together for a key initiative, such as a new product launch. Option C is about shared platforms for data, and Option B is about aligned KPIs. Option D is a joint activity, not the team structure itself."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 508, $official_bank_source${"itemId":"e305c581-4d0b-5ea0-a16e-d4810346dab7","questionId":"108c1d21-5c44-5f64-997c-6ea88615bc74","sourceKey":"bank:BUA201:FMH-054","payload":{"prompt":"A cosmetics firm estimates that there are 1,800,000 women aged 18-35 in Lagos. Market research shows 35% of them prefer natural hair products, and the firm plans to reach 40% of that segment in its first year. How many customers does it plan to reach?","options":["720,000","252,000","630,000","1,350,000"],"correctOption":1,"section":"Functional Areas I: Marketing and Human Resources","explanation":"First size the segment, then apply the target share: 1,800,000 x 0.35 = 630,000, and 630,000 x 0.40 = 252,000. Option C stops at the segment size and forgets the 40% target. Option A wrongly applies 40% to the whole market, and Option D adds the two percentages (75%) instead of applying them one after the other."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 509, $official_bank_source${"itemId":"e2027e93-2d34-5a8f-9ee2-3d36b0527d3b","questionId":"ecf497bf-0c82-5938-888f-ebb4e11cb515","sourceKey":"bank:BUA201:FMH-055","payload":{"prompt":"Total annual sales of bottled water in a Nigerian city are N12,000,000. AquaPure's sales in the city are N3,000,000. What is AquaPure's market share?","options":["25%","75%","4%","33.33%"],"correctOption":0,"section":"Functional Areas I: Marketing and Human Resources","explanation":"Market share = firm's sales / total market sales x 100 = 3,000,000 / 12,000,000 x 100 = 25%. Option C divides the wrong way round (12,000,000 / 3,000,000 = 4), and Option B is the share held by competitors. Option D divides the firm's sales by competitors' sales (3,000,000 / 9,000,000) instead of by the total market."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 510, $official_bank_source${"itemId":"3f084988-bc65-5540-8e56-9c90cd25f04c","questionId":"ed634286-58b1-5944-927b-b664f82f72a1","sourceKey":"bank:BUA201:PQ-001","payload":{"prompt":"A manufacturer that takes over or sets up its own supplier operations, so that it produces its own raw materials and depends less on outside suppliers, is pursuing:","options":["Backward vertical integration","Conglomerate diversification","Market penetration","Horizontal integration"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Backward vertical integration means a firm moves back up its supply chain by owning the sources of its inputs, such as a manufacturer owning its raw-material supplier. Option D would be joining with a firm at the same stage, like a competitor, while option B means entering unrelated businesses."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 511, $official_bank_source${"itemId":"e42224e6-424c-5040-b744-80e7ee45a3b9","questionId":"65ce9723-b6b2-5e45-b29e-799ff1b774c3","sourceKey":"bank:BUA201:PQ-020","payload":{"prompt":"Working capital is calculated as:","options":["Current assets minus current liabilities","Revenue minus expenses","Equity minus debt","Total assets minus total liabilities"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Working capital measures the funds available for day-to-day operations, found by subtracting current liabilities from current assets. Option D gives net assets (equity), and option B gives profit, not working capital."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 512, $official_bank_source${"itemId":"2ffa113a-4814-54c0-a1f1-3bc9b17a4bd2","questionId":"e9916ee7-e2d9-5dec-8ee9-4f9f4cea388d","sourceKey":"bank:BUA201:PQ-021","payload":{"prompt":"A very high current ratio may indicate:","options":["Strong liquidity, or idle assets that are not being used productively","Insolvency","Excessive leverage","Strong profitability"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A high current ratio means current assets comfortably cover current liabilities, which shows liquidity, but too high a ratio can mean cash or stock is sitting idle. Option B is the opposite situation, and option D is wrong because liquidity and profitability are measured differently."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 513, $official_bank_source${"itemId":"4018a485-39e5-5475-b7f7-66aede8e0b67","questionId":"f97f838c-580c-54bc-a1ee-d8f1d3082e9e","sourceKey":"bank:BUA201:PQ-022","payload":{"prompt":"Using more debt in a firm's capital structure (financial leverage) mainly increases the firm's:","options":["Tax avoidance only","Operational control","Governance transparency","Financial risk"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Debt carries fixed interest and repayment obligations that must be met whether profits are high or low, so higher leverage raises financial risk to shareholders. Option A is wrong because tax savings on interest are only one side effect, not the main result, and options B and C are unrelated to borrowing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 514, $official_bank_source${"itemId":"bc54b206-1408-5366-b4ff-191d95d3c6ee","questionId":"29b6c8d7-d401-5aea-801f-812b06b05ed1","sourceKey":"bank:BUA201:PQ-023","payload":{"prompt":"Just-in-time (JIT) inventory systems are especially vulnerable to:","options":["Supply chain disruptions","Excess inventory","Bureaucracy","Stable demand"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"JIT keeps very little stock and relies on suppliers delivering exactly when needed, so any delay in supply can halt production. Option B is the problem JIT is designed to remove, and option D actually suits JIT well."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 515, $official_bank_source${"itemId":"d967a059-7b4d-5bb9-a681-f283055e8b80","questionId":"8c3e96e8-df2c-5b90-bd16-78438ae7d199","sourceKey":"bank:BUA201:PQ-024","payload":{"prompt":"Total Quality Management (TQM) emphasises:","options":["Downsizing","Continuous improvement","Capital restructuring","Inspection at the end of production only"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"TQM is an organisation-wide approach in which everyone works to improve quality continuously and prevent defects. Option D is the traditional approach TQM moved away from, because it catches errors after they happen instead of building quality in."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 516, $official_bank_source${"itemId":"2e91d045-da8e-5fe7-91da-0ca323fd441f","questionId":"5ac4fd4b-de30-5e4d-b2fa-417277e02eb1","sourceKey":"bank:BUA201:PQ-032","payload":{"prompt":"A budget primarily functions as a tool for:","options":["Ethical enforcement","Motivation only","Legal compliance","Planning and control"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A budget sets out planned income and spending in money terms, and actual results are later compared with it to control performance. Option B is too narrow because motivation is only a side benefit, and options C and A are not what budgets are designed for."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 517, $official_bank_source${"itemId":"0ccfb9b5-c21b-5333-8f2d-5dd2f69bb9fd","questionId":"e0c91873-cb14-55f6-a45a-e11893c4f915","sourceKey":"bank:BUA201:PQ-033","payload":{"prompt":"If the marketing department overestimates demand and production follows that forecast, the operations department is most likely to face:","options":["Shortage of finished goods","Excess inventory","A regulatory penalty","Underproduction"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"If more is produced than customers actually buy, unsold goods pile up as excess stock, which shows why marketing and operations must coordinate. Options D and A would follow from underestimating demand, not overestimating it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 518, $official_bank_source${"itemId":"dd9b4295-dd02-5e0e-a48c-da483e2e04bc","questionId":"3fc2da26-3d3c-5050-ab20-8147a910d954","sourceKey":"bank:BUA201:PQ-040","payload":{"prompt":"A high debt-equity ratio indicates:","options":["High financial leverage","Operational efficiency","Strong liquidity","Low risk"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The debt-equity ratio compares borrowed funds with owners' funds, so a high ratio means the firm relies heavily on debt. Option D is the opposite, since heavy debt raises risk, and option C is measured by liquidity ratios like the current ratio."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 519, $official_bank_source${"itemId":"bd8f6194-4a02-59e7-b00c-c7d420df7fd9","questionId":"2b81e0e5-e6b0-5eea-a7e0-6a36dae1938c","sourceKey":"bank:BUA201:PQ-042","payload":{"prompt":"Forward vertical integration involves a manufacturer:","options":["Downsizing its workforce","Withdrawing from some markets (retrenchment)","Acquiring or setting up its own distributors or retail outlets","Acquiring its suppliers"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Forward integration means moving down the supply chain towards the final customer, for example a manufacturer owning its distribution or shops. Option D is backward integration, which moves towards the sources of inputs."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 520, $official_bank_source${"itemId":"a6826b7c-9d65-5cdd-a7eb-5cd84cc427f4","questionId":"672c548a-6798-52c9-a780-042758333f12","sourceKey":"bank:BUA201:PQ-044","payload":{"prompt":"Liquidity ratios measure a firm's ability to meet its:","options":["Short-term obligations","Market share goals","Profit targets","Long-term debt"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Liquidity ratios such as the current ratio and quick ratio compare liquid assets with debts falling due within a year. Option D is the concern of solvency or gearing ratios, and option C is measured by profitability ratios."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 521, $official_bank_source${"itemId":"cb8934fa-5deb-5848-b00b-725547a536ea","questionId":"8f748fe3-9931-5b8a-bdef-4bb0f9a7c2fe","sourceKey":"bank:BUA201:PQ-051","payload":{"prompt":"Productivity is best defined as:","options":["Employee satisfaction","Capital expansion","Revenue growth","Output divided by input"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Productivity measures how efficiently inputs such as labour, materials and capital are turned into goods and services, so it is output per unit of input. Option C can rise just from higher prices, and option B shows growth in resources, not how well they are used."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 522, $official_bank_source${"itemId":"36bbe375-f459-5bac-9de3-3c20815dc2f3","questionId":"77a683aa-e5b5-5187-b605-e9e56f40d4d6","sourceKey":"bank:BUA201:PQ-053","payload":{"prompt":"Net profit margin measures a firm's:","options":["Solvency","Asset turnover","Profitability","Liquidity"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Net profit margin is net profit expressed as a percentage of sales, showing how much profit each naira of sales earns. Option D is measured by ratios like the current ratio, and option A by gearing ratios such as debt-equity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 523, $official_bank_source${"itemId":"24788d89-dc36-53c0-b5c9-a192d882c0ee","questionId":"d5f14c3e-d9e8-5ec2-ace7-d3bc8e4bf4df","sourceKey":"bank:BUA201:PQ-054","payload":{"prompt":"A firm's operations strategy must be aligned with its:","options":["Corporate strategy","Stock exchange listing","Tax rate","Informal structure"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Operations decisions about capacity, quality, cost and delivery must support the firm's overall goals, otherwise functional areas pull in different directions. Options C and B are outside factors, and option D is the network of personal relationships, not a strategic guide."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 524, $official_bank_source${"itemId":"9288f1ea-a4e8-5801-b53f-fdfc4a871948","questionId":"b78c95e9-9a36-570e-88ea-7cc59e398a1c","sourceKey":"bank:BUA201:PQ-058","payload":{"prompt":"Budget variance analysis mainly supports:","options":["Legal reform","Corrective action when actual results differ from planned results","Market segmentation","Corporate personality"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Variance analysis compares actual figures with the budget and investigates the differences so managers can take corrective action, which is the essence of control. Options C, D and A relate to marketing, company law and government policy."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 525, $official_bank_source${"itemId":"05307b27-0b6c-5b78-a5a6-21b26b0d48dc","questionId":"863236ab-61be-5b9d-a1ac-e394b88781a9","sourceKey":"bank:BUA201:PQ-059","payload":{"prompt":"A company's dividend policy directly affects its:","options":["Recruitment of staff","Retained earnings","Production cost","Market demand"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Profit after tax is either paid out as dividends or kept in the business, so the more paid as dividends, the less is retained to finance growth. Options C, D and A are not directly determined by how profits are shared."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 526, $official_bank_source${"itemId":"67e75237-d916-5441-b676-0a5a84b66dcf","questionId":"bb839a17-4ea2-5855-b4a7-34f8430466c5","sourceKey":"bank:BUA201:PQ-066","payload":{"prompt":"Financial planning involves forecasting:","options":["Employee morale","Cash flows","Political risk only","Exchange rates only"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Financial planning estimates future inflows and outflows of funds so the firm knows when it will need finance and how much. Options D and C are too narrow because of the word only, and option A is an HR concern."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 527, $official_bank_source${"itemId":"6249db6f-b2a0-51df-95fd-6620d6b26192","questionId":"babc02e3-bab9-523d-b7da-75fbdb9bd5ef","sourceKey":"bank:BUA201:PQ-072","payload":{"prompt":"Venture capital is most suitable for:","options":["Start-ups with high growth potential","Cooperative societies","Non-governmental organisations","Mature firms with stable cash flows"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Venture capitalists invest equity in young, risky businesses that could grow fast, accepting high risk in exchange for a share of large future gains. Option D usually has cheaper options like bank loans or retained earnings, and options B and C are not structured to offer investors that kind of return."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 528, $official_bank_source${"itemId":"ea0d4bdf-a8a5-5d61-9dea-977b08d70d79","questionId":"7c336feb-7fe6-52a7-aee5-06ecdd0d42b0","sourceKey":"bank:BUA201:PQ-073","payload":{"prompt":"A cash flow statement shows:","options":["Profitability","Governance quality","Market segmentation","The movement of cash into and out of a business over a period"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The cash flow statement records actual cash received and paid in operating, investing and financing activities, showing how the firm's cash position changed. Option A is shown by the income statement, which can show a profit even when cash is short."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 529, $official_bank_source${"itemId":"063263fc-4ae2-5dc1-90e4-84d802f22d91","questionId":"40633508-302f-5c8d-95d4-45f7738e5ee7","sourceKey":"bank:BUA201:PQ-074","payload":{"prompt":"Economies of scale reduce:","options":["Risk","Unit cost","Ethics","Governance"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Economies of scale are the cost savings a firm enjoys as it produces more, because fixed costs are spread over more units and bulk buying becomes cheaper. The result is a lower average cost per unit. Option A is wrong because producing more does not by itself lower business risk, and options C and D have nothing to do with output size."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 530, $official_bank_source${"itemId":"e19bb355-cb45-5132-baf3-0f05573fe4dc","questionId":"fbdb1590-cc2d-5a2f-b1ab-113991799fad","sourceKey":"bank:BUA201:PQ-078","payload":{"prompt":"A rights issue increases a company's:","options":["Debt","Leverage","Share capital","Insolvency"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A rights issue is an offer of new shares to existing shareholders, usually in proportion to what they already hold, so the money raised adds to the company's share capital (equity). Option A is wrong because no borrowing takes place. Option B is also wrong: extra equity actually lowers the proportion of debt in the capital structure, and the new cash makes insolvency (option D) less likely, not more."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 531, $official_bank_source${"itemId":"0c2fac96-5586-5b0c-9919-2d973d33ee32","questionId":"54471b1d-a58c-59e1-a725-f8ee3fc83e12","sourceKey":"bank:BUA201:PQ-080","payload":{"prompt":"Outsourcing is most likely to improve efficiency when:","options":["All functions are handed to outside firms","Governance is weak","The firm's core competence is protected","The firm is heavily in debt"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Outsourcing works best when a firm hands non-core activities to specialists while keeping control of the core competence that gives it its edge. Option A is wrong because outsourcing everything, including the core, leaves the firm with nothing distinctive and little control. Options B and D are weaknesses that make any arrangement riskier, not conditions for efficiency."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 532, $official_bank_source${"itemId":"a85a7652-d9fc-5b4e-a0cb-e7d6253aac56","questionId":"f0127c7b-911e-5e78-b9a8-cbf8d0fbdf79","sourceKey":"bank:BUA201:PQ-086","payload":{"prompt":"Cost-volume-profit (CVP) analysis is used to determine the:","options":["Level of governance","Break-even point","Rate of inflation","Leadership style"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"CVP analysis studies how changes in costs and sales volume affect profit, and its best-known result is the break-even point, where total revenue equals total cost. Options A, C and D are not things that can be measured from costs, prices and volume."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 533, $official_bank_source${"itemId":"0f77e5e9-5dc0-5fd7-9655-ac00e45b1a92","questionId":"4a42e733-6aea-58a6-a5f3-4e52587dc75f","sourceKey":"bank:BUA201:PQ-090","payload":{"prompt":"A high gross profit margin indicates that:","options":["Sales revenue is high relative to the cost of goods sold","The firm has weak liquidity","The firm has high leverage","The firm has poor governance"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Gross profit margin is gross profit (sales minus cost of goods sold) divided by sales, so a high figure means the firm keeps a large share of each naira of sales after paying for what it sold, through good pricing, efficient production or both. Option B is about cash and short-term assets, option C is about debt in the capital structure, and option D is about how the firm is directed; none of these is measured by gross margin."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 534, $official_bank_source${"itemId":"ef39c1a4-4e69-5799-be8f-385ae0fbc046","questionId":"b26d337c-500b-5653-9602-28f981bebff9","sourceKey":"bank:BUA201:PQ-092","payload":{"prompt":"Benchmarking helps a firm to:","options":["Identify and adopt best practices","Control national inflation","Avoid paying taxes","Exit its market"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Benchmarking compares a firm's processes and performance with those of leading organisations, so it can find gaps and adopt the best practices it sees. Option B is a government task, option C is illegal, and option D has nothing to do with learning from better performers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 535, $official_bank_source${"itemId":"9063df68-410c-5044-8cd5-5c6732fa644a","questionId":"baef05a6-fed5-57ca-bddb-b0cfbef2f78c","sourceKey":"bank:BUA201:PQ-093","payload":{"prompt":"Diversification of risk mainly reduces:","options":["Liquidity","The variability of overall returns","Governance","Organisational culture"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Spreading investments or activities across several areas means a loss in one is likely to be offset by gains in others, so overall returns swing less. Option A is wrong because diversification is not meant to cut a firm's cash, and options C and D are unrelated to how risk is spread."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 536, $official_bank_source${"itemId":"577e8521-7199-559f-92c6-c9b8e1bb1b09","questionId":"71f455d6-78ae-5d37-9137-2f91084d0ca6","sourceKey":"bank:BUA201:PQ-094","payload":{"prompt":"Cash budgeting assists a business mainly in:","options":["Increasing its debt","Avoiding cash shortages that could lead to insolvency","Reducing ethical standards","Measuring its market share"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A cash budget forecasts cash coming in and going out over a period, so managers can spot shortfalls early and arrange finance before they are unable to pay their bills. Option A is wrong because the aim is to plan cash, not to borrow more for its own sake. Option C makes no sense, and option D is a marketing measure."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 537, $official_bank_source${"itemId":"8816ee61-7fd6-5cd0-a787-bcde427d905a","questionId":"239fa6f8-8643-5719-9d9e-f43811b504e9","sourceKey":"bank:BUA201:PQ-098","payload":{"prompt":"Capital rationing requires managers to:","options":["Accept all available projects","Prioritise the projects with the highest returns","Avoid planning","Increase debt without limit"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Capital rationing exists when a firm has less money to invest than it needs for all its attractive projects, so managers must rank projects and choose those that give the best return on the limited funds. Option A is impossible under a funding limit, while options C and D ignore the constraint altogether."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 538, $official_bank_source${"itemId":"edffff10-24b3-5304-bb4d-ccf886660c68","questionId":"f4a8c167-d770-5037-9df6-16523515b01c","sourceKey":"bank:BUA201:PQ-099","payload":{"prompt":"A diversified firm reduces risk mainly through:","options":["Concentrating on a single market","Retrenchment","Downsizing","Spreading its activities across a portfolio of businesses"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A diversified firm operates in several products, markets or industries, so a downturn in one area can be cushioned by the others. Option A is the opposite, as putting everything into one market increases exposure to that market. Options B and C are cost-cutting moves, not ways of spreading risk."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 539, $official_bank_source${"itemId":"72117683-a499-598d-8bf5-0103afbfcf22","questionId":"b041395c-c2bc-53f1-b35d-572cd2e0aa2b","sourceKey":"bank:BUA201:FAP-001","payload":{"prompt":"Accounting is best described as the process of:","options":["Deciding which products to sell to which market segments","Identifying, measuring, recording and communicating financial information to users for decision-making","Converting inputs into finished goods and services","Raising funds for a business from banks and investors"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Accounting identifies, measures, records and communicates financial information so that users can make informed decisions. Option D describes the finance function, Option C describes production, and Option A describes marketing decisions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 540, $official_bank_source${"itemId":"6b3391d7-6ffb-5930-a789-bbecd61aae06","questionId":"58418111-286d-5c3c-b0c2-f97d03db21ee","sourceKey":"bank:BUA201:FAP-002","payload":{"prompt":"The main purpose of accounting in a business is to:","options":["Replace the need for managers to plan","Determine the selling price of every product","Provide financial information that helps users make economic decisions","Guarantee that the business will always make a profit"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Accounting exists to supply useful financial information to owners, managers, lenders, government and others for decision-making. Option D is impossible, since accounting reports results but cannot guarantee profit. Option A is wrong because information supports planning rather than replacing it, and Option B is a pricing decision made mainly by marketing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 541, $official_bank_source${"itemId":"956f9d88-8305-565e-b01a-550b510352da","questionId":"727ed18b-42d8-5d29-a61c-704c493cf454","sourceKey":"bank:BUA201:FAP-003","payload":{"prompt":"The Federal Inland Revenue Service (FIRS) studies a company's published financial statements to assess the tax it owes. In this situation FIRS is acting as:","options":["An external user of accounting information","The preparer of the company's accounts","An internal user of accounting information","A shareholder of the company"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"External users are people and bodies outside the business, such as tax authorities, lenders and investors, who rely on its financial statements. Option C would be managers and staff inside the firm. Option B is the firm's own accountants, and Option D is wrong because a tax authority is not an owner."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 542, $official_bank_source${"itemId":"1ffbfafa-b802-5e90-9901-58e5e6df551b","questionId":"7f186c19-156f-5b1f-80b7-b3e8543379a9","sourceKey":"bank:BUA201:FAP-004","payload":{"prompt":"The main difference between financial accounting and management accounting is that management accounting:","options":["Mainly provides detailed information for internal users such as managers","Deals only with past transactions and never with forecasts","Must always follow a fixed published format","Is prepared only for shareholders and tax authorities"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Management accounting produces detailed, often forward-looking reports such as budgets and costings for managers inside the firm. Options C and D describe financial accounting, which reports to external users in standard formats. Option B is wrong because management accounting often includes forecasts and budgets."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 543, $official_bank_source${"itemId":"bdac7135-a7f7-5089-ab6a-dfd9efb6b32e","questionId":"76651c4e-aa28-5939-a3ee-9c16486c4d3b","sourceKey":"bank:BUA201:FAP-005","payload":{"prompt":"The basic accounting equation is:","options":["Assets = Liabilities - Owners' equity","Owners' equity = Assets + Liabilities","Liabilities = Assets + Owners' equity","Assets = Liabilities + Owners' equity"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Everything a business owns (assets) is financed either by outsiders (liabilities) or by the owners (equity), so assets = liabilities + owners' equity. Options A, B and C rearrange the terms incorrectly; for example, equity is assets minus liabilities, not assets plus liabilities."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 544, $official_bank_source${"itemId":"e018ac5f-6fdf-5560-ab60-726c59dfdfb2","questionId":"b0de853d-9472-5fac-8d1a-8ad1062e2421","sourceKey":"bank:BUA201:FAP-006","payload":{"prompt":"The going concern concept assumes that:","options":["Assets are always shown at their current market value","Income is recorded when cash is received","The business is separate from its owner","The business will continue to operate for the foreseeable future"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Under the going concern concept, accounts are prepared on the assumption that the business will keep operating and is not about to close down. Option C is the business entity concept. Option B is cash accounting, which the accruals concept rejects, and Option A conflicts with the historical cost concept."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 545, $official_bank_source${"itemId":"b82e0962-6f99-5561-aede-97aa1193fc08","questionId":"d22f4508-be22-5485-a23f-e2cbb111db95","sourceKey":"bank:BUA201:FAP-007","payload":{"prompt":"Mrs Ade owns a provision shop and pays her children's school fees from the shop's cash. The bookkeeper records this as drawings rather than a business expense. Which accounting concept explains this treatment?","options":["Accruals concept","Business entity concept","Historical cost concept","Going concern concept"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The business entity concept treats the business as separate from its owner, so personal spending from business cash is drawings, not a business expense. Option D is about the business continuing to operate, and Option A is about matching income and expenses to the period they relate to. Option C is about recording assets at their original cost."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 546, $official_bank_source${"itemId":"835998cf-e231-5a20-8b9d-4e021541241b","questionId":"b70ea332-aa94-580c-aac1-73077e3c1415","sourceKey":"bank:BUA201:FAP-008","payload":{"prompt":"A printing firm completes a job worth N400,000 in December but the customer pays in January. The firm records the N400,000 as December income. Which concept is being applied?","options":["Business entity concept","Accruals (matching) concept","Going concern concept","Cash concept"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The accruals concept records income when it is earned and expenses when they are incurred, not when cash moves. Option D would wait until January when the cash is received. Options A and C deal with separating owner from business and assuming continued operation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 547, $official_bank_source${"itemId":"31a5a745-21fa-5a6b-bf50-782955f5e36b","questionId":"750006e6-3130-5471-9492-6904392f8ccb","sourceKey":"bank:BUA201:FAP-009","payload":{"prompt":"The financial statement that shows a business's assets, liabilities and owners' equity at a particular date is the:","options":["Income statement","Statement of cash flows","Statement of financial position (balance sheet)","Budget"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The statement of financial position is a snapshot of what the business owns and owes, and the owners' stake, at one point in time. Option A covers income and expenses over a period. Option B shows cash movements over a period, and Option D is a plan, not a statement of actual results."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 548, $official_bank_source${"itemId":"4115b508-1abd-5eff-b4f0-6e0ddb3e5641","questionId":"0ce3c060-f752-5c7a-928a-627dbe24d2bb","sourceKey":"bank:BUA201:FAP-010","payload":{"prompt":"The income statement (profit or loss statement) shows:","options":["Revenue and expenses over a period and the resulting profit or loss","Assets and liabilities at a single date","Only the cash received from customers","The names of the company's shareholders"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The income statement matches revenue against expenses for a period, such as a year, to give profit or loss. Option B describes the statement of financial position. Option C is only part of cash flow information, and Option D is not a financial statement."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 549, $official_bank_source${"itemId":"922ab2de-430d-577d-b830-d128593e9908","questionId":"c9b6fb92-34b9-50de-a33b-152cdb753120","sourceKey":"bank:BUA201:FAP-011","payload":{"prompt":"In its statement of cash flows, a company records N15,000,000 paid to buy a new bottling machine. Under which heading should this appear?","options":["Investing activities","Owners' equity","Financing activities","Operating activities"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Buying long-term assets such as machinery is an investing activity in the statement of cash flows. Option D covers day-to-day trading cash such as receipts from customers and payments to suppliers. Option C covers raising or repaying funds from owners and lenders, and Option B is not a cash flow heading."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 550, $official_bank_source${"itemId":"083fe542-dbb3-5fa5-a619-28270dc294f8","questionId":"a2b8de34-3c3f-537e-803d-30d0d3b32269","sourceKey":"bank:BUA201:FAP-012","payload":{"prompt":"A company receives a N20,000,000 five-year bank loan. In the statement of cash flows, this receipt is classified under:","options":["Investing activities","Financing activities","Operating activities","Revenue"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Cash raised from lenders or owners, such as loans and share issues, is a financing activity. Option A is for buying or selling long-term assets, and Option C is for day-to-day trading. Option D is wrong because a loan must be repaid and is not income."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 551, $official_bank_source${"itemId":"3c89eb8a-5165-589d-a48e-d372fdd10786","questionId":"ce1ce142-02ec-56c0-9f52-c992deac8dc8","sourceKey":"bank:BUA201:FAP-013","payload":{"prompt":"Which of the following is NOT a current asset?","options":["Inventory","Cash at bank","Trade receivables","Land and buildings"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Current assets are expected to be used up or turned into cash within about a year, like inventory, receivables and cash. Land and buildings are held for long-term use, so they are non-current assets. Options A, B and C are all current assets."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 552, $official_bank_source${"itemId":"93975d47-fb1c-5db8-8a28-49e5a2f986c3","questionId":"505ce307-b80b-538f-8fe2-264ef4ecbc53","sourceKey":"bank:BUA201:FAP-014","payload":{"prompt":"Which of the following is a current liability?","options":["Bank overdraft","Ten-year debenture","Delivery van","Ordinary share capital"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Current liabilities are debts due within about a year, such as a bank overdraft or trade payables. Option B is a long-term liability. Option D is part of owners' equity, and Option C is a non-current asset."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 553, $official_bank_source${"itemId":"e68306c5-4e2f-5f5e-b77e-38473e308edf","questionId":"5e3b306a-2e8f-5f25-b8b3-791dcbf25fba","sourceKey":"bank:BUA201:FAP-015","payload":{"prompt":"The finance function of a business is mainly concerned with:","options":["Obtaining funds and allocating them efficiently to achieve the firm's objectives","Recording past transactions in the books of account","Inspecting finished goods for defects","Recruiting and training employees"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Financial management is about acquiring funds and using them wisely, through investment, financing and dividend decisions. Option B is the bookkeeping side of accounting. Option D belongs to HR, and Option C belongs to quality control in production."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 554, $official_bank_source${"itemId":"1ff3331e-d7e5-5b38-b653-06fcec11fd8c","questionId":"7c2e4c47-9176-560e-afeb-1ef9be47d381","sourceKey":"bank:BUA201:FAP-016","payload":{"prompt":"The board of a bakery is deciding whether to spend N8,000,000 on a new automated oven expected to raise output for ten years. This is mainly:","options":["A financing decision","A working capital audit","A dividend decision","An investment (capital budgeting) decision"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Deciding which long-term assets to acquire is the investment, or capital budgeting, decision. Option A concerns how to raise the money, for example debt or equity. Option C concerns how much profit to pay to shareholders, and Option B is not a decision about acquiring an asset."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 555, $official_bank_source${"itemId":"55a36e0d-61c3-5bae-a9db-e64c143bd79a","questionId":"26d08913-6147-5af7-b8f5-0e9b6d206157","sourceKey":"bank:BUA201:FAP-017","payload":{"prompt":"A company must choose between raising N50,000,000 by issuing new shares or by taking a bank loan. This is a:","options":["Dividend decision","Production decision","Investment decision","Financing decision"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Choosing the mix of debt and equity used to fund the business is the financing decision. Option C concerns what assets to buy, and Option A concerns how much profit to distribute. Option B concerns how goods are made."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 556, $official_bank_source${"itemId":"d33b0799-08ab-599c-9ea8-e7fafaeb2c91","questionId":"e4fa057f-5658-5cfa-b993-39e25f54b645","sourceKey":"bank:BUA201:FAP-018","payload":{"prompt":"After making a profit for the year, a company's directors decide how much to pay shareholders and how much to keep for expansion. This is a:","options":["Financing decision","Investment decision","Dividend decision","Pricing decision"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The dividend decision splits profit between payments to shareholders and retained earnings. Option A concerns raising new funds, and Option B concerns choosing assets to invest in. Option D is a marketing decision about product prices."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 557, $official_bank_source${"itemId":"c047796b-c079-5f5d-ad2d-b074ad88c0bd","questionId":"9d33934c-3c22-510a-9345-1319e2e6a119","sourceKey":"bank:BUA201:FAP-019","payload":{"prompt":"Which of the following is a short-term source of finance?","options":["Debentures","Trade credit from suppliers","Retained earnings used to build a factory","Ordinary share capital"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Trade credit, where suppliers allow time to pay, is short-term finance, like a bank overdraft. Options A and D are long-term finance. Option C is internal finance used for a long-term project."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 558, $official_bank_source${"itemId":"7b2317a3-cc70-5d70-89ce-62ce2228cf9d","questionId":"b8707d80-4c49-55ab-8a41-1ed2ade02f09","sourceKey":"bank:BUA201:FAP-020","payload":{"prompt":"Which of the following is an INTERNAL source of finance for a company?","options":["Bank loan","Retained earnings","Issue of new shares","Trade credit"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Retained earnings are profits kept in the business rather than paid out, so they come from inside the firm. Options A, C and D all come from outsiders: banks, new investors and suppliers."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 559, $official_bank_source${"itemId":"efaa41f7-915e-566a-ac12-22e7fc84c859","questionId":"1abf8c84-99e7-5521-8d20-20734f795bed","sourceKey":"bank:BUA201:FAP-021","payload":{"prompt":"Which statement correctly distinguishes ordinary shareholders from debenture holders?","options":["Ordinary shareholders are owners who may receive dividends; debenture holders are lenders who receive interest","Ordinary shareholders receive fixed interest whether or not profit is made","Debenture holders are owners; ordinary shareholders are lenders","Both ordinary shareholders and debenture holders are lenders to the company"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Ordinary shareholders own the company and share in profit through dividends, while debenture holders lend to the company and are paid interest. Option C reverses the roles, and Option D ignores that shareholders are owners. Option B describes debenture interest, not ordinary dividends."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 560, $official_bank_source${"itemId":"aebf3246-c79b-55ac-b45f-e033c9c0793f","questionId":"d5062658-3eff-5ff5-afa1-6a6e7b272084","sourceKey":"bank:BUA201:FAP-022","payload":{"prompt":"A business can show a profit in its income statement and still run out of cash mainly because:","options":["Profit always equals the cash balance at the bank","Cash is only recorded when goods are produced","Expenses are never included in the income statement","Profit is recorded when sales are made, but customers may not have paid yet"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Under accruals, credit sales count towards profit before the cash is collected, so a profitable firm can still face a cash shortage. That is why cash flow must be managed alongside profit. Option A is false because profit and cash differ. Options B and C misstate how cash and expenses are recorded."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 561, $official_bank_source${"itemId":"1dce8800-db79-504c-9dd1-1903a6a663cf","questionId":"e522b634-0561-5591-a4f2-5b598c3adc54","sourceKey":"bank:BUA201:FAP-023","payload":{"prompt":"A budget is best defined as:","options":["A statement of assets at a particular date","A record of last year's transactions","A financial plan, expressed in figures, for a future period","A list of the company's shareholders"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"A budget is a quantitative plan for the future, setting out expected income, spending or other targets for a period. Option B describes historical records. Option D is a register of members, and Option A is the statement of financial position."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 562, $official_bank_source${"itemId":"49ecb7ff-1795-5c3e-8d5d-e6458c359695","questionId":"8c62b2f3-7be3-5482-9431-b197ab46e085","sourceKey":"bank:BUA201:FAP-024","payload":{"prompt":"Production is best described as:","options":["The selling of goods to final consumers","The process of transforming inputs into goods and services","The recruitment of factory workers","The recording of business transactions"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Production converts inputs such as labour, capital and raw inputs into outputs of goods and services. Option A describes selling, a marketing activity. Option D is accounting, and Option C is an HR activity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 563, $official_bank_source${"itemId":"6171cee8-1785-561e-941e-2d43b4ad5827","questionId":"a605f4b9-1f16-57b2-bd15-81274b7560c2","sourceKey":"bank:BUA201:FAP-025","payload":{"prompt":"In the input-transformation-output model of operations, which of the following is an INPUT?","options":["Customer satisfaction","Labour and raw materials","Finished goods","Packaged products in a warehouse"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Inputs are the resources fed into the operation, such as labour, raw inputs, machines and energy. Options C and D are outputs of the transformation process. Option A is an outcome the outputs aim to achieve."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 564, $official_bank_source${"itemId":"930b2d98-f462-5ea0-b310-83f16c19d080","questionId":"eb698be5-9e6d-5396-b92c-d4bec552a8e2","sourceKey":"bank:BUA201:FAP-026","payload":{"prompt":"A tailor in Surulere makes a single wedding gown to one bride's exact measurements and design. This type of production is:","options":["Continuous process production","Mass (flow) production","Batch production","Job production"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Job production makes a one-off item to a specific customer's requirements. Option C makes groups of identical items at a time. Options A and B produce large volumes of standard items in a continuous flow."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 565, $official_bank_source${"itemId":"449adf53-8349-5f2f-9ace-525104ad6c45","questionId":"b6b6761b-c9b4-52ec-8930-375bd31b0fdb","sourceKey":"bank:BUA201:FAP-027","payload":{"prompt":"A bakery makes 500 loaves of wheat bread, then switches its ovens to make 300 loaves of coconut bread, then 400 meat pies. This type of production is:","options":["Project production","Mass (flow) production","Job production","Batch production"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Batch production makes a set quantity of one item before switching to another. Option C makes one-off items to order, and Option B makes one standard product continuously in large volumes. Option A is for large one-off projects such as building a bridge."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 566, $official_bank_source${"itemId":"9d2acb6d-0871-5ca9-a64a-a8c1573724ac","questionId":"ba519a57-2f22-548a-a86a-827f3a6d1a0b","sourceKey":"bank:BUA201:FAP-028","payload":{"prompt":"A soft drinks plant runs its bottling line all day, producing identical bottles in very large volumes along an assembly line. This type of production is:","options":["Mass (flow) production","Batch production","Job production","Project production"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Mass or flow production makes large volumes of standardised products moving continuously along a line. Option C is for one-off custom items, and Option B is for groups of items with switches between them. Option D is for single large undertakings."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 567, $official_bank_source${"itemId":"a2c8c199-d3c0-5301-8154-cfad0c355f4d","questionId":"2e9f9d13-858e-5774-91f2-9681d819e355","sourceKey":"bank:BUA201:FAP-029","payload":{"prompt":"Which statement correctly distinguishes efficiency from effectiveness in operations?","options":["Efficiency is achieving output with minimum use of resources; effectiveness is achieving the intended goals","Effectiveness is measured only by the number of workers employed","Efficiency is achieving the intended goals; effectiveness is minimising resource use","Efficiency and effectiveness mean exactly the same thing"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Efficiency is about 'doing things right', using the fewest resources for the output. Effectiveness is about 'doing the right things', actually reaching the goals set. Option C swaps the two ideas, Option D ignores the difference, and Option B is not how effectiveness is measured."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 568, $official_bank_source${"itemId":"d75e0506-42ed-5d8d-953f-c7fa769ef5a8","questionId":"844de6b4-f844-5575-9777-31872749d93a","sourceKey":"bank:BUA201:FAP-030","payload":{"prompt":"The main difference between quality control and quality assurance is that quality assurance:","options":["Is concerned with the selling price of products","Aims to prevent defects by building quality into the process","Only inspects finished products to detect defects","Is done by customers after purchase"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Quality assurance focuses on preventing defects by designing and managing processes so that quality is built in. Option C describes quality control, which inspects outputs to detect defects. Options A and D are unrelated to managing quality in operations."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 569, $official_bank_source${"itemId":"ea7a1e19-bc47-556f-b44f-d772cc7e2a58","questionId":"ade85113-2c1e-5860-89c5-09a3d8ad4c5a","sourceKey":"bank:BUA201:FAP-031","payload":{"prompt":"The Japanese term 'kaizen', used in quality management, means:","options":["One-off major redesign of the whole factory","Holding large stocks of inventory as a buffer","Continuous, small, step-by-step improvement","Inspecting every product only at the end of production"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Kaizen means continuous improvement through many small changes, involving everyone in the organisation. Option B is the opposite of lean thinking. Option A describes radical change rather than gradual improvement, and Option D describes end-of-line inspection."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 570, $official_bank_source${"itemId":"b74ab13b-2861-565c-9566-2a0ee7336a56","questionId":"6f5f31a5-d4a9-5b34-abba-1442826ca6fb","sourceKey":"bank:BUA201:FAP-032","payload":{"prompt":"A supply chain is best described as:","options":["The chain of command from the managing director to junior staff","The network of organisations and activities that moves a product from raw material suppliers to the final customer","The list of a firm's shareholders","The sequence of entries in a company's ledger"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"The supply chain links suppliers, producers, distributors and retailers in getting a product from raw inputs to the final customer. Option C has nothing to do with product flow. Option A is the organisational hierarchy, and Option D is an accounting record."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 571, $official_bank_source${"itemId":"89f7338d-7393-51ea-89bc-0ada4d8d5484","questionId":"150752ae-d816-5322-9841-691442b662e9","sourceKey":"bank:BUA201:FAP-033","payload":{"prompt":"The main aim of a just-in-time (JIT) inventory system is to:","options":["Keep very large stocks of raw materials in case of shortages","Buy all inputs once a year to obtain bulk discounts","Minimise inventory by receiving inputs only when they are needed for production","Produce goods long before customers order them"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"JIT keeps stock levels low by having inputs arrive just as they are needed, cutting storage and holding costs. Options A, B and D all build up stock in advance, which is the opposite of JIT."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 572, $official_bank_source${"itemId":"298881e5-92a6-5c01-ba92-cf7867e04c2d","questionId":"2ef85f86-4165-5818-be65-72db9c4d4ea3","sourceKey":"bank:BUA201:FAP-034","payload":{"prompt":"A Kano manufacturer finds that delivering goods to Lagos takes much longer than planned because of poor road conditions, raising transport and maintenance costs. This is an example of:","options":["A segmentation error","A dividend policy problem","An infrastructure-related operations challenge","A going concern problem"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Poor roads are an infrastructure deficit that increases logistics time and cost, a common operations challenge in Nigeria. Option B relates to sharing profit, and Option A relates to dividing the market. Option D is an accounting assumption about the business continuing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 573, $official_bank_source${"itemId":"74878178-58cb-595f-9488-dec9cc8aa19d","questionId":"4fcc1e54-8da3-5851-8684-e8eeed4204c7","sourceKey":"bank:BUA201:FAP-035","payload":{"prompt":"Marketing forecasts that demand for a firm's product will rise by 30% next year. Which response shows good cross-functional integration?","options":["Finance cuts the production budget to save cash","Operations keeps output unchanged until marketing's forecast is proven","HR freezes recruitment while marketing increases advertising","Operations plans extra capacity, finance budgets for it, and HR plans the extra staff"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Functional areas work together: the demand forecast drives production planning, which finance must fund and HR must staff. Options A, B and C each have one function acting against the forecast, which leads to shortages or wasted effort."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 574, $official_bank_source${"itemId":"6ee2f8b0-2244-5be4-9501-299983d98feb","questionId":"5fb6e69c-9bed-5687-a5b5-41c0209056a9","sourceKey":"bank:BUA201:FAP-036","payload":{"prompt":"Which of the following is NOT usually a measure aimed at improving productivity in a factory?","options":["Reducing waste and machine downtime","Increasing the inputs used while keeping output unchanged","Improving the layout of the production line","Training workers to use machines better"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Productivity is output per unit of input, so using more inputs for the same output lowers it. Options A, C and D all help produce more output from the same inputs, which raises productivity."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 575, $official_bank_source${"itemId":"e8f00727-4dd1-5a5b-b094-4b9d212d085b","questionId":"f41a8e24-5902-5ce9-b460-d2aa6f12eb6a","sourceKey":"bank:BUA201:FAP-037","payload":{"prompt":"A business has total assets of N9,500,000 and total liabilities of N3,800,000. Using the accounting equation, what is the owners' equity?","options":["N9,500,000","N3,800,000","N13,300,000","N5,700,000"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Owners' equity = assets - liabilities = N9,500,000 - N3,800,000 = N5,700,000. Option C adds liabilities to assets instead of subtracting them. Options A and B simply repeat one of the given figures."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 576, $official_bank_source${"itemId":"03bfe202-4712-5113-9ab5-0151d1d2e2d4","questionId":"8dd293ac-f573-5d23-8cbe-f8b491091cf7","sourceKey":"bank:BUA201:FAP-038","payload":{"prompt":"A company's liabilities are N4,200,000 and its owners' equity is N6,300,000. What are its total assets?","options":["N10,500,000","N4,200,000","N6,300,000","N2,100,000"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Assets = liabilities + owners' equity = N4,200,000 + N6,300,000 = N10,500,000. Option D subtracts liabilities from equity, which is the wrong way to use the equation. Options B and C ignore one side of the financing."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 577, $official_bank_source${"itemId":"b814005b-248c-5f12-abcb-f0af35506df6","questionId":"dd1a3711-7b78-5c41-a8fd-99350c5480a0","sourceKey":"bank:BUA201:FAP-039","payload":{"prompt":"A provisions store had sales revenue of N7,200,000 and cost of sales of N4,500,000 for the year. What was its gross profit?","options":["N4,500,000","N7,200,000","N11,700,000","N2,700,000"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Gross profit = revenue - cost of sales = N7,200,000 - N4,500,000 = N2,700,000. Option C adds the two figures instead of subtracting. Options A and B just restate cost of sales or revenue."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 578, $official_bank_source${"itemId":"db01eaa4-d3ab-59c9-bb53-1ee53a8fcfc7","questionId":"d893f3a5-9281-5ac7-ae96-7d49570f9d55","sourceKey":"bank:BUA201:FAP-040","payload":{"prompt":"A firm's revenue is N12,000,000, cost of sales is N7,000,000 and operating expenses are N3,100,000. What is its net profit (before tax)?","options":["N1,900,000","N8,100,000","N5,000,000","N8,900,000"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Gross profit = 12,000,000 - 7,000,000 = N5,000,000; net profit = 5,000,000 - 3,100,000 = N1,900,000. Option C stops at gross profit and forgets operating expenses. Option D forgets cost of sales, and Option B adds operating expenses instead of deducting them."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 579, $official_bank_source${"itemId":"b60cb5bd-1a98-5b15-9cfa-a6a72a289ab1","questionId":"1f9a59df-92a8-505d-b91b-b3aa2915b71d","sourceKey":"bank:BUA201:FAP-041","payload":{"prompt":"A company has revenue of N12,000,000 and gross profit of N5,000,000. What is its gross profit margin, to 2 decimal places?","options":["240.00%","58.33%","41.67%","71.43%"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Gross profit margin = gross profit / revenue x 100 = 5,000,000 / 12,000,000 x 100 = 41.67%. Option A divides revenue by gross profit (the ratio upside down). Option B is cost of sales as a share of revenue, and Option D divides gross profit by cost of sales, which is a mark-up, not a margin."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 580, $official_bank_source${"itemId":"db7b7d1a-8a2e-50fb-9ee3-d66d059fc8f0","questionId":"5a1e3778-f4ac-5568-8422-f2e4b385e9b7","sourceKey":"bank:BUA201:FAP-042","payload":{"prompt":"A company has current assets of N3,600,000 and current liabilities of N1,500,000. What is its working capital (current assets minus current liabilities)?","options":["N3,600,000","N2,100,000","N5,100,000","N1,500,000"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Working capital = current assets - current liabilities = 3,600,000 - 1,500,000 = N2,100,000. Option C adds the two figures. Options A and D each use only one of the two figures and so ignore the other side of the calculation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 581, $official_bank_source${"itemId":"be7c5d08-e825-5538-abdd-0a2bf6515280","questionId":"db3c01db-c8bc-5fdf-80fc-480122ea9a08","sourceKey":"bank:BUA201:FAP-043","payload":{"prompt":"A distributor has current assets of N4,500,000 and current liabilities of N1,800,000. What is its current ratio (current assets divided by current liabilities)?","options":["2.5 : 1","0.4 : 1","1.5 : 1","0.7 : 1"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Current ratio = current assets / current liabilities = 4,500,000 / 1,800,000 = 2.5 : 1. Option B divides the wrong way round (0.4). Option C wrongly subtracts current liabilities first ((4,500,000 - 1,800,000) / 1,800,000 = 1.5), and Option D wrongly divides by the total of both figures."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 582, $official_bank_source${"itemId":"93885893-3031-5a0a-b524-698c404ee808","questionId":"7e365efa-2109-5574-a5ad-08d712352182","sourceKey":"bank:BUA201:FAP-044","payload":{"prompt":"A small business starts March with N850,000 cash. During March it expects cash receipts of N2,400,000 and cash payments of N2,950,000. What is its expected closing cash balance for March?","options":["-N550,000","N6,200,000","N300,000","N1,400,000"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Closing cash = opening balance + receipts - payments = 850,000 + 2,400,000 - 2,950,000 = N300,000. Option A ignores the opening balance and gives only the net cash flow of -N550,000. Option B adds payments instead of deducting them, and Option D swaps receipts and payments."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 583, $official_bank_source${"itemId":"bcc9f6a8-38dd-5d65-be9a-254128ed27c6","questionId":"ffe3a349-1275-5eb7-a9cd-594ee522dbe8","sourceKey":"bank:BUA201:FAP-045","payload":{"prompt":"A trader borrows N2,000,000 from a microfinance bank at 15% simple interest per annum for 2 years. What is the total interest payable?","options":["N300,000","N645,000","N600,000","N2,600,000"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Simple interest = principal x rate x time = 2,000,000 x 0.15 x 2 = N600,000. Option A is interest for only one year. Option B uses compound interest, 2,000,000 x ((1.15)^2 - 1) = N645,000, and Option D is the total amount repaid (principal plus interest), not the interest."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 584, $official_bank_source${"itemId":"efaf0145-28eb-5876-8fc8-65ea1dd64748","questionId":"593dd84a-c0e6-5834-959b-1e1fb9c12b95","sourceKey":"bank:BUA201:FAP-046","payload":{"prompt":"A shoe factory produces 9,600 pairs of shoes using 1,200 labour hours in a week. What is its labour productivity?","options":["8 pairs per labour hour","10,800 pairs per labour hour","8,400 pairs per labour hour","0.125 pairs per labour hour"],"correctOption":0,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Labour productivity = output / labour input = 9,600 / 1,200 = 8 pairs per labour hour. Option D divides input by output, the ratio upside down. Options B and C subtract or add the two figures instead of dividing output by input."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 585, $official_bank_source${"itemId":"5aa3184f-fbe6-5b27-9fc2-b908a7d0e93c","questionId":"51da7a08-61b5-5c35-9287-18a668995b32","sourceKey":"bank:BUA201:FAP-047","payload":{"prompt":"Last month a plant produced 6,000 units with 1,000 labour hours. This month it produced 7,800 units with 1,200 labour hours. By what percentage did labour productivity change, to 2 decimal places?","options":["Increased by 20.00%","Decreased by 8.33%","Increased by 30.00%","Increased by 8.33%"],"correctOption":3,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Productivity was 6,000 / 1,000 = 6 units per hour and is now 7,800 / 1,200 = 6.5 units per hour, so the change is (6.5 - 6) / 6 x 100 = 8.33% increase. Option C measures only the growth in output (30%) and ignores the extra hours. Option A measures only the growth in labour hours (20%), and Option B gets the direction wrong."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 586, $official_bank_source${"itemId":"f49139f5-ebdf-58bd-a4f8-a5d4e58c27a7","questionId":"7cc89db1-1f9d-5910-8d91-ac598ba9d076","sourceKey":"bank:BUA201:FAP-048","payload":{"prompt":"A cement plant can produce a maximum of 48,000 tonnes a month but actually produced 36,000 tonnes last month. What was its capacity utilisation, to 2 decimal places?","options":["42.86%","133.33%","75.00%","25.00%"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Capacity utilisation = actual output / maximum capacity x 100 = 36,000 / 48,000 x 100 = 75%. Option B divides capacity by output (the ratio upside down). Option D is the unused capacity, and Option A wrongly divides by the sum of both figures."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 587, $official_bank_source${"itemId":"9a308504-1bc3-5203-8c37-abafc1337213","questionId":"ad8b5f3f-e65f-5dbd-a908-cfe4ee70c7ed","sourceKey":"bank:BUA201:FAP-049","payload":{"prompt":"A juice producer has fixed costs of N1,800,000 a month. Each bottle sells for N1,500 and has a variable cost of N900. How many bottles must it sell each month to break even?","options":["1,200 bottles","750 bottles","3,000 bottles","2,000 bottles"],"correctOption":2,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Break-even units = fixed costs / (selling price - variable cost per unit) = 1,800,000 / (1,500 - 900) = 1,800,000 / 600 = 3,000 bottles. Option A divides by the selling price and forgets variable cost. Option D divides by variable cost, and Option B adds price and variable cost instead of subtracting."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 588, $official_bank_source${"itemId":"18031047-8dc7-5a5c-b8f2-6e57ddca1215","questionId":"eab946fb-fd61-5479-a19a-bd7b9128b2e8","sourceKey":"bank:BUA201:FAP-050","payload":{"prompt":"A delivery van costs N5,400,000, has an expected useful life of 4 years and an estimated residual (scrap) value of N600,000. Using the straight-line method, what is the annual depreciation charge?","options":["N1,500,000","N1,200,000","N4,800,000","N1,350,000"],"correctOption":1,"section":"Functional Areas II: Accounting, Finance and Production","explanation":"Straight-line depreciation = (cost - residual value) / useful life = (5,400,000 - 600,000) / 4 = N1,200,000 a year. Option D forgets to deduct the residual value. Option A adds the residual value instead, and Option C is the total depreciable amount over all 4 years, not the annual charge."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 589, $official_bank_source${"itemId":"b1c0d401-f72f-5886-bbc7-5ed59116c734","questionId":"c5014ba3-043d-597d-9179-1bc8b3bc6587","sourceKey":"bank:BUA201:PQ-012","payload":{"prompt":"For a business manager, high and unpredictable inflation most directly makes which task difficult?","options":["Applying corporate governance codes","Choosing a leadership style","Segmenting the market","Forecasting costs and prices"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"When prices rise quickly and unevenly, managers cannot reliably predict what raw materials, wages and transport will cost, so budgets and price lists go out of date fast. Options C, A and B may be affected indirectly, but cost forecasting is hit first and hardest."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 590, $official_bank_source${"itemId":"84c30bf3-c810-5c29-b03e-add6a173727c","questionId":"338c6601-9551-5b02-837b-d2706a24499d","sourceKey":"bank:BUA201:PQ-013","payload":{"prompt":"In Nigeria, a sharp depreciation of the naira against the US dollar most directly raises costs for firms that are:","options":["Dependent on imported raw materials","Using mainly locally sourced inputs","Family-owned","Labour-intensive"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"When the naira falls, every dollar of imported input costs more naira, so import-dependent firms see their costs jump. Option B describes firms that are largely shielded from this, and options D and C describe how a firm is run or owned, not its exposure to the exchange rate."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 591, $official_bank_source${"itemId":"a3fa192b-b3df-5799-974d-3bce4185c191","questionId":"878b79be-f58d-5ef0-941c-bc7062a71926","sourceKey":"bank:BUA201:PQ-031","payload":{"prompt":"In Nigeria, infrastructural deficiencies such as bad roads and erratic power supply primarily increase:","options":["Strategic stability","Workforce productivity","Governance transparency","Logistics and operating costs"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Poor roads, ports and power force firms to spend more on transport, delays and alternative energy, which raises the cost of doing business. Options C, B and A are things weak infrastructure tends to reduce, not increase."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 592, $official_bank_source${"itemId":"9b82326f-6852-51a3-8819-756c7299603f","questionId":"16113e18-605f-58e0-ba26-e647a1da5030","sourceKey":"bank:BUA201:PQ-065","payload":{"prompt":"For Nigerian firms, high operating costs caused by heavy reliance on diesel generators mainly reflect:","options":["An external infrastructure challenge","An ethical lapse","A corporate governance issue","Internal inefficiency"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Firms run generators because public electricity supply is unreliable, which is a weakness in the external environment rather than in the firm. Option D is tempting, but the cost comes from the power problem outside the firm, not from poor internal management."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 593, $official_bank_source${"itemId":"da261fc8-e75c-536a-8fa1-ed19b938c4a4","questionId":"47252e0e-5e64-5734-9a06-884945de7c00","sourceKey":"bank:BUA201:PQ-071","payload":{"prompt":"An import substitution strategy, in which a firm produces locally what it used to import, mainly reduces the firm's:","options":["Market share","Exposure to foreign exchange risk","Productivity","Liquidity"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"When inputs or products are made at home instead of being bought abroad, the firm needs less foreign currency and is less hurt by naira depreciation. Options A, C and D are not what import substitution is meant to reduce."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 594, $official_bank_source${"itemId":"0dd9b107-4d74-5b00-be99-ef68774176e6","questionId":"4078a7e7-d805-5011-bfb3-fa2aac9de480","sourceKey":"bank:BUA201:PQ-077","payload":{"prompt":"Innovation strategy supports:","options":["Competitive advantage","Bureaucracy","Cost rigidity","Market exit"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"An innovation strategy helps a firm create new or better products, processes and business models, which lets it stand out from rivals and build competitive advantage. Options B and C are the opposite of what innovation aims for, since they make a firm slow and inflexible. Option D describes leaving a market, which is what often happens to firms that fail to innovate."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 595, $official_bank_source${"itemId":"be89e7b8-3828-59e6-900b-16a2e6a49a78","questionId":"8e6d8633-5510-521e-a8db-c009c4b672bc","sourceKey":"bank:BUA201:CON-001","payload":{"prompt":"A food processing company in the North-East hires private security guards, pays higher insurance premiums and moves goods only in escorted convoys. The most direct effect of insecurity shown here is:","options":["Reduced need for planning","Higher operating costs","Lower tax rates","Cheaper raw inputs"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Spending on guards, insurance and escorts adds to the cost of running the business, which is a key way insecurity hurts firms. Option C has nothing to do with insecurity. Option D is the opposite of what usually happens, and Option A is wrong because insecurity makes careful planning more important."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 596, $official_bank_source${"itemId":"5cf61a9c-7dd1-5aad-a6a8-2f9e1302666b","questionId":"04a1175c-208c-5726-84b2-86b66df4fbdd","sourceKey":"bank:BUA201:CON-002","payload":{"prompt":"Farmers in several states abandon their farms because of attacks, and an agro-processing firm can no longer get enough maize. This illustrates how insecurity can:","options":["Reduce transport costs","Increase the supply of farm produce","Disrupt the supply of raw inputs to businesses","Strengthen the naira exchange rate"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"When farmers cannot work safely, output falls and firms that depend on farm produce face shortages and higher input prices. Option B is the opposite effect. Options A and D do not follow from farmers abandoning their farms."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 597, $official_bank_source${"itemId":"6fc3f63a-8b21-5c42-b6f1-2631cff65ace","questionId":"706ab431-3d80-5b65-95b2-e3c691af13c7","sourceKey":"bank:BUA201:CON-003","payload":{"prompt":"Persistent insecurity in a country is most likely to affect foreign direct investment (FDI) by:","options":["Attracting more investors because assets become cheaper","Having no effect, since investors consider only profit","Discouraging foreign investors because of higher risk","Forcing foreign investors to double their investment"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Foreign investors weigh risk against expected returns, and insecurity raises the risk to lives, assets and operations, so it tends to discourage investment. Option A ignores the safety risk. Option B is wrong because risk is part of the profit calculation, and Option D has no basis."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 598, $official_bank_source${"itemId":"fdf1ab1b-a742-5f7a-950d-9ac522c21bd0","questionId":"88438e7e-f1e6-55ba-8da7-1d9bf040c4a0","sourceKey":"bank:BUA201:CON-004","payload":{"prompt":"Which of the following is NOT a likely effect of insecurity on business operations in Nigeria?","options":["Smaller reachable markets in affected areas","Difficulty attracting staff to postings in affected areas","Restricted movement of staff and goods","Easier movement of staff and goods across all regions"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Insecurity restricts movement, makes postings unattractive and shrinks reachable markets. Easier movement across regions is the opposite of what insecurity causes. Options A, B and C are all common effects."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 599, $official_bank_source${"itemId":"ee07880c-dd60-5e18-a7bb-e4524370616a","questionId":"25cf9f3e-6029-5b22-983e-9d5848464218","sourceKey":"bank:BUA201:CON-005","payload":{"prompt":"A Lagos manufacturer spends a large share of its budget on diesel to run generators because public electricity supply is unreliable. This shows how poor infrastructure:","options":["Only affects firms that export their goods","Raises production costs and reduces competitiveness","Has no effect on the price of finished goods","Lowers production costs for local firms"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Firms that must generate their own power pay much more for energy, which pushes up unit costs and makes local products less competitive than imports. Option D is the opposite. Option A is wrong because all firms that rely on power are affected, and Option C ignores that higher costs are usually passed into prices."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 600, $official_bank_source${"itemId":"481233d9-152c-5693-a58f-41c16821997d","questionId":"997c14d8-4e82-5127-b73b-7f6c7ac5a79a","sourceKey":"bank:BUA201:CON-006","payload":{"prompt":"An importer's containers of machine parts stay for weeks at a congested seaport before clearance, and the firm pays extra charges for the delay. This is mainly an example of:","options":["A marketing mix problem","A recruitment problem","A dividend policy problem","An infrastructure and logistics constraint"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Port congestion is a transport infrastructure and logistics problem that delays inputs and adds extra costs. Option A concerns product, price, place and promotion decisions. Options B and C concern profit distribution and hiring, which are not involved here."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 601, $official_bank_source${"itemId":"51a2931b-7a8f-5e5b-a311-78ddd108538b","questionId":"c7ccf3da-62a4-52e6-af7b-8a698cb722b7","sourceKey":"bank:BUA201:CON-007","payload":{"prompt":"Poor road networks in many parts of Nigeria mainly affect businesses by:","options":["Eliminating the need for warehouses","Reducing the cost of vehicle maintenance","Making it easier to reach rural customers","Increasing distribution time and transport costs"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Bad roads slow deliveries, damage vehicles and increase transport costs, especially when serving distant and rural markets. Options B and C are the opposite of what bad roads do. Option A is wrong because delays often force firms to hold more stock in more places."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 602, $official_bank_source${"itemId":"bbd74f27-6152-5b0f-90fb-fcb8cb26aeb3","questionId":"cbb2fe12-ad8e-51ea-b6ca-ec77560ab94e","sourceKey":"bank:BUA201:CON-008","payload":{"prompt":"Which of the following is a common business response to unreliable public electricity in Nigeria?","options":["Investing in alternative power sources such as generators or solar systems","Relocating all operations to rural areas without power","Ignoring energy costs when setting prices","Stopping all production permanently"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Many firms self-generate power or invest in alternatives like solar to keep operating, though this adds to cost. Option D is an extreme step few firms take. Option C would lead to losses, and Option B would make the power problem worse."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 603, $official_bank_source${"itemId":"9fc635b0-08ed-5b8f-9a86-3a39d0bd395b","questionId":"bb9a853e-a5cb-50c9-947a-8d5acd9b0482","sourceKey":"bank:BUA201:CON-009","payload":{"prompt":"Inflation is best defined as:","options":["An increase in the value of the naira against the dollar","A sustained rise in the general price level over time","A fall in the general price level over time","A one-time increase in the price of a single product"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Inflation is a general and persistent increase in prices across the economy, which reduces what money can buy. Option D is a single price change, not inflation. Option C is deflation, and Option A is currency appreciation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 604, $official_bank_source${"itemId":"dc867ab3-c909-5f70-b937-fe7922e6b54a","questionId":"b2c5f400-7400-59e2-ab2c-3d485fd160bc","sourceKey":"bank:BUA201:CON-010","payload":{"prompt":"For a Nigerian business, a major effect of high inflation is that it:","options":["Increases the real value of workers' fixed salaries","Reduces consumers' purchasing power and raises input costs","Lowers the cost of borrowing from banks","Makes long-term planning and pricing easier"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Rising prices mean each naira buys less, so customers can afford less while the firm pays more for inputs. Option A is wrong because inflation erodes fixed salaries. Option D is wrong since unstable prices make planning harder, and Option C is wrong because lenders usually raise interest rates when inflation is high."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 605, $official_bank_source${"itemId":"be9c1edd-2dfe-5065-ab6c-720d2ee09a6f","questionId":"4dfbddda-b3c1-52ab-95f4-81887ae90544","sourceKey":"bank:BUA201:CON-011","payload":{"prompt":"After a period of rapid price increases, workers at a textile firm demand a pay rise because their salaries no longer cover basic needs. This illustrates that inflation:","options":["Reduces the cost of living","Increases the real value of savings","Erodes the real value of fixed incomes","Has no effect on employees"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"When prices rise faster than wages, the real value, or purchasing power, of a fixed salary falls, which creates pressure on HR and management for pay reviews. Options A and B are the opposite of what inflation does. Option D ignores the situation the workers describe."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 606, $official_bank_source${"itemId":"647267d6-a7d6-57d4-9ef2-62175394701e","questionId":"ea838eb8-3e6a-5c14-9dff-cdc7df4452d7","sourceKey":"bank:BUA201:CON-012","payload":{"prompt":"A restaurant in Port Harcourt has to reprint its menu several times a year because the prices of its ingredients keep rising. This shows that inflation:","options":["Reduces the cost of ingredients over time","Allows businesses to keep prices fixed for years","Makes pricing and planning more difficult for businesses","Only affects manufacturing firms"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Frequent price rises force firms to keep revising prices and budgets, making planning harder. Options A and B contradict the rising ingredient costs in the scenario. Option D is wrong because a restaurant, a service business, is clearly affected."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 607, $official_bank_source${"itemId":"f86e52c8-6891-5499-8b01-b7f32eed57dd","questionId":"fcb6a9c1-cd3b-5ceb-9ff8-3f8c08770394","sourceKey":"bank:BUA201:CON-013","payload":{"prompt":"A sharp depreciation of the naira against the US dollar most directly affects a Nigerian firm that imports its raw materials by:","options":["Reducing its need for foreign exchange","Having no effect on its costs","Increasing the naira cost of its imported inputs","Reducing the naira cost of its imported inputs"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"When the naira loses value, more naira is needed to buy each dollar, so imported inputs cost more in naira. Option D describes what happens when the naira gains value. Options A and B ignore the firm's need to pay for imports in foreign currency."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 608, $official_bank_source${"itemId":"b3a19bfb-24bf-5f3d-943a-2ce59e747358","questionId":"16b9670d-cdb5-5446-a2c0-bd690d297ac7","sourceKey":"bank:BUA201:CON-014","payload":{"prompt":"A Nigerian cashew exporter is paid in US dollars. If the naira depreciates against the dollar, other things being equal, the exporter will:","options":["Receive fewer naira for each dollar earned","Receive more naira for each dollar earned","Lose all its foreign customers","Have to pay more for every dollar it earns"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"With a weaker naira, each dollar converts into more naira, so exporters' naira revenue rises, other things being equal. Option A is what happens when the naira strengthens. Options C and D do not follow from depreciation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 609, $official_bank_source${"itemId":"b848218c-506f-5e89-96b2-5cbb2106ba7f","questionId":"cea5600e-caf9-5f40-81e0-d16f13900965","sourceKey":"bank:BUA201:CON-015","payload":{"prompt":"Scarcity of foreign exchange creates a particular problem for multinational companies operating in Nigeria because:","options":["It becomes difficult to obtain dollars to pay foreign suppliers or send profits to parent companies","It makes local raw materials unavailable","It forces them to stop paying local staff","It reduces the number of local customers to zero"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Multinationals need foreign currency to pay for imports and to repatriate dividends to their parent companies, so FX scarcity directly hampers these payments. Options B, C and D exaggerate or misplace the effect, since FX scarcity mainly affects transactions in foreign currency."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 610, $official_bank_source${"itemId":"f0c77018-899e-5315-b63b-5a5f2b9de6ba","questionId":"227b0598-cf2f-5f3f-97b1-fed71275385e","sourceKey":"bank:BUA201:CON-016","payload":{"prompt":"To reduce its exposure to foreign exchange problems, a brewery sets up its own farms in Nigeria to grow the grains it previously imported. This strategy is best described as:","options":["Market segmentation","Dividend policy","Forward integration","Backward integration"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"By taking over the production of its own inputs, the firm moves back along its supply chain, which is backward integration, and it also cuts its need for foreign currency. Option C would mean moving towards distribution and customers. Options A and B are unrelated marketing and finance decisions."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 611, $official_bank_source${"itemId":"4d1bf5be-7b22-523b-8b47-15bdf6d7336e","questionId":"bb6105e2-4571-5a48-ab07-bd38e12a25f2","sourceKey":"bank:BUA201:CON-017","payload":{"prompt":"Corruption is commonly defined as:","options":["The fair award of contracts through open bidding","The legal payment of taxes to government","The abuse of entrusted power for private gain","The voluntary social responsibility of firms"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Corruption is the misuse of a position of trust, public or private, for personal benefit, such as bribery or embezzlement. Options A, B and D describe lawful or ethical practices that are the opposite of corruption."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 612, $official_bank_source${"itemId":"43206683-fc90-5ab7-9f8d-d7e95c248aef","questionId":"bfffca91-9221-5772-9c68-c81429283b04","sourceKey":"bank:BUA201:CON-018","payload":{"prompt":"Which of the following is a major effect of corruption on business in Nigeria?","options":["It raises the cost of doing business and creates unfair competition","It lowers the cost of obtaining permits","It increases public trust in institutions","It ensures contracts go to the most efficient firms"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Bribes and unofficial payments add to costs and allow firms to win through connections rather than efficiency, which distorts competition. Option D is the opposite of what corruption causes. Options B and C are wrong, since corruption makes approvals costlier and damages trust."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 613, $official_bank_source${"itemId":"0367106a-500d-5a55-844c-d98dff440014","questionId":"3b232228-f1e8-532e-81e7-abbe17f83c7f","sourceKey":"bank:BUA201:CON-019","payload":{"prompt":"An official asks a company's procurement manager for a personal payment before approving the firm's documents. The most professional and ethical response is to:","options":["Pay from personal funds to avoid involving the company","Ignore company policy since the practice is common","Refuse, document the request and report it through the proper channels","Pay quietly and record it as a 'miscellaneous' expense"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Ethical managers refuse bribes, keep a record and report through official channels, protecting both the firm and their professional integrity. Options A and D still involve paying a bribe, and Option D also falsifies records. Option B wrongly treats a common practice as acceptable."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 614, $official_bank_source${"itemId":"88baf636-589b-5f20-8758-4765ac48d546","questionId":"4303e74f-7c4c-5815-9aeb-f254756e4f9e","sourceKey":"bank:BUA201:CON-020","payload":{"prompt":"A bank collapses after its board fails to check the chief executive, who granted large unsecured loans to companies he secretly controlled. The main cause of failure here is:","options":["Weak corporate governance and insider abuse","Strong board oversight","Excessive government infrastructure spending","Too much market segmentation"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"When the board does not monitor management, insiders can abuse their position, as in this case of hidden related-party lending. Option B is the opposite of what happened. Options C and D are unrelated to the failure described."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 615, $official_bank_source${"itemId":"dcce30c3-eff0-53fb-b5f5-ff912f11a3ce","questionId":"5aa76f07-dbc0-5b8e-b39d-aa496b88a9d8","sourceKey":"bank:BUA201:CON-021","payload":{"prompt":"A successful family business collapses within three years of its founder's death because no one had been prepared to take over. This is mainly a failure of:","options":["Depreciation policy","Market segmentation","Succession planning","Inventory control"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Without a succession plan, the death or exit of a key leader can leave a firm without capable leadership, a common weakness in family businesses. Options A, B and D are routine marketing, operations and accounting issues that do not explain the collapse."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 616, $official_bank_source${"itemId":"912e0572-a224-5b03-818e-b81b8a6fe51b","questionId":"c7fd366f-7f9a-59b9-89a0-4c0015d5a2f2","sourceKey":"bank:BUA201:CON-022","payload":{"prompt":"Frequent and unexpected changes in government policies, such as sudden import bans or tariff changes, mainly affect businesses by:","options":["Guaranteeing higher profits for all firms","Reducing competition from abroad permanently","Making business planning unnecessary","Increasing uncertainty and making long-term planning difficult"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Policy inconsistency makes the business environment unpredictable, so firms find it hard to plan investments and may delay them. Options A and C are not consequences of policy changes. Option B is wrong because policies that change frequently cannot guarantee any lasting protection."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 617, $official_bank_source${"itemId":"ad1668de-3c97-53a3-a4e4-6999549cdd7e","questionId":"6a4dbc2e-81db-5fea-8271-3ccaf593d9d3","sourceKey":"bank:BUA201:CON-023","payload":{"prompt":"When a business pays several overlapping levies and taxes to different levels of government on the same activity, the problem is known as:","options":["Tax incentive","Double-entry bookkeeping","Tax holiday","Multiple taxation"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Multiple taxation occurs when firms are charged several taxes or levies by different authorities for the same activity, raising the cost of doing business. Options A and C are reliefs that reduce taxes. Option B is a method of recording accounts."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 618, $official_bank_source${"itemId":"f9eb52aa-2d5f-55a9-8957-55c0f5834313","questionId":"1312df69-8d58-5574-95ac-67f2a70ae19e","sourceKey":"bank:BUA201:CON-024","payload":{"prompt":"Which of the following is a major benefit of digital payment platforms and mobile banking for small businesses in Nigeria?","options":["Guaranteed protection from all fraud","Elimination of the need to keep records","Faster, easier transactions and access to customers without relying only on cash","Complete removal of all business risks"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Digital payments speed up transactions, reduce the need to handle cash and help small firms reach more customers. Options A and D overstate the benefits, since digital systems carry their own risks such as fraud. Option B is wrong because digital transactions still need proper records."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 619, $official_bank_source${"itemId":"48da12e7-1366-59ac-a1b0-f763110d0454","questionId":"8ed54c39-c221-530a-b9fc-7c5cb286003f","sourceKey":"bank:BUA201:CON-025","payload":{"prompt":"An employee of a logistics firm clicks a fake email link, and hackers gain access to the company's customer database. This illustrates which challenge of digitisation?","options":["Infrastructure deficit in roads","Multiple taxation","Cybersecurity risk","Foreign exchange scarcity"],"correctOption":2,"section":"Contemporary Management Issues in Nigeria","explanation":"Greater use of digital systems exposes firms to cyber threats such as phishing and data theft, so firms must invest in security and staff awareness. Options A, B and D are real challenges in Nigeria but are not shown in this scenario."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 620, $official_bank_source${"itemId":"5c71f290-a292-571f-9d88-115a5fd6eeeb","questionId":"1de875fe-b0de-5333-8f10-c582b6b8cdc1","sourceKey":"bank:BUA201:CON-026","payload":{"prompt":"Which of the following is a common challenge Nigerian firms face when adopting new digital technologies?","options":["Shortage of staff with the needed digital skills","Too many skilled workers for every role","Customers refusing to use mobile phones","Technology always reducing costs immediately"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"A digital skills gap means firms often need to train staff or compete hard for skilled workers before new technology pays off. Option B is the opposite of a skills gap. Option D is wrong because new technology usually involves upfront cost, and Option C contradicts the wide use of mobile phones."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 621, $official_bank_source${"itemId":"92b6ac61-65aa-52cc-8574-931dc1d1457c","questionId":"9803a143-ede9-58d7-a493-7d23c17aae1c","sourceKey":"bank:BUA201:CON-027","payload":{"prompt":"Managers in Nigeria increasingly rely on innovation and digitisation mainly in order to:","options":["Improve efficiency, reach new customers and stay competitive","Avoid all government regulation","Increase the number of paper records kept","Reduce the need to understand customers"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Innovation and digitisation help firms cut costs, serve customers better and compete with local and foreign rivals. Option B is wrong because digital firms are still regulated. Options C and D are the opposite of what digitisation aims to achieve."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 622, $official_bank_source${"itemId":"b1580416-565e-5f12-b225-c28b1eb8ab1e","questionId":"835998cd-d219-5f36-81a3-5d425b61f5c3","sourceKey":"bank:BUA201:CON-028","payload":{"prompt":"Globalisation is best described as:","options":["The increasing integration of national economies through trade, investment, technology and information flows","The movement of businesses from urban to rural areas within a country","The use of a single currency by every country in the world","A policy of banning all imports into a country"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Globalisation refers to the growing interconnection of economies through cross-border trade, capital, technology and ideas. Option D describes protectionism, the opposite tendency. Option B is internal relocation, and Option C is not what globalisation means."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 623, $official_bank_source${"itemId":"a42104f8-1caa-55f8-9b55-10b63c12fcc7","questionId":"6d560398-c0ab-5794-ae1b-eff76c5a3e40","sourceKey":"bank:BUA201:CON-029","payload":{"prompt":"For many Nigerian manufacturers, a major challenge brought by globalisation is:","options":["A ban on Nigerian exports","Stronger competition from imported goods and foreign firms","The disappearance of all foreign competitors","Reduced access to foreign technology"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Opening economies to world trade lets foreign products and firms compete directly with local producers, often on price and quality. Option C is the opposite. Option D is wrong since globalisation spreads technology, and Option A does not follow from globalisation."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 624, $official_bank_source${"itemId":"57e8d7af-8bc8-5e9e-8fca-28010c582e55","questionId":"f980d6cf-3b31-5b5e-bcac-76ddfbf30826","sourceKey":"bank:BUA201:CON-030","payload":{"prompt":"Which of the following is an OPPORTUNITY that globalisation offers Nigerian businesses?","options":["Freedom from international quality standards","Protection from all foreign competition","Guaranteed stable exchange rates","Access to wider international markets and foreign investment"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Globalisation lets local firms sell to larger markets abroad and attract foreign capital and partners. Option B is not an effect of globalisation, which increases competition. Options A and C are wrong because export markets usually demand high standards and exchange rates still fluctuate."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 625, $official_bank_source${"itemId":"249007bd-b3ec-5119-99f7-2ed7ab15aa32","questionId":"f64462f1-a032-521a-8cdf-969821c63bf8","sourceKey":"bank:BUA201:CON-031","payload":{"prompt":"A hospital in Lagos struggles to fill specialist positions because many experienced doctors have moved abroad for better pay and conditions. This is an example of:","options":["Market segmentation","Multiple taxation","Inflation","Brain drain"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Brain drain is the emigration of skilled professionals, which leaves local organisations short of talent and raises recruitment and retention costs. Options A, B and C are other concepts that do not describe people leaving the country."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 626, $official_bank_source${"itemId":"07a0c704-b90d-52cb-8203-142182ca58cf","questionId":"37b1ae53-7131-5f68-8382-8abc7e1b45d5","sourceKey":"bank:BUA201:CON-032","payload":{"prompt":"From an HR point of view, a sensible response by a Nigerian firm to brain drain is to:","options":["Stop all staff training so employees are less attractive to foreign employers","Improve retention through better pay, training and career development","Reduce salaries to cut costs","Avoid planning for staff replacement"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Firms can reduce the loss of skilled staff by improving compensation, development opportunities and succession plans. Option A would weaken the workforce and morale. Options C and D would make losing staff more likely and more damaging."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 627, $official_bank_source${"itemId":"6db680b4-1855-58c8-8ff5-12ab35c43ded","questionId":"8454226f-ef24-5de8-85d3-400fc9783749","sourceKey":"bank:BUA201:CON-033","payload":{"prompt":"High lending interest rates mainly affect small and medium enterprises (SMEs) in Nigeria by:","options":["Making bank loans expensive and limiting their ability to expand","Increasing the dividends they pay","Reducing their need for working capital","Making it cheaper for them to borrow"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"When interest rates are high, borrowing becomes costly, so many SMEs cannot afford loans to grow or fund working capital. Option D is the opposite. Options B and C do not follow from higher borrowing costs."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 628, $official_bank_source${"itemId":"33bc8986-0779-57c0-a434-f9342f5764c5","questionId":"b01bf170-f899-5091-ac50-e9407ea8ac5a","sourceKey":"bank:BUA201:CON-034","payload":{"prompt":"A Nigerian cosmetics producer loses sales because cheap fake copies of its products, bearing its brand name, are sold in open markets. This challenge is best described as:","options":["Positioning","Backward integration","Brain drain","Counterfeiting and unfair competition"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Counterfeit products copy a genuine brand, take its sales and can damage its reputation when the fakes are of poor quality. Option C concerns skilled workers leaving. Options A and B are strategies a firm chooses, not a threat imposed on it."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 629, $official_bank_source${"itemId":"9d24d635-7994-5909-8a16-a891301d28d2","questionId":"bebd90fd-36ac-50e7-b5ca-aa84a1cfe879","sourceKey":"bank:BUA201:CON-035","payload":{"prompt":"A large informal sector, where many businesses are unregistered, creates a challenge for policy and management mainly because:","options":["It eliminates competition for registered firms","It makes reliable business data and regulation harder to achieve","It guarantees full tax collection","It means there are no small businesses in the economy"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"Unregistered firms often lack records and stay outside the formal tax and regulatory system, which limits data and enforcement. Option D is wrong because informal firms are mostly small businesses. Options A and C are the opposite of what usually happens."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_bua201', 'add', 630, $official_bank_source${"itemId":"2af16e72-538a-5092-b50c-e3cf143b9401","questionId":"1ae4a31c-2e90-5d76-bf48-3be1b1fcb360","sourceKey":"bank:BUA201:CON-036","payload":{"prompt":"An oil company faces protests from a host community after a pipeline leak damages farmland and fishing waters. The best long-term management response is to:","options":["Clean up, compensate fairly and engage the community through social responsibility programmes","Pay only the community leaders privately","Deny the damage and ignore the community","Close the site without informing anyone"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Responsible management repairs environmental damage, compensates those affected and builds trust through genuine engagement and CSR. Option C worsens conflict. Option B is unethical and may amount to bribery, and Option D avoids accountability."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 631, $official_bank_source${"itemId":"f8eaf309-26eb-5043-bfcf-41fb6acfe44c","questionId":"ff293310-eaec-5967-b71a-611a053b63b8","sourceKey":"bank:BUA201:CON-037","payload":{"prompt":"Which of the following is NOT a contemporary challenge facing managers in Nigeria?","options":["Inflation and foreign exchange constraints","Infrastructure deficits such as poor roads","Insecurity in parts of the country","Uninterrupted and cheap public power supply across the country"],"correctOption":3,"section":"Contemporary Management Issues in Nigeria","explanation":"Unreliable power, not uninterrupted cheap power, is the problem firms face, so Option D is not a challenge. Options A, B and C are widely recognised challenges for managers in Nigeria."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 632, $official_bank_source${"itemId":"3d9a7805-a2f7-5237-be7b-fa296049449b","questionId":"bf4cec0b-d1c6-573f-87af-508800264c36","sourceKey":"bank:BUA201:CON-038","payload":{"prompt":"Scenario planning helps Nigerian managers cope with an uncertain environment mainly by:","options":["Preparing responses to several possible future situations","Predicting the future exactly","Eliminating the need for budgets","Ensuring that only one plan is ever made"],"correctOption":0,"section":"Contemporary Management Issues in Nigeria","explanation":"Scenario planning considers a range of possible futures, such as sharp currency changes or supply disruptions, and prepares responses for each. Option B is wrong since no method predicts the future exactly. Options C and D contradict the idea of preparing flexible plans."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 633, $official_bank_source${"itemId":"85295109-ac9a-529a-ad88-92efc8e5a27b","questionId":"e597110b-c165-5046-9ca5-ba2bb01ec727","sourceKey":"bank:BUA201:CON-039","payload":{"prompt":"Which pair correctly matches a contemporary challenge in Nigeria with its most direct business effect?","options":["Inflation - higher purchasing power of consumers","Naira depreciation - higher cost of imported inputs","Insecurity - lower insurance premiums","Poor roads - faster deliveries"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"A weaker naira means more naira is needed to pay for imports, raising input costs. Option C is wrong because insecurity raises insurance costs, and Option D is wrong because bad roads slow deliveries. Option A is the reverse of inflation's effect on purchasing power."}}$official_bank_source$::jsonb),
  ('official_bank_bua201', 'add', 634, $official_bank_source${"itemId":"70eb74f7-34b4-59a2-b927-9b26e829b41f","questionId":"2714d414-10e0-50ee-805f-aa3d391bce31","sourceKey":"bank:BUA201:CON-040","payload":{"prompt":"A Nigerian supplier refuses to sell to new customers on credit because, in its experience, recovering unpaid debts through the courts takes years. This reflects which governance weakness in the business environment?","options":["Excessive digital adoption","Slow and uncertain enforcement of contracts","Strong consumer purchasing power","Too much foreign investment"],"correctOption":1,"section":"Contemporary Management Issues in Nigeria","explanation":"When contracts cannot be enforced quickly and reliably, firms protect themselves by limiting credit and doing business only with people they know, which slows trade and growth. Options A, C and D would not make a supplier afraid of unpaid debts."}}$official_bank_source$::jsonb);
